P.entries["item:okra"] = {n="Okra",s="Alla Fattoria dei Saldean, l'okra contribuisce a nutrire i coloni delle Marche Occidentali. Cresce negli appezzamenti della fattoria e addensa gli stufati che li sostentano.",h="Alla Fattoria dei Saldean, l'okra contribuisce a nutrire i coloni delle Marche Occidentali.",kw={"raccolto","fattoria","okra","saldean","salma saldean","verdura","westfall stew"},ang={["faction:Alliance"]="I nobili di Roccavento banchettano con carni importate, mentre i coloni dell'Alleanza alla frontiera coltivano piante tenaci come l'okra tra le rovine delle Marche Occidentali.",["profession:Cooking"]="Un cuoco errante sa che un buon stufato richiede più della semplice carne cruda. L'okra dona ai coriacei alimenti raccolti nelle terre selvagge l'amido e la consistenza di un pasto caldo."},sec={{t="Un alimento base della Fattoria dei Saldean",b="La Fattoria dei Saldean produce ancora verdure mentre gran parte delle Marche Occidentali giace a maggese, minacciata dai fuorilegge Defias e dagli attacchi dei golem mietitori impazziti. L'okra cresce negli appezzamenti arati attorno alla fattoria e resiste alle dure condizioni. Nutre i coloni locali quando il commercio e le provviste da Roccavento vengono a mancare."},{t="Stufato delle Marche Occidentali",b="Il famoso Westfall Stew di Salma Saldean ha bisogno dell'okra. Salma unisce i baccelli affettati a qualsiasi carne i coloni riescano a procurarsi cacciando nelle pianure polverose, compresi carne di avvoltoio, grugni di zannacupa e occhi di murloc costieri. I baccelli si sfaldano con il calore, addensando un brodo leggero fino a farne un pasto saziante e rinvigorente. Per i coloni che si aggrappano alle proprie terre, l'okra fresca trasforma i pochi alimenti racimolati in una cena calda."}},faq={{q="Dove cresce l'okra nelle Marche Occidentali?",a="L'okra cresce negli appezzamenti arati della Fattoria dei Saldean, lungo la strada centrale delle Marche Occidentali. Le piante verdi prosperano nei solchi vicino alla casa del Contadino Saldean.",al={"posizione dell'okra","dove trovare l'okra","dove cresce l'okra"}},{q="A cosa serve l'okra?",a="Salma Saldean raccoglie l'okra alla Fattoria dei Saldean per il suo caratteristico Westfall Stew. Il suo amido naturale addensa il brodo, amalgamando carne di avvoltoio, grugni di cinghiale e occhi di murloc in un pasto sostanzioso.",al={"usi dell'okra","a cosa serve l'okra","perché ho bisogno dell'okra"}},{q="Perché l'okra è importante per i Saldean?",a="Con il commercio interrotto e scarsi aiuti dal regno, i coloni dipendono da ciò che riescono a coltivare e cacciare. L'okra è una delle poche colture rimaste alla Fattoria dei Saldean e contribuisce a nutrire la famiglia e i viaggiatori di passaggio.",al={"okra dei saldean","perché l'okra è importante"}}},fx={["301f0b5e"]={q="Cos'è l'okra?",a="L'okra è una verdura commestibile che cresce nel terreno coltivato delle Marche Occidentali. Coltivati in fattorie come la Fattoria Saldean, i suoi baccelli sono abbastanza robusti da sopravvivere al clima difficile della regione e costituiscono un raccolto base affidabile per i coloni in difficoltà.",al={"cos'è l'okra","oggetto okra","pianta okra"}},["5bbd3a8c"]={q="Da dove proviene l'okra?",a="L'okra viene coltivata localmente nelle fattorie delle Marche Occidentali, in particolare da Salma e dal Contadino Saldean presso la Fattoria Saldean. Mentre gran parte della campagna è caduta in rovina e abbandono, colture resistenti come l'okra continuano a crescere nei campi coltivati superstiti.",al={"da dove proviene l'okra","chi coltiva l'okra","origine okra"}},b45f6830={q="Perché Salma Saldean vuole l'okra?",a="Salma Saldean ha bisogno di okra fresca come ingrediente essenziale per il suo famoso Westfall Stew. Quando viene affettata e fatta sobbollire insieme a selvaggina e carne locale, la verdura aiuta ad addensare il brodo saporito, fornendo un pasto ricco e sostanzioso per sostenere la gente delle pianure.",al={"perché l'okra è richiesta","perché salma vuole l'okra","chi vuole l'okra"}}},fp="4,136,26.306.0,13.393.0,33.147.0,22.188.0,38.219.0"}
P.entries["item:ordanus-head"] = {n="Testa di Ordanus",s="Al Rifugio di Legnovivo, la Testa di Ordanus è ricercata come prova della caduta del Custode Ordanus. Braelyn Ardimano, una maga elfa del sangue, la cerca a Valtetra.",h="Al Rifugio di Legnovivo, la Testa di Ordanus è ricercata come prova della caduta del Custode Ordanus.",kw={"valtetra","braelyn ardimano","cenarius","custode del boschetto","ordanus","testa di ordanus","rifugio di legnovivo","petrartiglio","sunrock retreat"},ang={["class:Druid"]="Per un druido, portare la testa mozzata di uno dei figli più anziani di Cenarius è un crudo richiamo all'aspro rancore che gli stregoni arcani nutrono ancora verso i protettori della natura.",["faction:Horde"]="Come membro dell'Orda, abbattere Ordanus e consegnare la sua testa a Braelyn contribuisce a consolidare la presenza dell'Orda lungo i confini contesi di Stonetalon e Valtetra. Indebolisce i capi locali degli elfi della notte."},sec={{t="Un rancore dal passato",b="Il Custode Ordanus era un antico custode del boschetto e uno dei figli più anziani di Cenarius. I suoi druidi soffocavano la magia sulla vetta delle Vette di Petrartiglio, e Braelyn Ardimano scalò quelle alture su ordine del suo maestro. Intendeva porre fine al loro dominio e vendicarsi di Ordanus. Prima che potesse colpire, il custode fu portato via di nascosto nel cuore di Valtetra.\n\nBraelyn usò la divinazione arcana per scrutare attraverso le chiome della foresta e trovò il santuario di Ordanus tra i rami del Rifugio di Legnovivo. Lì pretese la sua testa mozzata come prova che all'arroganza del semidio selvaggio fosse stata data una risposta."},{t="Il prezzo della superbia",b="Braelyn Ardimano conobbe Ordanus molto tempo fa e nutre un vecchio rancore nei suoi confronti. Odia anche i druidi che cercano di soffocare la magia. In vita, Ordanus si considerava superiore persino all'antica nobiltà degli Eletti.\n\nPrendendo la sua testa, Braelyn colpisce l'eredità di Cenarius per vendicarsi. Dichiara che nessun guardiano della natura può arginare il ritorno del potere magico puro."}},faq={{q="Chi era il Custode Ordanus?",a="Il Custode Ordanus era un antico custode del boschetto e uno dei figli più anziani di Cenarius. Molto tempo fa, si scontrò con i praticanti della magia arcana tra la nobiltà degli elfi della notte e mostrò profonda arroganza verso chi praticava le arti arcane.",al={"chi è ordanus","storia di ordanus","cos'è ordanus"}},{q="Dove si raccoglie questa testa?",a="La Testa di Ordanus si ottiene dal Custode Ordanus sulla piattaforma di legno sopraelevata del Rifugio di Legnovivo, un insediamento fortificato degli elfi della notte tra le chiome degli alberi nel cuore di Valtetra.",al={"dove trovare la testa di ordanus","posizione di ordanus","rifugio di legnovivo ordanus"}},{q="Perché Braelyn Ardimano vuole la sua testa?",a="Braelyn Ardimano conobbe Ordanus molto tempo fa e ne disprezzava l'arroganza. Lui si considerava superiore persino agli Eletti. Odia anche i druidi e i figli di Cenarius perché cercano di arrestare il flusso della magia e perché portarono via Ordanus di nascosto dalla vetta prima che potesse raggiungerlo.",al={"perché braelyn vuole la testa di ordanus","rancore di braelyn","perché uccidere ordanus"}},{q="Cosa succede dopo che la testa viene consegnata?",a="Consegnare la Testa di Ordanus a Braelyn a Sunrock Retreat salda il suo debito di sangue. Lei ricompensa il mercenario con il potente dono che aveva promesso.",al={"consegna testa di ordanus","dopo la morte di ordanus","ricompensa missione braelyn ardimano"}}},fx={e1459048={q="Da dove proviene la Testa di Ordanus?",a="Questo macabro trofeo è stato preso direttamente dal Custode Ordanus, uno dei figli maggiori del semidio della foresta Cenarius. Sebbene un tempo si pensasse fosse al sicuro in cima al Picco di Petrartiglio, Ordanus è fuggito a Valtetra e si è rifugiato in alto all'interno del Rifugio di Legnovivo prima di essere braccato.",al={"origine testa di ordanus","da dove viene la testa di ordanus","a chi appartiene la testa di ordanus"}}},fp="13,146,22.579.0,19.368.1,23.225.0,29.161.0,40.265.0,41.141.1"}
P.entries["item:orendil-s-cure"] = {n="Cura di Orendil",s="Nel nord di Valtetra, Orendil Foglialarga prepara una pozione per una bambina malata ad Astranaar. La rara pianta Capelli di Bathran dà a Pelturas Lunabianca speranza per sua figlia, Relara.",h="Nel nord di Valtetra, Orendil Foglialarga prepara una pozione per una bambina malata ad Astranaar.",kw={"valtetra","astranaar","capelli di bathran","orendil foglialarga","cura di orendil","pelturas lunabianca","relara"},ang={["profession:Herbalism"]="Le piante autoctone di Valtetra possiedono un grande potere medicinale. I Capelli di Bathran sono una di queste erbe e crescono soltanto in alcuni angoli ombrosi della foresta.",["race:NightElf"]="Per gli Elfi della Notte di Astranaar, salvare Relara è una necessità urgente per la comunità. Gli eremiti come Orendil offrono la conoscenza dei boschi, mentre la fede in Elune porta aiuto divino."},sec={{t="La Speranza di un Padre",b="Relara Lunabianca si ammalò gravemente quando era ancora piccola, e i normali rimedi non riuscirono ad aiutarla ad Astranaar. Suo padre, Pelturas Lunabianca, cercò aiuto da Orendil Foglialarga, un eremita che vive nel nord di Valtetra ed è esperto di medicina naturale.\n\nOrendil raccolse fasci della rara pianta Capelli di Bathran tra le rovine infestate del Covo di Bathran e preparò una pozione per Relara. Quando arriva la fiala, Pelturas ritrova la speranza. Eppure la cura rallenta soltanto la malattia, quindi deve cercare gli ulteriori rimedi suggeriti da Orendil."}},faq={{q="A cosa serve la Cura di Orendil?",a="La Cura di Orendil serve ad alleviare le sofferenze di Relara Lunabianca, una bambina degli Elfi della Notte ad Astranaar. La malattia improvvisa e grave l'ha debilitata.",al={"scopo della cura di orendil","cosa fa la cura","per chi è la cura"}},{q="Chi ha creato la cura?",a="Orendil Foglialarga ha preparato la cura. È un erborista Elfo della Notte che vive appartato nei boschi settentrionali di Valtetra, rinomato per la sua conoscenza delle piante e dei rimedi della foresta.",al={"chi ha creato la cura di orendil","creatore della cura di orendil"}},{q="Quali ingredienti sono stati usati per crearla?",a="La cura utilizza i Capelli di Bathran, una pianta delicata e poco comune raccolta tra le rovine del Covo di Bathran, nel nord di Valtetra.",al={"ingredienti della cura","cosa c'è nella cura di orendil"}},{q="Questa pozione guarisce completamente la bambina?",a="No. Pelturas scopre che la Cura di Orendil rallenta soltanto la malattia che affligge sua figlia. Cerca quindi il rimedio più potente suggerito da Orendil: la Lacrima di Elune.",al={"ha curato relara","relara è guarita"}}},fx={["8e86537e"]={q="Cos'è la Cura di Orendil?",a="La Cura di Orendil è un preparato medicinale creato dall'erborista Orendil Foglialarga nel nord di Valtetra. Progettato come trattamento specializzato per una malattia improvvisa e grave, rappresenta uno sforzo urgente per salvare la vita di una giovane bambina elfo della notte che soffre di un malanno misterioso.",al={"lore cura di orendil","cos'è la cura di orendil","rimedio di orendil"}},["6add91d1"]={q="Perché è necessaria la Cura di Orendil?",a="Ad Astranaar, la giovane figlia di Pelturas Lunabianca, Relara, è gravemente malata. Disperato per un rimedio dopo che i trattamenti standard si sono rivelati inefficaci, suo padre ha cercato l'esperienza di Orendil Foglialarga. L'erborista ha preparato questa specifica miscela nella speranza di stabilizzare la bambina prima che la malattia le tolga la vita.",al={"perché serve la cura di orendil","chi ha bisogno della cura di orendil","perché consegnare la cura di orendil"}}},fp="14,163,15.497.0,32.142.0,21.161.0,38.126.0,43.152.1"}
P.entries["item:oslow-s-toolbox"] = {n="Cassetta degli Attrezzi di Oslow",s="Sul fondo del Lago Placido, gli attrezzi di Oslow giacciono dove gli orchi Roccianera affondarono la barca che li trasportava da Borgodoro.",h="Sul fondo del Lago Placido, gli attrezzi di Oslow giacciono dove gli orchi Roccianera affondarono la barca...",kw={"caposquadra oslow","lago placido","borgolago","oslow","crestarossa","forziere affondato","the lost tools","cassetta degli attrezzi"},ang={["faction:Alliance"]="Borgolago è quasi isolata sotto l'assedio dei Roccianera. Recuperare le provviste di Oslow è vitale per mantenere in buono stato le difese della città."},sec={{t="Una traversata fatidica",b="Il Caposquadra Oslow ha bisogno di attrezzi da costruzione per mantenere in buono stato le difese e gli edifici di Borgolago. Gli orchi Roccianera assediano le Montagne Crestarossa e il ponte che conduce in città è distrutto. Così il carico proveniente da Borgodoro attraversò il Lago Placido su una barca a remi.\n\nLe forze Roccianera colpirono l'imbarcazione con una catapulta. La barca e la pesante cassa di Oslow sprofondarono tra i murloc."}},faq={{q="Perché la Cassetta degli Attrezzi di Oslow si trova sul fondo del lago?",a="Gli attrezzi venivano trasportati da Borgodoro a Borgolago. Con il ponte distrutto, attraversarono il Lago Placido in barca. Gli orchi Roccianera colpirono la barca a remi con una catapulta, facendo affondare la cassetta degli attrezzi sul fondo del lago.",al={"perché la cassetta degli attrezzi è in acqua","come ha perso gli attrezzi oslow","storia della cassetta degli attrezzi affondata"}},{q="A chi appartiene questa cassetta degli attrezzi?",a="Il Caposquadra Oslow possiede la cassetta degli attrezzi e sovrintende ai lavori di costruzione e riparazione a Borgolago. Senza l'attrezzatura adeguata, mantenere in buono stato le fortificazioni della città sotto continui attacchi è quasi impossibile.",al={"chi è oslow","proprietario oslow","attrezzi caposquadra oslow"}},{q="In quale punto del Lago Placido sono affondati gli attrezzi?",a="Gli attrezzi si trovano in una cassa affondata vicino al relitto della barca a remi nel Lago Placido. La cassa giace tra i massi sommersi, a sud di un ben visibile accampamento di murloc sulla riva.",al={"posizione della cassetta degli attrezzi","dove si trova il forziere affondato","dove è affondata la barca"}},{q="Quali minacce fanno la guardia alla cassa affondata?",a="Murloc ostili e bestie acquatiche predatrici infestano le acque intorno al relitto. I pericolosi Lake Threshers si aggirano nelle zone più profonde del lago.",al={"pericoli vicino alla cassetta degli attrezzi","nemici di lago placido","cosa fa la guardia agli attrezzi di oslow"}}},fx={["543d5407"]={q="Perché il Caposquadra Oslow ha bisogno che venga recuperata la sua cassetta degli attrezzi?",a="Borgolago è sotto pesante assedio, il che lascia la città isolata e disperatamente a corto di rifornimenti essenziali. Come caposquadra della città, Oslow ha bisogno della sua attrezzatura per mantenere e riparare le strutture e le difese di Borgolago. Poiché il carro delle consegne da Borgodoro non è riuscito ad attraversare il ponte distrutto, perdere gli attrezzi sostitutivi nel lago ha bloccato lavori di costruzione critici, rendendo il loro recupero vitale per la sopravvivenza della città.",al={"perché oslow vuole la cassetta degli attrezzi","perché oslow ha bisogno degli attrezzi","perché recuperare la cassetta degli attrezzi di oslow"}}},fp="15,106,18.372.0,49.208.0,22.198.0,43.173.0,36.144.0"}
P.entries["item:osric-s-crate"] = {n="Cassa di Osric",s="A Guardiacolle, la Cassa di Osric porta nuove armature da Roccavento alla People's Militia. I difensori affrontano la Fratellanza dei Defias e gli gnoll razziatori senza l'esercito di Roccavento.",h="A Guardiacolle, la Cassa di Osric porta nuove armature da Roccavento alla People's Militia.",kw={"dungar longdrink","grifone","osric","cassa di osric","the people's militia","quartiermastro lewis","guardiacolle","marche occidentali"},ang={["faction:Alliance"]="Per l'Alleanza, ogni spedizione di armi e armature che raggiunge Guardiacolle aiuta a impedire che i confini occidentali del regno cadano nelle mani della Fratellanza dei Defias."},sec={{t="Rifornimenti per il Fronte",b="Il Quartiermastro Lewis riceve la spedizione e distribuisce l'equipaggiamento protettivo tra i combattenti volontari. La corona non offre alcun sostegno formale alla People's Militia. Queste armature appena forgiate servono ad aiutare i volontari a mantenere la posizione."},{t="Rete di Corrieri Alati",b="Dal posatoio di Dungar Longdrink nel Distretto Commerciale di Roccavento, un grifone trasporta la cassa fino a Thor, a Guardiacolle. Il volo evita le pericolose strade attraverso la Foresta di Elwynn e oltre il confine delle Marche Occidentali, dove i banditi possono tendere imboscate ai viaggiatori. I grifoni aiutano a mantenere rifornite le guarnigioni di frontiera in tempo di guerra."}},faq={{q="Cosa c'è dentro la Cassa di Osric?",a="La Cassa di Osric contiene armature protettive forgiate a Roccavento. Il Quartiermastro Lewis riceve la consegna e si prepara a distribuirla tra i combattenti che difendono Guardiacolle.",al={"cosa c'è nella cassa","contenuto della cassa di osric","contenuto cassa di osric"}},{q="Chi è Osric?",a="Osric è un armaiolo di Roccavento che ha preparato la spedizione per la People's Militia, impegnata a difendere le Marche Occidentali.",al={"chi è osric","chi ha inviato la cassa di osric"}},{q="Chi riceve la cassa?",a="Il Quartiermastro Lewis riceve la cassa. Gestisce i rifornimenti e l'equipaggiamento della People's Militia a Guardiacolle, nelle Marche Occidentali.",al={"dove va la cassa","a chi consegno la cassa di osric","destinatario della cassa"}},{q="Perché la cassa viene consegnata tramite grifone?",a="Banditi e fuorilegge rendono pericolose le strade che attraversano Roccavento, la Foresta di Elwynn e le Marche Occidentali. Un grifone trasporta le armature rapidamente e in sicurezza da Dungar Longdrink a Roccavento fino a Thor a Guardiacolle.",al={"perché trasportare la cassa in volo","perché usare i grifoni","volo cassa di osric"}}},fx={["34d354cb"]={q="Cos'è la Cassa di Osric?",a="La Cassa di Osric è una spedizione di armature inviata da Roccavento. È preparata per i difensori di stanza a Guardiacolle nelle Marche Occidentali, che sono disperatamente a corto di equipaggiamento mentre resistono contro la Fratellanza dei Defias.",al={"cos'è la cassa di osric","oggetto cassa di osric","cosa c'è nella cassa di osric"}},["091b5cbb"]={q="Da dove proviene la Cassa di Osric e chi l'ha preparata?",a="La cassa proviene da Roccavento, preparata e spedita da Osric per rifornire The People's Militia. Il Mastro Grifone Dungar Longdrink la affida a te per trasportarla in grifone attraverso il regno fino alle Marche Occidentali.",al={"chi ha preparato la cassa di osric","da dove proviene la cassa di osric","origine cassa di osric"}},["11fb3015"]={q="Perché qualcuno vuole la Cassa di Osric?",a="Il Quartiermastro Lewis e The People's Militia a Guardiacolle hanno un disperato bisogno dell'armatura all'interno. Con le Marche Occidentali abbandonate dalle forze reali e invase dai fuorilegge, ogni pezzo di equipaggiamento protettivo è vitale per mantenere in vita i difensori.",al={"perché consegnare la cassa di osric","perché lewis vuole la cassa di osric","scopo della cassa di osric"}}},fp="13,181,22.237.0,22.301.0,29.174.0,13.101.0,23.128.0,38.199.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="Cassa di Contenitori di Melma",s="A Forgiardente, una Cassa di Contenitori di Melma è destinata a pericolosi campionamenti a Vilbosco. Laris Perdiruote fornisce barattoli capaci di contenere melma corrotta e Melma Maledetta senza dissolversi.",h="A Forgiardente, una Cassa di Contenitori di Melma è destinata a pericolosi campionamenti a Vilbosco.",kw={"contenitori","maledetta","vilbosco","forgiardente","barattoli","laris perdiruote","melma","pacco","corrotta"},ang={["faction:Alliance"]="Come membro dell'Alleanza, raccogliere questi campioni ti aiuta a tenere il passo con le inquietanti ricerche della Società degli Speziali Reali dei Reietti.",["race:Gnome"]="Da gnomo, Laris Perdiruote può dimostrare con le sue ricerche sulla melma ai nani di Forgiardente che ospitare gli gnomi rifugiati valeva la pena."},sec={{t="Equipaggiamento Scientifico da Campo",b="Laris Perdiruote affida una dozzina di barattoli vuoti ai viaggiatori diretti a Vilbosco. Sei sono per la Melma Maledetta e sei per la melma corrotta. I campioni grezzi sono caustici e possono corrodere i normali bagagli. Il vetro robusto e sigillato trattiene i residui acidi durante il viaggio attraverso i continenti fino al banco di lavoro di Laris a Forgiardente."},{t="Il Mistero della Melma",b="L'interesse di Laris Perdiruote per la melma va oltre un passatempo eccentrico. Ha visto ricercatori Reietti della Società degli Speziali Reali raccogliere questi strani organismi in tutta Azeroth e si chiede cosa sappiano. Sospetta che le melme possano essere secrezioni primordiali legate alla creazione del mondo. Gli agenti sul campo raccolgono prove nei suoi barattoli, con cui spera di ottenere il plauso della Lega degli Esploratori."}},faq={{q="Cosa contiene la cassa di contenitori di melma?",a="La cassa contiene dodici barattoli vuoti per campioni: sei per la Melma Maledetta e sei per la melma corrotta.",al={"contenuto del pacco","cosa contiene il pacco","barattoli per melma all'interno"}},{q="Chi fornisce questo pacco?",a="Laris Perdiruote, uno studioso e ricercatore gnomo di Forgiardente, fornisce la cassa agli avventurieri dell'Alleanza.",al={"chi fornisce i barattoli","oggetto di missione di laris perdiruote","dove trovare la cassa di melma"}},{q="Dove devono essere utilizzati questi contenitori?",a="I contenitori sono destinati a Vilbosco. Lì, gli avventurieri sconfiggono melme corrotte e maledette, poi raccolgono i residui dalle creature abbattute.",al={"dove usare i barattoli per melma","quale zona per le melme","posizione dei barattoli per melma"}},{q="Perché Laris Perdiruote vuole questi campioni di melma?",a="Laris ha visto la Società degli Speziali Reali dei Reietti raccogliere melma in tutto il mondo e vuole scoprirne i segreti. Sospetta che le melme possano essere secrezioni primordiali legate alla creazione di Azeroth e spera che le prove gli valgano prestigio nella Lega degli Esploratori.",al={"perché raccogliere melma","ricerca di perdiruote","perché laris vuole la melma"}}},fx={d8bf9111={q="Cos'è la Cassa di Contenitori di Melma?",a="È un kit da campo assemblato dal ricercatore gnomo Laris Perdiruote a Forgiardente. Il pacco contiene una serie di barattoli appositamente preparati per raccogliere e conservare in sicurezza i campioni prelevati dalle melme corrotte che si trovano in tutto Vilbosco.",al={"cos'è la cassa di contenitori di melma","pacchetto contenitori di melma","set contenitori di melma vuoti"}}},fp="32,181,24.324.0,23.402.0,52.91.0,26.110.0,44.137.0,50.260.0"}
P.entries["item:painted-gnoll-armband"] = {n="Polsiera degli Gnoll Dipinta",s="Al Presidio Rivombroso, le Polsiere degli Gnoll Dipinte provano l'uccisione degli gnoll Riverpaw. I loro branchi premono contro il confine occidentale della Foresta di Elwynn.",h="Al Presidio Rivombroso, le Polsiere degli Gnoll Dipinte provano l'uccisione degli gnoll Riverpaw.",kw={"taglia","vicesceriffo rainer","foresta di elwynn","gnoll","polsiera degli gnoll dipinta","riverpaw","lago del memoriale","presidio rivombroso"},ang={["faction:Alliance"]="Come avventuriero dell'Alleanza, raccogliendo queste polsiere aiuti il Presidio Rivombroso a difendere la frontiera occidentale di Roccavento mentre l'esercito permanente della città è impegnato altrove."},sec={{t="Simboli dei Riverpaw",b="I guerrieri e i razziatori Riverpaw indossano rozze fasce segnate da rudimentali motivi tribali. Queste polsiere provengono dagli gnoll Riverpaw lungo i confini selvaggi della Foresta di Elwynn. I difensori di Roccavento affrontano una minaccia crescente vicino al Lago del Memoriale e nei boschi a sud del Presidio Rivombroso."},{t="Taglia per il Presidio Rivombroso",b="L'esercito di Roccavento è disperso per tutto il regno, e il Presidio Rivombroso fatica a difendere il confine occidentale. Il Vicesceriffo Rainer offre una taglia permanente per l'uccisione dei Riverpaw Outrunners e dei Riverpaw Runts. Le fasce dipinte consentono ai vicesceriffi di conteggiare le taglie e sfoltire i branchi nei pressi dei terreni agricoli circostanti."}},faq={{q="Perché il Presidio Rivombroso vuole queste polsiere?",a="Il Vicesceriffo Rainer, al Presidio Rivombroso, raccoglie le polsiere come prova dell'uccisione degli gnoll Riverpaw. Le truppe del presidio non riescono ad affrontare da sole i branchi che avanzano, così Roccavento paga taglie a chi riporta questi trofei.",al={"perché le polsiere","chi vuole le polsiere degli gnoll dipinte","taglia del vicesceriffo rainer"}},{q="Quali gnoll indossano queste polsiere dipinte?",a="Gli gnoll Riverpaw indossano le polsiere dipinte. I Riverpaw Outrunners e i Riverpaw Runts infestano i boschi a sud del Presidio Rivombroso e le rive del Lago del Memoriale.",al={"dove si trovano le polsiere","chi rilascia la polsiera degli gnoll dipinta","quali gnoll hanno le polsiere"}},{q="Perché gli gnoll Riverpaw si trovano nella Foresta di Elwynn?",a="I branchi Riverpaw sono avanzati verso est lungo i confini della Foresta di Elwynn, accampandosi vicino al Lago del Memoriale e ai margini della foresta. Con la presenza militare del regno ridotta, cacciano, rovistano in cerca di cibo e minacciano gli insediamenti vicini.",al={"perché gli gnoll sono qui","invasione degli gnoll a elwynn","riverpaw elwynn"}},{q="Qual è il significato della pittura sulle polsiere?",a="La pittura contrassegna i trofei sottratti agli gnoll Riverpaw e aiuta a provarne l'uccisione al Vicesceriffo Rainer. Ai motivi non è attribuito alcun grado o significato.",al={"perché sono dipinte","segni sulle polsiere degli gnoll"}}},fx={["586b453e"]={q="Cos'è la Polsiera degli Gnoll Dipinta?",a="La Polsiera degli Gnoll Dipinta è un rozzo ornamento personale indossato dagli gnoll Riverpaw. Realizzate e dipinte dal branco, queste polsiere segnano la loro presenza nelle terre di confine della Foresta di Elwynn. Per l'esercito di Roccavento, fungono da innegabile prova fisica che un predone gnoll è stato ucciso.",al={"cos'è la polsiera degli gnoll dipinta","lore della polsiera degli gnoll dipinta","polsiera gnoll"}}},fp="21,142,22.279.0,29.306.0,48.226.0,41.166.0,41.226.0,54.140.0"}
P.entries["item:panther-cage-key"] = {n="Chiave della Gabbia della Pantera",s="All'Accampamento di Manto Bianco, Wizlo Bearingshiner custodisce la Chiave della Gabbia della Pantera. Apre la gabbia rimasta tra i carri distrutti di una carovana caduta in un'imboscata a Millepicchi.",h="All'Accampamento di Manto Bianco, Wizlo Bearingshiner custodisce la Chiave della Gabbia della Pantera.",kw={"centauri","ingranaggio ipercapacitante","chiave della gabbia della pantera","millepicchi","accampamento di manto bianco","wizlo bearingshiner"},ang={["faction:Horde"]="Aiutare Wizlo può rendere più sicure le strade attorno all'Accampamento di Manto Bianco a Millepicchi dopo le incursioni dei centauri.",["profession:Engineering"]="La chiave apre una gabbia che racchiude il prototipo instabile di un meccanico. Wizlo ha lasciato la sua delicata invenzione in un luogo pericoloso."},sec={{t="Una serratura precaria",b="Wizlo Bearingshiner è un meccanico goblin scampato a stento a un attacco dei centauri contro la sua carovana a nord dell'Accampamento di Manto Bianco. I predoni hanno saccheggiato i carri e il carico, ma hanno lasciato intatta una robusta gabbia. Al suo interno attende una pantera rara e feroce. Al collo porta la preziosa invenzione di Wizlo, un Ingranaggio Ipercapacitante. La bestia ringhiante ha tenuto lontani i centauri, e solo la chiave di Wizlo permette di aprire la gabbia e recuperare il congegno."}},faq={{q="Chi fornisce la Chiave della Gabbia della Pantera?",a="Wizlo Bearingshiner, un meccanico goblin che si riposa all'Accampamento di Manto Bianco, nella parte nordoccidentale di Millepicchi, fornisce la chiave.",al={"chi dà la chiave della gabbia della pantera","dove trovare la chiave della gabbia della pantera","fonte della chiave della gabbia della pantera"}},{q="Cosa apre la chiave?",a="La chiave apre una gabbia di ferro tra i carri distrutti di una carovana devastata poco a nord dell'Accampamento di Manto Bianco. Al suo interno si trova una pantera infuriata e pericolosa.",al={"cosa apre la chiave della pantera","posizione della gabbia della pantera","dove si trova la gabbia"}},{q="Perché i centauri non hanno saccheggiato la gabbia?",a="I centauri hanno saccheggiato il resto della carovana, ma hanno lasciato stare la gabbia. La pantera prigioniera era troppo feroce e minacciosa perché osassero avvicinarsi.",al={"perché i centauri hanno lasciato la pantera","centauri spaventati dalla pantera"}},{q="Cosa c'è dentro la gabbia oltre alla bestia?",a="Il prezioso Ingranaggio Ipercapacitante di Wizlo pende dal collo della pantera. Per recuperarlo, qualcuno deve aprire la serratura della gabbia e affrontare il predatore.",al={"perché aprire la gabbia","cosa ha addosso la pantera"}}},fx={b335554a={q="Perché Wizlo Bearingshiner vuole indietro la Chiave della Gabbia della Pantera?",a="Wizlo Bearingshiner ti affida la chiave solo affinché tu possa aprire la gabbia presso la sua carovana distrutta per uccidere la feroce pantera al suo interno. La bestia indossa al collo il suo prezioso ingranaggio ipercapacitante. Vuole che la chiave gli venga restituita insieme alla sua invenzione una volta compiuta l'azione, assicurandosi che i resti della carovana e la sua pericolosa proprietà siano interamente recuperati.",al={"perché la chiave della gabbia della pantera","perché wizlo ha bisogno della chiave","perché volere la chiave della gabbia della pantera"}}},fp="16,160,17.423.0,34.115.0,25.142.0,37.137.0,42.139.0"}
P.entries["item:parker-s-lunch"] = {n="Pasto di Parker",s="A Borgolago, Darcy prepara il Pasto di Parker per la pattuglia della Guardia Parker. Il pasto offre uno scorcio sui legami e sui modesti confort dei difensori di Crestarossa.",h="A Borgolago, Darcy prepara il Pasto di Parker per la pattuglia della Guardia Parker.",kw={"a free lunch","darcy","guardia parker","borgolago","pasto di parker","crestarossa"},ang={["faction:Alliance"]="Con i rinforzi dalla capitale che tardano ad arrivare, gli abitanti e le poche guardie rimaste si sostengono a vicenda per mantenere in funzione Borgolago.",["profession:Cooking"]="Per le guardie di frontiera, un pasto caldo al sacco porta conforto durante le lunghe ore nelle terre selvagge, tra bestie ostili."},sec={{t="Un pasto per il viaggio",b="Darcy lavora come cameriera alla locanda di Borgolago, dove prepara un pasto per la Guardia Parker. Lui pattuglia la strada esposta che conduce a sud verso Boscovespro, mentre Crestarossa subisce gli attacchi degli gnoll e degli orchi Roccianera. La guarnigione è allo stremo e tagliata fuori dagli aiuti di Roccavento, così le sue guardie affrontano turni di sorveglianza lunghi e solitari. Il piccolo gesto di Darcy sfama Parker e dà inizio a un timido corteggiamento tra i due."}},faq={{q="Chi ha preparato il Pasto di Parker?",a="Darcy, una cameriera della locanda di Borgolago, prepara il Pasto di Parker per la Guardia Parker mentre lui è di pattuglia. Un viaggiatore gli porta il pasto.",al={"chi ha preparato il pasto di parker","chi mi ha dato il pasto di parker","darcy crestarossa pasto"}},{q="Dove si trova la Guardia Parker?",a="La Guardia Parker pattuglia la strada sterrata principale che da Borgolago conduce a sudovest verso il confine con Boscovespro. Marcia avanti e indietro, tenendo d'occhio gli gnoll che si aggirano nei dintorni.",al={"posizione della guardia parker","dove si trova la guardia parker","trovare la guardia parker"}},{q="Cosa fa la Guardia Parker dopo aver ricevuto il pranzo?",a="Parker è commosso dalla premura di Darcy e cerca un modo per ricambiare la sua gentilezza. Fa in modo che le vengano inviati dei narcisi freschi dall'erborista.",al={"seguito del pasto di parker","darcy e parker","reazione di parker al pranzo"}},{q="Perché Darcy non consegna il pranzo di persona?",a="Gli gnoll e gli invasori Roccianera minacciano le strade fuori Borgolago. Darcy è una comune cittadina, mentre Parker ha l'addestramento e l'armatura per pattugliarle.",al={"perche darcy non puo portarlo","perche consegnare il pasto crestarossa"}}},fx={["2351e721"]={q="Cos'è il Pasto di Parker?",a="Il Pasto di Parker è un pasto confezionato preparato da Darcy, l'assistente di un locandiere a Borgolago. Lo ha preparato appositamente per sostenere la Guardia Parker, che trascorre lunghe ed estenuanti ore a pattugliare le insidiose strade a sud della città verso Boscovespro.",al={"cos'è il pasto di parker","oggetto pasto di parker"}},b73a829b={q="Perché la Guardia Parker ha bisogno che gli venga consegnato il pasto?",a="La Guardia Parker è di stanza ben lontano dalla relativa sicurezza di Borgolago, a fare la guardia contro gnoll erranti e orchi Roccia Nera lungo la strada di confine. Impossibilitato ad abbandonare il suo posto per tornare alla locanda, dipende dalla gentilezza degli abitanti come Darcy, e dei viaggiatori di passaggio, per essere sfamato durante il servizio.",al={"perché consegnare il pasto di parker","perché parker vuole il pasto","perché la guardia parker ha bisogno del pasto"}}},fp="14,154,19.382.0,28.143.0,32.148.0,52.147.1,44.158.0"}
P.entries["item:partially-filled-vessel"] = {n="Ampolla Mezza Piena",s="Ad Aldrassil, Tenaron Fermatuono consegna ai giovani iniziati elfi della notte l'Ampolla Mezza Piena. Contiene acqua benedetta del pozzo lunare, in viaggio da Vallombra verso Dolanaar.",h="Ad Aldrassil, Tenaron Fermatuono consegna ai giovani iniziati elfi della notte l'Ampolla Mezza Piena.",kw={"aldrassil","corithras lunafuria","crown of the earth","dolanaar","pozzo lunare","ampolla mezza piena","vallombra","tenaron fermatuono","ampolla"},ang={["class:Druid"]="Come druido, trasporti acqua consacrata per contribuire agli sforzi del Circolo Cenariano volti a nutrire l'Albero del Mondo e verificarne la salute.",["race:NightElf"]="Come giovane elfo della notte, trasportare quest'ampolla ti conduce dal santuario di Vallombra al più ampio compito di prenderti cura di Teldrassil."},sec={{t="Una consegna sacra",b="I giovani iniziati kaldorei raccolgono acqua benedetta dal pozzo lunare appartato di Vallombra. Ad Aldrassil, Tenaron Fermatuono ne versa un campione nell'ampolla per il viaggio attraverso Teldrassil. Serve altra acqua dai pozzi lunari dell'albero per prendersi cura della salute dell'isola."},{t="Verso Dolanaar",b="Porta l'ampolla a sud attraverso i cancelli della valle, poi segui le strade acciottolate verso ovest fino a Dolanaar. Il viaggio conduce oltre la culla protetta di Vallombra, nelle più vaste terre selvagge di Teldrassil. Presso il pozzo lunare centrale di Dolanaar, Corithras Lunafuria riceve l'ampolla e indica la fase successiva del rituale."}},faq={{q="Cosa c'è dentro l'ampolla?",a="Il druido Tenaron Fermatuono versa nell'ampolla acqua pura dal sacro pozzo lunare di Vallombra.",al={"cosa c'è nell'ampolla","contenuto dell'ampolla","che acqua c'è dentro"}},{q="Perché è solo mezza piena?",a="Il pozzo lunare di Vallombra fornisce soltanto il primo campione. Per prendersi cura di Teldrassil serve acqua da diversi pozzi lunari prima che l'ampolla sia piena.",al={"perché mezza piena","perché non è piena"}},{q="A chi porto questa ampolla?",a="Porta l'ampolla a sud, fuori da Vallombra, poi segui la strada acciottolata verso ovest fino a Dolanaar. Consegnala a Corithras Lunafuria, che si prende cura del pozzo lunare del villaggio.",al={"a chi va l'ampolla","dove la porto","consegna ampolla"}},{q="Perché l'acqua del pozzo lunare viene spostata su Teldrassil?",a="Druidi e sacerdotesse sorvegliano e nutrono Teldrassil attraverso le acque dei suoi pozzi lunari. Trasportare l'acqua tra i pozzi aiuta a mantenerne le benedizioni sui rami sofferenti dell'Albero del Mondo appena cresciuto.",al={"perché trasportare l'acqua del pozzo lunare","scopo dell'acqua","perché spostare l'acqua"}}},fx={["5f4a3df1"]={q="Cos'è l'Ampolla Mezza Piena?",a="L'Ampolla Mezza Piena è un contenitore incantato usato dai druidi elfi della notte per raccogliere e trasportare le acque sacre dei pozzi lunari di Teldrassil. Quando Tenaron Fermatuono ti invia da Vallombra, unisce la tua fiala raccolta di acqua benedetta del pozzo lunare in questa ampolla, affinché il lavoro sacro possa continuare attraverso i rami dell'Albero del Mondo.",al={"lore dell'ampolla mezza piena","cos'è questa ampolla","cos'è l'ampolla mezza piena"}},["4f920d4c"]={q="Da dove proviene l'Ampolla Mezza Piena e chi l'ha creata?",a="Tenaron Fermatuono, uno dei druidi anziani di stanza in cima ad Aldrassil a Vallombra, ti fornisce questo contenitore. Dopo che avrai attinto l'acqua dal pozzo lunare di Vallombra, Tenaron verserà la tua fiala nel contenitore per iniziare la raccolta, affidandoti il compito di trasportarlo verso le distese più ampie di Teldrassil.",al={"chi ha creato l'ampolla","da dove proviene l'ampolla","origine dell'ampolla"}},["089d2d88"]={q="Perché Corithras Lunafuria vuole l'Ampolla Mezza Piena?",a="Corithras Lunafuria attende il contenitore presso il pozzo lunare di Dolanaar per proseguire un compito druidico vitale noto come la Crown of the Earth. Raccogliere le acque di Teldrassil è essenziale per ispezionare e prendersi cura del giovane Albero del Mondo, e Corithras richiede l'acqua che hai trasportato da Aldrassil prima di poterti indirizzare verso le fasi successive del rituale.",al={"perché corithras vuole questo","perché portare l'ampolla a dolanaar","perché portare l'ampolla a corithras"}}},fp="23,159,17.262.0,18.309.0,26.93.0,32.142.0,29.159.0,52.198.0"}
P.entries["item:pendant-of-shadow"] = {n="Pendente dell'Ombra",s="Alla Torre di Ilgalar, Morganth porta il Pendente dell'Ombra mentre cerca la Falce di Elune. Theocritus vuole che venga portato alla Torre di Azora come prova che Morganth è stato ucciso.",h="Alla Torre di Ilgalar, Morganth porta il Pendente dell'Ombra mentre cerca la Falce di Elune.",kw={"morganth","pendente dell'ombra","crestarossa","falce di elune","theocritus","torre di azora","torre di ilgalar"},ang={["class:Mage"]="Se sei un mago, recuperare il talismano per Theocritus dimostra la responsabilità dei maghi di fermare gli incantatori rinnegati e sconsiderati che minacciano il regno.",["class:Warlock"]="Se sei uno stregone, Morganth mostra il pericolo di attirare l'attenzione della Torre di Azora mentre si cercano artefatti instabili e proibiti come la Falce di Elune."},sec={{t="Emblema di un Oscuro Stregone",b="Alla Torre di Ilgalar, Morganth custodisce il Pendente dell'Ombra. Lo stregone rinnegato cerca i misteri della Falce di Elune, un'antica reliquia dal potere immenso e instabile.\n\nTheocritus teme la devastazione che Morganth potrebbe scatenare sulle Montagne Crestarossa e sul regno di Roccavento. Il mago invia avventurieri a infiltrarsi a Ilgalar, porre fine alle trame di Morganth e prendere il talismano come prova della sua morte."}},faq={{q="Dove trovo il Pendente dell'Ombra?",a="Morganth porta con sé il pendente in cima alla Torre di Ilgalar, nella parte nordorientale delle Montagne Crestarossa.",al={"posizione del pendente dell'ombra","dove si trova il pendente dell'ombra","come ottenere il pendente dell'ombra"}},{q="Chi vuole il Pendente dell'Ombra?",a="Theocritus vuole che il talismano gli venga portato alla Torre di Azora, nella parte orientale della Foresta di Elwynn.",al={"chi accetta il pendente dell'ombra","consegna del pendente dell'ombra","il pendente di theocritus"}},{q="Perché Theocritus ha bisogno di questo pendente?",a="A Theocritus serve il pendente come prova che Morganth è stato ucciso e che la ricerca della pericolosa Falce di Elune è terminata.",al={"perché theocritus lo vuole","scopo del pendente dell'ombra"}},{q="Quale minaccia rappresentava Morganth con il pendente?",a="Morganth cercava la Falce di Elune. Theocritus temeva che lo stregone avrebbe scatenato un potere catastrofico su Crestarossa e sul regno circostante se fosse riuscito a impossessarsi dell'artefatto.",al={"cosa stava facendo morganth","storia di morganth"}}},fx={d0e37f9a={q="Cos'è il Pendente dell'Ombra?",a="Il Pendente dell'Ombra è un oscuro talismano indossato dal famigerato stregone Morganth in cima alla Torre di Ilgalar nelle Montagne Crestarossa. Legato direttamente alle sinistre ambizioni e alle arti oscure di Morganth, il pendente funge da prova della sua sconfitta per il mago Theocritus, che teme il caos che Morganth potrebbe scatenare su Roccavento se lasciato indisturbato.",al={"cos'è il pendente dell'ombra","lore del pendente dell'ombra","informazioni sul pendente dell'ombra"}}},fp="17,180,23.403.1,38.99.0,32.92.0,38.121.1,47.171.1"}
P.entries["item:pendant-of-the-sea-lion"] = {n="Pendente del Leone Marino",s="Al Santuario di Remulos, i druidi uniscono le due metà del Pendente del Leone Marino. Il talismano completo dimostra che un iniziato è pronto a imparare un'Aquatic Form.",h="Al Santuario di Remulos, i druidi uniscono le due metà del Pendente del Leone Marino.",kw={"aquatic form","dendrite ardistella","mathrengyl domaorsi","radaluna","pendente del leone marino","remulos","turak totem runico"},ang={["class:Druid"]="Come druido, assemblare il pendente segna una tappa fondamentale del tuo addestramento. Ti permette di respirare sott'acqua e nuotare velocemente come un leone marino.",["race:Tauren"]="Come tauren che segue il sentiero del Circolo Cenariano, onori i tuoi antenati e gli insegnamenti di Radaluna quando porti il pendente a Turak Totem Runico."},sec={{t="Un Simbolo degli Abissi",b="Un druido deve affrontare i pericoli dell'acqua per ottenere l'aspetto acquatico del leone marino. Il pendente è composto da due metà. Una conferisce l'agilità necessaria per eludere i predatori acquatici, mentre l'altra dona la resistenza per sopportare immersioni prolungate. Al Santuario di Remulos, a Radaluna, i druidi uniscono i pezzi."},{t="Prova di Maestria",b="Una volta forgiato il pendente, un iniziato lo porta a un mentore anziano. Turak Totem Runico attende sulle alture di Picco del Tuono, mentre Mathrengyl Domaorsi si trova a Darnassus. Il talismano dimostra che l'iniziato ha completato le prove sotto la guida di Dendrite Ardistella. L'anziano può quindi insegnargli i segreti per assumere un'Aquatic Form."}},faq={{q="Qual è lo scopo del Pendente del Leone Marino?",a="Il pendente dimostra che un iniziato ha completato le prove di agilità e resistenza acquatiche ed è pronto a imparare un'Aquatic Form.",al={"a cosa serve il pendente del leone marino","uso del pendente del leone marino","perché ottenere il pendente del leone marino"}},{q="Dove viene assemblato il pendente?",a="I druidi uniscono le due metà del pendente al Santuario di Remulos, a Radaluna. Una metà serve per l'agilità e l'altra per la resistenza.",al={"come creare il pendente del leone marino","dove unire le metà del pendente"}},{q="A chi devo consegnare il pendente a Picco del Tuono?",a="A Picco del Tuono, consegni il pendente completo a Turak Totem Runico sull'Altura degli Anziani.",al={"chi riceve il pendente a picco del tuono","pendente turak totem runico","consegna aquatic form horde"}},{q="Anche gli elfi della notte possono ottenere questo pendente?",a="Sì. I druidi Elfi della Notte affrontano la stessa prova a Radaluna, poi portano il pendente assemblato a Mathrengyl Domaorsi a Darnassus.",al={"pendente del leone marino alliance","pendente del leone marino darnassus"}}},fx={["203d1c94"]={q="Cos'è il Pendente del Leone Marino?",a="Il Pendente del Leone Marino è un sacro talismano druidico che simboleggia la maestria sull'acqua. Incarna l'agilità necessaria per eludere i pericolosi predatori acquatici insieme alla profonda resistenza necessaria per rimanere immersi senza riemergere. I druidi portano questa reliquia unita come prova tangibile che comprendono l'equilibrio selvaggio della natura prima di adottare un aspetto acquatico.",al={"cos'è il pendente del leone marino","informazioni sul pendente del leone marino","lore del pendente del leone marino"}},ad633d46={q="Da dove proviene il Pendente del Leone Marino e chi l'ha creato?",a="Il talismano è forgiato dai giovani druidi che affrontano la Trial of the Sea Lion. Viene creato recuperando due pezzi separati, il Mezzo Pendente dell'Agilità Acquatica e il Mezzo Pendente della Resistenza Acquatica, dai luoghi della prova e riunendoli davanti al Santuario di Remulos a Radaluna, unendo gli aspetti in un unico sacro emblema.",al={"chi ha creato il pendente del leone marino","origine del pendente del leone marino","come viene creato il pendente del leone marino"}},["384283bf"]={q="Perché qualcuno vuole il Pendente del Leone Marino?",a="I mentori druidici richiedono di vedere il pendente completato come prova innegabile del tuo addestramento. A Picco del Tuono, Turak Totem Runico richiede il medaglione per verificare che tu abbia superato le prove di Radaluna prima di impartirti i segreti dell'Aquatic Form. Anche Dendrite Ardistella a Radaluna ispeziona la reliquia unita per confermare il completamento della prova.",al={"perché volere il pendente del leone marino","chi vuole il pendente del leone marino","perché mostrare il pendente del leone marino"}}},fp="23,154,19.299.0,16.307.0,51.119.0,31.128.0,49.89.0,39.130.0"}
P.entries["item:perenolde-tiara"] = {n="Diadema di Perenolde",s="Tra le Rovine d'Alterac, il Diadema di Perenolde è riemerso. Gli artigiani nani di Forgiardente crearono questo cimelio tempestato di smeraldi, e i collezionisti di Roccavento lo cercano.",h="Tra le Rovine d'Alterac, il Diadema di Perenolde è riemerso.",kw={"alterac","smeraldi","grel'borg","forgiardente","avaro","perenolde","remington","crestafonda","diadema"},ang={["faction:Alliance"]="Come membro dell'Alleanza, ti trovi davanti a un amaro ricordo della casata Perenolde, il cui tradimento durante la Seconda Guerra quasi distrusse l'originaria Alleanza di Lordaeron.",["race:Dwarf"]="Come nano, puoi riconoscere l'arte orafa di Forgiardente negli smeraldi che i suoi maestri gioiellieri tagliarono e incastonarono per i sovrani umani del nord."},sec={{t="Una reliquia di un regno in rovina",b="La famiglia Perenolde governò Alterac fino alla caduta del regno durante la Seconda Guerra. Tra i suoi tesori c'era un delicato diadema, creato dai maestri gioiellieri di Forgiardente e impreziosito da brillanti smeraldi. Dopo che il tradimento di re Aiden Perenolde portò Alterac alla rovina, il diadema svanì nella devastazione delle alte rupi."},{t="Il bottino dell'avaro",b="Grel'borg the Miser, un ogre mago, dissotterrò il diadema mentre cercava ricchezze abbandonate tra le Rovine d'Alterac. La notizia della reliquia raggiunse il Conte Remington Crestafonda, un ricco nobile di Roccavento che colleziona celebri reliquie per il museo della sua famiglia. Ora il conte cerca di sottrarre il diadema all'ogre."}},faq={{q="Cos'è il Diadema di Perenolde?",a="Il Diadema di Perenolde è un cimelio della famiglia Perenolde, la casa reale di Alterac. I gioiellieri nani di Forgiardente lo crearono e vi incastonarono degli smeraldi prima che andasse perduto nella caduta del regno.",al={"storia del diadema di perenolde","cos'è questo diadema","diadema di alterac"}},{q="Chi possiede il diadema adesso?",a="Grel'borg the Miser, un ogre mago, trovò il diadema tra le Rovine d'Alterac sepolte dalla neve. Lo custodisce mentre cerca altri tesori nel regno in rovina.",al={"dove si trova il diadema","chi rilascia il diadema","diadema di grelborg"}},{q="Perché il Conte Remington Crestafonda lo vuole?",a="Il Conte Remington Crestafonda colleziona antichità storiche e prestigiose per il museo della sua famiglia a Roccavento. Vuole il diadema come gioiello della corona di un regno umano caduto.",al={"chi vuole il diadema","perché remington lo vuole","movente di remington crestafonda"}},{q="Chi erano i Perenolde?",a="I Perenolde governavano il regno di Alterac. Durante la Seconda Guerra, re Aiden Perenolde tradì l'Alleanza a favore dell'Orda orchesca, e il suo regno cadde in rovina.",al={"famiglia perenolde","casata dei perenolde","governanti di alterac"}}},fx={da959daa={q="Da dove proviene il Diadema di Perenolde e chi l'ha creato?",a="Il diadema proviene dal distrutto regno settentrionale di Alterac, dove fungeva da prezioso cimelio di famiglia per la stirpe reale di Perenolde. Invece di essere forgiato da artigiani umani, si dice che sia stato realizzato da maestri gioiellieri nanici a Forgiardente, che hanno incastonato il pezzo ornato con i migliori smeraldi.",al={"chi ha creato il diadema di perenolde","origine del diadema di perenolde","dove è stato creato il diadema"}}},fp="15,167,27.319.0,17.295.0,28.187.0,28.152.0,43.172.0,24.161.0"}
P.entries["item:phial-of-scrying"] = {n="Fiala della Chiaroveggenza",s="In tutta Rivafosca, gli esploratori contattano Onu da luoghi pericolosi. Onu fornisce la Fiala della Chiaroveggenza, le cui acque incantate formano un bacile per la divinazione attraverso i boschi corrotti.",h="In tutta Rivafosca, gli esploratori contattano Onu da luoghi pericolosi.",kw={"rivafosca","gladio del maestro","onu","fiala della chiaroveggenza","bacile di chiaroveggenza","martello del crepuscolo"},ang={["class:Druid"]="Come druido, riconosci nei bacili di chiaroveggenza un connubio di acqua naturale e magia di comunione. Permettono ai custodi della foresta di scambiarsi sussurri attraverso terre corrotte.",["race:NightElf"]="Come Elfo della Notte di Rivafosca, sai che le acque di chiaroveggenza aiutano a sorvegliare i boschi sacri in cui si insinuano culti estranei."},sec={{t="Una lente su Rivafosca",b="Gli esploratori nelle profondità di Rivafosca usano la Fiala della Chiaroveggenza per la divinazione a distanza. Le sue acque mistiche formano un bacile temporaneo sul terreno. Da luoghi pericolosi come il Gladio del Maestro, possono parlare con Onu senza tornare al suo boschetto."},{t="Svelare la Setta",b="Onu dà agli esploratori la fiala per sorvegliare i cultisti del Martello del Crepuscolo. Nel luogo in cui un antico maestro caduto giace trafitto da un enorme gladio, un esploratore stabilisce un legame di chiaroveggenza. La visione conferma che oscuri cultisti si radunano attorno agli antichi resti, cercando frammenti di potere dimenticato che persistono persino nella morte."}},faq={{q="Cosa fa la Fiala della Chiaroveggenza?",a="Stappa la Fiala della Chiaroveggenza e un bacile magico si forma sul terreno. Sul campo, puoi usarlo per contattare Onu e parlare con lui attraverso immense distanze.",al={"usare la fiala della chiaroveggenza","funzione del bacile di chiaroveggenza","a cosa serve questa fiala"}},{q="Chi fornisce la Fiala della Chiaroveggenza?",a="L'antico treant Onu dà la fiala agli esploratori a Rivafosca quando li invia a sud per perlustrare il Gladio del Maestro.",al={"chi dà la fiala della chiaroveggenza","dove ottengo la fiala"}},{q="Cosa succede se la fiala viene persa o esaurita?",a="Se perdi la fiala o la usi prima di completare la missione, Onu può dartene un'altra mentre medita a Rivafosca.",al={"fiala della chiaroveggenza persa","ottenere un'altra fiala","sostituire la fiala"}},{q="Perché Onu scruta verso il Gladio del Maestro?",a="Onu sa che un antico signore cadde al Gladio del Maestro e ti chiede di cercarvi i cultisti del Martello del Crepuscolo. Il loro scopo diventa chiaro man mano che l'indagine prosegue.",al={"perché scrutare gladio del maestro","missione di onu gladio"}}},fx={["92e56a99"]={q="Cos'è la Fiala della Chiaroveggenza?",a="La Fiala della Chiaroveggenza è un contenitore incantato contenente acque mistiche fornite dall'antico del sapere, Onu. Quando viene versata sul campo, crea una Coppa della Chiaroveggenza temporanea che funge da condotto magico, permettendoti di stabilire un legame spirituale diretto con l'antico attraverso vaste distanze.",al={"cos'è la fiala della chiaroveggenza","lore della fiala della chiaroveggenza","fiala della chiaroveggenza spiegata"}},["16c85a4e"]={q="Perché Onu vuole che tu usi la Fiala della Chiaroveggenza?",a="Onu ti chiede di perlustrare il Gladio del Maestro alla ricerca dei cultisti del Martello del Crepuscolo. La fiala ti permette di creare una coppa della chiaroveggenza e parlare con lui dopo aver perlustrato il sito, senza dover prima tornare al suo boschetto.",al={"perché usare la fiala della chiaroveggenza","perché onu vuole la fiala","perché serve la fiala della chiaroveggenza"}}},fp="16,173,23.242.0,19.313.1,34.155.0,34.122.0,47.120.0,44.171.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="Pezzo dello Stendardo di Krom'zar",s="Al bunker di Regthar Deathgate a ovest di Crocevia, uno stendardo lacero ricorda l'assalto fallito. Il Signore della Guerra Krom'zar guidò verso est da Desolanda la forza di rappresaglia dei Kolkar.",h="Al bunker di Regthar Deathgate a ovest di Crocevia, uno stendardo lacero ricorda l'assalto fallito.",kw={"stendardo","centauro","contrattacco","crocevia","deathgate","kolkar","krom'zar","regthar"},ang={["faction:Horde"]="Sconfiggere Krom'zar e prendere il suo stendardo ferma una grande offensiva dei centauri. Le vie settentrionali tra Durotar, Mulgore e Crocevia sono sicure.",["race:Tauren"]="In quanto tauren, sai che l'aggressività dei centauri tormenta da tempo le tribù nomadi. L'avanguardia di Krom'zar è stata distrutta e i sentieri verso Mulgore sono più sicuri."},sec={{t="Trofeo dell'Incursione dei Centauri",b="Il Signore della Guerra Krom'zar guidò la sua banda da guerra verso est da Desolanda per contrattaccare. I capitribù Kolkar erano caduti in tutte le Savane, e i centauri infuriati attaccarono i bunker difensivi a ovest di Crocevia. Un lembo tagliato dallo stendardo abbattuto di Krom'zar dimostra a Regthar Deathgate che l'assalto è stato respinto e le rotte commerciali meridionali sono state preservate per l'Orda."}},faq={{q="A cosa serve questo pezzo di stendardo?",a="Porta la stoffa strappata a Regthar Deathgate, nel suo bunker a ovest di Crocevia. Dimostra che il Signore della Guerra Krom'zar è stato ucciso e la sua forza d'incursione annientata, concludendo la difesa delle Savane settentrionali.",al={"scopo dello stendardo","perché tenere lo stendardo","cosa fare con il pezzo di stendardo"}},{q="Chi era il Signore della Guerra Krom'zar?",a="Krom'zar era un comandante Kolkar proveniente da Desolanda. Dopo l'uccisione dei capi Kolkar locali, guidò un contrattacco diretto contro gli avamposti dell'Orda.",al={"chi è kromzar","storia di krom'zar","signore della guerra krom'zar"}},{q="Perché i Kolkar hanno attaccato il bunker?",a="Dopo la caduta di Barak, Verog, Hezrul e degli altri capitribù locali, i centauri infuriati radunarono rinforzi da Desolanda. Cercavano vendetta contro la presenza dell'Orda a ovest di Crocevia.",al={"perché il contrattacco","perché invasione kolkar","motivo del contrattacco nelle savane"}},{q="Thrall viene a sapere di questa vittoria?",a="Sì. Regthar Deathgate promette di inviare la notizia direttamente al Capoguerra Thrall a Orgrimmar. Elogerà i difensori che hanno respinto l'invasione.",al={"ricompensa di thrall","thrall lo sa"}}},fx={["92115071"]={q="Cos'è il Pezzo dello Stendardo di Krom'zar?",a="È un brandello strappato recuperato dallo stendardo da battaglia del Signore della Guerra Krom'zar, comandante dell'esercito di centauri Kolkar in cerca di vendetta che ha marciato da Desolanda verso The Barrens. Per le forze dell'Orda a difesa dei bunker occidentali, funge da innegabile prova fisica che il signore della guerra è caduto in battaglia e la sua invasione è stata spezzata.",al={"cos'è il pezzo dello stendardo di krom'zar","pezzo dello stendardo di krom'zar","cos'è il frammento di stendardo"}},caa193f6={q="Da dove proviene il Pezzo dello Stendardo di Krom'zar?",a="Lo stendardo è stato portato a The Barrens dal Signore della Guerra Krom'zar e dalla sua orda Kolkar, che hanno viaggiato fino dalla loro patria a Desolanda per vendicarsi sull'Orda. Quando Krom'zar scende in campo fuori dai bunker occidentali e cade in combattimento, il suo stendardo viene lasciato sul campo di battaglia, dove questo frammento può essere strappato via.",al={"da dove proviene lo stendardo di krom'zar","chi ha creato lo stendardo di krom'zar","origine dello stendardo di krom'zar"}},["7a980ed6"]={q="Perché Regthar Deathgate vuole un Pezzo dello Stendardo di Krom'zar?",a="Regthar Deathgate ha bisogno di una prova concreta che l'invasore esercito Kolkar sia stato decisamente schiacciato. Presentare questo stendardo strappato conferma che il Signore della Guerra Krom'zar è stato ucciso davanti ai bunker dell'Orda, permettendo a Regthar di dichiarare ufficialmente finita l'invasione e inviare notizia del tuo valore direttamente al Capoguerra Thrall.",al={"perché regthar vuole lo stendardo","perché portare lo stendardo di krom'zar a regthar","perché serve lo stendardo di krom'zar"}}},fp="26,163,31.357.0,35.193.0,25.140.0,37.197.0,33.139.0"}
P.entries["item:plainstrider-beak"] = {n="Becco di Zampalunga delle Pianure",s="In tutte le Savane, i cacciatori portano Becchi di Zampalunga delle Pianure a Crocevia come prova dell'abbattimento degli uccelli che minacciano le scorte.",h="In tutte le Savane, i cacciatori portano Becchi di Zampalunga delle Pianure a Crocevia come prova...",kw={"savane","crocevia","becco di zampalunga delle pianure","minaccia dei plainstrider","sergra darkthorn","tallstrider"},ang={["class:Hunter"]="Come cacciatore, bracchi gli zampalunga nelle pianure aperte di Kalimdor e raccogli i loro becchi, imparando ad assicurarti la preda.",["faction:Horde"]="Come membro dell'Orda, contribuisci a proteggere le rotte commerciali e di rifornimento che sostentano l'avamposto abbattendo gli stormi molesti a est di Crocevia."},sec={{t="Una misura della caccia",b="Gli zampalunga cercano cibo nei pressi di Crocevia e ne minacciano le scorte. Zampalunga maggiori, fugaci e irascibili vagano per la savana circostante. Sergra Darkthorn chiede ai cacciatori in arrivo di riportare i loro becchi, come prova che gli stormi sono stati allontanati dalle linee di rifornimento e dai magazzini."}},faq={{q="Perché Sergra Darkthorn vuole i Becchi di Zampalunga delle Pianure?",a="Sergra Darkthorn chiede ai cacciatori di abbattere gli zampalunga perché gli uccelli insidiano le scorte alimentari intorno a Crocevia. I loro becchi dimostrano che la minaccia alle scorte locali è stata ridotta.",al={"perché raccogliere becchi","sergra missione becco di zampalunga delle pianure","perché becchi"}},{q="Quali creature forniscono questi becchi?",a="I cacciatori ricavano i becchi dagli zampalunga maggiori, fugaci e irascibili che vagano per la savana delle Savane.",al={"cosa rilascia becco di zampalunga delle pianure","fonti becco di zampalunga delle pianure","dove trovare becchi"}},{q="Perché non tutti gli zampalunga forniscono un becco quando vengono uccisi?",a="Gli zampalunga, veloci e pronti a dibattersi, possono ritrovarsi con il becco incrinato, frantumato o inadatto come trofeo integro durante la lotta. I cacciatori raccolgono solo becchi intatti.",al={"perché percentuale di rilascio bassa","becco di zampalunga delle pianure non viene rilasciato"}}},fx={["7e2762f5"]={q="Cos'è il Becco di Zampalunga delle Pianure?",a="Un Becco di Zampalunga delle Pianure è il becco reciso preso dai volatili incapaci di volare che vagano per la savana di The Barrens. Duri e appuntiti, questi becchi vengono raccolti dai cacciatori come prova tangibile che gli uccelli fastidiosi che minacciavano le scorte locali sono stati abbattuti.",al={"oggetto becco di zampalunga delle pianure","cos'è il becco di zampalunga delle pianure","becchi di zampalunga delle pianure"}},["6978f6b2"]={q="Da dove proviene il Becco di Zampalunga delle Pianure?",a="Questi becchi provengono direttamente dalle varie razze di zampalunghe, come gli zampalunghe maggiori, fuggitivi e irascibili, nativi di The Barrens. Vengono raccolti dai cacciatori attraverso le pianure aride come trofei e prova di un abbattimento riuscito.",al={"dove ottenere il becco di zampalunga delle pianure","chi lascia il becco di zampalunga delle pianure","fonte del becco di zampalunga delle pianure"}}},fp="17,120,21.282.0,50.177.0,34.101.0,54.148.0"}
P.entries["item:plainstrider-feather"] = {n="Piuma di Zampalunga delle Pianure",s="Su Mesa Nuvola Rossa, i giovani cacciatori raccolgono Piume di Zampalunga delle Pianure dagli uccelli che vagano per le pianure di Mulgore. A Campo Narache, le piume vengono usate per confezionare abiti e ornamenti tribali, onorando le creature che provvedono al villaggio.",h="Su Mesa Nuvola Rossa, i giovani cacciatori raccolgono Piume di Zampalunga delle Pianure dagli uccelli che...",kw={"campo narache","piuma","grull vento agile","mulgore","zampalunga","mesa nuvola rossa","the hunt begins"},ang={["class:Hunter"]="Come cacciatore, seguire furtivamente i rapidi zampalunga su Mesa Nuvola Rossa mette alla prova la tua pazienza e abilità nel seguire le tracce, e ti insegna a onorare la preda.",["race:Tauren"]="Come giovane tauren, raccogliere le piume di uno zampalunga ti insegna ad apprezzare le creature dell'Earth Mother e a usare ogni parte della preda abbattuta per ricavarne cibo e indumenti."},sec={{t="La prima offerta di un cacciatore",b="I giovani tauren di Mesa Nuvola Rossa imparano a seguire le tracce e a cacciare per soddisfare i bisogni della tribù. Gli zampalunga vagano per l'altopiano erboso e forniscono cibo e piume utili. A Campo Narache, il loro piumaggio viene usato per confezionare indumenti ed equipaggiamento.\n\nI giovani cacciatori portano piume e carne fresca a Grull Vento Agile per rifornire il campo. Questa offerta è la loro prima prova. Il Capo Vento Agile li riconosce e li accoglie a Picco del Tuono."}},faq={{q="A cosa servono le Piume di Zampalunga delle Pianure?",a="A Campo Narache, le Piume di Zampalunga delle Pianure vengono usate per confezionare abiti e oggetti cerimoniali. Grull Vento Agile le raccoglie dai giovani cacciatori per rifornire la tribù.",al={"scopo delle piume","uso piuma di zampalunga delle pianure","perché raccogliere piume"}},{q="Chi raccoglie le Piume di Zampalunga delle Pianure su Mesa Nuvola Rossa?",a="Su richiesta di Grull Vento Agile, i giovani cacciatori raccolgono Piume di Zampalunga delle Pianure su Mesa Nuvola Rossa. Grull rifornisce le scorte di Campo Narache e mette alla prova la loro disciplina nel provvedere alla tribù.",al={"chi vuole le piume","chi ha bisogno di piume","piume grull vento agile"}},{q="Dove si possono trovare gli zampalunga?",a="Gli zampalunga vagano per le praterie aperte di Mesa Nuvola Rossa e le pianure ondulate di Mulgore.",al={"dove trovare gli zampalunga","posizione zampalunga","raccolta piume"}},{q="Perché Grull Vento Agile richiede queste piume per i riti tribali?",a="Nella cultura tauren, la caccia è fonte di sostentamento e uno sport. Portare carne e piumaggio al Capo Vento Agile dimostra che un giovane cacciatore sa sostentare la tribù prima di proseguire verso Picco del Tuono.",al={"the hunt begins storia","caccia di prova tauren","perché cacciare gli zampalunga"}}},fx={f2ff74a3={q="Cos'è una Piuma di Zampalunga delle Pianure?",a="Una Piuma di Zampalunga delle Pianure è un piumaggio raccolto dai grandi uccelli non volatori che vagano per le praterie di Mulgore. I tauren della Mesa Nuvola Rossa utilizzano ogni risorsa offerta dalla terra con profondo rispetto, e queste penne robuste e colorate servono come materiali pratici per fabbricare capi di vestiario quotidiani così come ornamenti tradizionali.",al={"cos'è la piuma di zampalunga delle pianure","informazioni sulla piuma di zampalunga delle pianure","piume di zampalunga delle pianure"}},["8bb68bd8"]={q="Da dove provengono le Piume di Zampalunga delle Pianure?",a="Queste piume sono piumaggio cresciuto naturalmente, raccolto direttamente dai zampalunga selvatici che vagano per la Mesa Nuvola Rossa e le vaste pianure di Mulgore. Non sono fabbricate da mani mortali, ma raccolte dai cacciatori dopo una battuta di caccia riuscita nella prateria.",al={"fonte piuma di zampalunga delle pianure","dove trovare piume di zampalunga delle pianure","chi ha creato la piuma di zampalunga delle pianure"}}},fp="20,225,25.400.0,40.153.0,52.186.0,33.85.0,64.179.0"}
P.entries["item:plainstrider-kidney"] = {n="Fegato di Zampalunga delle Pianure",s="Nelle Savane, i cacciatori raccolgono il Fegato di Zampalunga delle Pianure per le insolite tradizioni birrarie di Kalimdor. La maggior parte dei viaggiatori trova l'organo poco appetitoso, ma è essenziale per una birra esotica.",h="Nelle Savane, i cacciatori raccolgono il Fegato di Zampalunga delle Pianure per le insolite tradizioni...",kw={"mastro birraio drohn","chen birra triplo malto","plainstrider","fegato di zampalunga delle pianure","porto paranco","birra triplo malto","le savane"},ang={["class:Hunter"]="Come cacciatore, devi eviscerare con cura gli zampalunga nella savana per mantenere intatti gli organi interni da scambiare con i mastri birrai di Porto Paranco.",["profession:Cooking"]="Come cuoco, potresti esitare all'idea di far fermentare reni di uccello per ottenere liquori pregiati. Nelle terre selvagge di Kalimdor, sopravvivere significa spesso sfruttare ogni parte della preda."},sec={{t="Un insolito ingrediente di birrificazione",b="Alti zampalunga incapaci di volare vagano per le Savane, e i cacciatori ne ricavano piume e carne per utensili e semplici razioni. Il Mastro Birraio Drohn di Porto Paranco cerca i loro reni per un altro scopo: dice che servono a ricreare la leggendaria birra forte di Chen Birra Triplo Malto.\n\nDrohn dice che i reni conferiscono alla birra una grinta unica. La ricetta appartiene a una stirpe di mastri birrai fuori dagli schemi ed è stata tramandata negli anni."}},faq={{q="A cosa serve un Fegato di Zampalunga delle Pianure?",a="Il Mastro Birraio Drohn di Porto Paranco ha bisogno di reni di zampalunga per ricreare una leggendaria cotta di birra Birra Triplo Malto. Dice che il suo mentore apprese la ricetta da Chen Birra Triplo Malto, il mastro birraio pandaren errante.",al={"uso fegato di zampalunga delle pianure","perché servono i fegati di zampalunga delle pianure","scopo fegato di zampalunga delle pianure"}},{q="Perché qualcuno dovrebbe produrre birra con organi animali?",a="Le insolite birre di Kalimdor spesso impiegano parti della resistente fauna locale per ottenere sapori forti e una grinta inconfondibile. Il Mastro Birraio Drohn dice che preparare ricette forti e stravaganti gli ricorda creazioni poco ortodosse come la birra dei trogg.",al={"rene nella birra","perché i reni nella birra triplo malto","parti di animali nell'alcol"}},{q="Quali creature rilasciano questi fegati?",a="Questi reni si ricavano dagli zampalunga fugaci, irascibili e maggiori che vagano per le Savane.",al={"dove si trova il fegato di zampalunga delle pianure","chi rilascia il fegato di zampalunga delle pianure","fonte fegato di zampalunga delle pianure"}},{q="Quali altri ingredienti sono necessari oltre ai fegati?",a="Il Mastro Birraio Drohn chiede cinque reni di zampalunga, cinque zanne di leone della savana e un Corno di Sauro del Tuono per il suo intruglio.",al={"altri ingredienti della birra","cos'altro serve a drohn","ingredienti della birra triplo malto"}}},fx={d14d143c={q="Cos'è un Fegato di Zampalunga delle Pianure?",a="È un organo interno estratto dai grandi zampalunga non volatori che vagano per le savane delle The Barrens. Mentre la maggior parte dei cacciatori scarta tali interiora o le lascia agli spazzini, alcuni birrai eccentrici le apprezzano come aggiunte potenti e non convenzionali a liquori esotici.",al={"cos'è il fegato di zampalunga delle pianure","informazioni sul fegato di zampalunga delle pianure","parlami del fegato di zampalunga delle pianure"}},["4fd58422"]={q="Da dove proviene un Fegato di Zampalunga delle Pianure?",a="Questi organi vengono estratti direttamente dai zampalunga selvatici nativi delle The Barrens, incluse le varietà più grandi, scontrose e fugaci. Sono parti naturali dell'anatomia degli uccelli piuttosto che beni manifatturieri, sebbene procurarsene uno richieda di cacciare le veloci e aggressive bestie aviarie attraverso le pianure.",al={"fonte fegato di zampalunga delle pianure","dove trovare fegato di zampalunga delle pianure","origine fegato di zampalunga delle pianure"}},["53f4067b"]={q="Perché il Mastro Birraio Drohn vuole i Fegati di Zampalunga delle Pianure?",a="Il Mastro Birraio Drohn a Porto Paranco cerca questi fegati per ricreare la leggendaria e potente birra omonima di Chen Stormstout. Chen ha tramandato la ricetta non convenzionale al mentore di Drohn, e Drohn ha bisogno dei fegati insieme a zanne di leone e a un Corno di Sauro del Tuono per produrre la birra con il suo caratteristico, feroce vigore.",al={"perché sono necessari i fegati di zampalunga delle pianure","chi vuole i fegati di zampalunga delle pianure","scopo fegato di zampalunga delle pianure drohn"}}},fp="19,181,32.415.0,39.198.0,46.215.0,36.86.0,56.126.0"}
P.entries["item:plainstrider-meat"] = {n="Carne di Zampalunga delle Pianure",s="Sulla Mesa Nuvola Rossa, i giovani tauren raccolgono Carne di Zampalunga delle Pianure per nutrire Campo Narache. Cacciare questi uccelli per ricavarne cibo e piume dimostra la loro abilità e autosufficienza.",h="Sulla Mesa Nuvola Rossa, i giovani tauren raccolgono Carne di Zampalunga delle Pianure per nutrire Campo...",kw={"campo narache","capo vento agile","grull vento agile","mulgore","zampalunga","carne di zampalunga delle pianure","mesa nuvola rossa","the hunt begins"},ang={["class:Hunter"]="Come cacciatore, puoi mettere alla prova la tua abilità nel seguire le tracce e la tua mira contro i rapidi zampalunga nelle aperte pianure di Mulgore.",["race:Tauren"]="Se sei un giovane tauren sulla Mesa Nuvola Rossa, cacciare gli zampalunga è un primo passo per guadagnarti il rispetto di Capo Vento Agile e il diritto di entrare a Picco del Tuono."},sec={{t="Sostentamento per la Mesa",b="Campo Narache, sulla Mesa Nuvola Rossa, dipende dalla selvaggina delle praterie circostanti. Quando le scorte di cibo scarseggiano, la carne di zampalunga aiuta a sfamare il villaggio. Questi uccelli forniscono anche piume per abiti e ornamenti cerimoniali. I tauren dipendono dalla terra e prendono ciò di cui hanno bisogno rispettando la natura."},{t="La prova di un giovane cacciatore",b="Grull Vento Agile manda i giovani cacciatori sulla Mesa Nuvola Rossa a seguire le tracce dei rapidi zampalunga. Raccolgono carne e piume per dimostrare la loro abilità nel seguire le tracce e la loro autosufficienza. Poi si presentano al cospetto del padre di Grull, Capo Vento Agile."}},faq={{q="A cosa serve la Carne di Zampalunga delle Pianure?",a="I giovani cacciatori raccolgono Carne di Zampalunga delle Pianure sulla Mesa Nuvola Rossa per rifornire le scorte alimentari di Campo Narache per Grull Vento Agile.",al={"perché la carne di zampalunga delle pianure","missione carne di zampalunga delle pianure","cosa fare con la carne di zampalunga delle pianure"}},{q="Chi richiede questa carne?",a="Grull Vento Agile chiede ai giovani cacciatori di cacciare gli zampalunga e rifornire le scorte alimentari della tribù, dimostrandosi capaci di provvedere al suo sostentamento.",al={"chi vuole la carne di zampalunga delle pianure","grull vento agile carne"}},{q="Dove si può trovare la Carne di Zampalunga delle Pianure?",a="Gli zampalunga vagano per le praterie di Mulgore, compresa la Mesa Nuvola Rossa, dove i cacciatori ne raccolgono la carne.",al={"dove trovare la carne di zampalunga delle pianure","posizioni zampalunga","farmare carne di zampalunga delle pianure"}},{q="Perché la caccia agli zampalunga è considerata importante per i tauren?",a="I tauren cacciano gli zampalunga per nutrirsi e come disciplina spirituale. Portare selvaggina al campo dimostra rispetto per l'Earth Mother, autosufficienza e capacità di sostentare la tribù.",al={"cultura della caccia dei tauren","perché cacciare gli zampalunga"}}},fx={f404715e={q="Cos'è la Carne di Zampalunga delle Pianure?",a="La Carne di Zampalunga delle Pianure è selvaggina fresca ricavata dagli uccelli non volatori che vagano per le pianure di Mulgore. Per i tauren della Mesa Nuvola Rossa, funge da alimento base vitale, raccolto tramite le tradizionali battute di caccia che sostengono l'insediamento e onorano il legame tra cacciatore e preda.",al={"informazioni sulla carne di zampalunga delle pianure","cos'è la carne di zampalunga delle pianure","lore carne di zampalunga delle pianure"}},["00c8b7f8"]={q="Da dove proviene la Carne di Zampalunga delle Pianure?",a="La Carne di Zampalunga delle Pianure proviene dai zampalunga selvatici nativi di Mulgore. I giovani cacciatori la raccolgono direttamente dalle bestie che vagano per la Mesa Nuvola Rossa durante i loro primi riti di caccia per la tribù.",al={"da dove proviene la carne di zampalunga delle pianure","origine carne di zampalunga delle pianure","come ottenere carne di zampalunga delle pianure"}},f1043112={q="Perché la Carne di Zampalunga delle Pianure è richiesta a Campo Narache?",a="Le scorte di cibo di Campo Narache sono diminuite e la tribù conta su un'abile caccia per rifornire le proprie provviste. Grull Vento Agile chiede ai giovani cacciatori di raccogliere Carne di Zampalunga delle Pianure per sfamare il villaggio e dimostrare la loro abilità al Capo Vento Agile.",al={"perché serve carne di zampalunga delle pianure","scopo carne di zampalunga delle pianure","perché raccogliere carne di zampalunga delle pianure"}}},fp="17,165,23.293.0,22.221.0,35.116.0,23.135.0,37.99.0,64.176.0"}
P.entries["item:plainstrider-scale"] = {n="Scaglia di Zampalunga delle Pianure",s="A Mulgore, Maur Invoca Pioggia ha bisogno di una Scaglia di Zampalunga delle Pianure per un rimedio al Villaggio di Zoccolo Sanguinario. La scaglia resistente aiuta a contrastare un'infezione che si sta diffondendo.",h="A Mulgore, Maur Invoca Pioggia ha bisogno di una Scaglia di Zampalunga delle Pianure per un rimedio al...",kw={"villaggio di zoccolo sanguinario","maur invoca pioggia","mazzranache","mulgore","zampalunga delle pianure","rimedio","scaglia","tallstrider"},ang={["race:Tauren"]="Come Tauren, impari a raccogliere dalla terra ciò che serve per i rimedi e a usare la fauna delle pianure per sostentare la tua tribù."},sec={{t="Un ingrediente raro",b="Gli zampalunga delle pianure vagano per Mulgore con scaglie resistenti sulle zampe possenti. Le scaglie li proteggono, ma solo alcune sono abbastanza dure da essere macinate per preparare rimedi popolari."},{t="Un rimedio per un morso velenoso",b="Maur Invoca Pioggia, al Villaggio di Zoccolo Sanguinario, è stato morso alla spalla da Mazzranache, un leggendario zampalunga dagli occhi rossi demoniaci e dal morso velenoso. La ferita ha lasciato Maur in preda al delirio per la febbre. Per debellare l'infezione che si sta diffondendo prima che risulti fatale, gli servono una Scaglia di Zampalunga delle Pianure, un cuore di lupo, un femore di puma e uno stomaco di avvoltoio."}},faq={{q="A cosa serve la Scaglia di Zampalunga delle Pianure?",a="Maur Invoca Pioggia, al Villaggio di Zoccolo Sanguinario, ha bisogno di una Scaglia di Zampalunga delle Pianure per un rimedio. La combina con parti di altri predatori di Mulgore per curare la ferita infetta causata dal morso velenoso di Mazzranache.",al={"a cosa serve la scaglia di zampalunga delle pianure","uso scaglia di zampalunga delle pianure","perché serve la scaglia di zampalunga delle pianure"}},{q="Dove si trova una Scaglia di Zampalunga delle Pianure?",a="Trovi le Scaglie di Zampalunga delle Pianure sugli zampalunga selvatici che vagano per le praterie aperte di Mulgore.",al={"dove trovare la scaglia di zampalunga delle pianure","come ottenere la scaglia di zampalunga delle pianure","posizione scaglia di zampalunga delle pianure"}},{q="Perché Maur Invoca Pioggia è infetto?",a="Maur Invoca Pioggia è stato morso alla spalla da Mazzranache, uno zampalunga dagli occhi cremisi e dal morso velenoso. La ferita lo ha lasciato in preda al delirio e a una febbre sempre più alta.",al={"come si è ammalato maur","perché maur è malato","morso di mazzranache"}},{q="Di quali altri ingredienti ha bisogno Maur per il suo rimedio?",a="A Maur servono una Scaglia di Zampalunga delle Pianure, un Cuore di Lupo della Prateria, un Femore di Puma delle Pianure e uno Stomaco dell'Avvoltoio per il suo rimedio.",al={"ingredienti di maur invoca pioggia","cura per mazzranache","oggetti della missione di mazzranache"}}},fx={["95a4c3dd"]={q="Cos'è una Scaglia di Zampalunga delle Pianure?",a="È una scaglia resistente e specializzata raccolta dagli zampalunga che vagano per le praterie spazzate dal vento di Mulgore. Sebbene uccelli e zampalunga siano noti principalmente per il loro piumaggio e i becchi affilati, le loro zampe robuste e i piedi portano scaglie grossolane e indurite capaci di resistere alle pianure impervie. Sciamani ed erboristi apprezzano queste rare e dense scaglie per le loro proprietà protettive quando preparano impiastri e cure specializzate.",al={"cos'è la scaglia di zampalunga delle pianure","scaglia di zampalunga delle pianure","scaglie di zampalunga delle pianure"}},d7ded3c8={q="Da dove proviene una Scaglia di Zampalunga delle Pianure?",a="È una parte animale naturale presa direttamente dai zampalunga selvatici che vagano per Mulgore. Nessuno la fabbrica; i cacciatori la raccolgono dalle zampe degli zampalunga caduti attraverso le pianure, riunendo solo le scaglie più robuste per l'uso in preparazioni medicinali.",al={"fonte scaglia di zampalunga delle pianure","da dove proviene la scaglia di zampalunga delle pianure","chi ha creato la scaglia di zampalunga delle pianure"}}},fp="18,142,17.156.0,28.325.1,40.203.0,39.85.0,32.167.0,53.115.0"}
P.entries["item:plainstrider-talon"] = {n="Artiglio di Zampalunga delle Pianure",s="In tutta Mulgore, gli sciamani tauren raccolgono Artigli di Zampalunga delle Pianure per purificare i totem. Gli artigli affilati provengono dai grandi zampalunga delle pianure, uccelli incapaci di volare originari della regione, e aiutano a purificare l'acqua contaminata.",h="In tutta Mulgore, gli sciamani tauren raccolgono Artigli di Zampalunga delle Pianure per purificare i totem.",kw={"villaggio di zoccolo sanguinario","totem della purificazione","mulgore","mull corno tonante","zampalunga delle pianure","artiglio di zampalunga delle pianure","poison water","pozzo degli zoccolo artico"},ang={["class:Shaman"]="Come sciamano, puoi vedere come i rituali tauren usino parti del corpo delle bestie, come gli artigli, per creare totem purificatori e attingere al potere degli spiriti locali della terra.",["race:Tauren"]="Come tauren, onori la fauna di Mulgore attraverso la caccia. Ogni bestia abbattuta aiuta a guarire l'Earth Mother quando lo sfruttamento dei goblin la colpisce."},sec={{t="Legami delle Pianure",b="Grandi zampalunga delle pianure, incapaci di volare, vagano per le distese erbose di Mulgore. Le zampe potenti e gli artigli affilati li aiutano a cercare cibo nella dura terra della prateria e a difendersi dai predatori. Per i tauren del Villaggio di Zoccolo Sanguinario, ogni parte di una bestia cacciata ha un significato spirituale.\n\nQuando le attività dei goblin contaminarono fonti sacre come il Pozzo degli Zoccolo Artico, lo sciamano Mull Corno Tonante cercò artigli di zampalunga delle pianure e zampe di lupo della prateria. Nella creazione rituale dei tauren, le parti di predatori e animali in cerca di cibo locali incanalano l'essenza spirituale della terra in totem che eliminano i veleni innaturali."}},faq={{q="Quali creature rilasciano un Artiglio di Zampalunga delle Pianure?",a="Gli zampalunga delle pianure adulti, quelli anziani e il famigerato zampalunga Mazzranache forniscono Artigli di Zampalunga delle Pianure nelle distese erbose di Mulgore.",al={"chi rilascia l'artiglio di zampalunga delle pianure","dove trovare gli artigli di zampalunga delle pianure","fonte dell'artiglio di zampalunga delle pianure"}},{q="A cosa servono gli Artigli di Zampalunga delle Pianure?",a="Mull Corno Tonante, nel Villaggio di Zoccolo Sanguinario, ha bisogno di artigli di zampalunga delle pianure e zampe di lupo della prateria per creare un Totem della Purificazione. Lo usa per purificare il Pozzo degli Zoccolo Artico contaminato.",al={"uso dell'artiglio di zampalunga delle pianure","perché servono gli artigli","missione artiglio di zampalunga delle pianure"}},{q="Perché Mull Corno Tonante ha bisogno di parti di animali per purificare l'acqua?",a="Lo sciamanesimo tauren si fonda sull'armonia con gli spiriti naturali di Mulgore. Legare la fauna locale a un totem rituale richiama il potere primordiale della terra per combattere le sostanze inquinanti innaturali introdotte dai goblin della S.P.R. & Co.",al={"perché zampe e artigli di animali","artigli per il rituale di purificazione sciamanico"}},{q="Chi ha avvelenato i pozzi d'acqua a Mulgore?",a="Gli agenti della S.P.R. & Co. che operano a Mulgore, insieme ai loro scagnozzi, hanno contaminato i sacri pozzi tribali. Le loro azioni sconvolgono l'ambiente locale e minacciano le tribù tauren.",al={"chi ha corrotto i pozzi","chi ha avvelenato l'acqua di mulgore","colpevole di poison water"}}},fx={fdecb439={q="Cos'è un Artiglio di Zampalunga delle Pianure?",a="Un Artiglio di Zampalunga delle Pianure è l'artiglio affilato raccolto dai grandi zampalunga non volatori che vagano per Mulgore. Sebbene usato naturalmente da questi veloci uccelli per la difesa e per foraggiare attraverso le pianure, gli artigli portano anche un legame innato con il mondo naturale. Per i tauren, tali materiali rappresentano la forza della terra e possono essere canalizzati attraverso rituali sciamanici.",al={"cos'è l'artiglio di zampalunga delle pianure","lore artiglio di zampalunga delle pianure","artigli di zampalunga delle pianure"}},["07c33870"]={q="Da dove provengono gli Artigli di Zampalunga delle Pianure?",a="Questi artigli sono presi dai zampalunga maturi che vagano per le pianure aperte di Mulgore, a sud-ovest del Villaggio di Zoccolo Sanguinario. I cacciatori li raccolgono da zampalunga adulti e anziani, o anche da bestie rare come Mazzranache, come offerte della generosità della terra.",al={"fonte artiglio di zampalunga delle pianure","dove trovare artigli di zampalunga delle pianure","origine artiglio di zampalunga delle pianure"}},["826885d3"]={q="Perché Mull Corno Tonante vuole gli Artigli di Zampalunga delle Pianure?",a="Mull Corno Tonante nel Villaggio di Zoccolo Sanguinario ha bisogno di questi artigli per fabbricare un Totem della Purificazione per il Pozzo degli Zoccolo Artico. I goblin e i loro lacchè della S.P.R. & Co. hanno contaminato l'acqua sacra, e Mull deve invocare l'essenza primordiale delle bestie native di Mulgore per contrastare il veleno e ripristinare la purezza del pozzo.",al={"perché mull vuole gli artigli","perché serve l'artiglio di zampalunga delle pianure","scopo artiglio di zampalunga delle pianure"}}},fp="18,188,19.568.0,41.136.0,38.171.0,63.212.0,40.189.0"}
P.entries["item:podrig-s-order"] = {n="Podrig's Order",s="In Selva Pinargento, Podrig's Order chiede a Sepulcra armi per rifornire Mausolea.",h="In Selva Pinargento, Podrig's Order chiede a Sepulcra armi per rifornire Mausolea.",kw={"gordon wendham","hadrec","karos razok","podrig","podrig's order","mausolea","selva pinargento"},ang={["profession:Blacksmithing"]="Come fabbro, sai che le armi forgiate sono vitali in prima linea. I combattimenti consumano continuamente le scorte di una guarnigione.",["race:Undead"]="Come Undead, puoi vedere come Sepulcra rifornisce avamposti come Mausolea. Questo mantiene armati i soldati della Dark Lady contro il Flagello."},sec={{t="Armare Mausolea",b="La Guardiamorte Podrig trovò le scorte di Mausolea perlopiù adeguate dopo che Executor Hadrec ebbe ordinato un inventario. Eppure le armi di ricambio stavano disperatamente scarseggiando. Il suo dispaccio indica le lame e le armi necessarie alle Guardiemorte che presidiano l'avamposto nella Selva Pinargento. Il Flagello, le bestie feroci e altri pericoli minacciano la frontiera."},{t="Dispaccio tramite Maestro dei Pipistrelli",b="La richiesta è indirizzata a Gordon Wendham, un mercante d'armi nel Trade Quarter di Sepulcra. Le cripte umide della Selva Pinargento rendono difficile forgiare armi. I corrieri portano il documento al maestro dei pipistrelli Karos Razok, affinché le rotte aeree dei Reietti possano accelerare la spedizione dalla capitale."}},faq={{q="Cosa c'è scritto in Podrig's Order?",a="Podrig's Order elenca le armi di ricambio per le Guardiemorte di Mausolea. Le loro armi sono andate perdute o si sono rotte sul campo.",al={"cosa dice l'ordine","contenuto di podrig's order","dettagli di podrig's order"}},{q="Chi ha scritto Podrig's Order?",a="La Guardiamorte Podrig scrisse la richiesta su ordine di Executor Hadrec. Lo fece dopo un inventario dell'armeria di Mausolea.",al={"chi lo ha scritto","autore di podrig's order"}},{q="Chi riceve l'ordine?",a="Gordon Wendham, un mercante d'armi nel Trade Quarter di Sepulcra, è il destinatario della richiesta.",al={"chi riceve l'ordine","dove va podrig's order","destinatario di podrig's order"}},{q="Perché Mausolea ha bisogno di nuove armi?",a="Le schermaglie contro il Flagello e altre forze ostili nella Selva Pinargento lasciano spesso le Guardiemorte con l'equipaggiamento rotto o perduto. Hanno bisogno di armi di ricambio.",al={"perché servono armi","carenza di armi a mausolea"}}},fx={["92a3bbc0"]={q="Cos'è l'Ordine di Podrig?",a="L'Ordine di Podrig è un documento ufficiale di requisizione dei Reietti scritto per assicurare nuovi armamenti per l'avamposto alla Mausolea. Redatto da Podrig per conto dell'Esecutore Hadrec, il rotolo elenca le armi sostitutive necessarie alle Guardie della Morte della guarnigione per sopravvivere ai loro continui scontri contro il Flagello e altri terrori che si annidano nella Selva Pinargento.",al={"cos'è l'ordine di podrig","oggetto ordine di podrig","requisizione podrig"}},["6fc9fe58"]={q="Perché Gordon Wendham ha bisogno dell'Ordine di Podrig?",a="Come mercante di armi nel Trade Quarter di Undercity, Gordon Wendham necessita della requisizione formale per verificare ed evadere la richiesta di rifornimenti della guarnigione. Senza questo manifesto verificato, la Mausolea non può ricevere la necessaria spedizione di lame ed equipaggiamento per rifornire le sue Guardie della Morte in prima linea.",al={"perché gordon wendham vuole l'ordine","perché portare l'ordine di podrig a undercity","perché serve l'ordine di podrig"}}},fp="14,82,20.335.0,24.268.0,34.124.0,25.121.0,23.96.0,40.152.0"}
P.entries["item:pork-belly-pie"] = {n="Pasticcio di Carne di Cinghiale",s="Nella Foresta di Elwynn, Billy Maclure aspetta un pasticcio dalla Fattoria dei Pietradura prima di parlare di una collana scomparsa. Zia Bernice lo prepara nonostante la lunga faida tra le famiglie.",h="Nella Foresta di Elwynn, Billy Maclure aspetta un pasticcio dalla Fattoria dei Pietradura prima di parlare di...",kw={"zia bernice pietradura","ritorno da billy","billy maclure","foresta di elwynn","maclure","pasticcio di carne di cinghiale","pietradura"},ang={["faction:Alliance"]="Per i viaggiatori dell'Alleanza che prestano aiuto nelle campagne di Elwynn, consegnare pasticci rivela le liti radicate nel cuore agricolo di Roccavento.",["profession:Cooking"]="Il pasticcio fatto in casa di zia Bernice mantiene il suo potere anche nel pieno della faida tra le famiglie, sebbene la ricetta resti segreta."},sec={{t="Una tangente tra fattorie rivali",b="Le famiglie Stonefield e Maclure litigano da anni per la terra e per l'orgoglio. Il giovane Billy Maclure ha un debole per il Pasticcio di Carne di Cinghiale di zia Bernice. Quando scompare una preziosa collana della famiglia Stonefield, Billy si rifiuta di rivelare ciò che sa finché un avventuriero non gli porta una fetta calda. Bernice lo prepara con riluttanza, augurandosi che il ragazzo ingordo ci si strozzi."}},faq={{q="A cosa serve il Pasticcio di Carne di Cinghiale?",a="Zia Bernice Stonefield prepara il pasticcio per convincere il giovane Billy Maclure a parlare. Lui sa qualcosa della collana scomparsa della famiglia Stonefield, ma si rifiuta di parlare finché non ottiene qualcosa cucinato da lei.",al={"uso del pasticcio","perché pasticcio di carne di cinghiale","cosa faccio con il pasticcio"}},{q="Chi prepara il Pasticcio di Carne di Cinghiale?",a="Zia Bernice Stonefield prepara il pasticcio alla Fattoria dei Pietradura. Prova rancore verso Billy Maclure e la sua famiglia, ma lo prepara per aiutare a recuperare la collana perduta della propria famiglia.",al={"chi ha fatto il pasticcio","preparatore del pasticcio","pasticcio di nonna pietradura"}},{q="Perché Billy Maclure vuole il cibo di una famiglia rivale?",a="Billy Maclure vuole gustare la cucina di zia Bernice nonostante la faida tra gli Stonefield e i Maclure. Il desiderio di un Pasticcio di Carne di Cinghiale è più forte del rancore della sua famiglia.",al={"perché billy vuole il pasticcio","perché maclure vuole cibo dei pietradura"}},{q="I giocatori possono mangiare il Pasticcio di Carne di Cinghiale?",a="No. Il pasticcio è destinato a Billy Maclure e non può essere mangiato per ripristinare salute o mana.",al={"posso mangiarlo","il pasticcio di carne di cinghiale è commestibile"}}},fx={["6505ed9f"]={q="Cos'è il Pasticcio di Carne di Cinghiale?",a="È un saporito pasticcio di carne cotto con pancetta di cinghiale, rinomato per essere delizioso nonostante l'amara faida tra le due famiglie di contadini della Foresta di Elwynn meridionale. Appena preparato nella cucina dei Stonefield, serve come succulento tributo per estorcere informazioni al ragazzo Maclure, Billy, che sostiene che la sua memoria funzioni solo a stomaco pieno.",al={"cos'è il pasticcio di carne di cinghiale","lore pasticcio di carne di cinghiale","a proposito del pasticcio di carne di cinghiale"}}},fp="14,167,29.366.0,36.188.0,29.161.0,53.181.0,35.85.0"}
P.entries["item:powdered-azurite"] = {n="Azurite Polverosa",s="Nelle Alture di Colletorto, i lavoratori macinano la pietra blu della Miniera di Venazzurra per ottenere Azurite Polverosa. Thun'grim Firegaze ne ha bisogno per forgiare armature brutali per i guerrieri emergenti dell'Orda.",h="Nelle Alture di Colletorto, i lavoratori macinano la pietra blu della Miniera di Venazzurra per ottenere...",kw={"miniera di venazzurra","azurite","brutal armor","colletorto","azurite polverosa","reagente","thun'grim firegaze"},ang={["class:Warrior"]="Come guerriero, metti alla prova la tua resistenza in terre lontane mentre raccogli Azurite Polverosa per Thun'grim Firegaze. Gli serve questo reagente per forgiare la tua armatura dalla forza selvaggia.",["faction:Horde"]="Come membro dell'Orda, devi addentrarti nei Regni Orientali e sottrarre la polvere raffinata dalle mani dell'Alleanza nelle Alture di Colletorto."},sec={{t="Un raro composto minerale",b="I lavoratori umani estraggono pietra blu dalle vene minerarie sotto le Alture di Colletorto. La macinano e la confezionano per il commercio e la lavorazione dei metalli. Un abile fabbro mescola la polvere con metalli densi, rendendo le armature più durevoli e resistenti."},{t="Forgiare la Brutal Armor",b="I fabbri dell'Orda apprezzano l'Azurite Polverosa per la robustezza che conferisce ai metalli, sebbene provenga da gallerie controllate dagli umani oltre il Grande Mare. Thun'grim Firegaze è un anziano armaiolo orco delle Savane. Ne richiede piccole quantità insieme a ferro raffinato e reagenti infuocati. Mescolata al metallo fuso, la polvere lo aiuta a forgiare le pesanti piastre della sua Brutal Armor."}},faq={{q="A cosa serve l'Azurite Polverosa?",a="Thun'grim Firegaze mescola Azurite Polverosa con lingotti di ferro e reagenti volatili per forgiare pezzi di Brutal Armor per i campioni dell'Orda.",al={"uso di azurite polverosa","cos'è l'azurite polverosa"}},{q="Dove si trova l'Azurite Polverosa?",a="I minatori umani raccolgono Azurite Polverosa nella Miniera di Venazzurra, lungo la costa meridionale delle Alture di Colletorto, nei Regni Orientali.",al={"dove trovare l'azurite polverosa","posizione di azurite polverosa","chi rilascia azurite polverosa"}},{q="Perché un armaiolo delle Savane ha bisogno di reagenti provenienti da Colletorto?",a="Thun'grim Firegaze cerca materiali pregiati per armature degne di guerrieri leggendari. Il ferro è facile da trovare, ma il minerale di Azurelode tempra il metallo, quindi manda i suoi campioni oltre il mare a procurarselo.",al={"perché colletorto","fonte del minerale di thungrim"}}},fx={["139f7c50"]={q="Cos'è l'Azurite Polverosa?",a="L'Azurite Polverosa è un reagente minerale blu frantumato estratto da vene profonde nelle Alture di Colletorto. Riverito dai maestri armaioli per le sue proprietà metallurgiche uniche, la polvere fine può essere legata o temprata in metalli di base durante la forgiatura. È particolarmente apprezzata dall'armaiolo dell'Orda Thun'grim Firegaze, che la usa insieme a reagenti esotici per fabbricare armature a maglia pesanti e resilienti degne di rinomati guerrieri.",al={"cos'è l'azurite polverosa","lore azurite polverosa","oggetto azurite polverosa"}},["720f3d61"]={q="Da dove proviene l'Azurite Polverosa e chi l'ha estratta?",a="La sostanza viene estratta dalla Miniera di Venazzurra annidata lungo le colline meridionali delle Alture di Colletorto. I minatori umani che lavorano nei pozzi sotterranei di Venazzurra dissotterrano il grezzo minerale di azurite e lo macinano riducendolo in una polvere raffinata. Poiché la miniera rimane sotto il saldo controllo dei lavoratori umani di Colletorto, ottenere la polvere richiede di prenderla direttamente dai minatori che lavorano sotto terra.",al={"dove trovare azurite polverosa","chi estrae l'azurite polverosa","fonte azurite polverosa"}}},fp="16,168,23.218.0,20.366.0,34.133.0,36.128.0,67.193.0"}
P.entries["item:powers-of-the-void"] = {n="Poteri del Vuoto",s="Nella Contea del Nord, un tomo rubato attira l'attenzione di Drusilla La Salle. Un novizio ha sottratto Poteri del Vuoto da un'ala sorvegliata della biblioteca dell'Abbazia della Contea del Nord mentre partiva per unirsi alla Fratellanza dei Defias. Drusilla cerca il libro per i propri studi sulla magia oscura.",h="Nella Contea del Nord, un tomo rubato attira l'attenzione di Drusilla La Salle.",kw={"fratellanza dei defias","drusilla la salle","demonietto","khadgar","abbazia della contea del nord","poteri del vuoto","libri rubati","the stolen tome","negromante"},ang={["class:Warlock"]="Come stregone, recuperare il tomo rubato mette alla prova la tua determinazione a meritarti gli insegnamenti per evocare un Imp.",["race:Human"]="Come umano, puoi vedere che l'Holy Order della Contea del Nord custodisce pericolosi documenti magici accanto ai testi ecclesiastici, nascosti agli occhi dei novizi."},sec={{t="Un testo riservato della Contea del Nord",b="Poteri del Vuoto era custodito dietro scaffali sorvegliati nella biblioteca dell'Abbazia della Contea del Nord. Gli archivi dell'abbazia conservano sacre scritture e documenti ecclesiastici, oltre a opere accademiche sulle energie dell'ombra e del potere fatuo. Si ritiene che l'arcimago Khadgar abbia scritto il tomo. Il suo argomento era pericoloso, così le autorità dell'abbazia lo tenevano sotto sorveglianza e lontano dai visitatori occasionali. Questo impediva a Drusilla La Salle, l'istruttrice degli stregoni della Contea del Nord, di consultarlo senza destare i sospetti del clero."},{t="Furto dei Defias e recupero",b="Un novizio della Contea del Nord portò via il tomo quando abbandonò i suoi voti per unirsi alla Fratellanza dei Defias. Mentre fuggiva nelle vigne vicine, sottrasse diversi volumi di valore dall'abbazia. Drusilla invia i più promettenti iniziati stregoni all'accampamento dei banditi Defias per recuperare il libro dalle loro tende. Vuole le sue conoscenze oscure per i propri studi. L'impresa mette alla prova il coraggio di un iniziato nel vincolare demoni ultraterreni."}},faq={{q="Che cos'è Poteri del Vuoto?",a="Poteri del Vuoto è un raro libro occulto sulle energie dell'ombra e del potere fatuo, che si ritiene scritto dall'arcimago Khadgar. Prima del furto, il tomo era custodito in un'ala sorvegliata della biblioteca dell'Abbazia della Contea del Nord.",al={"cos'è poteri del vuoto","libro poteri del vuoto","cos'è the stolen tome"}},{q="Perché il libro era rinchiuso nell'Abbazia della Contea del Nord?",a="L'Abbazia della Contea del Nord custodisce archivi storici, compresi testi pericolosi sulla magia proibita. I libri sulle energie del Vuoto e sulla demonologia sono tenuti sotto chiave, affinché novizi e praticanti sregolati non possano abusarne.",al={"perché si trovava nell'abbazia","perché i sacerdoti lo avevano","ala della biblioteca della contea del nord"}},{q="Come ha ottenuto il libro la Fratellanza dei Defias?",a="Un novizio dell'Abbazia della Contea del Nord disertò per unirsi alla Fratellanza dei Defias e sottrasse diversi volumi di valore dalla biblioteca riservata. Li nascose nell'accampamento dei banditi nelle vigne della Contea del Nord.",al={"chi ha rubato il libro","libri rubati defias","come l'hanno ottenuto i defias"}},{q="Perché Drusilla La Salle vuole Poteri del Vuoto?",a="Drusilla La Salle vuole le conoscenze del tomo per le proprie arti oscure. In quanto istruttrice degli stregoni della Contea del Nord, non poteva entrare nella biblioteca sorvegliata dell'abbazia senza destare sospetti.",al={"perché drusilla lo vuole","chi vuole il libro","drusilla la salle the stolen tome"}},{q="Cosa dimostra a Drusilla il recupero del tomo?",a="Recuperare il tomo mette alla prova il coraggio di un iniziato nel vincolare demoni. Drusilla ricorre a questa prova prima di insegnargli a evocare il suo primo Imp.",al={"perché i negromanti hanno bisogno del libro","prova di evocazione del demonietto","ricompensa the stolen tome"}}},fx={["082e56cb"]={q="Chi ha scritto Poteri del Vuoto?",a="Si ritiene che il trattato arcano sia stato redatto dal leggendario arcimago Khadgar, che studiò molti aspetti profondi e pericolosi della magia prima di avventurarsi oltre il Portale Oscuro. Le sue intuizioni proibite sul vuoto profondo furono considerate troppo pericolose per una lettura casuale, spingendo i sacerdoti e gli studiosi dell'Abbazia della Contea del Nord a sigillarlo all'interno di un'ala protetta della loro biblioteca finché un novizio traditore non lo rubò.",al={"autore di poteri del vuoto","chi ha creato poteri del vuoto","creatore di poteri del vuoto"}}},fp="18,251,28.476.0,25.427.0,27.217.0,47.198.0,44.183.0,51.175.0,48.147.0"}
P.entries["item:prairie-alpha-tooth"] = {n="Dente di Lupo Alfa",s="Vicino a Picco del Tuono, i lupi alfa della prateria vagano per le pianure aperte di Mulgore. Mull Corno Tonante ha bisogno dei loro denti per purificare il Pozzo di Wildmane.",h="Vicino a Picco del Tuono, i lupi alfa della prateria vagano per le pianure aperte di Mulgore.",kw={"villaggio di zoccolo sanguinario","mulgore","mull corno tonante","dente di lupo alfa","lupo alfa della prateria","pozzo d'acqua","wildmane totem"},ang={["class:Shaman"]="Come sciamano, plachi gli spiriti dei pozzi ripristinando l'equilibrio terreno. Offrire le zanne di un predatore al vertice della catena alimentare consolida quell'armonia naturale.",["race:Tauren"]="Come tauren, prelevare una zanna di lupo alfa della prateria onora il tuo sacro dovere di cacciatore. Raccogli ciò che serve con rispetto, poi restituisci quell'essenza primordiale per guarire la terra avvelenata."},sec={{t="Un'offerta purificatrice",b="I pozzi di Mulgore sostentano i tauren, e i riti di rispetto e sacrificio li mantengono puri. Mull Corno Tonante del Villaggio di Zoccolo Sanguinario ha bisogno dei denti dei lupi alfa della prateria ai piedi di Picco del Tuono per purificare il Pozzo di Wildmane. Questi feroci capibranco incarnano la forza della natura selvaggia. I loro denti onorano l'equilibrio tra cacciatore, preda e spiriti della terra."}},faq={{q="A cosa serve un Dente di Lupo Alfa?",a="Mull Corno Tonante usa otto denti di lupo alfa della prateria in un rituale per purificare il Pozzo di Wildmane. È l'ultimo pozzo contaminato vicino al Villaggio di Zoccolo Sanguinario.",al={"scopo dente alfa","a cosa servono i denti di lupo mulgore","oggetto wildmane totem"}},{q="Dove si aggirano i lupi alfa della prateria?",a="I lupi alfa della prateria vagano per le pianure erbose aperte di Mulgore, soprattutto nelle zone centrali e settentrionali, vicino alle rupi alla base di Picco del Tuono.",al={"dove trovare i lupi alfa della prateria","posizioni lupo alfa","punti lupo alfa della prateria"}},{q="Perché un rituale di purificazione dell'acqua richiede denti di lupo?",a="I riti dei tauren onorano l'equilibrio della natura. La purificazione richiede parti sacre delle feroci bestie native di Mulgore, simboli di sacrificio e della vitalità della sua fauna.",al={"perché denti di lupo per acqua","storia del rituale del dente di mull corno tonante"}}},fx={f1f3b80c={q="Cos'è un Dente di Lupo Alfa?",a="Un Dente di Lupo Alfa è un dente preso da un lupo alfa della prateria, uno dei più feroci capibranco che si aggirano per le pianure di Mulgore. Tra i tauren, queste zanne rappresentano la forza e lo spirito dei predatori alfa della terra, portando un peso spirituale quando offerte in rituale.",al={"dente di lupo alfa","cos'è il dente di lupo alfa"}},["0674aadd"]={q="Da dove proviene un Dente di Lupo Alfa?",a="Questi denti vengono raccolti dai lupi alfa della prateria che vagano per le praterie di Mulgore, in particolare vicino alla base di Picco del Tuono a nord. Essendo zanne naturali di predatori viventi, vengono prelevate direttamente dalle bestie durante la caccia anziché essere fabbricate da mani mortali.",al={"da dove provengono i denti di lupo alfa","origine dente di lupo alfa","chi lascia cadere il dente di lupo alfa"}}},fp="19,134,20.357.0,39.147.0,34.146.0,53.169.0"}
P.entries["item:prairie-wolf-heart"] = {n="Cuore di Lupo della Prateria",s="Maur Invoca Pioggia, al Villaggio di Zoccolo Sanguinario, ha bisogno di un Cuore di Lupo della Prateria per curare un morso velenoso.",h="Maur Invoca Pioggia, al Villaggio di Zoccolo Sanguinario, ha bisogno di un Cuore di Lupo della Prateria per...",kw={"villaggio di zoccolo sanguinario","maur invoca pioggia","mazzranache","mulgore","predatore della prateria","cuore di lupo della prateria","cuore di lupo"},ang={["class:Hunter"]="Come cacciatore, impari a seguire le tracce dei branchi di lupi che cacciano nelle pianure di Mulgore e a conoscere le bestie che vi abitano.",["race:Tauren"]="Come tauren, sai che le parti animali possono contribuire a preparare rimedi pratici per sopravvivere nelle terre selvagge di Mulgore."},sec={{t="Un rimedio per un morso velenoso",b="Maur Invoca Pioggia vive al Villaggio di Zoccolo Sanguinario, dove il veleno di Mazzranache, il leggendario zampalunga, gli ha causato la febbre. Il morso minaccia di diffondere il veleno nel suo corpo. Maur cerca un cuore di lupo della prateria, un osso di puma e uno stomaco di volatile per un rimedio tradizionale delle pianure. Spera di fermare l'infezione prima che il delirio si riveli fatale."}},faq={{q="A cosa serve un Cuore di Lupo della Prateria?",a="Maur Invoca Pioggia, al Villaggio di Zoccolo Sanguinario, ha bisogno di un Cuore di Lupo della Prateria per un rimedio popolare. Lo combina con altre parti animali per curare il morso velenoso inflittogli da Mazzranache.",al={"uso del cuore di lupo","perché procurarsi il cuore di lupo","scopo del cuore di lupo della prateria"}},{q="Dove si ottiene un Cuore di Lupo della Prateria?",a="Lupi della prateria, lupi alfa della prateria e predatori della prateria cacciano nelle pianure di Mulgore. Dai loro corpi si ricava il cuore.",al={"posizione del cuore di lupo","chi rilascia il cuore di lupo","come trovare il cuore di lupo della prateria"}},{q="Perché Maur Invoca Pioggia ha bisogno di organi animali per curare la sua ferita?",a="Il morso infetto di Mazzranache provoca febbre e delirio. Maur si affida ai rimedi dei tauren delle pianure, preparati con un cuore di lupo, un femore di puma, una Scaglia di Zampalunga delle Pianure e uno Stomaco dell'Avvoltoio, per debellare l'infezione prima che si riveli letale.",al={"perché il cuore di lupo per la medicina","rimedio di maur"}},{q="Si può usare qualsiasi cuore di lupo per il rimedio?",a="Maur chiede un cuore di lupo. Il cuore per il suo rimedio si ricava dai lupi della prateria, dai lupi alfa della prateria o dai predatori della prateria nelle pianure di Mulgore.",al={"qualsiasi cuore di lupo","quali lupi lo rilasciano"}}},fx={ee1c9772={q="Cos'è un Cuore di Lupo della Prateria?",a="Un Cuore di Lupo della Prateria è l'organo raccolto dai lupi predatori che si aggirano nella Piana Ondulata di Mulgore. Sebbene abbia poco valore commerciale comune, la vitalità del cuore di una bestia selvatica lo rende un ingrediente pregiato nella medicina tradizionale tauren. Serve come uno dei numerosi e potenti reagenti necessari per preparare rimedi in grado di purificare veleni naturali virulenti e infezioni profonde.",al={"cos'è il cuore di lupo della prateria","cuore di lupo della prateria","informazioni cuore di lupo della prateria"}},["1392571f"]={q="Da dove proviene un Cuore di Lupo della Prateria?",a="Il cuore viene preso direttamente dai lupi della prateria selvatici, dai lupi alfa della prateria e dagli inseguitori della prateria nativi degli altipiani erbosi di Mulgore. È un organo biologico naturale raccolto da un predatore ucciso piuttosto che un oggetto fabbricato da mani mortali.",al={"da dove proviene il cuore di lupo della prateria","origine cuore di lupo della prateria","chi ha creato il cuore di lupo della prateria"}}},fp="18,89,28.330.0,38.170.0,43.121.0,63.220.0,42.143.0"}
P.entries["item:prairie-wolf-paw"] = {n="Zampa di Lupo della Prateria",s="In tutta Mulgore, i lupi della prateria cacciano nelle pianure e le loro zampe vengono raccolte per l'opera di uno sciamano. Al Villaggio di Zoccolo Sanguinario, Mull Corno Tonante le unisce agli artigli di zampalesta per creare un Totem della Purificazione.",h="In tutta Mulgore, i lupi della prateria cacciano nelle pianure e le loro zampe vengono raccolte per l'opera...",kw={"villaggio di zoccolo sanguinario","mulgore","mull corno tonante","artiglio di zampalunga delle pianure","poison water","lupo della prateria","zampa di lupo della prateria","pozzo degli zoccolo artico"},ang={["class:Shaman"]="Come sciamano, usi i Totem della Purificazione creati con parti di animali locali per attingere all'essenza vivente della terra ed eliminare la corruzione innaturale.",["race:Tauren"]="Come tauren, raccogli zampe di lupo per prenderti cura della terra. Le sue bestie native aiutano a risanare i pozzi ancestrali contaminati dall'avidità dei goblin."},sec={{t="Reagenti Naturali delle Pianure",b="I lupi della prateria cacciano in branco tra le distese d'erba di Mulgore, insieme ai cacciatori delle praterie e ai loro capobranco. Minacciano i giovani cacciatori e il bestiame locale. Gli sciamani tauren considerano le zampe più che semplici trofei, poiché racchiudono la vitalità naturale della terra e contribuiscono all'equilibrio spirituale delle pianure."},{t="Purificare i Pozzi",b="Quando le attività dei goblin contaminarono le sacre riserve d'acqua di Mulgore, lo sciamano Mull Corno Tonante ebbe bisogno dell'aiuto della terra contro l'inquinamento. Unite agli artigli di zampalesta, le zampe di lupo conferiscono risonanza spirituale ai Totem della Purificazione. Una volta creato il totem, può iniziare l'opera di purificazione del Pozzo degli Zoccolo Artico."}},faq={{q="Quali creature rilasciano una Zampa di Lupo della Prateria?",a="I lupi della prateria, i cacciatori delle praterie e i lupi capobranco della prateria cacciano nelle pianure di Mulgore, soprattutto a sudovest del Villaggio di Zoccolo Sanguinario, e forniscono Zampe di Lupo della Prateria.",al={"chi rilascia zampa di lupo della prateria","dove trovare zampe di lupo della prateria","fonte zampa di lupo della prateria"}},{q="Chi richiede le Zampe di Lupo della Prateria?",a="Mull Corno Tonante, uno sciamano tauren del Villaggio di Zoccolo Sanguinario, vuole le zampe per contribuire a creare un Totem della Purificazione per i pozzi contaminati.",al={"chi ha bisogno di zampe di lupo della prateria","mull corno tonante zampe di lupo","consegna zampa di lupo della prateria"}},{q="Perché sono necessarie le zampe di lupo per purificare l'acqua?",a="Gli sciamani tauren invocano la vitalità naturale della terra contro la corruzione. Unite agli artigli degli uccelli, le zampe di lupo vincolano lo spirito vivente di Mulgore a un totem elementale capace di eliminare i veleni dei goblin.",al={"perché zampe di lupo","storia zampa di lupo della prateria","perché mull vuole le zampe"}},{q="Quale pozzo d'acqua aiutano a purificare queste zampe?",a="Le zampe contribuiscono a creare un Totem della Purificazione per il Pozzo degli Zoccolo Artico, avvelenato dagli intrusi goblin e dai loro agenti.",al={"quale pozzo","purificazione pozzo degli zoccolo artico"}}},fx={["94c15e4c"]={q="Cos'è una Zampa di Lupo della Prateria?",a="Una Zampa di Lupo della Prateria è un componente rituale naturale raccolto dai canidi selvatici che vagano per le pianure di Mulgore. Piuttosto che servire come semplici trofei, queste zampe portano l'essenza vivente della terra, rendendole preziose per gli sciamani tauren che fabbricano totem per guarire e preservare la terra.",al={"zampa di lupo della prateria","cosa sono le zampe di lupo della prateria","zampa di lupo mulgore"}},["7a637be5"]={q="Da dove provengono le Zampe di Lupo della Prateria?",a="Queste zampe vengono raccolte direttamente dai lupi della prateria, dagli inseguitori della prateria e dai lupi alfa nativi degli altipiani erbosi di Mulgore. Sono parti naturali della natura selvaggia, prese dai cacciatori per offrire la forza della terra nei momenti di bisogno spirituale.",al={"da dove provengono le zampe di lupo della prateria","fonte zampe di lupo della prateria","chi lascia cadere le zampe di lupo"}}},fp="16,198,30.301.0,19.306.0,39.155.0,28.130.0,42.193.0,44.116.0"}
P.entries["item:pridewing-venom-sac"] = {n="Sacca di Veleno di Viverna",s="Attorno al Lago Mirkfallon, il veleno dei pridewings attira l'attenzione degli Elfi della Notte di Astranaar. Secondo alcuni rapporti, gli agenti dell'Orda lo raccolgono per attacchi clandestini, e le Sentinelle cercano di sottrarre loro quel veleno.",h="Attorno al Lago Mirkfallon, il veleno dei pridewings attira l'attenzione degli Elfi della Notte di Astranaar.",kw={"astranaar","lago mirkfallon","pridewing","shindrell fuocolesto","vette di petrartiglio","sacca di veleno","viverna"},ang={["faction:Alliance"]="Sottrarre agli agenti dell'Orda il veleno dei pridewings aiuta a proteggere le pattuglie di frontiera dagli assassini nascosti lungo i confini contesi delle Vette di Petrartiglio e di Valtetra.",["race:NightElf"]="Come Elfo della Notte, potresti rammaricarti che si debbano cacciare bestie selvatiche innocenti. Tuttavia, proteggere le vite degli elfi dalle lame avvelenate ha la precedenza."},sec={{t="Una minaccia tra i picchi",b="I pridewings cacciano tra le rupi a sud di Valtetra, soprattutto vicino al Lago Mirkfallon. Pur essendo originari delle Vette di Petrartiglio, questi predatori alati si spingono fin qui, e il loro veleno si trova in ghiandole all'interno del corpo. I rapporti da Theramore indicano che gli assassini dell'Orda usano il veleno per cospargere le lame destinate ad attacchi segreti contro gli insediamenti degli Elfi della Notte. Per questo le Sentinelle di Astranaar inviano esploratori a cacciare le viverne e raccoglierne le ghiandole prima che gli agenti dell'Orda se ne impossessino."}},faq={{q="Quali creature rilasciano una Sacca di Veleno di Viverna?",a="Le sacche di veleno si ricavano dai giovani pridewings, dagli skyhunters, dai patriarchs e dai consorts vicino al Lago Mirkfallon.",al={"dove trovare la sacca di veleno di viverna","chi rilascia la sacca di veleno di viverna","fonti di veleno di pridewing"}},{q="Perché Astranaar vuole le Sacche di Veleno di Viverna?",a="Shindrell Fuocolesto ha ricevuto rapporti secondo cui gli agenti dell'Orda applicano il veleno dei pridewings alle armi per attacchi silenziosi contro l'Alleanza. Sottrarre o distruggere le ghiandole può impedire quegli attacchi.",al={"perché raccogliere le sacche di veleno","shindrell fuocolesto veleno"}},{q="Chi accetta queste sacche di veleno a Valtetra?",a="Ad Astranaar, la cittadina degli Elfi della Notte a Valtetra, Shindrell Fuocolesto raccoglie le sacche di veleno per proteggere la sua gente dagli attacchi clandestini.",al={"chi accetta il veleno di pridewing","consegna missione pridewing"}},{q="I pridewings sono alleati dell'Orda per natura?",a="No. I pridewings vicino al Lago Mirkfallon sono bestie selvatiche, non alleati consenzienti dell'Orda. Gli agenti orcheschi ne sfruttano il veleno per la guerra.",al={"i pridewings sono dell'orda","i pridewing lavorano per gli orchi"}}},fx={e2bba8d5={q="Cos'è una Sacca di Veleno di Viverna?",a="Una Sacca di Veleno di Viverna è un organo raccolto dalle viverne pridewing che nidificano nelle Vette di Petrartiglio. Contiene le potenti tossine naturali che questi predatori alati producono per soggiogare le loro prede. Nel fragile stallo tra gli elfi della notte e l'Orda, tale veleno è diventato un'arma pregiata per attacchi furtivi, spingendo i difensori di Astranaar a prestare attenzione.",al={"cos'è la sacca di veleno di viverna","oggetto sacca di veleno di viverna","cosa sono le sacche di veleno di viverna"}},["816b56c2"]={q="Da dove proviene una Sacca di Veleno di Viverna?",a="Queste sacche vengono raccolte direttamente dai corpi delle pridewing, feroci viverne selvatiche che si appollaiano vicino al Lago Mirkfallon nelle Vette di Petrartiglio. Poiché sono organi corporei naturali prodotti dalle bestie stesse anziché beni manufatti, ottenerle richiede di cacciare le viverne tra le rocce e assicurarsi il veleno prima che gli agenti dell'Orda possano raccoglierlo.",al={"fonte sacca di veleno di viverna","da dove provengono le sacche di veleno di viverna","chi lascia cadere la sacca di veleno di viverna"}}},fp="19,193,21.446.0,43.97.0,45.181.0,42.133.0,51.133.0"}
P.entries["item:prismatic-punch-card"] = {n="Scheda Perforata Prismatica",s="A Gnomeregan, la Scheda Perforata Prismatica ha il livello di accesso più alto. I profughi gnomi a Forgiardente cercano i documenti che permette di consultare.",h="A Gnomeregan, la Scheda Perforata Prismatica ha il livello di accesso più alto.",kw={"tuboduro","data rescue","engineering labs","gnomeregan","matrix punchograph","scheda perforata prismatica"},ang={["profession:Engineering"]="Come ingegnere, puoi vedere nella programmazione sequenziale delle schede perforate e nella rete automatizzata di terminali esempi dell'elevata qualità dei macchinari di calcolo costruiti dagli inventori di Gnomeregan.",["race:Gnome"]="Come gnomo, puoi vedere nel sistema di sicurezza Punchograph l'ingegno e la burocrazia gnomici ancora all'opera dopo la caduta della tua patria."},sec={{t="Una questione di sicurezza",b="Quando gli gnomi fuggirono da Gnomeregan, furono i trogg e le radiazioni tossiche a scacciarli dalla città. Enormi quantità di ricerche e documenti civici rimasero nelle sue profondità. Gli gnomi proteggevano i sistemi di alto livello con diversi livelli di autorizzazione. Per raggiungere il Matrix Punchograph 3005-D nei livelli inferiori degli Engineering Labs, una scheda deve passare attraverso una serie di terminali.\n\nLa scheda parte bianca, poi passa al giallo, al blu e al rosso. Al terminale finale, viene perforata e diventa Prismatica. Il suo livello di accesso codificato è indicato come in attesa dell'invenzione di un numero del tutto nuovo."},{t="La trasmissione vitale",b="Il Maestro Meccanico Tuboduro invia avventurieri dalle enclave dei profughi di Forgiardente nelle sale contaminate di Gnomeregan per recuperare dati che definisce vitali e indispensabili. Il messaggio binario sulla Scheda Perforata Prismatica rivela il contenuto della trasmissione: Tuboduro viene informato che il suo bucato è pronto per il ritiro."}},faq={{q="Come si crea una Scheda Perforata Prismatica?",a="Inserisci una Scheda Perforata Rossa nel Matrix Punchograph 3005-D nei livelli inferiori degli Engineering Labs di Gnomeregan. Prima, potenzia una Scheda Perforata Bianca passando in sequenza dai terminali modello A, B e C sparsi nel complesso.",al={"come ottenere la scheda perforata prismatica","creare la scheda perforata prismatica","sequenza di potenziamento delle schede perforate"}},{q="Quali dati sono memorizzati sulla Scheda Perforata Prismatica?",a="La scheda indica che il suo livello di sicurezza è in attesa dell'invenzione di un nuovo numero, seguito da una lunga stringa di codice binario. Il Maestro Meccanico Tuboduro afferma che i dati sono vitali.",al={"cosa dice la scheda","traduzione binaria della scheda perforata","scheda perforata decodificata"}},{q="Chi vuole la Scheda Perforata Prismatica?",a="Il Maestro Meccanico Tuboduro, un ingegnere gnomo in esilio a Forgiardente, richiede la scheda durante Data Rescue. Dice che contiene informazioni urgenti e inestimabili, lasciate indietro quando gli gnomi evacuarono Gnomeregan.",al={"a chi consegnare la scheda perforata prismatica","missione di tuboduro","chi ha bisogno della scheda"}},{q="Dove si trovano i terminali Matrix Punchograph?",a="I terminali sono distribuiti per Gnomeregan in base al livello di accesso. Il Punchograph 3005-A si trova vicino al Train Depot in superficie e al Workshop Entrance. Il modello B è nel Dormitory oltre la Clean Zone, il modello C si trova più in profondità nel complesso e il modello D nei livelli inferiori degli Engineering Labs.",al={"posizioni dei terminali","dove sono i punchograph","dove perforare le schede"}}},fx={f4168582={q="Cos'è una Scheda Perforata Prismatica?",a="Una Scheda Perforata Prismatica è una scheda dati con un livello di autorizzazione straordinariamente alto generata dai sistemi computazionali all'interno di Gnomeregan. La sua classificazione di sicurezza automatizzata è presumibilmente così elevata che la matematica gnomica non ha ancora inventato un numero adeguato per descriverla. In verità, contiene testo binario codificato prodotto dai terminali della città profonda, funzionando come l'apice del protocollo di recupero dati a livelli degli gnomi.",al={"cos'è la scheda perforata prismatica","storia della scheda perforata prismatica","scheda prismatica gnomeregan"}},["7551673e"]={q="Da dove proviene la Scheda Perforata Prismatica e chi l'ha creata?",a="La scheda è prodotta nelle profondità della città caduta di Gnomeregan dal Matrix Punchograph 3005-D, un terminale automatizzato ad alta sicurezza che si trova al livello inferiore degli Engineering Labs. Non è fatta a mano da una persona, ma piuttosto codificata dalla rete meccanizzata degli gnomi quando un utente inserisce una Scheda Perforata Rossa adeguatamente potenziata nell'apparato.",al={"origine scheda perforata prismatica","chi ha creato la scheda perforata prismatica","dove ottenere la scheda perforata prismatica"}}},fp="20,134,20.538.0,22.316.1,41.204.0,48.169.1,35.200.0,51.268.0"}
P.entries["item:pristine-spider-silk"] = {n="Seta di Ragno Intatta",s="A Boscovespro, i ragni velenosi forniscono il Filo Pregiato che serve ai maghi di Roccavento per vesti resistenti agli incantamenti.",h="A Boscovespro, i ragni velenosi forniscono il Filo Pregiato che serve ai maghi di Roccavento per vesti...",kw={"black widow hatchling","carrion recluse","boscovespro","veste da mago","seta di ragno intatta","santuario della magia","wynne larson"},ang={["class:Mage"]="Come mago di Roccavento, vieni inviato a Boscovespro per raccogliere questo Filo Pregiato e guadagnarti una veste adeguata alla tua crescente statura arcana.",["profession:Tailoring"]="Come sarto, lavori con un filo delicato e resistente, raccolto da ragni letali. È una fibra naturale pregiata per le vesti magiche."},sec={{t="Tessere l'Arcano",b="Ai maghi di Roccavento serve una seta abbastanza resistente da reggere gli incantamenti e l'usura di un adepto. I sarti usano la comune Seta di Ragno, ma i fili dei carrion recluses e dei black widow hatchlings di Boscovespro sono più resistenti. I maghi del Santuario della Magia inviano gli adepti emergenti in quei boschi per raccoglierla. La maestra sarta Wynne Larson tesse poi la seta per realizzare una veste per un adepto."}},faq={{q="Da dove proviene la Seta di Ragno Intatta?",a="La Seta di Ragno Intatta si ricava dai carrion recluses e dai black widow hatchlings di Boscovespro.",al={"dove trovare la seta di ragno intatta","chi rilascia la seta di ragno intatta","posizione della seta di ragno intatta"}},{q="Chi crea indumenti con questa seta?",a="Wynne Larson, una sarta del Quartiere dei Maghi di Roccavento, tesse la seta raccolta per realizzare una veste per il Santuario della Magia.",al={"chi usa la seta di ragno intatta","chi trasforma la seta in vesti","veste di wynne larson"}},{q="Perché i maghi richiedono questa seta specifica?",a="Ai maghi serve una seta abbastanza resistente perché la veste di un adepto regga gli incantamenti e l'usura. La seta dei ragni di Boscovespro ha la resistenza e la qualità necessarie.",al={"perché la seta intatta","uso della seta di ragno magica"}}},fx={dfaa8e27={q="Cos'è la Seta di Ragno Intatta?",a="La Seta di Ragno Intatta è una tela eccezionalmente fine e immacolata filata dagli aracnidi che infestano Boscovespro. A differenza delle comuni ragnatele logore che si trovano appese agli alberi in tutta la foresta oscurata, solo i fili più puri e senza imperfezioni si qualificano come intatti. Sarti e maghi la apprezzano molto per la sua qualità e consistenza superiori, utilizzandola come tessuto base essenziale per confezionare capi distinti adatti a maghi praticanti.",al={"seta di ragno intatta","cos'è la seta intatta","oggetto seta intatta"}}},fp="20,108,18.366.0,42.88.0,35.120.0,44.157.0"}
P.entries["item:prowler-claws"] = {n="Prowler Claws",s="Da ogni parte delle Savane, i Prowler Claws vengono riportati a Sergra Darkthorn al Crocevia. Dimostrano che un cacciatore sa seguire le tracce e sconfiggere i prowler che si aggirano furtivi per le pianure.",h="Da ogni parte delle Savane, i Prowler Claws vengono riportati a Sergra Darkthorn al Crocevia.",kw={"savane","crocevia","prowler claws","prowlers of the barrens","savannah prowler","sergra darkthorn"},ang={["class:Hunter"]="Da cacciatore, seguire le tracce dei savannah prowlers e prendere i loro artigli mette alla prova la tua abilità nella furtività, nel seguire tracce e nell'affrontare bestie da vicino.",["faction:Horde"]="Come membro dell'Orda, aiutare a ridurre il numero dei prowler intorno al Crocevia protegge messaggeri, carovane e coloni sulle strade centrali di Kalimdor."},sec={{t="Trofei del predatore furtivo",b="I Savannah Prowlers attendono nell'erba alta delle Savane, pronti a colpire con pazienza e astuzia. A differenza dei plainstriders e degli zhevra che pascolano, questi grandi felini tendono agguati alle creature che entrano nei loro territori di caccia. Prendere i loro artigli ricurvi significa affrontare predatori che si affidano alla furtività e difendono il proprio territorio. Per i guerrieri e gli esploratori dell'Orda, la caccia mette alla prova la capacità di seguire un predatore furtivo sul suo terreno e trasformarlo in preda."},{t="Una prova per la cacciatrice",b="Sergra Darkthorn, la cacciatrice del Crocevia, chiede agli iniziati di portarle dei Prowler Claws prima di affrontare prove più impegnative. Gli artigli dimostrano che un cacciatore sa seguire le tracce tra l'erba della savana e resistere all'attacco di un predatore. Chi torna con questi trofei ha dimostrato di saper restare all'erta tra le pericolose bestie delle pianure."}},faq={{q="Dove trovo i Prowler Claws?",a="I Savannah Prowlers si aggirano nelle praterie delle Savane centrali, soprattutto nelle pianure a sudovest del Crocevia. Prendi i loro artigli e riportali indietro.",al={"posizione prowler claws","come ottenere prowler claws","dove trovare prowler claws"}},{q="Chi vuole questi artigli e perché?",a="Sergra Darkthorn, un'esperta cacciatrice del Crocevia, vuole sette Prowler Claws. Portarglieli mette alla prova la tua capacità di seguire le tracce e combattere predatori pericolosi.",al={"chi ha bisogno di prowler claws","consegnare prowler claws","missione sergra artigli"}},{q="Perché i Savannah Prowler sono considerati una preda significativa?",a="I Savannah Prowlers sono carnivori furtivi che si appostano nella vegetazione alta per insidiare viaggiatori e prede. Cacciarli mette alla prova la tua capacità di evitare un agguato e sconfiggere una bestia astuta e letale.",al={"perché cacciare i prowler","prowler pericolosi"}}},fx={["551eb0e2"]={q="Cosa sono i Prowler Claws?",a="I Prowler Claws sono gli artigli affilati come rasoi presi dalle zampe dei predatori della savana, i mortali felini predatori che perseguitano l'erba alta della savana di The Barrens. Per i cacciatori di Crocevia, prendere questi trofei dimostra che puoi rintracciare e superare una bestia astuta e letale senza diventare tu stesso una preda.",al={"cosa sono i prowler claws","oggetto prowler claws","informazioni prowler claws"}},c8bad4fe={q="Da dove provengono i Prowler Claws?",a="Questi artigli provengono direttamente dai predatori della savana che vagano per le pianure di The Barrens, in particolare nelle praterie a sud-ovest di Crocevia. Sono trofei naturali raccolti dalle carcasse dei grandi felini da cacciatori abbastanza abili da abbatterli.",al={"da dove provengono i prowler claws","fonte prowler claws","come ottenere i prowler claws"}}},fp="13,154,23.425.0,22.323.0,29.143.0,30.170.0,56.179.0"}
P.entries["item:pure-hearts"] = {n="Cuori Puri",s="A Sepulcra, i Cuori Puri attirano una succube dalla Distorsione Fatua. Carendin Halgar dà questi reagenti rituali agli stregoni Reietti, che li usano per evocare il demone e tentare di sconfiggerla e vincolarla.",h="A Sepulcra, i Cuori Puri attirano una succube dalla Distorsione Fatua.",kw={"carendin halgar","magic quarter","cuori puri","succube","evocazione","the binding","sepulcra"},ang={["class:Warlock"]="Per uno stregone, usare i Cuori Puri segna una svolta nella demonologia. Dimostra la tua forza mentale contro le lusinghe seducenti della Distorsione Fatua.",["race:Undead"]="Da Undead, usi cuori incontaminati per manipolare gli appetiti demoniaci. Questa stregoneria fredda e pragmatica esemplifica le pratiche dei Reietti."},sec={{t="Esca per la Distorsione",b="Carendin Halgar dà i Cuori Puri agli stregoni che evocano una succube nel Magic Quarter di Sepulcra. Gli stregoni collocano le essenze spirituali incontaminate sul cerchio di evocazione. I cuori attirano il demone attraverso la Distorsione Fatua fino al regno mortale.\n\nUna volta apparsa, lo stregone deve resistere ai suoi ammalianti incantesimi mentali e abbatterla. Sconfiggere la succube dimostra il proprio dominio mistico e la rimanda nella Distorsione Fatua. Poi Carendin insegna allo stregone l'incantesimo per evocarla a piacimento."}},faq={{q="A cosa servono i Cuori Puri?",a="I Cuori Puri attirano una succube attraverso la Distorsione Fatua e la portano nel regno mortale. Al cerchio di evocazione nel Magic Quarter di Sepulcra, uno stregone può affrontarla e vincolarla.",al={"uso dei cuori puri","perché i cuori puri","cosa fanno i cuori puri"}},{q="Chi fornisce i Cuori Puri?",a="Carendin Halgar, un istruttore degli stregoni Reietti a Sepulcra, dà i Cuori Puri agli stregoni che si preparano a evocare una succube.",al={"chi dà i cuori puri","chi assegna la missione dei cuori puri"}},{q="Perché una succube risponde ai Cuori Puri?",a="Le succubi prosperano nella corruzione e nella seduzione. Lo splendore dei cuori immacolati le attira attraverso la Distorsione Fatua fino al cerchio di evocazione di uno stregone.",al={"perché la succube vuole i cuori puri","storia dei cuori puri"}},{q="Si possono tenere i Cuori Puri dopo il rituale?",a="No. Dopo che la succube è stata evocata e soggiogata, i resti dei Cuori Puri vengono restituiti a Carendin Halgar come prova del completamento della prova di vincolo.",al={"si tengono i cuori puri","cosa succede ai cuori puri"}}},fx={["105bfa16"]={q="Cosa sono i Cuori Puri?",a="I Cuori Puri sono potenti componenti rituali usati dagli stregoni Rinnegati a Undercity. Quando vengono lanciati su un cerchio di evocazione, la loro essenza incontaminata funge da esca attraverso la Distorsione Fatua, aprendo una frattura progettata specificamente per attirare ed evocare una pericolosa succube alla tua presenza.",al={"cosa sono i cuori puri","oggetto cuori puri","cuori puri stregone"}},["3abadf0f"]={q="Perché qualcuno vorrebbe i Cuori Puri?",a="Un aspirante stregone richiede i Cuori Puri per completare il pericoloso rituale di vincolo per una succube. Senza offrire un'esca così incontaminata per colmare il vuoto, non puoi attirare il demone attraverso il reame mortale per sottometterla e padroneggiare l'arte di evocarla al tuo comando.",al={"perché volere i cuori puri","scopo dei cuori puri","perché i cuori puri sono ricercati"}}},fp="11,206,19.499.0,34.183.0,29.123.0,43.149.0,52.151.0"}
P.entries["item:purified-kor-gem"] = {n="Gemma Kor Purificata",s="Alla forgia di Jordan Stilwell fuori da Forgiardente, serve una Gemma Kor Purificata per plasmare un'arma della Luce. Prima, la magia elfica deve purificare la pietra corrotta.",h="Alla forgia di Jordan Stilwell fuori da Forgiardente, serve una Gemma Kor Purificata per plasmare un'arma...",kw={"auberdine","abissi di fondocupo","gemma kor corrotta","dun morogh","jordan stilwell","gemma kor purificata","the test of righteousness","thundris windweaver"},ang={["class:Paladin"]="Come paladino, dimostri la tua devozione recuperando e purificando questa gemma. Poi la porti da Kalimdor a Dun Morogh, dove contribuisce a forgiare un'arma della Luce.",["faction:Alliance"]="Come membro dell'Alleanza, ti affidi alla saggezza degli Elfi della Notte di Auberdine per aiutare un fabbro umano sulle pendici di Dun Morogh."},sec={{t="Dalla Corruzione alla Santità",b="I naga custodiscono la Gemma Kor Corrotta negli Abissi di Fondocupo, sotto la costa di Valtetra. Un paladino la porta a Thundris Windweaver, un Elfo della Notte di Auberdine. Lì, Thundris attinge alle arti arcane e naturali per eliminarne la contaminazione acquatica e oscura. La pietra ne esce purificata, pronta a incanalare il potere sacro."},{t="Il Capolavoro del Fabbro",b="Jordan Stilwell, un fabbro d'armi umano fuori da Forgiardente, ha bisogno della gemma per un'arma di fattura magistrale. Da tempo possiede i progetti per un'arma degna della Mano d'Argento, ma gli mancavano i materiali rari per forgiarla. La Gemma Kor Purificata, la Catasta di Legname di Quercia Scorzasecca e un minerale raro conferiscono all'arma il nucleo spirituale per incanalare la giusta ira di un paladino."}},faq={{q="A cosa serve la Gemma Kor Purificata?",a="La gemma viene consegnata a Jordan Stilwell, il fabbro fuori da Forgiardente, a Dun Morogh. La usa per forgiare un'arma consacrata per un paladino che sta affrontando le sue prove.",al={"uso della gemma kor purificata","perché mi serve la gemma kor","a cosa serve la gemma kor"}},{q="Da dove proviene la gemma?",a="I naga custodiscono la pietra corrotta negli Abissi di Fondocupo, sotto la costa di Valtetra.",al={"origine della gemma kor","dove si trova la gemma kor","chi rilascia la gemma kor"}},{q="Chi purifica la gemma?",a="Thundris Windweaver, un Elfo della Notte di Auberdine, purifica la Gemma Kor Corrotta e la riporta a uno stato di purezza.",al={"come purificare la gemma kor","chi purifica la gemma kor","thundris windweaver gemma kor"}},{q="Qualsiasi avventuriero può utilizzare la Gemma Kor Purificata?",a="I paladini che affrontano il Test of Righteousness cercano la gemma. Jordan Stilwell forgia armi per i guerrieri sacri che gli portano il cristallo purificato e altri materiali rari.",al={"la gemma kor è solo per paladini","chiunque può usare la gemma kor purificata"}}},fx={a30b14db={q="Cos'è una Gemma Kor Purificata?",a="La Gemma Kor Purificata è un raro componente minerale santificato ripulito da un ripugnante contaminazione. Originariamente recuperata come una pietra corrotta detenuta dai naga negli Abissi di Fondocupo, è stata faticosamente ripulita dalla sua oscura influenza da Thundris Windweaver ad Auberdine in modo che le sue proprietà latenti possano essere sfruttate in sicurezza per opere sacre.",al={"cos'è la gemma kor purificata","significato gemma kor purificata","info gemma kor purificata"}}},fp="16,161,27.299.0,23.338.0,38.161.0,29.83.0,21.114.0,52.161.0"}
P.entries["item:putrid-claw"] = {n="Artiglio Putrido",s="Vicino a Brill, le taglie per l'Artiglio Putrido aiutano a tenere a bada il Flagello. Non morti senza volontà vagano nei boschi a ovest del paese, soprattutto vicino al vecchio ponte, e il Guardiamorte Dillinger riceve gli artigli come prova.",h="Vicino a Brill, le taglie per l'Artiglio Putrido aiutano a tenere a bada il Flagello.",kw={"a putrid task","brill","guardiamorte dillinger","artiglio putrido","ravaged corpse","rotting dead","flagello","radure di tirisfal"},ang={["race:Undead"]="Come nuova recluta dei Reietti che lascia Albamorta, scopri che la liberazione significa difendersi dai gusci vuoti senza volontà a cui un tempo somigliavi."},sec={{t="Trofeo dei senza cervello",b="Il Flagello senza volontà continua a penetrare nelle Radure di Tirisfal. Morti marcescenti e cadaveri martoriati vagano lungo i confini orientali, radunandosi lungo le strade e vicino al vecchio ponte a ovest di Brill. Le Guardiemorte offrono taglie su questi orrori per proteggere i viaggiatori e le linee di rifornimento della guarnigione. Un artiglio putrido mozzato dimostra che un altro cadavere barcollante è stato abbattuto per sempre."}},faq={{q="A cosa servono gli artigli putridi?",a="Il Guardiamorte Dillinger a Brill raccoglie artigli putridi in cambio di taglie. Dimostrano che le reclute locali dei Reietti stanno sfoltendo le schiere del Flagello che vagano nelle Radure di Tirisfal.",al={"uso dell'artiglio putrido","perché raccogliere artigli putridi","chi vuole gli artigli putridi"}},{q="Da dove provengono gli artigli putridi?",a="Gli artigli putridi provengono dai morti marcescenti e dai cadaveri martoriati che vagano nei boschi infestati a ovest di Brill, soprattutto vicino al vecchio ponte sul fiume.",al={"dove trovare gli artigli putridi","bottino artiglio putrido","bottino del morto marcescente"}},{q="Perché il Flagello si trova nelle Radure di Tirisfal?",a="Dopo la devastazione di Lordaeron, i resti del Flagello senza volontà del Re dei Lich continuano ad avanzare verso ovest, a Tirisfal. Minacciano strade e insediamenti se nessuno ne riduce il numero.",al={"perché ci sono zombi vicino a brill","flagello a tirisfal"}},{q="Perché i Reietti non lasciano semplicemente vagare i non morti senza volontà?",a="La regina Sylvanas e i Reietti si sono liberati dalla morsa del Re dei Lich e hanno riacquistato la propria volontà. I membri del Flagello senza volontà obbediscono a istinti oscuri o ai suoi ordini persistenti, attaccando a vista qualsiasi vivente o non morto libero.",al={"reietti contro zombi senza volontà","perché uccidere altri non morti"}}},fx={["37750c4d"]={q="Cos'è un Artiglio Putrido?",a="Un Artiglio Putrido è la mano mozzata e putrefatta di uno zombi senza mente appartenente al Flagello. Queste appendici in decomposizione vengono prese dai cadaveri che camminano che infestano le Radure di Tirisfal come prova della loro distruzione.",al={"cos'è l'artiglio putrido","info artiglio putrido","storia dell'artiglio putrido"}}},fp="11,191,22.354.0,31.155.0,32.140.0,38.170.0,59.205.0"}
P.entries["item:pyrewood-shackle"] = {n="Manette di Rovonero",s="A Rovonero, ceppi incantati vincolano gli abitanti alla strana magia dell'Arcimago Arugal. Quando cala la notte, un oscuro destino attende i paesani.",h="A Rovonero, ceppi incantati vincolano gli abitanti alla strana magia dell'Arcimago Arugal.",kw={"arugal","tessalba","moonrage","rovonero","mausolea","ceppo","selva pinargento","worgen"},ang={["class:Mage"]="In quanto mago, puoi riconoscere la sconsiderata magia di trasmutazione e vincolo intessuta nel comune acciaio.",["race:Undead"]="In quanto Reietto, sai che la stregoneria sfrenata di Arugal minaccia i tuoi confini. Raccogliere questi ceppi incantati è vitale per neutralizzare l'influenza del Forte di Zannascura."},sec={{t="La Magia Vincolante di Arugal",b="Gli abitanti di Rovonero vivono come umani di giorno, poi al tramonto si trasformano in feroci worgen Moonrage. L'Arcimago Arugal li vincolò con ceppi incantati durante i suoi esperimenti con la stregoneria dei worgen. A Mausolea, Dalar Tessalba, un ricercatore arcano dei Reietti, studia questi ceppi. Ne raccoglie l'energia residua per scoprire cosa fanno gli incantamenti, comprendere la magia di Arugal e allentare la morsa del folle arcimago sulla regione."}},faq={{q="A cosa servono i Ceppi di Rovonero?",a="A Mausolea, Dalar Tessalba studia gli incantamenti dei ceppi. Spera di svelare gli incantesimi dell'Arcimago Arugal e smantellare la sua influenza nella Selva Pinargento.",al={"uso dei ceppi di rovonero","perché raccogliere i ceppi","ceppi di dalar tessalba"}},{q="Chi trasporta questi ceppi?",a="Gli abitanti maledetti di Rovonero, nella parte meridionale della Selva Pinargento, portano i ceppi. Li indossano come umani di giorno e come worgen Moonrage di notte.",al={"chi rilascia i ceppi di rovonero","fonte dei ceppi","dove trovare i ceppi di rovonero"}},{q="Perché gli abitanti del villaggio si trasformano di notte?",a="Gli esperimenti sconsiderati e gli incantamenti dell'Arcimago Arugal fecero sì che gli abitanti di Rovonero si trasformassero di notte. I ceppi racchiudono un incantamento che permette loro di apparire come comuni umani alla luce del giorno, mentre l'oscurità rivela le loro feroci forme di worgen.",al={"perché rovonero si trasforma in worgen","maledizione di rovonero","segreto dei lupi mannari di rovonero"}},{q="Chi è Dalar Tessalba?",a="Dalar Tessalba è un mago dei Reietti che si trova a Mausolea, nella Selva Pinargento. Studia le anomalie arcane lasciate dall'Arcimago Arugal, cercando di spezzare le sue maledizioni.",al={"dalar tessalba","chi è dalar"}}},fx={b92f5faa={q="Cosa sono le Manette di Rovonero?",a="Le Manette di Rovonero sono un vincolo incantato legato agli sfortunati residenti di Rovonero nella Selva Pinargento meridionale. Imbevute della strana e sconsiderata stregoneria del folle mago Arci-Mago Arugal, queste manette svolgono un ruolo diretto nel legare gli abitanti alla sua volontà e nel mascherare l'oscura maledizione che li affligge.",al={"manette di rovonero","cosa sono le manette di rovonero"}},f6bcbb50={q="Da dove provengono le Manette di Rovonero e chi le ha create?",a="Queste manette incantate sono state forgiate e poste sugli abitanti del villaggio dall'Arci-Mago Arugal, il mago rinnegato di Dalaran che prese residenza a Forte di Zannascura. Arugal ha lanciato le manette sui contadini di Rovonero come parte dei suoi incantesimi contorti, tenendoli sotto il suo controllo mentre nascondeva la loro trasformazione lupina sotto un'illusione diurna di normale vita umana.",al={"chi ha creato le manette di rovonero","origine manette di rovonero","da dove provengono le manette"}},["98d012f7"]={q="Perché qualcuno vuole le Manette di Rovonero?",a="Dalar Tessalba, un ambizioso mago Rinnegato che conduce ricerche a Mausolea, cerca queste manette incantate per studiare la magia di Arugal. Sifonando la loro energia residua, Dalar spera di svelare lo strano incantesimo che fa apparire gli abitanti del villaggio umani di giorno e trasformarsi in voraci worgen Ira Lunare dopo il tramonto, cercando infine di smantellare gli incantesimi di Arugal.",al={"perché raccogliere le manette di rovonero","chi ha bisogno delle manette di rovonero","scopo delle manette di rovonero"}}},fp="16,141,22.410.1,36.176.0,27.155.1,40.234.1,24.167.0"}
P.entries["item:quinn-s-potion"] = {n="Pozione di Quinn",s="A Mausolea, lo Speziale Renferrel prepara la Pozione di Quinn per un esploratore ferito. Quinn Yorick ne ha bisogno dopo un disastroso pattugliamento nella Selva Pinargento.",h="A Mausolea, lo Speziale Renferrel prepara la Pozione di Quinn per un esploratore ferito.",kw={"speziale renferrel","deathstalker","podere di ivar","quinn yorick","pozione di quinn","mausolea","selva pinargento"},ang={["race:Undead"]="In quanto Reietto, sai che la Società degli Speziali Reali raramente si dedica a semplici rimedi da campo, a meno che non aiutino a preservare gli esploratori che sorvegliano i confini della Selva Pinargento."},sec={{t="La cura di Renferrel",b="Lo Speziale Renferrel prepara un rimedio per il Deathstalker Quinn Yorick. La notizia raggiunse la Società degli Speziali Reali a Mausolea dopo che Quinn era rimasto gravemente ferito vicino al Podere di Ivar e non riusciva più a muoversi. Renferrel preparò l'infuso per aiutarlo a riprendersi.\n\nI feriti meno gravi sul campo raramente distolgono Renferrel dalle sue oscure ricerche per Lady Sylvanas. Ciononostante, fornì il rimedio affinché Quinn recuperasse abbastanza forze da poter viaggiare."}},faq={{q="A cosa serve la Pozione di Quinn?",a="La Pozione di Quinn aiuta il Deathstalker Quinn Yorick a riprendersi dalle ferite nella Selva Pinargento settentrionale. Gli restituisce abbastanza forze da permettergli di viaggiare di nuovo.",al={"scopo pozione di quinn","cosa fa la pozione di quinn","perché creare la pozione di quinn"}},{q="Chi ha distillato questa pozione?",a="Lo Speziale Renferrel, un alchimista della Società degli Speziali Reali di stanza nelle cripte di Mausolea, preparò l'infuso.",al={"chi ha creato la pozione di quinn","chi l'ha distillata","pozione di renferrel"}},{q="Dove deve essere consegnata la pozione?",a="Porta la pozione a nord di Mausolea a Quinn Yorick, che si è rifugiato vicino alla fattoria chiamata Podere di Ivar.",al={"dove porto la pozione","posizione di quinn","luogo di quinn yorick"}},{q="Perché Quinn Yorick aveva bisogno di una pozione?",a="Quinn era in ricognizione nella Selva Pinargento settentrionale con una pattuglia di Deathstalker. Al Podere di Ivar, il ghoul Ivar the Foul attaccò gli esploratori, lasciando Quinn gravemente ferito e impossibilitato a muoversi.",al={"perché quinn è ferito","cosa è successo a quinn yorick","quinn ferito"}}},fx={["52098f03"]={q="Cos'è la Pozione di Quinn?",a="È un infuso ricostituente preparato dallo Speziale Renferrel a Mausolea. Formulato specificamente per aiutare lo scout ferito Quinn Yorick, la pozione fornisce la forza di cui ha bisogno per riprendersi dalle sue ferite e riguadagnare abbastanza mobilità per viaggiare.",al={"pozione di quinn","cos'è questa pozione","cos'è l'infuso di quinn"}}},fp="14,154,16.415.0,32.156.0,23.123.0,43.109.0,41.169.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="Teschio di Ran Zannarossa",s="A Valtetra, il Teschio di Ran Zannarossa giunge agli Elfi della Notte di Astranaar come prova della caduta di una feroce minaccia.",h="A Valtetra, il Teschio di Ran Zannarossa giunge agli Elfi della Notte di Astranaar come prova della caduta di...",kw={"valtetra","astranaar","teschio di zannarossa","zannarossa","furbolg","raene braccalupo","raene's cleansing","ran zannarossa"},ang={["faction:Alliance"]="La consegna del macabro trofeo dimostra il valore dei campioni dell'Alleanza che difendono i fragili confini di Valtetra al fianco delle Sentinelle.",["race:NightElf"]="Per gli Elfi della Notte, il teschio segna una mesta vittoria e rende onore al compito incompiuto di Teronis. Ricorda anche quanto profondamente la corruzione demoniaca abbia devastato i furbolg, loro antichi alleati."},sec={{t="Un trofeo per la difesa di Valtetra",b="La contaminazione demoniaca e la corruzione della natura hanno spinto i furbolg di Valtetra a una follia omicida. Ran Bloodtooth guidava una delle tribù più feroci. Il suo teschio dimostra alle Sentinelle degli Elfi della Notte che è caduto e che il suo dominio sui furbolg locali è spezzato. Astranaar ottiene un po' di tregua."},{t="Onorare i caduti",b="Ad Astranaar, la Sentinella Raene Braccalupo riceve il Teschio di Ran Zannarossa. Segna la fine di un'indagine iniziata dall'esploratore caduto Teronis. Accanto al teschio riposa la Verga di Dartol, ricostruita dopo che Teronis era partito per trovarla. Insieme, il teschio e la verga onorano coloro che hanno combattuto per preservare la foresta sacra."}},faq={{q="Chi era Ran Bloodtooth?",a="Ran Bloodtooth guidava una tribù di furbolg corrotti a Valtetra. Le Sentinelle degli Elfi della Notte lo annoveravano tra le minacce più feroci della regione.",al={"chi è ran zannarossa","storia di ran zannarossa","chi era zannarossa"}},{q="Perché le Sentinelle vogliono il suo teschio?",a="Raene Braccalupo riceve il Teschio di Ran Zannarossa ad Astranaar come prova della sua caduta. Riposa accanto alla Verga di Dartol in memoria di coloro che sono caduti difendendo Valtetra.",al={"perché serve il teschio","teschio raene braccalupo","a cosa serve il teschio"}},{q="Chi era Teronis?",a="Teronis era un amico di lunga data di Raene Braccalupo e un alleato delle Sentinelle a Valtetra. Cercava una gemma per una verga creata dal defunto mago Dartol, sperando che potesse rallentare gli attacchi dei furbolg. I murloc lo uccisero al Lago Falathim, così Raene Braccalupo e alcuni avventurieri di passaggio proseguirono il suo compito.",al={"storia di teronis","chi è teronis","teronis astranaar"}}},fx={["4d0a3ce4"]={q="Cos'è il Teschio di Ran Zannarossa?",a="Questo è il teschio mozzato di Ran Zannarossa, una delle più feroci e pericolose minacce furbolg corrotte che infestano Valtetra. Preso come prova della sua sconfitta, segna la fine del terrore che ha portato contro le Sentinelle e la foresta.",al={"teschio di ran zannarossa","cos'è il teschio di ran","testa di ran zannarossa"}},f5c7858d={q="Da dove proviene il Teschio di Ran Zannarossa?",a="Il teschio viene reclamato direttamente da Ran Zannarossa dopo averlo ucciso a Valtetra. Non è un artefatto forgiato o creato da mani mortali, ma piuttosto il macabro trofeo ottenuto dal capotribù stesso.",al={"da dove viene il teschio di ran","chi ha creato il teschio di ran zannarossa","origine teschio di ran zannarossa"}}},fp="22,115,31.284.0,19.305.1,23.136.0,36.164.0,16.287.0"}
P.entries["item:raptor-head"] = {n="Testa di Raptor",s="A Crocevia, i trofei Testa di Raptor fruttano la taglia offerta da Gazrog. La paga delle guardie è sparita da una torre di guardia e un raptor selvaggio è stato colto sul fatto.",h="A Crocevia, i trofei Testa di Raptor fruttano la taglia offerta da Gazrog.",kw={"savane","crocevia","gazrog","testa di raptor","raptor thieves","argento rubato","sunscale"},ang={["class:Hunter"]="Seguire le tracce dei raptor Sunscale nell'arida boscaglia delle Savane mette alla prova la tua abilità contro alcuni dei più aggressivi e astuti cacciatori in branco della savana.",["faction:Horde"]="Crocevia è il cuore degli spostamenti dell'Orda nel Kalimdor centrale. Eliminare i predatori ladri aiuta a proteggere le provviste e la paga della guarnigione."},sec={{t="La taglia di Crocevia",b="Una cassa con la paga delle guardie è stata rubata dalla torre di guardia di Crocevia, lasciando i difensori senza il loro argento. Increduli, hanno colto sul fatto un raptor selvaggio. Gazrog ora offre una taglia sugli scaltri rettili che si aggirano per le Savane. Porta le loro teste mozzate all'avamposto e sarà possibile sfoltire i predatori prima che rubino altre provviste dell'Orda."}},faq={{q="Perché Gazrog vuole teste di raptor?",a="Una cassa contenente l'argento per le guardie di Crocevia è stata rubata dalla loro torre. Tra l'incredulità generale, un raptor è stato colto sul fatto. Gazrog vuole che si dia la caccia alle bestie in tutte le Savane, affinché non possano più razziare l'insediamento.",al={"perché raccogliere teste di raptor","gazrog raptor","taglia testa di raptor"}},{q="Perché dei raptor selvaggi dovrebbero rubare argento?",a="Gazrog ammette di non avere idea del perché delle bestie selvagge dovrebbero volere monete di metallo. I raptor di Kalimdor sono noti per la loro inquietante astuzia. Il furto ha lasciato le guardie di Crocevia imbarazzate e desiderose di vendetta.",al={"perché i raptor vogliono l'argento","raptor che rubano monete","mistero raptor thieves"}},{q="Quali raptor portano queste teste?",a="Le teste si ottengono dai raptor Sunscale che vagano nelle zone centrali e meridionali delle Savane, tra cui Sunscale Lashtails, Screechers e Scytheclaws. Anche bestie famigerate come Ishamuhale e Takk the Leaper forniscono teste.",al={"dove trovare teste di raptor","quali raptor rilasciano teste","raptor delle savane"}},{q="Cosa succede dopo aver consegnato le teste?",a="Dopo che Gazrog ha ricevuto dodici teste e la minaccia dei raptor è stata ridotta, l'attenzione si sposta sulla ricerca del carico d'argento rubato.",al={"cosa segue raptor thieves","dopo aver raccolto teste di raptor"}}},fx={f6102aac={q="Cos'è una Testa di Raptor?",a="Una Testa di Raptor è il trofeo mozzato e la prova di taglia prelevati dai raptor che vagano nelle Barrens, inclusi i branchi locali dei Sunscale e bestie famigerate come Ishamuhale o Takk il Saltatore. Le autorità di Crocevia richiedono questi macabri pegni come prova verificabile che i predatori astuti che tormentano le loro linee di rifornimento e le guardie siano stati abbattuti.",al={"cos'è la testa di raptor","oggetto testa di raptor","cosa sono le teste di raptor"}},["377da5ba"]={q="Da dove proviene una Testa di Raptor?",a="Queste teste provengono direttamente dai raptor predatori che perseguitano le savane e le creste delle Barrens. I Sunscale Lashtail, gli Screecher, gli Scytheclaw e i noti cacciatori delle pianure le lasciano cadere una volta uccisi. Essendo resti biologici raccolti sul campo, non sono creati da nessuno, ma piuttosto reclamati come trofei di una caccia riuscita.",al={"da dove vengono le teste di raptor","origine testa di raptor","chi ha creato la testa di raptor"}}},fp="11,150,24.355.0,34.228.0,36.207.0,32.207.0,40.139.0"}
P.entries["item:rare-earth"] = {n="Terra Rara",s="A Dolanaar, la Terra Rara attende un viaggiatore diretto all'accampamento di Denalan vicino al Lago Al'ameth. Il terriccio proviene da Darnassus ed è destinato ai suoi esperimenti botanici su Teldrassil.",h="A Dolanaar, la Terra Rara attende un viaggiatore diretto all'accampamento di Denalan vicino al Lago Al'ameth.",kw={"darnassus","denalan","dolanaar","erbalismo","lago al'ameth","terra rara","syral fogliaguzza"},ang={["profession:Herbalism"]="Come erborista, puoi prendere a riferimento Syral Fogliaguzza e Denalan, che studiano come terricci specifici modifichino la crescita e le proprietà degli alberelli di Teldrassil.",["race:NightElf"]="Come Elfo della Notte che si prende cura del giovane World Tree, puoi vedere come gli esperimenti presso il Lago Al'ameth rivelino i modi in cui la vita si adatta ai rami selvaggi di Teldrassil."},sec={{t="Terriccio di Darnassus",b="La Terra Rara è arrivata in ritardo a Dolanaar da Darnassus. Denalan, un eccentrico botanico sulla riva orientale del Lago Al'ameth, l'ha richiesta per studiare le piante nel giovane ecosistema di Teldrassil. Ora l'erborista Syral Fogliaguzza affida il terriccio ai viaggiatori diretti a sud. Spera che raggiunga Denalan prima di perdere la sua efficacia."}},faq={{q="A cosa serve la Terra Rara?",a="Presso il Lago Al'ameth, Denalan usa la Terra Rara nei suoi esperimenti botanici. Coltiva le piante autoctone di Teldrassil con composti minerali e terricci arricchiti provenienti da Darnassus.",al={"uso di terra rara","cosa fa denalan con terra rara","scopo di terra rara"}},{q="Chi invia la Terra Rara a Denalan?",a="L'erborista Syral Fogliaguzza custodisce il pacco a Dolanaar. È arrivato in ritardo da Darnassus, e lei chiede ai viaggiatori diretti a sud verso il Lago Al'ameth di portarlo a Denalan.",al={"chi dà terra rara","dove trovare terra rara","pacco di syral fogliaguzza"}},{q="Perché Denalan era preoccupato per la consegna?",a="La spedizione ha subito un ritardo lungo il tragitto verso Dolanaar, lasciando Denalan in attesa presso il lago. Quando arriva, lui teme che il terriccio abbia perso la freschezza necessaria ai suoi esperimenti.",al={"terra rara è rovinata","terra fresca denalan","perché terra in ritardo"}}},fx={e720b4cb={q="Cos'è la Terra Rara?",a="La Terra Rara è una spedizione di terreno fertile appositamente reperito e inviato da Darnassus. Viene accuratamente preparato e imballato per ricerche agricole e botaniche sensibili, conservando nutrienti specializzati che richiedono che venga consegnato fresco per mantenere la sua potenza per delicati esperimenti di coltivazione.",al={"cos'è la terra rara","oggetto terra rara","storia terra rara"}},["5312d2a9"]={q="Perché Denalan vuole la Terra Rara?",a="Denalan è un ricercatore erborista di stanza sulle rive orientali del Lago Al'ameth, che studia e sperimenta con la flora locale di Teldrassil. Si affida a questo terreno raro e ricco di nutrienti proveniente da Darnassus per nutrire le sue delicate piantagioni e far avanzare il suo lavoro botanico sull'isola.",al={"perché denalan vuole la terra rara","perché volere terra rara","perché serve la terra rara"}}},fp="10,160,17.313.0,28.170.0,36.170.0,43.172.0"}
P.entries["item:rattlecage-skull"] = {n="Teschio di Scuotiossa",s="Ad Albamorta, gli stregoni Reietti alle prime armi raccolgono teschi dai non morti privi di senno. Venya Marthand impone questa prova prima di insegnare loro le arti oscure dell'evocazione.",h="Ad Albamorta, gli stregoni Reietti alle prime armi raccolgono teschi dai non morti privi di senno.",kw={"albamorta","evocazione dell'imp","piercing the veil","rattlecage skeleton","teschio di scuotiossa","radure di tirisfal","venya marthand"},ang={["class:Warlock"]="Come stregone Reietto, raccogliere questi teschi è il tuo primo passo nella disciplina. Dimostra che possiedi la fredda volontà necessaria ad asservire il tuo primo demone.",["race:Undead"]="Come non morto, fare a pezzi scheletri inferiori e privi di senno rispecchia la convinzione dei Reietti di poter dominare con la sola forza di volontà. I non morti dotati di libero arbitrio si distinguono dai servi privi di senno."},sec={{t="La prova di un neofita",b="Ad Albamorta, Venya Marthand guida i Reietti appena risorti dotati di un'affinità per la magia oscura. Li manda a sottomettere i Rattlecage Skeletons vicino alla fucina in rovina e a riportare i loro teschi. La prova verifica se un giovane stregone sa piegare al proprio comando creature provenienti da oltre questo mondo. Li prepara a squarciare il vuoto e a vincolare il loro primo servitore demoniaco."}},faq={{q="A cosa servono i Teschi di Scuotiossa?",a="Ad Albamorta, Venya Marthand riceve tre Teschi di Scuotiossa dagli stregoni Reietti. Dimostrano la loro concentrazione e determinazione prima che lei insegni loro a evocare e vincolare un diavoletto.",al={"cosa sono i teschi di scuotiossa","uso del teschio di scuotiossa","chi vuole i teschi di scuotiossa"}},{q="Da dove provengono i Teschi di Scuotiossa?",a="I Teschi di Scuotiossa provengono dai Rattlecage Skeletons privi di senno che vagano per le strade invase dalla vegetazione e i terreni dissestati vicino alla fucina abbandonata di Albamorta.",al={"dove trovare i teschi di scuotiossa","chi rilascia i teschi di scuotiossa","posizione del teschio di scuotiossa"}},{q="Perché Venya Marthand richiede teschi scheletrici per una prova da stregone?",a="Venya Marthand crede che il potere sfugga agli ignoranti e che la padronanza consista nel piegare le forze esterne alla propria volontà. Uccidere scheletri privi di senno e prenderne le teste dimostra che un apprendista sa dominare le energie caotiche senza esserne consumato.",al={"perché teschi per gli stregoni","prova di venya marthand"}},{q="Quale conoscenza viene concessa dopo aver raccolto questi teschi?",a="Una volta offerti i teschi, Venya Marthand insegna il rituale segreto per evocare e vincolare un diavoletto. Questo dona ai giovani stregoni il loro primo vero servitore demoniaco.",al={"cosa si ottiene dai teschi di scuotiossa","ricompensa di piercing the veil"}}},fx={["9627b388"]={q="Cos'è un Teschio di Scuotiossa?",a="Un Teschio di Scuotiossa è la testa mozzata di uno Scheletro Scuotiossa, uno dei non morti senza mente che vagano per i terreni devastati vicino alla forgia abbandonata di Albamorta. Per gli aspiranti stregoni dei Reietti, questi macabri trofei servono come prova di base di risolutezza e concentrazione magica, mostrando che un iniziato può affrontare e sconfiggere i morti che camminano.",al={"cos'è il teschio di scuotiossa","storia teschio di scuotiossa"}}},fp="16,155,17.352.0,36.172.0,37.145.0,68.239.0,55.160.0"}
P.entries["item:raven-claw-talisman"] = {n="Talismano Artiglio del Corvo",s="Nell'Eremo di Ban'ethil, il Talismano Artiglio del Corvo attende tra le reliquie destinate a risvegliare i druidi dormienti. È una delle quattro Relics of Wakening, usate per ricondurre al sicuro i Druidi dell'Artiglio dal Sogno di Smeraldo.",h="Nell'Eremo di Ban'ethil, il Talismano Artiglio del Corvo attende tra le reliquie destinate a risvegliare i...",kw={"athridas orsomanto","ban'ethil","eremo","dolanaar","druidi dell'artiglio","talismano artiglio del corvo","reliquie del risveglio","teldrassil"},ang={["class:Druid"]="Come druido, sai che il Talismano Artiglio del Corvo riflette l'uso dei focus rituali da parte dei Druidi dell'Artiglio per proteggere uno spirito che vaga nel Sogno di Smeraldo.",["race:NightElf"]="Come elfo della notte, proteggi un'antica tradizione e i tuoi simili dormienti recuperando questa reliquia dai furbolg Gnarlpine."},sec={{t="Una chiave per il risveglio",b="Il Talismano Artiglio del Corvo riposa in una cassa all'interno dell'Eremo di Ban'ethil. Lì, i Druidi dell'Artiglio di Teldrassil sono entrati in un profondo sonno meditativo. Senza il dovuto focus cerimoniale, un druido isolato dal mondo della veglia può rimanere intrappolato nel Sogno di Smeraldo. Ad Athridas Orsomanto, a Dolanaar, servono questo talismano e altre tre reliquie per ricondurre al sicuro i dormienti: la Piuma Nera, lo Zaffiro del Cielo e la Runa della Nidificazione."},{t="La minaccia nell'Eremo",b="I furbolg Gnarlpine corrotti hanno invaso l'Eremo di Ban'ethil. Le casse sacre e i druidi dormienti sono ora in pericolo. La loro profanazione ha isolato il santuario dagli aiuti esterni, e le reliquie potrebbero andare perdute o essere distrutte. Athridas Orsomanto chiama i difensori di Teldrassil ad affrontare i tortuosi cunicoli di terra dell'eremo e recuperare il Talismano Artiglio del Corvo prima che i druidi smarriti siano perduti nel Sogno per sempre."}},faq={{q="A cosa serve il Talismano Artiglio del Corvo?",a="Il Talismano Artiglio del Corvo è una delle quattro sacre Relics of Wakening. Le reliquie servono a risvegliare i Druidi dell'Artiglio dal profondo letargo nel Sogno di Smeraldo.",al={"a cosa serve il talismano artiglio del corvo","scopo del talismano artiglio del corvo","perché serve il talismano artiglio del corvo"}},{q="Dove si trova il Talismano Artiglio del Corvo?",a="Il Talismano Artiglio del Corvo riposa nel Chest of the Raven Claw, nei cunicoli di terra dell'Eremo di Ban'ethil. L'eremo si trova a ovest di Dolanaar, su Teldrassil.",al={"dove si trova il talismano artiglio del corvo","posizione cassa dell'artiglio del corvo","come trovare il talismano artiglio del corvo"}},{q="Chi ha bisogno del Talismano Artiglio del Corvo?",a="Ad Athridas Orsomanto, un druido elfo della notte a Dolanaar, serve il talismano. Lo userà per preparare i riti del risveglio per i suoi simili smarriti.",al={"chi vuole il talismano artiglio del corvo","chi prende il talismano artiglio del corvo","a chi si consegna"}},{q="Perché i druidi non possono svegliarsi senza di esso?",a="Il letargo druidico è una delicata trance nel Sogno di Smeraldo. Senza le Relics of Wakening a fare da ancoraggio al rituale, lo spirito di un dormiente rischia di restarvi smarrito a tempo indeterminato.",al={"perché ai druidi servono le reliquie per svegliarsi","perché le reliquie del risveglio","i druidi possono svegliarsi senza reliquie"}}},fx={["33636b37"]={q="Cos'è il Talismano Artiglio del Corvo?",a="Il Talismano Artiglio del Corvo è una delle quattro sacre Reliquie del Risveglio custodite dai Druidi dell'Artiglio. Conservato all'interno di uno scrigno dedicato nell'Eremo di Ban'ethil, è un componente essenziale del delicato rituale necessario per richiamare in sicurezza i druidi dormienti dal loro letargo nel Sogno di Smeraldo.",al={"cos'è il talismano artiglio del corvo","info talismano artiglio del corvo","reliquia talismano artiglio del corvo"}}},fp="19,210,18.440.0,28.413.0,41.164.0,39.153.0,34.139.0,40.175.0"}
P.entries["item:razorflank-s-medallion"] = {n="Medaglione di Fiancospino",s="Nel cuore delle Gallerie di Lamaspina, Charlga Fiancospino porta il medaglione che simboleggia il suo dominio. La sua riconsegna dà alle sentinelle degli Elfi della Notte la prova della sua caduta.",h="Nel cuore delle Gallerie di Lamaspina, Charlga Fiancospino porta il medaglione che simboleggia il suo dominio.",kw={"agamaggan","charlga fiancospino","falfindel waywarder","lonebrow","gallerie di lamaspina","medaglione di fiancospino","thalanaar"},ang={["faction:Alliance"]="Come avventuriero dell'Alleanza, recuperando il medaglione vendichi Heralath, l'esploratore caduto, e Lonebrow, l'esploratore nano. Così metti al sicuro la via di confine che da Thalanaar conduce a Feralas.",["race:NightElf"]="Come Elfo della Notte, uccidendo Charlga e prendendo il suo medaglione permetti al tuo popolo di studiare in sicurezza le sacre terre corrotte in cui riposa Agamaggan."},sec={{t="Prova della caduta della megera",b="Charlga Fiancospino guida i verrospino di Lamaspina e porta il medaglione. A Thalanaar, Falfindel Waywarder apprende della morte di alcuni esploratori, tra cui Heralath e il nano Lonebrow. Invia gli avventurieri dell'Alleanza contro la guida dei verrospino.\n\nIl medaglione conferma la morte di Charlga alle sentinelle degli Elfi della Notte che sorvegliano i confini di Feralas. Le forze radunate nelle Gallerie hanno perso la loro guida."}},faq={{q="Chi porta il Medaglione di Fiancospino?",a="Charlga Fiancospino porta il medaglione nel cuore delle Gallerie di Lamaspina. È lei a guidare i verrospino di quel luogo.",al={"chi rilascia il medaglione di fiancospino","fonte medaglione di fiancospino","medaglione di charlga"}},{q="A chi deve essere portato questo medaglione?",a="Falfindel Waywarder, a Thalanaar, chiede il medaglione. Vuole la prova che Charlga sia stata uccisa.",al={"chi vuole il medaglione di fiancospino","consegna medaglione di fiancospino","medaglione di falfindel"}},{q="Perché Falfindel ha bisogno della prova della morte di Charlga?",a="Charlga ha radunato una forza ostile di verrospino nelle Gallerie di Lamaspina, minacciando le regioni circostanti. Heralath e Lonebrow erano tra gli esploratori caduti. Il medaglione assicura agli Elfi della Notte che la minaccia immediata è stata sventata, permettendo loro di proseguire le indagini.",al={"perché uccidere charlga","scopo del medaglione","perché serve il medaglione"}}},fx={b119a669={q="Cos'è il Medaglione di Fiancospino?",a="Il Medaglione di Fiancospino è un pegno personale portato da Charlga Fiancospino, la vecchia e leader dei quilboar che dimorano nelle profondità delle Gallerie di Lamaspina. Più che un semplice ornamento, funge da inconfondibile simbolo della sua autorità sulle tribù brulicanti nelle Gallerie, rendendolo il trofeo definitivo della sua caduta.",al={"cos'è il medaglione di fiancospino","storia medaglione di fiancospino","medaglione di charlga fiancospino"}}},fp="22,157,25.393.0,35.98.0,41.100.0,49.269.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Borsa dei Reagenti",s="A Durotar, i cultisti delle Lame Ardenti portano reagenti per la prima Sapta di Fuoco di uno sciamano. Telf Joolam li mescola con il Catrame di Fuoco dei verrospini Razormane per preparare una pozione che permette a un giovane sciamano di vedere il regno del fuoco.",h="A Durotar, i cultisti delle Lame Ardenti portano reagenti per la prima Sapta di Fuoco di uno sciamano.",kw={"lame ardenti","call of fire","durotar","grotta di ventolordo","sapta di fuoco","totem del fuoco","borsa dei reagenti","telf joolam"},ang={["class:Shaman"]="Come sciamano, recuperare la sacca è un rito di passaggio per ottenere il tuo Fire Totem. Ti insegna che le forze elementali corrotte possono essere recuperate e messe al servizio dell'equilibrio.",["class:Warlock"]="Come stregone, riconosci nelle sacche delle scorte magiche per i cultisti del vile. I loro elementi rituali sono destinati alla piromanzia demoniaca, non alla comunione con la natura."},sec={{t="Componenti della Fiamma",b="I cultisti delle Lame Ardenti portano reagenti per la prima Sapta di Fuoco di un giovane sciamano. L'eremita Telf Joolam mescola le polveri e gli oli delle loro sacche con il Catrame di Fuoco dei verrospini Razormane. Insieme, questi ingredienti creano una pozione che permette di vedere il regno del fuoco e sintonizza lo sciamano con gli spiriti della fiamma."},{t="Fonti Corrotte, Visione Pura",b="I cultisti delle Lame Ardenti usano la fiamma per la distruzione e la stregoneria vile. Eppure, gli elementi nelle loro sacche restano legati al calore e alla combustione. Gli sciamani insegnano che le forze elementali esistono in tensione: il fuoco crea e distrugge. Uno sciamano può usare gli strumenti dei cultisti per risvegliare un'autentica comunione con gli spiriti."}},faq={{q="A cosa serve la borsa dei reagenti?",a="Telf Joolam usa i reagenti insieme al Catrame di Fuoco dei verrospini Razormane per preparare una Sapta di Fuoco. Bevendola, uno sciamano ottiene una vista visionaria con cui cercare gli spiriti elementali e rivendicare il Fire Totem.",al={"uso della borsa dei reagenti","a cosa serve la borsa dei reagenti","missione sciamano borsa dei reagenti"}},{q="Dove trovo una borsa dei reagenti?",a="Puoi recuperare una sacca dai cultisti delle Lame Ardenti nella Grotta di Ventolordo, sulle alture rocciose a nord-est di Tranciacolle, a Durotar.",al={"bottino borsa dei reagenti","dove trovare la borsa dei reagenti","posizione borsa delle lame ardenti"}},{q="Perché uno sciamano ha bisogno di reagenti da stregone?",a="I cultisti delle Lame Ardenti riempiono le loro sacche di ingredienti legati alla magia del fuoco. I loro rituali della fiamma rendono i reagenti utili catalizzatori per preparare una Sapta di Fuoco.",al={"perché oggetti da stregone","perché reagenti delle lame ardenti","sciamano che usa oggetti vili"}}},fx={ad39cae0={q="Cos'è la Borsa dei Reagenti?",a="È una piccola borsa portata dai cultisti delle Lame Ardenti, piena di erbe rituali, ceneri e catalizzatori occulti che usano per alimentare i loro incantesimi oscuri. Sebbene destinata alla stregoneria oscura, l'elevata concentrazione di componenti infuocati rende l'intera borsa un potente fascio di materiali elementali grezzi.",al={"cos'è la borsa dei reagenti","storia borsa dei reagenti","borsa dei reagenti lame ardenti"}},["2a611680"]={q="Da dove proviene la Borsa dei Reagenti?",a="Le borse sono assemblate e portate dai cultisti delle Lame Ardenti che si nascondono nelle caverne di Durotar e delle Barrens. Questi stregoni raccolgono e conservano componenti specifici necessari per i loro riti distruttivi, tenendoli a portata di mano ogni volta che lanciano magie di fuoco e Shadow Magic.",al={"origine borsa dei reagenti","chi ha creato la borsa dei reagenti","da dove viene la borsa dei reagenti"}}},fp="22,209,23.316.0,28.307.0,35.189.0,32.126.0,40.160.0"}
P.entries["item:reconstructed-tome"] = {n="Tomo Ricostruito",s="Nelle mani degli stregoni, il Tomo Ricostruito raccoglie gli insegnamenti dispersi della cabala. Le sue pagine custodiscono riti per evocare e vincolare un vilsegugio dalla Distorsione Fatua.",h="Nelle mani degli stregoni, il Tomo Ricostruito raccoglie gli insegnamenti dispersi della cabala.",kw={"vincolo","fauce del drago","felhunter","porto paranco","tomo ricostruito","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Come stregone, ricomporre il Tomo Ricostruito ti dà accesso a riti oscuri per dominare un vilsegugio. La sua fame di magia può essere rivolta contro gli incantatori avversari."},sec={{t="Un grimorio riassemblato",b="Gli stregoni dell'Alleanza e dell'Orda cercano le pagine strappate del Tome of the Cabal. Una volta ricomposto il grimorio, consultano studiosi dell'occulto. Gli studiosi sono impazienti di dare un'occhiata ai suoi rari insegnamenti prima che il libro completo venga consegnato."},{t="La chiave per il felhunter",b="Strahad Farsan riceve il tomo restaurato e le verghe d'incanalamento sottratte agli incantatori Fauce del Drago. È un maestro delle evocazioni che si trova vicino al porto di Porto Paranco, nelle Savane. I rituali del tomo forniscono ai suoi accoliti le parole per evocare un vilsegugio famelico, sopraffarlo e vincolarlo alla volontà di uno stregone."}},faq={{q="A cosa serve il Tomo Ricostruito?",a="Il Tomo Ricostruito custodisce insegnamenti della cabala e riti per evocare e vincolare un vilsegugio. Uno stregone lo porta insieme alle verghe d'incanalamento a Strahad Farsan, a Porto Paranco, per il rituale.",al={"scopo del tomo ricostruito","perché serve il tomo ricostruito","uso del tomo ricostruito"}},{q="Chi è Strahad Farsan?",a="Strahad Farsan è un esperto evocatore che dimora sopra il porto di Porto Paranco, nelle Savane. Supervisiona le prove degli stregoni che cercano di soggiogare demoni più pericolosi.",al={"chi è strahad","ruolo di strahad farsan"}},{q="Perché gli studiosi che esaminano il libro ne vogliono una copia?",a="Gli studiosi che aiutano a decifrare le pagine strappate trovano rari e affascinanti i testi occulti della cabala. I ricercatori nani e Reietti bramano questa conoscenza demoniaca, che supera le loro letture abituali.",al={"chi l'ha tradotto","studiosi tomo ricostruito"}},{q="Cos'altro serve insieme al tomo per il rituale?",a="Strahad richiede tre verghe d'incanalamento per aiutare i suoi accoliti a sostenere il rituale d'evocazione. Gli incantatori Fauce del Drago nelle Paludi Grigie sono in possesso delle verghe.",al={"altri oggetti necessari","cosa serve insieme al tomo ricostruito"}}},fx={a9385a16={q="Cos'è il Tomo Ricostruito?",a="Il Tomo Ricostruito è la versione riassemblata del Tome of the Cabal, un grimorio proibito contenente rituali demoniaci esoterici. Dopo che le sue pagine sparse e i materiali di rilegatura sono stati raccolti da tutto il mondo, gli studiosi riassemblano minuziosamente il testo frammentato in modo che la sua oscura conoscenza possa essere decifrata e messa in uso.",al={"cos'è il tomo ricostruito","storia tomo ricostruito","libro tome of the cabal"}},d276d405={q="Da dove proviene il Tomo Ricostruito e chi l'ha creato?",a="Il libro è la forma recuperata dell'antico Tome of the Cabal. Gli studiosi stregoni riassemblano i suoi capitoli strappati e la rilegatura logora dopo che praticanti avventurosi recuperano i suoi componenti sparsi da luoghi pericolosi in tutti i continenti.",al={"origine tomo ricostruito","chi ha creato il tomo ricostruito","da dove viene il tomo ricostruito"}},["04500ccd"]={q="Perché il Tomo Ricostruito è ricercato?",a="Stregoni e studiosi oscuri cercano il tomo per i segreti potenti e proibiti registrati nelle sue pagine recuperate. Strahad Farsan richiede i suoi riti specifici per guidare un aspirante stregone nell'evocazione e nel legame di un feroce felhunter demoniaco, mentre gli studiosi locali desiderano una copia puramente per la sua rara e affascinante conoscenza magica.",al={"perché volere il tomo ricostruito","perché strahad vuole il tomo ricostruito","scopo del tomo ricostruito"}}},fp="18,172,22.250.0,20.291.1,40.182.0,22.160.0,51.199.0,54.146.0"}
P.entries["item:recruitment-letter"] = {n="Lettera di Reclutamento",s="A Durotar, Takrin Trovapista invia avventurieri promettenti a ovest per prestare servizio nelle Savane. La sua lettera indirizza i volontari idonei al servizio all'avamposto di confine di Kargal Sfregiofondo.",h="A Durotar, Takrin Trovapista invia avventurieri promettenti a ovest per prestare servizio nelle Savane.",kw={"savane","coscritto dell'orda","crocevia","kargal sfregiofondo","tranciacolle","lettera di reclutamento","takrin trovapista"},ang={["faction:Horde"]="Come membro dell'Orda, portare questa lettera segna il tuo passaggio dalla difesa locale di Durotar al servizio militare attivo lungo la frontiera di Kalimdor.",["race:Orc"]="Per un giovane orco come te, presentare una lettera di servizio firmata a un veterano come Kargal Sfregiofondo è uno dei primi passi per guadagnare onore nella nuova Orda del Capoguerra Thrall."},sec={{t="Arruolamento per la Frontiera",b="Nei dintorni di Tranciacolle, Takrin Trovapista osserva giovani guerrieri ed esploratori dare prova del loro valore. Sceglie quelli abbastanza forti per il servizio in prima linea e consegna loro una lettera per prestare servizio nelle Savane. Le reclute attraversano il ponte sul Fiume Furialunga, lasciano la protetta terra rossa di Durotar e si uniscono alle difese dell'Orda contro verrospini, centauri ed esploratori dell'Alleanza."},{t="Rapporto a Sfregiofondo",b="Appena oltre il fiume, Kargal Sfregiofondo accoglie le reclute all'avamposto. Il veterano brizzolato gestisce il presidio e valuta ogni coscritto prima di approvarne l'arruolamento. Le reclute che ricevono la sua approvazione vengono presto inviate più a ovest, a Crocevia, dove gli avamposti di frontiera sono a corto di effettivi."}},faq={{q="Chi ha scritto questa lettera di reclutamento?",a="Takrin Trovapista consegna la lettera. L'esploratore orco è di stanza lungo la strada che parte da Tranciacolle e cerca reclute capaci dirette a ovest.",al={"chi consegna la lettera di reclutamento","chi l'ha scritta","lettera di takrin trovapista"}},{q="Dove deve andare questa lettera?",a="Porta la lettera a Kargal Sfregiofondo al posto di guardia degli orchi appena oltre il ponte sul Fiume Furialunga, al confine tra Durotar e le Savane.",al={"dove portare la lettera di reclutamento","consegnare lettera di reclutamento","a chi consegnarla"}},{q="Cosa succede una volta firmata la lettera?",a="Kargal firma il documento per ufficializzare il tuo arruolamento, poi ti ordina di addentrarti nelle pianure per prendere servizio a Crocevia, dove servono urgentemente rinforzi.",al={"cosa succede dopo la firma di kargal","missione successiva a lettera di reclutamento"}},{q="Perché l'Orda arruola avventurieri nelle Savane?",a="L'Orda arruola avventurieri perché le Savane sono una terra vasta e pericolosa che collega i suoi principali insediamenti. I clan dei centauri, gli aggressivi verrospini Bristleback e le operazioni dell'Alleanza mantengono costante la minaccia, quindi ai comandanti in prima linea serve ogni braccio valido.",al={"perché stanno reclutando","perché la coscrizione nelle savane"}}},fx={e6a35429={q="Cos'è la Lettera di Reclutamento?",a="La Lettera di Reclutamento è un documento ufficiale di coscrizione rilasciato ad avventurieri capaci a Durotar. Lo Scout Takrin Trovapista la consegna a coloro che sembrano abbastanza forti da assistere la crescente presenza dell'Orda nella dura frontiera delle Barrens, raccomandandoli ai comandanti degli avamposti militari.",al={"cos'è la lettera di reclutamento","scopo lettera di reclutamento","cos'è questa lettera"}},["6a5949ec"]={q="Perché Kargal Sfregiofondo vuole la Lettera di Reclutamento?",a="Kargal Sfregiofondo comanda l'avamposto di frontiera che protegge il ponte verso le Barrens e ha un disperato bisogno di reclute capaci per rafforzare la frontiera. La lettera firmata verifica che sei stato esaminato dallo Scout Takrin Trovapista e sei pronto per essere assegnato dove l'Orda ha più bisogno di te.",al={"perché kargal vuole la lettera","perché consegnare la lettera di reclutamento","lettera di reclutamento consegnata"}}},fp="18,168,27.348.0,23.286.0,34.141.0,34.139.0,39.174.0,57.263.0"}
P.entries["item:red-burlap-bandana"] = {n="Bandana Avvolta Rossa",s="Vicino ai vigneti dell'abbazia nella Valle della Contea del Nord, il Deputy Willem raccoglie bandane rosse dai ladri Defias uccisi. La stoffa contraddistingue i briganti e i borsaioli di basso rango della Fratellanza.",h="Vicino ai vigneti dell'abbazia nella Valle della Contea del Nord, il Deputy Willem raccoglie bandane rosse...",kw={"bandana","brotherhood of thieves","defias","maschera","contea del nord","bandana avvolta rossa","willem"},ang={["class:Rogue"]="Come ladro alle prime armi, puoi imparare dai maldestri predoni della Contea del Nord quanto rapidamente i fuorilegge indisciplinati diventino facili bersagli per le guardie locali.",["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere le bandane rosse arrivare alle porte dell'Abbazia della Contea del Nord, segno che Roccavento sta perdendo il controllo dei confini rurali del regno."},sec={{t="Un segno della Fratellanza",b="Nella Contea del Nord, le giovani reclute e i comuni scagnozzi della Fratellanza dei Defias indossano maschere rosse di tela di sacco. La stoffa ruvida ed economica nasconde i loro volti e ne segnala la fedeltà alla crescente ribellione. Portano queste sciarpe nei frutteti orientali, dove le guardie locali riconoscono il tessuto rosso come prova dell'uccisione di ladri nelle vicinanze."}},faq={{q="Perché il Deputy Willem vuole queste bandane?",a="Il Deputy Willem raccoglie le bandane come prova che un avventuriero ha ucciso degli scagnozzi Defias vicino all'Abbazia della Contea del Nord. I ladri indossano apertamente la stoffa rossa, confermando che la taglia è stata riscossa.",al={"perché raccogliere le bandane","bandane willem","consegna brotherhood of thieves"}},{q="Chi indossa le Bandane Avvolte Rosse?",a="I predoni e gli scagnozzi della Fratellanza dei Defias indossano bandane rosse di tela di sacco. La stoffa grezza nasconde i loro volti e ne segnala la fedeltà ai fuorilegge.",al={"chi indossa la bandana rossa","storia maschera defias","chi rilascia le bandane rosse"}},{q="Perché i ladri Defias operano nella Contea del Nord?",a="Esploratori e briganti Defias si accampano oltre il ruscello a est dell'Abbazia della Contea del Nord per raccogliere e rubare provviste. La guarnigione dell'abbazia è a corto di uomini, e i frutteti vicini restano esposti ai briganti.",al={"perché i defias si trovano nella contea del nord","ladri vicino all'abbazia"}},{q="Cosa rende rosse le bandane?",a="Una tintura cremisi dona il colore rosso alle economiche bandane di tela di sacco. Questa tonalità è lo stendardo e l'uniforme della Fratellanza dei Defias e aiuta i suoi membri a riconoscersi sul campo.",al={"perché le maschere defias sono rosse","significato stoffa rossa"}}},fx={c4ebebb0={q="Cos'è una Bandana Avvolta Rossa?",a="Una Bandana Avvolta Rossa è la maschera di stoffa distintiva indossata dai membri della Fratellanza dei Defias. Realizzata a buon mercato con ruvida iuta e tinta di rosso, nasconde il volto di chi la indossa e segna la loro lealtà alla gilda dei fuorilegge. Nella Contea del Nord, funge da prova diretta della presenza e dell'attività di un delinquente a est del fiume.",al={"identità bandana avvolta rossa","cosa sono le bandane rosse","storia bandana defias"}}},fp="18,180,25.319.0,43.189.0,34.148.0,47.188.0,28.172.0"}
P.entries["item:red-leather-bandana"] = {n="Bandana di Cuoio Rossa",s="Nelle Marche Occidentali, la Bandana di Cuoio Rossa contraddistingue chi sfida la Corona di Roccavento. I membri della Fratellanza dei Defias la indossano per coprirsi il volto e manifestare la propria causa.",h="Nelle Marche Occidentali, la Bandana di Cuoio Rossa contraddistingue chi sfida la Corona di Roccavento.",kw={"fratellanza","defias","galiaan","maschera","bandana di cuoio rossa","guardiacolle","marche occidentali"},ang={["class:Rogue"]="Come ladro, conosci la maschera cremisi come un simbolo del banditismo clandestino nelle terre umane. La indossano ladri organizzati con precisione militare.",["faction:Alliance"]="Per l'Alleanza, ogni bandana rossa sottratta a un fuorilegge caduto significa un brigante in meno a minacciare i contadini affamati e la milizia assediata delle Marche Occidentali."},sec={{t="Marchio della Fratellanza",b="Tra i campi e le fattorie abbandonate delle Marche Occidentali, briganti, saccheggiatori e braccianti ribelli indossano bandane cremisi per nascondere il volto. La People's Militia di Guardiacolle considera ciascuna una prova di fedeltà alla confraternita fuorilegge di Edwin VanCleef. L'Esploratore Galiaan raccoglie le bandane dai viaggiatori per seguire gli spostamenti della Fratellanza e il calo dei suoi membri in tutta la regione."}},faq={{q="Perché i Defias indossano bandane di cuoio rosse?",a="I Defias indossano bandane rosse per nascondere il volto mentre compiono razzie nelle fattorie e lungo le strade. Mostrano anche la loro fedeltà alla rivolta di Edwin VanCleef contro Roccavento.",al={"maschera defias","perché bandana rossa","significato bandana defias"}},{q="Chi richiede la raccolta di queste bandane nelle Marche Occidentali?",a="L'Esploratore Galiaan della People's Militia di Guardiacolle chiede ai viaggiatori di raccogliere le bandane. Le usa per seguire gli spostamenti della banda e confermare la morte dei banditi che si aggirano nella zona.",al={"chi prende le bandane rosse","missione bandana galiaan","consegna bandana guardiacolle"}},{q="Dove si trovano queste bandane?",a="Ladri, briganti e contrabbandieri dei Defias portano queste bandane negli accampamenti, nei campi e nelle miniere di tutte le Marche Occidentali.",al={"bottino bandana rossa","farmare bandane rosse","chi rilascia bandana di cuoio rossa"}}},fp="19,153,23.372.1,44.153.1,47.179.0,31.112.0"}
P.entries["item:red-linen-bandana"] = {n="Red Linen Bandana",s="In tutta la Foresta di Elwynn, la Red Linen Bandana identifica la Fratellanza dei Defias e nasconde il volto di chi la indossa. Sara Timberlain, al Campo di Taglio di Vallevante, vuole la stoffa per ricavarne indumenti e bende.",h="In tutta la Foresta di Elwynn, la Red Linen Bandana identifica la Fratellanza dei Defias e nasconde il volto...",kw={"maschera defias","vallevante","foresta di elwynn","lino","red linen bandana","sara timberlain"},ang={["class:Rogue"]="Da ladro, conosci la stoffa cremisi annodata sulla parte inferiore del volto. Contraddistingue i briganti e i tagliaborse nei boschi attorno alla capitale.",["profession:Tailoring"]="Nelle campagne di Elwynn, i tessitori possono trasformare il lino delle maschere dei banditi in abiti da lavoro."},sec={{t="Marchio dei Defias",b="Nella Valle della Contea del Nord, gli iniziati e i comuni teppisti indossano maschere di ruvida tela di sacco. Il lino cremisi indica la fedeltà dei membri a pieno titolo alla confraternita di canaglie di Edwin VanCleef. Segnala anche la ribellione contro la corona di Roccavento."},{t="Stoffa riutilizzata",b="Sara Timberlain chiede ai viaggiatori di raccogliere bandane dagli accampamenti dei fuorilegge. Le maschere sono legate ai banditi, ma il loro lino è di buona qualità. Lavata e lavorata con un ago, la stoffa può diventare abiti robusti e bende per i lavoratori della foresta."}},faq={{q="Perché i Defias indossano red linen bandana?",a="I membri dei Defias indossano Red Linen Bandana per nascondere il volto. La stoffa indica anche la loro fedeltà alla confraternita di Edwin VanCleef e la loro sfida a Roccavento.",al={"significato maschera defias","perché maschere rosse","bandana rossa defias"}},{q="In che cosa differiscono da quelle indossate nella Contea del Nord?",a="I teppisti della Valle della Contea del Nord indossano maschere di ruvida tela di sacco. I membri affermati dei Defias in tutta la Foresta di Elwynn indossano lino rosso più pregiato.",al={"tela di sacco contro lino","maschere della contea del nord","bandana di tela di sacco"}},{q="Chi vuole raccogliere queste bandane?",a="Sara Timberlain, al Campo di Taglio di Vallevante, vuole le bandane. Lava e disfa le maschere per tessere indumenti pratici.",al={"chi accetta red linen bandana","bandana sara timberlain","consegna missione bandana"}},{q="Quali nemici trasportano red linen bandana?",a="I membri dei Defias in tutta la Foresta di Elwynn portano Red Linen Bandana. Tra loro ci sono Banditi Defias, Ambushers, Rogue Wizards, lavoratori portuali e capibanda come Morgan il Collezionista.",al={"chi rilascia red linen bandana","dove farmare bandane","bottino bandana defias"}}},fp="17,190,18.223.0,16.251.0,42.165.0,54.122.0,36.127.0,39.178.0"}
P.entries["item:red-wool-bandana"] = {n="Bandana di Lana Rossa",s="Nelle Segrete di Roccavento, i brandelli di Bandana di Lana Rossa contraddistinguono la Fratellanza dei Defias. I prigionieri strappano la lana dalle loro coperte e indossano il tessuto rosso come emblema di sfida.",h="Nelle Segrete di Roccavento, i brandelli di Bandana di Lana Rossa contraddistinguono la Fratellanza dei...",kw={"defias","mac raskol","nikova raskol","bandana di lana rossa","roccavento","the color of blood","segrete di roccavento"},ang={["faction:Alliance"]="Per i difensori dell'Alleanza, recuperare queste bandane rende una cupa giustizia al giovane Mac Raskol e colpisce i rivoltosi che controllano la prigione della città.",["profession:Tailoring"]="Queste rozze bandane mostrano come mani disperate, in prigionia, possano disfare coperte di lana grezza e riutilizzarne le fibre."},sec={{t="Cucite con Sfida",b="Nelle Segrete di Roccavento, i detenuti della Fratellanza dei Defias mantengono viva la propria identità. In segreto strappano brandelli dalle coperte di lana della prigione e li cuciono per farne bandane rosse. Le guardie considerano queste sciarpe oggetti di contrabbando, e il loro ritrovamento può scatenare ammutinamenti mortali. Ogni bandana proclama che la fratellanza e la sua ribellione resistono, persino in catene."},{t="La Vendetta di una Nonna",b="Le Bandane di Lana Rossa sono legate alla morte di Mac Raskol, una guardia carceraria di quattordici anni. Sorprese i detenuti a fare a brandelli le coperte per ricavarne sciarpe e tentò di punirli. I galeotti Defias lo pugnalarono alla schiena. Sua nonna Nikova, affranta dal dolore, ora cerca avventurieri che entrino nella prigione in rivolta, abbattano i rivoltosi e riportino un panno cremisi come prova di vendetta."}},faq={{q="Dove si procurano queste bandane i prigionieri nelle Segrete di Roccavento?",a="I detenuti Defias ricavano le bandane strappando le coperte di lana in dotazione nella prigione. Benché disarmati e imprigionati, trasformano le loro misere coperte in simboli di sfida da indossare nelle celle.",al={"da dove vengono le bandane","fonte bandane segrete di roccavento","come si fanno le bandane rosse"}},{q="Chi vuole che queste bandane vengano raccolte?",a="Nikova Raskol, una nonna affranta dal dolore a Roccavento, chiede agli avventurieri di raccogliere le bandane. Suo nipote Mac, di quattordici anni, sorvegliava le Segrete di Roccavento, e i prigionieri lo uccisero dopo che li aveva sorpresi a fabbricare le sciarpe.",al={"a chi servono le bandane di lana rossa","chi assegna la missione color of blood","nikova raskol bandana"}},{q="Perché ai prigionieri importa così tanto indossare sciarpe rosse?",a="La Fratellanza dei Defias indossa maschere e bandane rosse come colori distintivi e uniforme della banda. Dietro le sbarre, i brandelli aiutano i detenuti a mantenere il proprio rango, il morale e l'unità.",al={"perché bandane rosse","simbolo rosso defias","significato della bandana rossa"}},{q="Quali detenuti le hanno con sé?",a="Quasi ogni membro dei Defias in rivolta nelle Segrete di Roccavento ne porta una, compresi Defias Captives, Inmates, Prisoners, Insurgents e Convicts.",al={"chi rilascia la bandana di lana rossa","bottino bandane segrete di roccavento"}}},fx={["7f0c1a2a"]={q="Cos'è una Bandana di Lana Rossa?",a="Una Bandana di Lana Rossa è una sciarpa cremisi improvvisata creata dai membri imprigionati della Fratellanza dei Defias all'interno delle Segrete di Roccavento. Facendo a pezzi e tingendo le coperte di lana fornite dalla prigione, i detenuti creano questi pegni di stoffa per mostrare apertamente la loro lealtà alla Fratellanza e mantenere la loro identità di banda anche dietro le sbarre.",al={"cos'è la bandana di lana rossa","oggetto bandana di lana rossa","bandana rossa delle segrete"}}},fp="16,166,20.335.0,25.366.0,54.181.0,35.218.0,60.156.0,25.134.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="Ultime Gocce di Acqua Purissima",s="Tra Kalimdor e Lordaeron, le Ultime Gocce di Acqua Purissima attendono un viaggio pericoloso. Brine ha raccolto l'acqua per una pozione destinata ad aiutare gli sciamani.",h="Tra Kalimdor e Lordaeron, le Ultime Gocce di Acqua Purissima attendono un viaggio pericoloso.",kw={"braciere della sorgente eterna","brine","call of water","manifestazione corrotta","acqua purissima","selva pinargento","totem dell'acqua"},ang={["class:Shaman"]="Come sciamano, porti le gocce dalle aride Savane alla costa piagata della Selva Pinargento durante le prove per padroneggiare l'acqua. Questo pellegrinaggio è essenziale per ottenere il tuo Water Totem.",["faction:Horde"]="Come membro dell'Orda, viaggi dai territori dell'Orda a Kalimdor fino ai precari possedimenti dei Reietti nella Selva Pinargento. Lungo questa distanza, il pellegrinaggio porta rinnovamento spirituale contro la piaga del Flagello."},sec={{t="Un rimedio per le acque contaminate",b="Nelle Savane, Brine prepara una pozione con l'acqua raccolta tra Kalimdor e Lordaeron. Una parte permette agli sciamani di vedere elementi lontani. Le gocce rimaste hanno uno scopo più arduo.\n\nGli sciamani le portano sulla costa della Selva Pinargento, vicino a Mausolea, dove sorge il Braciere della Sorgente Eterna. Lì bruciano le gocce insieme ai bracciali di un elementale caduto e corrotto. L'acqua pura penetra la corruzione della piaga dei non morti e richiama uno spirito dell'acqua incontaminato affinché entri in comunione con lo sciamano. Così la loro comunione con l'elemento è completa."}},faq={{q="A cosa servono queste gocce?",a="Sulla costa della Selva Pinargento, le gocce vengono bruciate sul Braciere della Sorgente Eterna insieme ai bracciali di una manifestazione dell'acqua corrotta. Il rito purifica il santuario elementale corrotto ed evoca uno spirito dell'acqua incontaminato.",al={"a cosa servono le ultime gocce","scopo delle ultime gocce","usare l'acqua purissima"}},{q="Da dove proviene il liquido?",a="Brine, una sciamana orchesca che vive su una collina nella parte meridionale delle Savane, ha preparato la pozione. La prepara durante le prove spirituali degli aspiranti sciamani, e queste gocce sono ciò che ne rimane.",al={"chi ha creato l'acqua purissima","origine delle gocce","brine gocce d'acqua"}},{q="Perché il rituale viene celebrato fino alla Selva Pinargento?",a="Un santuario dell'acqua sulla costa della Selva Pinargento, a ovest di Mausolea, è stato corrotto dalla piaga della non morte. I suoi spiriti elementali sono diventati ostili e distorti. Purificare la pozza mette alla prova la devozione di uno sciamano e la sua padronanza dell'elemento su grandi distanze.",al={"perché selva pinargento","perché andare a selva pinargento","santuario dell'acqua di selva pinargento"}},{q="Cosa succede quando toccano il braciere?",a="Versate sulle fiamme del braciere insieme ai bracciali corrotti, le gocce crepitano nel fuoco. L'incantesimo purifica la piaga persistente ed evoca una manifestazione dell'acqua pura.",al={"rituale del braciere","cosa succede sul braciere","rituale del braciere della sorgente eterna"}}},fx={db79eea5={q="Cosa sono le Ultime Gocce di Acqua Purissima?",a="Questa piccola fiala contiene gli ultimi resti della pozione purificante preparata dall'eremita Brine nelle Savane Meridionali. Infuso con acqua raccolta dalle Barrens, dal Mulino di Tarren e da Valtetra, il potente liquido possiede immense proprietà purificanti. Sebbene rimangano solo poche gocce, la sua purezza concentrata è sufficiente per tagliare la corruzione persistente quando offerta nei riti elementali.",al={"cosa sono le ultime gocce di acqua purissima","cosa sono le gocce di acqua purissima","storia gocce di acqua purissima"}},["55d7092f"]={q="Perché Islen Scruta Lagune vuole che tu usi le Ultime Gocce di Acqua Purissima?",a="Islen Scruta Lagune richiede che tu versi le gocce sul Braciere di Everfount nella Selva Pinargento. Un sacro santuario dell'acqua lì ha ceduto alla piaga dei non morti, assordando i suoi spiriti locali alla comunione sciamanica. Offrendo queste gocce rimanenti insieme ai bracciali di una manifestazione corrotta caduta, il braciere può accendere un rituale purificante abbastanza potente da evocare uno spirito d'acqua pura.",al={"perché usare le gocce di acqua purissima","perché servono le ultime gocce di acqua purissima","perché ti servono le gocce di acqua purissima"}}},fp="31,152,27.549.0,30.221.0,31.181.0,61.235.0,41.179.0"}
P.entries["item:remedy-of-arugal"] = {n="Rimedio di Arugal",s="Nella Selva Pinargento, Dalar Tessalba cerca l'incantesimo di Arugal per capire come funziona la sua magia dei worgen.",h="Nella Selva Pinargento, Dalar Tessalba cerca l'incantesimo di Arugal per capire come funziona la sua magia...",kw={"arugal","arugal's folly","dalar tessalba","libri degli incantesimi impolverati","furia lunare","rimedio di arugal","mausolea","selva pinargento"},ang={["class:Mage"]="Come mago dei Reietti, potresti condividere il disprezzo di Dalar Tessalba per gli esperimenti maldestri e avventati di Arugal, pur riconoscendo il pericolo della magia di evocazione incontrollata.",["race:Undead"]="Come membro dei Reietti, contribuisci a recuperare questo incantesimo come primo passo vitale contro i worgen feroci che minacciano i confini della Selva Pinargento."},sec={{t="Il Rimasuglio di un mago",b="Prima di impadronirsi del Forte di Zannascura, l'Arcimago Arugal si rifugiò in una fattoria di grano abbandonata a nord del ponte sul fiume nella Selva Pinargento. Tra attrezzi agricoli e assi marcescenti del pavimento, lasciò libri degli incantesimi che documentavano le sue strane arti. Una pergamena, il Rimedio di Arugal, descrive i primi metodi e le formule magiche dei suoi esperimenti con le trasmutazioni che maledissero la popolazione locale."},{t="L'esame dei Reietti",b="A Mausolea, Dalar Tessalba è un incantatore dei Reietti che ha poca considerazione della reputazione di Arugal. Ritiene l'intelletto di Arugal fragile e trasparente. Eppure, Tessalba deve capire come funziona la maledizione dei worgen. Recuperare il Rimedio fornisce agli agenti dei Reietti le conoscenze arcane che cerca per contrastare la crescente minaccia di Arugal e assicurare a Lady Sylvanas il controllo della Selva Pinargento."}},faq={{q="Che cos'è il Rimedio di Arugal?",a="Il Rimedio di Arugal documenta i metodi arcani usati da Arugal nei suoi primi esperimenti con la magia dei worgen nella Selva Pinargento.",al={"cos'è il rimedio di arugal","oggetto rimedio di arugal","incantesimo rimedio"}},{q="Dove è stato lasciato il Rimedio?",a="Arugal lasciò il Rimedio tra polverosi libri degli incantesimi al piano superiore di una fattoria di grano abbandonata a nord del ponte sul fiume nella Selva Pinargento.",al={"dove trovare il rimedio di arugal","posizione rimedio di arugal","libro degli incantesimi della fattoria"}},{q="Perché Dalar Tessalba vuole questo incantesimo?",a="Dalar Tessalba vuole studiare la magia di Arugal affinché i Reietti trovino il modo di contrastarla e assicurarsi il controllo della Selva Pinargento.",al={"perché dalar vuole il rimedio","rimedio di dalar tessalba"}},{q="Chi fa la guardia ai libri degli incantesimi alla fattoria?",a="I servitori lupini di Arugal infestano la fattoria. Quando qualcuno disturba i polverosi libri degli incantesimi al secondo piano, un Moonrage Darkrunner balza fuori per difendere gli averi del suo padrone.",al={"cosa attacca alla fattoria","imboscata del libro degli incantesimi"}}},fx={["157696b2"]={q="Da dove viene il Rimedio di Arugal e chi lo ha creato?",a="Il Rimedio di Arugal è un incantesimo scritto dall'Arcimago Arugal in persona durante i suoi primi giorni nella Selva Pinargento. Dopo che i suoi piani iniziarono a prendere forma, risiedette brevemente in una fattoria di grano a nord del ponte principale del fiume, lasciando dietro di sé polverosi libri di incantesimi contenenti le sue ricerche.",al={"chi ha creato il rimedio di arugal","origine del rimedio di arugal","da dove viene il rimedio di arugal"}}},fp="16,96,18.379.0,17.375.0,29.124.0,33.136.0,42.113.0,38.171.0"}
P.entries["item:rendered-spores"] = {n="Spore Trasformate",s="Le Spore Trasformate attraversano in fretta le Savane verso Picco del Tuono prima che la loro emulsione si degradi. Apothecary Zamah deve stabilizzarla sotto la città.",h="Le Spore Trasformate attraversano in fretta le Savane verso Picco del Tuono prima che la loro emulsione si...",kw={"speziale helbrim","apothecary zamah","savane","crocevia","emulsione","pozze delle visioni","spore trasformate","picco del tuono"},ang={["race:Tauren"]="Come tauren, vedi gli speziali dei Reietti condurre esperimenti sulla strana flora delle Savane nelle sacre Pozze delle Visioni. Il loro lavoro riflette l'alleanza tesa e pragmatica stretta a Picco del Tuono.",["race:Undead"]="Come non morto, appartieni a un popolo la cui Royal Apothecary Society cerca composti biologici in tutta Kalimdor per aiutare i Reietti. Corrieri veloci collegano ricercatori sul campo come Helbrim a specialisti come Zamah."},sec={{t="Una Miscela Volatile",b="Vicino alle umide oasi delle Savane, lo Speziale Helbrim raccoglie spore fungine e le trasforma in un'emulsione chimica attiva. La miscela è instabile. Dopo quarantacinque minuti, si degrada e non può più essere studiata."},{t="Consegna alle Pozze delle Visioni",b="Nel suo remoto avamposto, lo Speziale Helbrim non può completare la raffinazione dell'emulsione. Deve arrivare alla sua collega dei Reietti, Apothecary Zamah, sotto l'Altura degli Spiriti a Picco del Tuono. Nelle Pozze delle Visioni, Zamah dispone delle attrezzature e dei reagenti per sigillare nuovamente le spore e completarne la lavorazione per la Royal Apothecary Society."}},faq={{q="A cosa servono le Spore Trasformate?",a="Lo Speziale Helbrim trasforma la materia fungina in un'emulsione destinata agli studi della Royal Apothecary Society. A Picco del Tuono, Apothecary Zamah la usa per continuare a indagare sulle strane escrescenze che si diffondono nelle Savane.",al={"scopo delle spore trasformate","cosa fa zamah con le spore","perché spore trasformate"}},{q="Perché l'emulsione ha un limite di tempo?",a="L'emulsione preparata dallo Speziale Helbrim è volatile e comincia a degradarsi non appena viene miscelata. La sua efficacia dura solo quarantacinque minuti, quindi deve attraversare le pianure fino a Picco del Tuono prima di diventare inerte.",al={"perché le spore trasformate hanno un tempo limite","perché le spore scadono","durata delle spore trasformate"}},{q="Chi ha creato queste spore?",a="A Crocevia, nelle Savane, lo Speziale Helbrim trasforma le spore fungine grezze raccolte vicino alle oasi in un composto liquido instabile.",al={"chi ha creato le spore trasformate","chi trasforma le spore","spore di helbrim"}},{q="Dove deve andare la miscela?",a="La miscela deve raggiungere Apothecary Zamah nelle Pozze delle Visioni, sotto l'Altura degli Spiriti a Picco del Tuono, la capitale dei tauren.",al={"dove portare le spore trasformate","posizione di zamah","posizione delle pozze delle visioni"}}},fx={["7897c588"]={q="Cosa sono le Spore Trasformate?",a="Le Spore Trasformate sono l'estratto lavorato di strane escrescenze fungine raccolte in tutte le The Barrens. Lo Speziale Helbrim ha bollito e trasformato le spore grezze in un'emulsione liquida volatile e instabile, preparando accuratamente la miscela per un ulteriore studio alchemico da parte dello Speziale Reale.",al={"cosa sono le spore trasformate","info sulle spore trasformate","cosa sono le spore"}}},fp="15,153,18.219.0,31.310.0,34.217.0,40.211.0,25.134.0,34.120.0"}
P.entries["item:renferrel-s-findings"] = {n="Scoperte di Renferrel",s="Nella Selva Pinargento, le Scoperte di Renferrel portano le sue ricerche a sud, al Mulino di Tarren. Lo Speziale Renferrel ha raccolto gli appunti a Mausolea per lo Speziale Lydon, che contribuisce a preparare la New Plague dei Reietti.",h="Nella Selva Pinargento, le Scoperte di Renferrel portano le sue ricerche a sud, al Mulino di Tarren.",kw={"scoperte","lydon","nuova piaga","renferrel","società degli speziali reali","mausolea","mulino di tarren"},ang={["faction:Horde"]="Come membro dell'Orda, sai che i corrieri con i documenti di Renferrel collegano avamposti come Mausolea e il Mulino di Tarren, rafforzando la presenza dell'Orda in tutta Lordaeron.",["race:Undead"]="Come non morto, sai che questi documenti servono l'ambizione di Sylvanas Ventolesto: perfezionare una New Plague contro il Flagello e i nemici viventi che invadono le terre dei Reietti."},sec={{t="Una Piaga in Sviluppo",b="A Mausolea, lo Speziale Renferrel documenta il suo lavoro sulla New Plague. La Società degli Speziali Reali risponde direttamente a Lady Sylvanas Ventolesto, la Dama Oscura. I ricercatori sparsi per Lordaeron devono unire i loro sforzi per giungere a una svolta. Così Renferrel invia le sue scoperte a sud, al Mulino di Tarren, dove gli altri speziali possono proseguire il lavoro partendo dai suoi risultati."},{t="Verso il Mulino di Tarren",b="I documenti di Renferrel collegano la Selva Pinargento alle Alture di Colletorto e al lavoro alchemico dei Reietti. Lo Speziale Lydon attende gli appunti al Mulino di Tarren, dove può confrontarli con le proprie ricerche contro i vivi e il Flagello. Le strade di Colletorto sono contese, perciò la Società dipende da corrieri affidabili. Senza di loro, le sue ricerche sparse sul territorio si fermerebbero presto."}},faq={{q="Cosa contengono le Scoperte di Renferrel?",a="Le Scoperte di Renferrel contengono le ultime ricerche e i dati sperimentali dello Speziale Renferrel provenienti dalla Selva Pinargento. Gli appunti riguardano il lavoro dei Reietti per preparare una New Plague.",al={"cosa sono le scoperte","ricerche di renferrel","cosa c'è negli appunti"}},{q="Chi dovrebbe ricevere questa ricerca?",a="Lo Speziale Lydon deve ricevere i documenti. Conduce ricerche sulla piaga al Mulino di Tarren, un insediamento dei Reietti nelle Alture di Colletorto.",al={"chi riceve le scoperte di renferrel","dove vanno le scoperte","destinazione della consegna"}},{q="Perché gli speziali condividono gli appunti?",a="Lady Sylvanas Ventolesto ha ordinato alla Società degli Speziali Reali di creare una New Plague. Gli speziali credono che confrontare i risultati porterà a una svolta molto prima che lavorando da soli.",al={"perché condividere le scoperte","perché inviare a lydon","comunicazione tra speziali"}},{q="Dove conduce i suoi esperimenti lo Speziale Renferrel?",a="Lo Speziale Renferrel conduce i suoi esperimenti a Mausolea, il principale avamposto dei Reietti nel cuore della Selva Pinargento.",al={"dove si trova renferrel","posizione dello speziale renferrel","chi ha scritto le scoperte di renferrel"}}},fx={f680c460={q="Cosa sono le Scoperte di Renferrel?",a="Le Scoperte di Renferrel sono una raccolta di appunti alchemici e documenti di ricerca compilati dallo Speziale Renferrel. Dettagliano i suoi esperimenti in corso condotti per conto dello Speziale Reale, destinati ad essere condivisi direttamente con i suoi colleghi in tutta Lordaeron.",al={"cosa sono le scoperte di renferrel","oggetto scoperte di renferrel","cosa sono queste scoperte"}},bf8d559a={q="Da dove vengono le Scoperte di Renferrel e chi le ha create?",a="Questi documenti sono stati scritti dallo Speziale Renferrel, un ricercatore ambizioso di stanza a Mausolea nella Selva Pinargento. Lavorando diligentemente sotto il mandato dei Reietti, ha scritto questi appunti per registrare i suoi progressi e le sue scoperte nella preparazione di miscele sperimentali.",al={"chi ha scritto le scoperte di renferrel","da dove vengono le scoperte di renferrel","creatore delle scoperte di renferrel"}},["21b2c0f4"]={q="Perché qualcuno vuole le Scoperte di Renferrel?",a="Lo Speziale Reale affronta un'immensa pressione da parte di Sylvanas Ventolesto per preparare A New Plague. Credendo che la collaborazione accelererà il loro cupo lavoro, Renferrel ha inviato la sua ricerca allo Speziale Lydon a Mulino di Tarren, che è ansioso di studiare i metodi del suo collega e integrarli nei propri sforzi.",al={"perché consegnare le scoperte di renferrel","chi vuole le scoperte di renferrel","perché lydon vuole le scoperte di renferrel"}}},fp="20,209,23.354.0,14.377.0,36.173.0,41.139.0,39.189.0,56.127.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="Rapporto sulla Fratellanza dei Defias",s="Al Forte di Roccavento, i risultati dell'indagine sulla Fratellanza dei Defias giungono alla corte reale. L'architetto cittadino Baros Alexston affida il rapporto all'avventuriero che ha scoperto la cospirazione.",h="Al Forte di Roccavento, i risultati dell'indagine sulla Fratellanza dei Defias giungono alla corte reale.",kw={"udienza con il re","baros alexston","defias","rapporto","forte di roccavento","vancleef","marche occidentali"},ang={["faction:Alliance"]="La consegna del rapporto porta davanti alla corte reale la lunga lotta per rendere sicure le Marche Occidentali e avvertire i vertici di Roccavento dell'insurrezione ai suoi confini.",["race:Human"]="Come umano del regno, porti un rapporto sul conflitto irrisolto tra la casata nobiliare di Roccavento e gli scalpellini che ricostruirono la città."},sec={{t="Un Dispaccio per il Trono",b="L'architetto cittadino Baros Alexston preparò il rapporto per i vertici di Roccavento dopo una lunga indagine sui disordini nelle Marche Occidentali e nelle terre vicine. Lo affidò all'avventuriero che aveva svelato la cospirazione.\n\nIl rapporto viene portato al Forte di Roccavento per un'udienza privata. Lì, i risultati dell'indagine riguardano i piani dei cospiratori e il pericolo che rappresentano per il regno."},{t="Ricevimento al Forte",b="Re Varian Wrynn è in viaggio diplomatico quando il corriere raggiunge la sala del trono. I consiglieri reali e la reggenza che governa per il re bambino Anduin ricevono il rapporto in sua vece. Lodano il corriere per aver sventato i piani di VanCleef.\n\nDama Katrana Prestor è tra le figure di corte presenti quando gli avvertimenti giungono alla reggenza."}},faq={{q="Che cos'è il Rapporto sulla Fratellanza dei Defias?",a="Il rapporto è una relazione ufficiale di Baros Alexston. Raccoglie informazioni su Edwin VanCleef, sul suo esercito sotterraneo e sulla più vasta cospirazione dei Defias contro Roccavento.",al={"cos'è questo rapporto","oggetto rapporto defias","rapporto di baros alexston"}},{q="Chi ha scritto questo rapporto?",a="L'architetto cittadino di Roccavento, Baros Alexston, preparò il rapporto. Un tempo lavorava al fianco degli scalpellini, prima che si separassero per formare la Fratellanza dei Defias.",al={"chi ha redatto il rapporto sui defias","autore del rapporto"}},{q="Perché lo sto consegnando al Forte di Roccavento?",a="Baros Alexston ritiene che l'avventuriero che ha scoperto la cospirazione meriti di presentare i risultati dell'indagine al trono. Spera che tu ottenga un riconoscimento reale per aver protetto il regno.",al={"perché lo consegno","consegna udienza con il re"}},{q="Re Varian legge il rapporto?",a="No. Re Varian Wrynn è in viaggio diplomatico quando raggiungi il Forte di Roccavento. La sua corte e la reggenza ricevono il rapporto in sua vece.",al={"il re lo legge","udienza con varian wrynn"}}},fp="32,178,25.367.0,21.337.1,45.170.1,22.160.1,43.182.0,33.138.0"}
P.entries["item:resonite-crystal"] = {n="Cristallo di Resonite",s="Nella Caverna dei Franamassi, i coboldi scavano freneticamente in cerca del Cristallo di Resonite. Il loro lavoro ha destato la preoccupazione di Mor'rogal al Rifugio Roccia del Sole.",h="Nella Caverna dei Franamassi, i coboldi scavano freneticamente in cerca del Cristallo di Resonite.",kw={"franamassi","cristallo","terrigeni","coboldo","mor'rogal","resonite","petrartiglio","titani"},ang={["class:Shaman"]="Come sciamano, puoi percepire l'inquietante risonanza dei Cristalli di Resonite. È magia della terra sopita e primordiale, lasciata dalle creazioni dei Titani sepolte sotto le montagne.",["profession:Mining"]="Come minatore, trovi la Resonite in formazioni estremamente concentrate, diverse dalle comuni vene di rame o stagno. Per raggiungerla devi superare coboldi aggressivi e addentrarti negli strati più profondi del sottosuolo."},sec={{t="Risonanza antica",b="I coboldi scavano freneticamente in cerca del Cristallo di Resonite nelle profondità della Gola dei Franamassi. Il loro improvviso interesse allarma gli sciamani del Rifugio Roccia del Sole. Mor'rogal esamina le pietre e sente un debole ronzio magico. Riconosce tracce della magia dei Terrigeni. Gli indizi rimandano a un antico strato plasmato dai Titani."},{t="Attingere alla terra",b="Gli scavatori coboldi si sono spinti abbastanza in profondità da disturbare gli antichi Terrigeni. I Titani plasmarono i Terrigeni affinché scavassero e modellassero le fondamenta del mondo. La loro magia permea ancora la roccia circostante. Gli agenti dell'Orda raccolgono il Cristallo di Resonite per capire cosa spinga i coboldi e rivolgere il potere della pietra incantata contro qualunque cosa dorma nel sottosuolo."}},faq={{q="Dove si trovano i Cristalli di Resonite?",a="I Cristalli di Resonite si trovano nella Caverna dei Franamassi, nelle profondità della Gola dei Franamassi, nella parte sudorientale delle Vette di Petrartiglio.",al={"posizione resonite","dove trovare la resonite","farming cristalli di resonite"}},{q="Perché i coboldi stanno estraendo i Cristalli di Resonite?",a="I coboldi estraggono freneticamente i rari cristalli, ma Mor'rogal non sa perché. Chiede dei campioni e un'indagine nelle profondità della caverna per scoprire cosa stiano facendo.",al={"perché i coboldi scavano","piano dei cristalli dei coboldi","coboldi dei franamassi"}},{q="Che tipo di potere si trova in un Cristallo di Resonite?",a="Mor'rogal sospetta che i cristalli siano legati a qualcosa di inquietante sotto le montagne. Ne riconosce la natura magica dopo aver ricevuto campioni e notizie dalla caverna.",al={"magia del cristallo di resonite","cos'è la resonite","la resonite è magica"}},{q="Chi sta studiando questi cristalli?",a="Mor'rogal, un tauren al Rifugio Roccia del Sole nelle Vette di Petrartiglio, studia i cristalli. Cerca di comprendere l'improvviso aumento dell'attività dei coboldi e di trovare un modo per contrastare il male portato alla luce.",al={"chi vuole la resonite","cristalli di mor'rogal","resonite rifugio roccia del sole"}},{q="Chi sono i Terrigeni menzionati in relazione al cristallo?",a="I Terrigeni furono creati dai Titani per plasmare la terra. Mor'rogal indaga su un possibile legame tra loro e la Resonite.",al={"cosa sono i terrigeni","connessione tra terrigeni e titani"}}},fx={c14b6c8c={q="Cos'è il Cristallo di Resonite?",a="La Resonite è un raro minerale cristallino che si trova nella Caverna dei Franamassi nelle Vette di Petrartiglio. L'estrazione frenetica dei coboldi ha allarmato Mor'rogal, che richiede campioni e notizie dalla caverna per indagare.",al={"cos'è la resonite","storia del cristallo di resonite","minerale di resonite"}},af246400={q="Perché qualcuno vuole il Cristallo di Resonite?",a="Mor'rogal vuole campioni di minerale per comprendere l'estrazione frenetica dei coboldi e scoprire cosa giace sotto la Gola dei Franamassi. Chiede a un avventuriero di esplorare la caverna e di raccogliere i cristalli.",al={"perché raccogliere cristalli di resonite","chi vuole il cristallo di resonite","scopo del cristallo di resonite"}}},fp="16,131,17.290.1,17.334.1,34.123.0,45.172.0,44.170.0,31.194.0,60.129.0"}
P.entries["item:restabilization-cog"] = {n="Ingranaggio Stabilizzatore",s="Alle porte di Gnomeregan, gli gnomi lebbrosi portano ancora con sé Ingranaggi Stabilizzatori. A Kharanos, gli inventori hanno bisogno di ingranaggi intatti per una macchina destinata a invertire la mutazione lebbrosa.",h="Alle porte di Gnomeregan, gli gnomi lebbrosi portano ancora con sé Ingranaggi Stabilizzatori.",kw={"dun morogh","gibblewilt","gnomeregan","kharanos","gnomo lebbroso","operation recombobulation","razzle mollapazza","ingranaggio stabilizzatore"},ang={["profession:Engineering"]="Come ingegnere, puoi capire come gli Ingranaggi Stabilizzatori si inseriscano nei macchinari gnomici come il Recombobulator.",["race:Gnome"]="Come gnomo esiliato a Dun Morogh, recuperi macchinari dai tuoi simili corrotti nella speranza di trovare una cura per gli gnomi caduti di Gnomeregan."},sec={{t="Componenti per una cura",b="Le radiazioni inondarono Gnomeregan in un tentativo fallito di annientare i trogg invasori. Innumerevoli gnomi si ammalarono e divennero ostili, poi fuggirono dalla loro patria come esuli. Persino nella loro follia, portano con sé complessi macchinari gnomici.\n\nOzzie Valvotron e Razzle Mollapazza credono che la terribile trasformazione possa essere annullata. Il loro prototipo di Recombobulation Device richiede componenti recuperati dagli afflitti fuori dalle porte di Gnomeregan. Gli Ingranaggi Stabilizzatori intatti bilanceranno i suoi sistemi di combustione interna."}},faq={{q="A cosa serve un Ingranaggio Stabilizzatore?",a="A Kharanos, l'inventore Razzle Mollapazza ha bisogno di Ingranaggi Stabilizzatori per il Recombobulator. Insieme ai Gyromechanic Gears, fanno parte della macchina sperimentale destinata a curare gli gnomi lebbrosi irradiati.",al={"scopo dell'ingranaggio","cosa fa l'ingranaggio stabilizzatore","perché raccogliere ingranaggi"}},{q="Dove si possono trovare questi ingranaggi?",a="Gli gnomi lebbrosi e il folle Gibblewilt portano con sé questi ingranaggi. Si aggirano presso le porte esterne e nelle trincee fuori da Gnomeregan, nella parte occidentale di Dun Morogh.",al={"posizione dell'ingranaggio stabilizzatore","chi rilascia gli ingranaggi","dove trovare ingranaggi"}},{q="Il Recombobulator può davvero curare gli gnomi lebbrosi?",a="Razzle Mollapazza e Ozzie Valvotron credono che macchinari calibrati possano invertire la mutazione. Resta da verificare se il Recombobulator possa risanare le menti e i corpi degli gnomi lebbrosi, e la ricerca di una cura continua.",al={"il recombobulator funziona","esiste una cura per gli gnomi lebbrosi"}}},fx={["8ac7e8f1"]={q="Cos'è un Ingranaggio Stabilizzatore?",a="Un Ingranaggio Stabilizzatore è un componente meccanico di precisione recuperato dalle macchine cadute e dai gnomi contaminati lebbrosi che vagano fuori dalla città in rovina di Gnomeregan. Progettati per mantenere l'equilibrio strutturale e rotazionale in complessi dispositivi gnomici, questi ingranaggi sono apprezzati dai meccanici in cerca di parti robuste e pre-lavorate per stabilizzare invenzioni temperamentali come il Ricombobulatore di Ozzie Valvotron.",al={"cos'è un ingranaggio stabilizzatore","storia dell'ingranaggio stabilizzatore","informazioni sull'ingranaggio stabilizzatore"}},ceb0040c={q="Da dove vengono gli Ingranaggi Stabilizzatori?",a="Questi ingranaggi provengono dalle vaste opere meccaniche di Gnomeregan. Quando la città è stata evacuata in seguito allo sfogo di radiazioni disastroso, innumerevoli dispositivi automatizzati e i tragici sopravvissuti che hanno ceduto alla follia lebbroso hanno portato questi componenti standardizzati fuori sulla neve davanti ai cancelli.",al={"chi ha creato l'ingranaggio stabilizzatore","origine dell'ingranaggio stabilizzatore","da dove viene l'ingranaggio stabilizzatore"}}},fp="19,156,21.476.0,39.203.0,30.142.0,54.220.0"}
P.entries["item:ring-of-zoram"] = {n="Anello di Zoram",s="A Zoram, l'anello indossato dai sovrani della città è riemerso dopo millenni trascorsi sotto il mare. I naga lo custodiscono e Talen cerca la chiave per aprire un'antica statuetta.",h="A Zoram, l'anello indossato dai sovrani della città è riemerso dopo millenni trascorsi sotto il mare.",kw={"statuetta antica","valtetra","lady vespia","anello di zoram","ruuzel","talen","spiaggia di zoram"},ang={["faction:Alliance"]="Recuperare l'anello dai naga aiuta lo studioso Talen, un Elfo della Notte, a riappropriarsi della storia dei Kaldorei lungo i confini contesi di Valtetra.",["race:NightElf"]="L'anello è una testimonianza del retaggio precedente al Grangorgo, di un tempo in cui la superbia arcana e i mari non avevano ancora lacerato e sommerso l'impero dei Kaldorei."},sec={{t="Anello della Città Sommersa",b="Prima che il Pozzo dell'Eternità collassasse, Zoram sorgeva sulla costa occidentale di Kalimdor, gioiello dell'impero degli Elfi della Notte. I suoi sovrani indossavano l'Anello di Zoram, la cui fascia interna reca uno strano codice nella lingua degli Elfi della Notte. Il Grande Grangorgo sconvolse il continente diecimila anni fa. L'anello sprofondò con la città sotto le maree e ora giace nelle acque della Spiaggia di Zoram."},{t="Rivendicazione da parte dei Naga",b="Per millenni, il limo e le rovine nascosero l'anello. Poi i naga iniziarono a perlustrare la costa di Valtetra e Ruuzel, la loro guida su un isolotto al largo della spiaggia settentrionale, lo scoprì tra i detriti sommersi. Lo studioso Talen, un Elfo della Notte, lo cerca per ragioni che vanno oltre la sua antichità. L'anello è l'unica chiave capace di aprire reliquie recuperate dalle profondità, comprese antiche statuette sigillate sul fondo del mare."}},faq={{q="A cosa serve l'Anello di Zoram?",a="Prima che il Grangorgo sommergesse Zoram, i suoi sovrani indossavano l'anello, che fungeva anche da chiave per un'antica serratura. Ora Talen lo cerca per aprire una statuetta chiusa a chiave, recuperata dalle rovine sommerse.",al={"scopo dell'anello di zoram","cosa fa l'anello","storia dell'anello di zoram"}},{q="Chi possiede l'Anello di Zoram?",a="I naga che invadono la Spiaggia di Zoram hanno recuperato l'anello dalle rovine. Ruuzel, la loro guida, lo custodisce su un'isola al largo della costa settentrionale, sebbene anche l'influente naga Lady Vespia sia stata vista portarlo.",al={"chi possiede l'anello","bottino anello di zoram","dove trovare l'anello di zoram"}},{q="Perché Talen vuole l'anello?",a="Talen vuole svelare i segreti di un'antica statuetta recuperata dalla Spiaggia di Zoram. Senza l'Anello di Zoram a fare da chiave, il meccanismo della statuetta non può essere aperto.",al={"perché talen vuole l'anello","missione anello di talen"}},{q="Dov'è finita la città di Zoram?",a="Prima del Grande Grangorgo, Zoram era una città degli Elfi della Notte all'estremità occidentale di Kalimdor. Quando il Pozzo dell'Eternità implose diecimila anni fa, la città fu distrutta e sommersa dalle onde, lasciando solo la Spiaggia di Zoram.",al={"cosa è successo a zoram","storia della città di zoram"}}},fx={["7e40c0d5"]={q="Cos'è l'Anello di Zoram?",a="L'Anello di Zoram è un'antica reliquia un tempo indossata dai sovrani della città sommersa di Zoram, prima che le onde del Grande Cataclisma la sommergessero. Uno strano codice è scritto all'interno della fascia nella lingua degli elfi della notte, e l'anello è la chiave dell'antica serratura di una statuetta recuperata dalle rovine.",al={"cos'è l'anello di zoram","storia dell'anello di zoram","oggetto anello di zoram"}},["770adfa7"]={q="Da dove viene l'Anello di Zoram e chi lo ha creato?",a="L'anello proviene dalla città elfica notturna di Zoram, pre-Cataclisma, lungo la costa dell'antica Kalimdor. Apparteneva ai sovrani della città prima che maremoti cataclismatici sommergessero Zoram diecimila anni fa, lasciando la reliquia perduta nel mare finché i naga non l'hanno recentemente dragata dalle rovine.",al={"origine dell'anello di zoram","chi ha creato l'anello di zoram","da dove viene l'anello di zoram"}}},fp="13,163,23.386.0,23.375.0,35.192.0,32.200.0,29.173.0,31.228.0"}
P.entries["item:robo-mechanical-guts"] = {n="Interiora Robomeccaniche",s="A Roccavento, Shoni raccoglie pezzi dalle macchine che vagano per Gnomeregan. Le servono per riparare veicoli da scavo costruiti per aiutare a riconquistare la città a Dun Morogh.",h="A Roccavento, Shoni raccoglie pezzi dalle macchine che vagano per Gnomeregan.",kw={"meccanico","dun morogh","gnomeregan","gyrodrillmatic excavationators","interiora robomeccaniche","shoni","roccavento"},ang={["profession:Engineering"]="Ogni groviglio di cavi e ogni ingranaggio giroscopico proviene da progetti gnomici di macchine automatizzate. Le radiazioni e l'isolamento hanno cambiato le macchine, che ora vagano senza meta.",["race:Gnome"]="Per uno gnomo, recuperare pezzi dalle sentinelle a orologeria fuori controllo della propria patria perduta può suscitare sentimenti contrastanti. I loro meccanismi forniscono pezzi per aiutare a riconquistare Gnomeregan."},sec={{t="Materiale di Recupero per la Flotta",b="Dopo che il Gran Meccanista Gelbin Meccatork e gli gnomi superstiti fuggirono da Gnomeregan, migliaia di macchine rimasero sul posto. Meccanismi automatizzati, sentinelle a orologeria e robot industriali vagano ancora per i corridoi della città radioattiva.\n\nA Roccavento, l'artefice Shoni sta assemblando dei Gyrodrillmatic Excavationators per sfondare le difese di Gnomeregan e riconquistare la città perduta. Invia avventurieri nelle sale contaminate per recuperare pezzi funzionanti dai robot, tra cui molle, cavi e componenti giroscopici."}},faq={{q="A cosa servono le Interiora Robomeccaniche?",a="Shoni, a Roccavento, raccoglie Interiora Robomeccaniche per riparare i Gyrodrillmatic Excavationators. Questi veicoli da scavo sono destinati ad aiutare nella riconquista di Gnomeregan a Dun Morogh.",al={"a cosa servono le interiora di robot","uso delle interiora robomeccaniche","perché raccogliere le interiora meccaniche"}},{q="Dove si trovano questi componenti?",a="Puoi recuperare questi componenti dagli automi a orologeria ostili, dai robot e dai nemici contaminati che vagano nei dintorni e nelle profondità di Gnomeregan.",al={"dove trovare le interiora robomeccaniche","luogo di rilascio interiora di robot","parti di robot di gnomeregan"}},{q="Chi è Shoni e perché ha bisogno di così tanti pezzi?",a="Shoni è un'ingegnera gnomica di stanza nel Distretto dei Nani di Roccavento. Le servono pezzi per preparare quasi quattrocento macchine da scavo sotterraneo ad aprire una breccia nelle rovine occupate di Gnomeregan.",al={"chi è shoni","shoni roccavento","flotta di gyrodrillmatic excavationators"}}},fx={b1d0efc3={q="Cosa sono le Interiora Robomeccaniche?",a="Sono i grovigli di macchinari interni, ingranaggi, cablaggi e componenti meccanici recuperabili estratti dagli automi a orologeria che vagano per Gnomeregan. Sebbene per un occhio inesperto non siano altro che rottami, queste interiora funzionali forniscono meccanismi grezzi cruciali che gli ingegnosi ingegneri gnomi possono riutilizzare per complessi progetti di veicoli.",al={"cosa sono le interiora robomeccaniche","oggetto interiora robomeccaniche","cosa sono le robo interiora"}},cf2ae288={q="Da dove vengono le Interiora Robomeccaniche e chi le ha create?",a="Questi assemblaggi hanno avuto origine nelle officine di Gnomeregan, creati da inventori gnomi per alimentare la loro forza lavoro automatizzata e le difese cittadine. Quando il disastro radioattivo colpì e l'Alto Artificiere Mekkatorque ordinò l'evacuazione, innumerevoli costrutti meccanici furono abbandonati all'interno, dove continuano a vagare per i passaggi in rovina con i loro ingranaggi interni ancora intatti.",al={"chi ha creato le interiora robomeccaniche","da dove vengono le interiora robomeccaniche","origine delle interiora robomeccaniche"}},f52d09f9={q="Perché qualcuno vuole le Interiora Robomeccaniche?",a="Shoni la Shilente a Roccavento ne ha un disperato bisogno come componenti di ricambio per riparare un'intera flotta di Gyrodrillmatic Excavationators. Con scorte limitate nella capitale umana, guarda ai mech ribelli di Gnomeregan come a un abbondante deposito di recupero per mantenere operativa la sua flotta ingegneristica.",al={"perché raccogliere le interiora robomeccaniche","chi vuole le interiora robomeccaniche","perché shoni vuole le interiora robomeccaniche"}}},fp="20,161,21.513.0,39.171.0,35.145.0,49.191.0"}
P.entries["item:rocket-car-parts"] = {n="Parti di Razzomacchina",s="Nelle Distese Salate, le Parti di Razzomacchina giacciono sparse dopo gli incidenti alla Pista dei Miraggi. I piloti gnomi e goblin spingono al limite i loro bolidi sperimentali, e i mercanti raccolgono rottami da rivendere alle scuderie.",h="Nelle Distese Salate, le Parti di Razzomacchina giacciono sparse dopo gli incidenti alla Pista dei Miraggi.",kw={"ingegneria","gnomo","goblin","kravel koalbeard","pista dei miraggi","parti di razzomacchina","recupero","distese salate","millepicchi"},ang={["profession:Engineering"]="Ingranaggi bruciati e gruppi di scarico contorti sono sparsi sulle distese salate, a testimonianza degli estremi a cui si spingono gli ingegneri gnomi e goblin.",["race:Dwarf"]="Gnomi e goblin si concentrano sulla gara, mentre nani come Kravel Koalbeard possono guadagnare recuperando i rottami abbandonati."},sec={{t="Velocità, schianti e commercio scaltro",b="Alla Pista dei Miraggi, nelle Distese Salate, gli ingegneri gnomi e goblin si sfidano ferocemente. I loro piloti cercano velocità sempre maggiori sulla terraferma. Guasti, accensioni difettose e schianti spargono metallo sulle distese salate, dove recuperatori e mercanti raccolgono presto ciò che rimane.\n\nIl nano Kravel Koalbeard assolda viaggiatori per perlustrare la luminosa distesa e raccogliere i detriti. Entrambe le scuderie hanno bisogno di componenti di ricambio per i prossimi prototipi, così i rottami possono tornare alle scuderie le cui vetture li hanno lasciati."}},faq={{q="Da dove provengono tutte queste parti di razzomacchina?",a="Le Parti di Razzomacchina provengono da schianti, esplosioni e guasti meccanici alla Pista dei Miraggi. I piloti gnomi e goblin spingono veicoli sperimentali a razzo sulle distese salate di Millepicchi finché le vetture non cadono a pezzi.",al={"perché ci sono pezzi sulle distese salate","origine dei rottami di razzomacchina","da dove provengono i pezzi"}},{q="Chi compra questi rottami recuperati?",a="Mercanti come il nano Kravel Koalbeard comprano i rottami raccolti dai viaggiatori. Rivendono ingranaggi, piastre e altri pezzi a gnomi e goblin, che hanno bisogno di materiali per riparare e migliorare le loro vetture da corsa.",al={"chi vuole le parti di razzomacchina","kravel koalbeard parti di razzo","chi compra i rottami"}},{q="È pericoloso recuperare queste parti?",a="I rottami sono inerti, ma il metallo può recare macabri segni degli schianti, tra cui arti mozzati rimasti incastrati. Basilischi, scorpidi bruciacchiati e predatori avvoltoi delle saline si aggirano sulle distese salate vicino ai detriti.",al={"è sicuro raccogliere i pezzi","minacce durante la raccolta dei pezzi"}},{q="Agli gnomi e ai goblin importa che le parti provengano da veicoli distrutti?",a="I piloti gnomi e goblin usano volentieri pezzi riciclati. Vogliono componenti meccanici funzionanti, ingranaggi e piastre per costruire vetture abbastanza veloci da superarsi a vicenda in pista.",al={"ai piloti importano i rottami","perché i goblin riutilizzano i rottami"}}},fx={["9a01e74a"]={q="Cosa sono le Parti di Razzomacchina?",a="Sono i detriti sparsi dei disastri delle corse ad alta velocità in tutte le Distese Salate. Composti da ingranaggi allentati, cilindri, piastre metalliche contorte e aggeggi recuperati, questi rottami un tempo erano imbullonati ai ruggenti macchinari sperimentali costruiti da velocisti goblin e gnomi che gareggiavano alla Pista dei Miraggi.",al={"cosa sono le parti di razzomacchina","storia delle parti di razzomacchina","cosa sono queste parti"}}},fp="16,216,34.487.0,46.227.0,31.210.0,36.213.0,68.161.0"}
P.entries["item:rod-of-channeling"] = {n="Verga della Canalizzazione",s="Nelle Paludi Grigie, gli incantatori Fauce del Drago portano la Verga della Canalizzazione. A Strahad Farsan ne servono tre affinché i suoi accoliti stabilizzino un cerchio di evocazione di un felhunter a Porto Paranco.",h="Nelle Paludi Grigie, gli incantatori Fauce del Drago portano la Verga della Canalizzazione.",kw={"accampamento zannarabbiosa","bonewarder","fauce del drago","felhunter","verga della canalizzazione","shadowwarder","strahad farsan","tome of the cabal"},ang={["class:Warlock"]="Come stregone, raccogli tre Verghe della Canalizzazione durante le prove del Tome of the Cabal. Aiutano a contenere il rituale mentre vincoli il tuo primo felhunter."},sec={{t="Strumenti di Vincolamento",b="Agli stregoni serve più della forza di volontà per vincolare un felhunter. Strahad Farsan richiede tre verghe identiche affinché i suoi accoliti possano canalizzare insieme la magia e stabilizzare il cerchio di evocazione mentre lo stregone vincola la bestia. Gli incantatori oscuri Fauce del Drago portano le verghe per le proprie pratiche.\n\nAll'Accampamento Zannarabbiosa e nelle rovine circostanti delle Paludi Grigie, i Bonewarders e gli shadowwarders Fauce del Drago portano le verghe. I combattimenti le lasciano usurate e intaccate, eppure continuano a concentrare la caotica energia del nether."}},faq={{q="A cosa serve la Verga della Canalizzazione?",a="Strahad Farsan, sulle alture sopra Porto Paranco, ha bisogno delle verghe per i suoi accoliti. Canalizzano la magia per stabilizzare il cerchio in cui uno stregone evoca e vincola un felhunter ostile.",al={"cos'è la verga della canalizzazione","scopo della verga della canalizzazione","perché serve la verga della canalizzazione"}},{q="Dove si possono trovare le Verghe della Canalizzazione?",a="Gli incantatori Fauce del Drago portano le verghe nelle Paludi Grigie. I Bonewarders e gli Shadowwarders Fauce del Drago le portano nei dintorni dell'Accampamento Zannarabbiosa.",al={"dove trovare le verghe della canalizzazione","chi rilascia la verga della canalizzazione","posizione della verga della canalizzazione"}},{q="Perché Strahad ha bisogno di tre verghe?",a="Gli accoliti di Strahad assistono nel rituale di evocazione del felhunter. A ciascuno serve un catalizzatore per stabilizzare il condotto mentre lo stregone soggioga la bestia.",al={"perché tre verghe","perché 3 verghe della canalizzazione"}},{q="Perché i Fauce del Drago usano queste verghe?",a="Il clan Fauce del Drago usa le verghe per il suo sciamanesimo oscuro e le sue arti dell'ombra, retaggi dell'Old Horde. I suoi bonewarders e shadowwarders canalizzano maledizioni, necromanzia e Shadow Magic nelle continue guerre territoriali nelle Paludi Grigie.",al={"verghe fauce del drago","perché i fauce del drago le possiedono"}}},fx={af4e8f1c={q="Cos'è una Verga della Canalizzazione?",a="Una Verga della Canalizzazione è un focus arcano utilizzato dagli incantatori per focalizzare e imbrigliare energie magiche volatili. Sebbene originariamente impugnate dagli incantatori oscuri del clan Fauce del Drago nelle Paludi, queste verghe sono potenti strumenti rituali in grado di stabilizzare evocazioni di alto ordine se maneggiate da stregoni esperti.",al={"cos'è la verga della canalizzazione","storia della verga della canalizzazione","informazioni sulla verga della canalizzazione"}}},fp="17,163,22.464.0,39.158.0,38.133.0,33.140.0,39.227.0"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Medaglioni di Rolf e Malakai",s="Nell'Elwynn orientale, i Medaglioni di Rolf e Malakai recano l'insegna del regno, ma i loro proprietari sono scomparsi durante una pattuglia. La Guardia Thomas cerca i medaglioni per scoprire cosa sia accaduto ai suoi uomini.",h="Nell'Elwynn orientale, i Medaglioni di Rolf e Malakai recano l'insegna del regno, ma i loro proprietari sono...",kw={"vallevante","elwynn","guardia thomas","malakai","medaglioni","murloc","rolf","guardia di roccavento"},ang={["faction:Alliance"]="Persino nel cuore dell'Alleanza, le guardie locali affrontano pericoli mortali mentre proteggono le vie commerciali nelle campagne.",["race:Human"]="Per gli umani di Elwynn, questi distintivi testimoniano la perdita di figli e difensori. Le loro morti mostrano la vulnerabilità del regno mentre il suo esercito è impegnato altrove."},sec={{t="Una tetra conferma",b="La Guardia Thomas comanda la postazione nell'Elwynn orientale. Quando Rolf e Malakai sono scomparsi lungo le rive del fiume, ha temuto il peggio. I loro medaglioni confermano che le guardie sono morte per mano dei murloc che avanzano nella zona. La guarnigione di Roccavento ha perso soldati che tenevano a bada le minacce delle terre selvagge mentre le forze del regno erano disperse su troppi fronti."},{t="Distintivi di servizio",b="Le guardie umane portano medaglioni di identificazione durante i turni di guardia in città e le pattuglie nelle campagne. Questi distintivi attestano la loro fedeltà e l'autorità conferita loro dalla corona. Restituire i medaglioni di Rolf e Malakai alla Guardia Thomas gli permette di accertare la sorte dei suoi uomini scomparsi e annotarne il sacrificio nel rapporto dal campo. Può anche segnalare l'insediamento di tribù aggressive di murloc vicino alle vie commerciali."}},faq={{q="Cosa sono i Medaglioni di Rolf e Malakai?",a="I Medaglioni di Rolf e Malakai sono distintivi di identificazione in servizio portati dalle guardie di Roccavento. I murloc hanno teso un'imboscata alle guardie e le hanno uccise mentre erano di stanza nella parte orientale della Foresta di Elwynn.",al={"cosa sono i medaglioni","medaglione di rolf","medaglione di malakai"}},{q="A chi appartengono questi medaglioni?",a="I medaglioni appartenevano alle guardie Rolf e Malakai. Servivano sotto il comando della Guardia Thomas, sorvegliando il fiume e le strade tra Borgodoro e il Campo di Taglio di Vallevante.",al={"chi erano rolf e malakai","di chi sono i medaglioni"}},{q="A chi dovrei portare questi medaglioni?",a="Porta i medaglioni alla Guardia Thomas. Sorveglia il ponte orientale sulla strada tra Borgodoro e il Campo di Taglio di Vallevante.",al={"chi vuole i medaglioni","dove si consegnano","consegna dei medaglioni"}},{q="Perché questi medaglioni sono importanti per la Guardia Thomas?",a="La Guardia Thomas ha mandato entrambe le guardie in pattuglia e temeva che avessero fatto una brutta fine. I loro medaglioni ne confermano la morte, permettendogli di registrarne il sacrificio e avvertire Roccavento della crescente minaccia dei murloc.",al={"perché thomas li vuole","reazione della guardia thomas"}}},fp="29,178,19.339.0,17.358.0,39.180.1,34.161.0,39.135.0,51.197.1"}
P.entries["item:rot-blossom"] = {n="Fiore Marcio",s="A Boscovespro, i Fiori Marci spuntano dalle tombe profanate, nutriti dal suolo corrotto e dai resti dei non morti. Le loro ripugnanti proprietà alchemiche li rendono ricercati.",h="A Boscovespro, i Fiori Marci spuntano dalle tombe profanate, nutriti dal suolo corrotto e dai resti dei non...",kw={"althea ebonlocke","borgoscuro","boscovespro","fiore marcio","skeletal fiend","skeletal horror","cimitero parcosereno","zombie juice"},ang={["faction:Alliance"]="Raccogliere questi fiori macabri nel suolo maledetto aiuta anche la Night Watch a tenere gli scheletri famelici lontani dai confini di Borgoscuro.",["profession:Herbalism"]="I Fiori Marci sono piante ripugnanti nutrite dal marciume necrotico e dalla terra dei cimiteri, a differenza delle erbe alimentate dalla luce e dalla pioggia. Offrono un macabro oggetto di studio sulla flora corrotta."},sec={{t="Flora delle cripte",b="A Boscovespro, i Fiori Marci crescono nella terra profanata dei cimiteri, compreso il Cimitero Parcosereno. Voci locali dicono che attecchiscano nei teschi incrinati degli Skeletal Horrors e degli Skeletal Fiends che si aggirano tra i tumuli. Raccoglierli è un lavoro macabro per gli abitanti di Borgoscuro. Smuovi la terra e dovrai affrontare i morti senza riposo."},{t="Un ingrediente raccapricciante",b="I Fiori Marci forniscono un ingrediente per gli infusi locali. Le loro essenze oscure servono a preparare lo Zombie Juice, una bevanda ripugnante legata alla lotta di Boscovespro per sopravvivere. Chi viene mandato a raccogliere i fiori spesso aiuta la Night Watch abbattendo gli scheletri senza riposo che vagano tra le tombe infestate."}},faq={{q="Dove si possono trovare i Fiori Marci?",a="I Fiori Marci crescono nei luoghi di sepoltura corrotti di Boscovespro, soprattutto nel Cimitero Parcosereno. Spuntano anche dai resti di demoni scheletrici non morti.",al={"dove cresce il fiore marcio","posizione fiore marcio","trovare fiori marci"}},{q="A cosa servono i Fiori Marci?",a="I preparatori di infusi e gli alchimisti locali usano i Fiori Marci per preparare lo Zombie Juice, una miscela potente e ripugnante.",al={"uso fiore marcio","perché raccogliere fiori marci","a cosa serve il fiore marcio"}},{q="Perché questi fiori crescono negli scheletri?",a="La magia oscura che persiste a Boscovespro infetta la terra e i morti senza riposo. I Fiori Marci si nutrono di corruzione necrotica e decomposizione, e possono spuntare nei teschi e nelle gabbie toraciche degli scheletri erranti.",al={"fiori marci nei teschi","fiore di orrore scheletrico","scheletri fiore marcio"}},{q="In che modo raccogliere i Fiori Marci aiuta Borgoscuro?",a="Raccogliere Fiori Marci in luoghi come Tranquil Gardens significa abbattere gli Skeletal Horrors e i Fiends che infestano quei terreni. Questo offre un sollievo necessario ad Althea Ebonlocke e alla Night Watch in difficoltà.",al={"althea ebonlocke fiore marcio","the night watch fiore marcio","aiutare borgoscuro"}}},fx={["93f3afdd"]={q="Cos'è un Fiore Marcio?",a="Un Fiore Marcio è una morbosa stranezza botanica che mette radici nei cimiteri contaminati di Boscovespro. Piuttosto che germogliare in un terreno sano, questi fiori cupi prosperano tra la decomposizione, germogliando notoriamente all'interno dei teschi cavi di Orrori Scheletrici e Demoni Scheletrici non morti. Infusi di energie impure, sono ricercati dalla gente del posto eccentrica che prepara potenti miscele dal marciume.",al={"cosa sono i fiori marci","oggetto fiore marcio","cos'è il fiore marcio"}}},fp="11,152,19.329.0,21.281.0,32.165.0,31.94.0,40.188.0,47.215.0"}
P.entries["item:rot-hide-ichor"] = {n="Icore di Pellemarcia"}
P.entries["item:rough-quartz"] = {n="Quarzo Grezzo",s="A Durotar, uno sciamano riceve del Quarzo Grezzo da una Manifestazione Minore della Terra. Un anziano incastona la pietra nel primo Earth Totem dello sciamano.",h="A Durotar, uno sciamano riceve del Quarzo Grezzo da una Manifestazione Minore della Terra.",kw={"call of earth","invocatore della terra canaga","earth totem","manifestazione minore della terra","quarzo grezzo","valle delle sfide"},ang={["class:Shaman"]="Per te che sei uno sciamano, il Quarzo Grezzo segna la tua prima comunione con l'elemento della terra. Ancora i tuoi incantesimi e segna il tuo cammino come tramite degli spiriti."},sec={{t="Totem del Cuore della Terra",b="A Durotar o a Mulgore, una Manifestazione Minore della Terra dona del Quarzo Grezzo a uno sciamano che entra in comunione con gli spiriti. A un occhio inesperto, la pietra sembra un comune ciottolo del deserto. Rappresenta la resistenza, la pazienza e una forza incrollabile.\n\nNella Valle delle Sfide, l'Invocatore della Terra Canaga incastona il quarzo nel legno intagliato per creare un Earth Totem. La pietra diventa il fulcro spirituale che unisce un giovane sciamano alla terra vivente di Azeroth."}},faq={{q="A cosa serve il Quarzo Grezzo?",a="Uno sciamano anziano incastona del Quarzo Grezzo nel primo Earth Totem di un iniziato come nucleo spirituale. La pietra dimostra anche che il novizio è entrato in comunione con lo spirito elementale della terra.",al={"a cosa serve il quarzo grezzo","uso del quarzo grezzo","perché serve il quarzo grezzo"}},{q="Chi ti dà il Quarzo Grezzo?",a="Una Manifestazione Minore della Terra ti dona del Quarzo Grezzo dopo che entri in comunione con lo spirito durante il rituale Call of Earth a Durotar o a Mulgore.",al={"dove trovare il quarzo grezzo","chi rilascia il quarzo grezzo"}},{q="A chi devo portare questa pietra a Durotar?",a="Porta il Quarzo Grezzo all'Invocatore della Terra Canaga, l'istruttore degli sciamani nella Valle delle Sfide. Canaga lo usa per creare il tuo Earth Totem.",al={"dove consegnare il quarzo grezzo","consegna del quarzo grezzo","chi accetta il quarzo grezzo"}},{q="Questo quarzo viene usato per qualcos'altro?",a="No. Il Quarzo Grezzo è un oggetto rituale sacro usato per creare un Earth Totem. Non ha alcun impiego nel commercio comune.",al={"si può vendere il quarzo grezzo","il quarzo grezzo serve per creare oggetti"}}},fx={f25f16be={q="Cos'è il Quarzo Grezzo?",a="Il Quarzo Grezzo è un piccolo ciottolo elementale dato agli aspiranti sciamani da una Manifestazione Minore della Terra. Sebbene modesto nelle dimensioni e nell'aspetto, la pietra rappresenta il superamento da parte di un iniziato del rito della terra e la comunione con lo spirito elementale, fungendo da prova tangibile del loro legame.",al={"cos'è il quarzo grezzo","oggetto quarzo grezzo","significato del quarzo grezzo"}},["871e2ee1"]={q="Perché l'Invocatore della Terra Canaga vuole il Quarzo Grezzo?",a="L'Invocatore della Terra Canaga richiede il Quarzo Grezzo come prova che hai ascoltato la chiamata e sei entrato in comunione con lo spirito elementale. Usa il ciottolo come cuore del tuo primo Totem della Terra, permettendoti di entrare ulteriormente in comunione con la terra e lanciare incantesimi legati direttamente al suo potere.",al={"perché serve il quarzo grezzo","scopo del quarzo grezzo","perché portare il quarzo grezzo a canaga"}}},fp="12,143,24.439.0,40.172.0,31.143.0,40.127.0,38.102.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="Munizioni di Granzuffa",s="Vicino alla Tana Selvaggia, le Munizioni di Granzuffa giacciono abbandonate nella neve. Il corriere fuggì da wendigo affamati prima che la cassa potesse raggiungere l'armaiolo Hegnar Granzuffa a Dun Morogh.",h="Vicino alla Tana Selvaggia, le Munizioni di Granzuffa giacciono abbandonate nella neve.",kw={"munizioni","cassa","dun morogh","tana selvaggia","hegnar","loslor","granzuffa","wendigo"},ang={["class:Hunter"]="Come cacciatore a Dun Morogh, mantieni asciutta la polvere da sparo di Hegnar e ben fornite le sue scorte di proiettili. Le armi da fuoco naniche richiedono un rifornimento costante di munizioni.",["profession:Engineering"]="Come ingegnere, hai bisogno di proiettili e polvere da sparo per collaudare le armi da fuoco fabbricate e gli armamenti sperimentali."},sec={{t="Una spedizione bloccata",b="Hegnar Granzuffa gestisce un'armeria lungo il sentiero di montagna che dal Passo Crestafredda conduce verso Forgiamara. I fucilieri di Forgiardente, i montanari e le squadre di mortai naniche si addestrano sulle alture innevate, quindi le sue scorte si esauriscono tanto rapidamente quanto brucia la polvere da sparo.\n\nLoslor inviò i proiettili da Kharanos, ma la spedizione non raggiunse mai gli scaffali. Il corriere si accampò troppo vicino alla Tana Selvaggia. Quando i wendigo attaccarono, il corriere fuggì in preda al panico e lasciò la pesante cassa nei loro territori di caccia."}},faq={{q="Chi è Hegnar Granzuffa?",a="Hegnar Granzuffa è un armaiolo nano con una bottega appena fuori dalla strada verso Forgiamara. Rifornisce tiratori, cacciatori e artiglieri dell'esercito della zona che si esercitano tra le rupi di Dun Morogh.",al={"granzuffa","chi è hegnar","mercante di armi da fuoco"}},{q="Come è andata perduta la cassa di munizioni?",a="Un corriere che trasportava la cassa si accampò vicino alla Tana Selvaggia. Quando i wendigo che la abitavano attaccarono, il corriere spaventato fuggì e lasciò la pesante cassa nella neve.",al={"perché le munizioni sono andate perdute","cosa è successo alle munizioni","corriere munizioni"}},{q="Dove si trova la Tana Selvaggia?",a="La Tana Selvaggia è un complesso di caverne nelle montagne a sud-ovest di Kharanos. I wendigo vi hanno la loro tana e mettono in pericolo i viaggiatori solitari sui pendii circostanti.",al={"posizione tana selvaggia","dove si trova la caverna dei wendigo"}}},fx={["4221fe47"]={q="Cosa sono le Munizioni di Granzuffa?",a="È una cassa di munizioni fresche preparata per il negozio di Hegnar Granzuffa, lungo la strada per Forgiamara. Con i fucilieri e le squadre di mortaio naniche locali che si esercitano costantemente nelle vicinanze, Hegnar dipende da spedizioni regolari come questa per mantenere i suoi scaffali riforniti e i suoi clienti armati.",al={"cosa sono le munizioni di granzuffa","cassa di munizioni di granzuffa","cosa sono queste munizioni"}},["008970c2"]={q="Da dove vengono le Munizioni di Granzuffa?",a="La cassa è stata fornita e spedita da Loslor Rudge da Kharanos. Sfortunatamente, il corriere incaricato di portarla a sud-ovest verso Forgiamara è stato imboscato da feroci wendigo vicino alla Tana Selvaggia ed è fuggito, abbandonando l'intero carico nella neve.",al={"chi ha fabbricato le munizioni di granzuffa","da dove vengono le munizioni di granzuffa","chi ha spedito le munizioni"}},["6d6b5eaa"]={q="Perché Hegnar Granzuffa ha bisogno di queste munizioni?",a="Hegnar è sul punto di esaurire completamente le scorte. I montanari, i fucilieri e le squadre di mortaio nelle vicinanze consumano polvere da sparo e proiettili a un ritmo vertiginoso durante le esercitazioni di tiro, lasciando molti acquirenti impazienti in attesa del momento in cui arriverà la nuova spedizione.",al={"perché servono le munizioni di granzuffa","perché volere le munizioni di granzuffa","chi ha bisogno delle munizioni di granzuffa"}}},fp="17,177,19.477.0,25.175.0,32.152.0,26.171.0"}
P.entries["item:rune-inscribed-parchment"] = {n="Cartapecora con Rune",s="Nella Valle delle Sfide, Gornek consegna agli aspiranti sciamani orchi una convocazione da parte di Shikrik. Li chiama a guidare il loro popolo e a entrare in comunione con gli spiriti elementali.",h="Nella Valle delle Sfide, Gornek consegna agli aspiranti sciamani orchi una convocazione da parte di Shikrik.",kw={"durotar","gornek","cartapecora","cartapecora con rune","sciamano","shikrik","valle delle sfide"},ang={["class:Shaman"]="Come sciamano, muovi il primo passo sul sentiero degli elementi. Sotto la guida di Shikrik, apprendi il culto degli antenati e il dominio degli elementi.",["race:Orc"]="Come orco, porti con te la saggezza ancestrale a Durotar. La riscoperta della tradizione sciamanica è fondamentale per la nuova Orda."},sec={{t="Una chiamata agli spiriti",b="I nuovi sciamani orchi si addestrano sotto la guida di sorveglianti veterani nella Valle delle Sfide. Durante le prime prove di un iniziato, Gornek gli consegna un messaggio coperto di rune da parte di Shikrik, l'istruttore sciamanico locale. Lo invita a rafforzare il suo legame con gli elementi.\n\nTra gli orchi, gli sciamani fanno da mediatori tra i vivi e i loro antenati. Il messaggio segna il passaggio dalla forza bruta a una venerazione disciplinata delle tradizioni ancestrali."}},faq={{q="Cos'è la Cartapecora con Rune?",a="Nella Valle delle Sfide, Gornek consegna agli sciamani orchi novizi un messaggio scritto a mano. Li invita a presentarsi da Shikrik per ricevere un addestramento formale.",al={"cartapecora runica","cos'è questo oggetto","cartapecora dello sciamano"}},{q="Chi ha scritto la pergamena?",a="Shikrik, l'istruttore degli sciamani nella Valle delle Sfide, ha scritto la pergamena. Istruisce i giovani iniziati nelle vie degli elementi e degli spiriti ancestrali.",al={"chi ha inviato la cartapecora","autore della cartapecora"}},{q="Perché gli sciamani sono considerati prescelti tra gli orchi?",a="Gli sciamani orchi guidano il loro popolo come capi spirituali. Ascoltano gli spiriti elementali e fungono da tramite per i loro antenati. Shikrik insegna agli apprendisti a curare gli alleati e a scatenare la furia degli elementi contro i nemici.",al={"perché essere uno sciamano","ruolo dello sciamano orco"}}},fx={["00232829"]={q="Perché Shikrik vuole che tu legga la Cartapecora con Rune?",a="Shikrik ha inviato questo messaggio tramite Gornek per convocarti direttamente da lei. Avendo riconosciuto che sei stato scelto per guidare la vita spirituale della tua gente, intende iniziare il tuo addestramento formale nella comunione con gli antenati, nella maestria elementale e nei riti di uno sciamano orco.",al={"perché leggere la cartapecora con rune","perché shikrik invia la cartapecora","scopo della cartapecora con rune"}}},fp="24,154,24.414.0,37.140.0,24.153.0,49.220.0"}
P.entries["item:rune-inscribed-pendant"] = {n="Pendente con Rune Inscritte",s="Nella Selva Pinargento, un Pendente con Rune Inscritte arriva a Mausolea in un carico diretto a Mulino d'Ambra. Il Kirin Tor usa pendenti simili per incanalare il potere arcano.",h="Nella Selva Pinargento, un Pendente con Rune Inscritte arriva a Mausolea in un carico diretto a Mulino...",kw={"allister","mulino d'ambra","dalar tessalba","dalaran","kirin tor","pendente","pendente con rune inscritte","mausolea"},ang={["class:Mage"]="Come mago, puoi riconoscere nelle rune la maestria del Kirin Tor. Stabilizzano correnti instabili durante l'incanalamento di potenti incantesimi.",["race:Undead"]="Come uno dei Reietti a guardia della Selva Pinargento, sai che i focus di Dalaran intercettati, come questo pendente, offrono indizi sulla resistenza umana che si sta radunando dietro le mura di Mulino d'Ambra."},sec={{t="Reliquia del Kirin Tor",b="Un Pendente con Rune Inscritte viene trovato tra le forniture cartografiche destinate all'enclave di Dalaran a Mulino d'Ambra. Le sue raffinate iscrizioni arcane ne rivelano lo scopo: focalizzare e potenziare gli incantesimi di un mago. Altri pendenti per l'incanalamento stanno arrivando nella regione, e i Reietti di Mausolea si chiedono cosa stia preparando il Kirin Tor."},{t="Un Indizio sui Piani di Mulino d'Ambra",b="A Mausolea, il Sacerdote dell'Ombra Allister vede un pericolo nella posizione fortificata dei maghi di Dalaran. Invia il pendente a Dalar Tessalba per un esame più approfondito. Tessalba lo riconosce come parte delle operazioni dei maghi. Il Kirin Tor sta raccogliendo focus arcani per potenti opere magiche, difensive o offensive, oltre i confini di Mulino d'Ambra."}},faq={{q="A cosa serve il Pendente con Rune Inscritte?",a="I maghi del Kirin Tor usano il pendente per incanalare e dirigere potenti flussi di magia. Focalizza complesse magie.",al={"cosa fa il pendente","scopo del pendente","uso del pendente con rune"}},{q="Da dove proviene questo pendente?",a="Il pendente arriva in un carico diretto a Mulino d'Ambra, nella Selva Pinargento, dove i superstiti del Kirin Tor si sono fortificati.",al={"dove trovare il pendente","origine del pendente","dove è stato trovato"}},{q="Chi analizza il pendente a Mausolea?",a="Il Sacerdote dell'Ombra Allister esamina brevemente il pendente insieme ad alcune mappe catturate. Lo invia a Dalar Tessalba a Mausolea, che riconosce l'opera del Kirin Tor.",al={"chi studia il pendente","chi vuole il pendente","pendente di dalar"}},{q="Perché i Reietti se ne preoccupano?",a="Grandi carichi di pendenti per l'incanalamento suggeriscono che il Kirin Tor a Mulino d'Ambra stia preparando un'importante impresa magica. I Reietti temono che possa minacciare il loro controllo sulla Selva Pinargento.",al={"perché i reietti se ne preoccupano","minaccia di mulino d'ambra","perché il pendente è pericoloso"}}},fx={bf28d080={q="Cos'è il Pendente con Rune Inscritte?",a="È un artefatto arcano creato e utilizzato dai potenti maghi di Dalaran. Spesso usato dal Kirin Tor per concentrare e incanalare enormi energie magiche, tali pendenti sono condotti di potente potere arcano piuttosto che semplici ornamenti.",al={"cos'è il pendente con rune inscritte","identità del pendente con rune","cos'è questo pendente di dalaran"}}},fp="22,166,15.327.0,27.338.1,44.111.0,33.125.0,42.165.0,40.185.0"}
P.entries["item:rune-inscribed-tablet"] = {n="Tavoletta con Rune",s="Nella Valle delle Sfide, Gornek consegna un messaggio di pietra ai giovani sciamani troll Puntascura. Indirizza i mistici promettenti a Shikrik per un'istruzione spirituale formale.",h="Nella Valle delle Sfide, Gornek consegna un messaggio di pietra ai giovani sciamani troll Puntascura.",kw={"puntascura","durotar","gornek","tavoletta con rune","sciamano","shikrik","istruttore","valle delle sfide"},ang={["class:Shaman"]="Per te che sei uno sciamano, la tavoletta segna il primo passo ufficiale verso il dominio di terra, fuoco, acqua e aria. La tua forza scaturisce dagli spiriti ancestrali.",["race:Troll"]="Come troll Puntascura, rispondi alla convocazione di un istruttore orco. Segna un legame sempre più forte e un cammino spirituale condiviso tra il tuo popolo e i suoi nuovi alleati dell'Orda."},sec={{t="Una chiamata agli spiriti",b="Gornek consegna una pietra incisa con rune agli iniziati che dimostrano il proprio valore nella Valle delle Sfide. Lo sciamano troll Ishi-yo la invia a Shikrik, l'istruttore degli sciamani. Per i troll Puntascura, la tavoletta dà inizio a un cammino condiviso con gli orchi. Le loro antiche tradizioni spirituali si uniscono al retaggio sciamanico rinnovato dal capoguerra Thrall."}},faq={{q="A cosa serve la Tavoletta con Rune?",a="Gornek consegna la tavoletta ai giovani sciamani troll nella Valle delle Sfide. Li indirizza a Shikrik per una formazione spirituale formale.",al={"scopo della tavoletta","cosa fa la tavoletta","uso della tavoletta con rune"}},{q="Chi invia la tavoletta?",a="Lo sciamano troll Ishi-yo invia la tavoletta. Indirizza l'iniziato a Shikrik, l'istruttore degli sciamani orchi appena fuori dall'Antro del Tirocinio, nella Valle delle Sfide. Shikrik sa che stanno arrivando.",al={"chi ha scritto la tavoletta","mittente della tavoletta","chi l'ha incisa"}},{q="Chi riceve questa tavoletta?",a="Gornek consegna la tavoletta agli sciamani troll Puntascura appena arrivati, come prima convocazione di classe a Durotar.",al={"chi riceve la tavoletta con rune","quale classe riceve la tavoletta"}}},fx={cd2cca59={q="Cos'è la Tavoletta con Rune?",a="La Tavoletta con Rune è una convocazione scritta diretta agli aspiranti sciamani troll che si addestrano nella Valle delle Sfide. Contrassegnata da rune sciamaniche, funge da messaggio personale trasmesso tramite Gornek per presentare le promettenti reclute direttamente al loro istruttore locale.",al={"cos'è la tavoletta con rune","storia della tavoletta con rune","cos'è questa tavoletta"}},["33b46b09"]={q="Perché Shikrik vuole che tu riceva la Tavoletta con Rune?",a="La tavoletta in realtà proviene da Ishi-yo, lo sciamano troll che ti ha dato le prime lezioni; Gornek ipotizza solo che provenga da Shikrik. Ishi-yo ti manda da Shikrik, che ti sta già aspettando. Lei vuole radicarti negli elementi e negli spiriti dei tuoi antenati, affinché un giorno tu possa guidare e proteggere i villaggi e le città dell'Orda proprio come Thrall guida l'Orda stessa.",al={"perché shikrik invia la tavoletta","perché mi serve questa tavoletta","tavoletta con rune di shikrik"}}},fp="21,159,24.315.0,43.130.0,21.178.0,25.105.0"}
P.entries["item:rune-of-nesting"] = {n="Runa della Nidificazione",s="Nell'Eremo di Ban'ethil, la Runa della Nidificazione aiuta a preparare un rito per risvegliare i Druids of the Talon. Dormono nel Sogno di Smeraldo e quattro reliquie sacre li guidano verso un ritorno sicuro.",h="Nell'Eremo di Ban'ethil, la Runa della Nidificazione aiuta a preparare un rito per risvegliare i Druids of...",kw={"athridas orsomanto","eremo di ban'ethil","chest of nesting","druids of the talon","sogno di smeraldo","relics of wakening","runa della nidificazione"},ang={["class:Druid"]="Come druido, sai che la Runa della Nidificazione fa parte dei riti sacri del Circolo Cenariano. Ti ricorda il pericolo che i confratelli dormienti corrono quando i loro santuari vengono violati.",["race:NightElf"]="Come elfo della notte, vedi nella perdita delle reliquie del risveglio e nella profanazione degli eremi i segni di una crescente corruzione tra la fauna e i furbolg di Teldrassil."},sec={{t="Un catalizzatore sacro per il risveglio",b="Nelle profondità delle tortuose camere dell'Eremo di Ban'ethil, la Runa della Nidificazione si trova nella Chest of Nesting. I druidi elfi della notte dormono negli eremi sotterranei e comunicano con la natura attraverso il Sogno di Smeraldo.\n\nPer tornare in sicurezza, i Druids of the Talon hanno bisogno di un attento rituale di risveglio guidato da reliquie sacre. La Runa della Nidificazione è una delle quattro, insieme al Talismano Artiglio del Corvo, alla Piuma Nera e allo Zaffiro del Cielo. Insieme, le reliquie richiamano i druidi dormienti nel mondo della veglia."},{t="Crisi a Ban'ethil",b="I furbolg Gnarlpine corrotti hanno invaso l'Eremo di Ban'ethil e i suoi difensori dormienti sono in pericolo. Senza le reliquie, i druidi rischiano di rimanere intrappolati nel Sogno di Smeraldo mentre gli invasori profanano il loro santuario. Recuperare la Runa della Nidificazione e le altre reliquie permette ad Athridas Orsomanto a Dolanaar di preparare il rito che può risvegliarli in sicurezza."}},faq={{q="A cosa serve la Runa della Nidificazione?",a="Athridas Orsomanto ha bisogno della Runa della Nidificazione per preparare il rituale che risveglia in sicurezza i Druids of the Talon dal loro profondo sonno nel Sogno di Smeraldo. È una delle quattro Relics of Wakening usate nel rito.",al={"cosa fa la runa della nidificazione","scopo della runa della nidificazione"}},{q="Dove si trova la Runa della Nidificazione?",a="La Runa della Nidificazione si trova nella Chest of Nesting, nei tunnel sotterranei dell'Eremo di Ban'ethil, a ovest di Dolanaar su Teldrassil.",al={"dove si trova la runa della nidificazione","posizione della chest of nesting"}},{q="Perché i druidi dormienti non possono semplicemente svegliarsi da soli?",a="I druidi entrano in una delicata trance quando dormono nel Sogno di Smeraldo. Senza reliquie sacre e un rituale di risveglio, potrebbero non riuscire a tornare, lasciando le loro menti alla deriva e i loro corpi in pericolo.",al={"perché i druidi hanno bisogno del rituale del risveglio","perché i druidi non possono svegliarsi"}},{q="Quali altre reliquie sono necessarie insieme alla Runa della Nidificazione?",a="Il rito richiede quattro Relics of Wakening: la Runa della Nidificazione, il Talismano Artiglio del Corvo, la Piuma Nera e lo Zaffiro del Cielo.",al={"altre relics of wakening","oggetti relics of wakening"}}},fx={["375c0565"]={q="Cos'è la Runa della Nidificazione?",a="La Runa della Nidificazione è una delle quattro sacre Reliquie del Risveglio custodite dai Druidi del Talone a Teldrassil. Conservata all'interno di un forziere dedicato nell'Eremo di Ban'ethil, porta gli incantesimi specializzati necessari per eseguire correttamente il rituale di risveglio per i druidi che riposano in profonda comunione con il Sogno di Smeraldo.",al={"runa della nidificazione","cos'è la runa della nidificazione","storia della runa della nidificazione"}}},fp="15,179,28.497.0,19.354.0,37.212.0,35.133.0,58.204.0,59.139.0"}
P.entries["item:runes-of-summoning"] = {n="Rune dell'Evocazione",s="Nel Magic Quarter di Sepulcra, gli stregoni richiamano un abissale dal Nether con le Rune dell'Evocazione. La creatura entra in un cerchio, dove un aspirante stregone può piegarla alla propria volontà.",h="Nel Magic Quarter di Sepulcra, gli stregoni richiamano un abissale dal Nether con le Rune dell'Evocazione.",kw={"carendin halgar","magic quarter","rune dell'evocazione","the binding","sepulcra","voidwalker","warlock"},ang={["class:Warlock"]="Come stregone, usi le rune per dimostrare il tuo dominio sul Void, trasformando un'ombra caotica in un servitore fedele e duraturo.",["race:Undead"]="In quanto Undead, segui i praticanti Reietti nelle profondità di Sepulcra, dove vincolano entità del Void sotto le Rovine di Lordaeron nonostante antichi tabù."},sec={{t="Sottomissione nel Magic Quarter",b="Carendin Halgar consegna le Rune dell'Evocazione agli stregoni pronti a comandare un abissale. Nel Magic Quarter di Sepulcra, i praticanti Reietti studiano come manipolare il Nether. Uno stregone lancia le rune nel cerchio di evocazione attivo sotto la postazione di Halgar. Il rituale squarcia il Void e richiama una creatura da sopraffare e vincolare alla servitù."}},faq={{q="A cosa servono le Rune dell'Evocazione?",a="Uno stregone lancia le rune nel Magic Quarter di Sepulcra per richiamare dal Nether nel mondo fisico un abissale non vincolato. Lo stregone può quindi sconfiggerlo e piegarlo alla propria volontà.",al={"scopo delle rune dell'evocazione","a cosa servono le rune dell'evocazione","come usare le rune dell'evocazione"}},{q="Chi fornisce le Rune dell'Evocazione?",a="Carendin Halgar, l'istruttore degli stregoni Reietti nel Magic Quarter di Sepulcra, fornisce le rune durante la fase finale dell'addestramento per vincolare un abissale.",al={"chi fornisce le rune dell'evocazione","istruttore rune dell'evocazione","carendin halgar rune"}},{q="Dove devono essere attivate le rune?",a="Porta le rune al cerchio di evocazione viola direttamente sotto la piattaforma di Carendin Halgar nel Magic Quarter.",al={"dove si usano le rune dell'evocazione","posizione delle rune dell'evocazione","cerchio di evocazione sepulcra"}},{q="Cosa succede dopo che l'entità è stata evocata?",a="L'abissale attacca non appena viene evocato. Lo stregone deve sottometterlo con la magia e le armi. Una volta sconfitta, l'entità viene vincolata alla servitù e Carendin Halgar insegna l'incantesimo permanente per evocarla.",al={"cosa succede dopo aver usato le rune","voidwalker sottomesso","dopo aver evocato il voidwalker"}}},fx={["1ce5479a"]={q="Cosa sono le Rune dell'Evocazione?",a="Le Rune dell'Evocazione sono un catalizzatore rituale specializzato dato agli aspiranti stregoni Reietti nella Città Bassa. Quando portate al circolo di evocazione nel Magic Quarter, le rune concentrano le energie magiche per aprire un passaggio e richiamare un vuoto abissale scatenato dal Nether.",al={"cosa sono le rune dell'evocazione","rune dell'evocazione","oggetto rune dell'evocazione"}},["0508549c"]={q="Perché Carendin Halgar vuole che le Rune dell'Evocazione vengano restituite?",a="Carendin Halgar fornisce le rune specificamente come prova di maestria. Una volta attivate e sottomesso il vuoto abissale evocato in combattimento, restituire le rune gli dimostra che hai dominato la creatura, permettendogli di insegnarti correttamente l'incantesimo permanente per evocare e comandare i vuoti abissali.",al={"perché restituire le rune dell'evocazione","perché carendin vuole le rune","restituzione rune dell'evocazione"}}},fp="18,188,32.366.0,41.187.0,36.155.0,34.110.0,42.200.0"}
P.entries["item:sack-of-murloc-heads"] = {n="Sacco di Teste di Murloc",s="Lungo le spiagge di Colletorto viene raccolto un Sacco di Teste di Murloc come prova dell'eliminazione delle minacce costiere locali. Il Tenente Farren Orinelle affida il fagotto agli avventurieri di passaggio perché lo consegnino al Maresciallo Tracciarossa a Riva del Sud.",h="Lungo le spiagge di Colletorto viene raccolto un Sacco di Teste di Murloc come prova dell'eliminazione delle...",kw={"taglia","farren orinelle","teste","colletorto","maresciallo tracciarossa","murloc","riva del sud"},ang={["faction:Alliance"]="Come membro dell'Alleanza, vedi le difficoltà logistiche e i poco gloriosi fardelli quotidiani dei difensori di Riva del Sud, impegnati a tenere unita l'enclave settentrionale dell'Alleanza."},sec={{t="Burocrazia e parassiti costieri",b="Riva del Sud subisce attacchi dai fuorilegge della Lega dei Tagliagole, dagli schermagliatori dei Reietti e dai murloc selvaggi lungo la costa. Gli ufficiali devono dimostrare ai capi della città che le minacce costiere vengono eliminate, così da ottenere finanziamenti e favore. Il Tenente Farren Orinelle raccoglie teste mozzate come prova, sebbene trovi il carico disgustoso. La sua ripugnanza lo spinge ad affidare il sacco ai viaggiatori diretti dal Maresciallo Tracciarossa, anziché trasportare di persona le macabre prove."}},faq={{q="Cos'è il Sacco di Teste di Murloc?",a="Il sacco contiene teste mozzate di murloc raccolte sulle spiagge occidentali di Colletorto. Fornisce al comandante della guarnigione di Riva del Sud una prova tangibile degli sforzi per pacificare la costa.",al={"sacco di teste","sacco di murloc","cos'è questo oggetto"}},{q="Perché il Tenente Farren non lo consegna di persona?",a="Il Tenente Farren Orinelle trova rivoltante trasportare un sacco di teste di murloc in decomposizione. Affida la sgradevole consegna a un avventuriero disponibile, perché la porti attraverso Riva del Sud.",al={"perché farren te lo fa portare","la scusa di farren","farren pigro"}},{q="Chi riceve il sacco?",a="Il Maresciallo Tracciarossa riceve il sacco. Comanda le difese di Riva del Sud, valuta la sicurezza della città ed esige prove degli sforzi difensivi.",al={"chi riceve le teste","dove lo porto","consegna al maresciallo tracciarossa"}},{q="Perché Riva del Sud richiede teste di murloc come prova?",a="Riva del Sud richiede teste di murloc come prova perché i murloc compiono continue incursioni sulla costa e minacciano il porto. Gli ufficiali devono verificare che le pattuglie mantengano sicuro il perimetro. Trofei tangibili aiutano a garantire che i soldati non si attribuiscano meriti per turni di guardia trascorsi nell'ozio.",al={"perché raccogliere teste di murloc","prova dell'uccisione"}}},fx={["3f14ed35"]={q="Da dove viene il Sacco di Teste di Murloc e chi l'ha fatto?",a="Il sacco è assemblato con le teste mozzate dei murloc che hai cacciato lungo la costa meridionale delle Alture di Colletorto. Il Tenente Farren Orinelle li ha impacchettati insieme per presentarli al suo ufficiale in comando, anche se ti restituisce rapidamente il ripugnante pacchetto affinché tu lo consegni al suo posto.",al={"chi ha fatto il sacco di teste di murloc","da dove viene il sacco di teste","chi ha dato il sacco di teste di murloc"}}},fp="20,217,29.433.0,33.166.0,47.170.0,22.139.0,50.248.0"}
P.entries["item:sack-of-supplies"] = {n="Sacca di Provviste",s="Nel Canyon Brezza Aguzza, i sacchi di provviste destinati a Rezlak giacciono sparsi tra i posatoi delle arpie. Le arpie Dustwind hanno sequestrato le merci mentre attraversavano Durotar.",h="Nel Canyon Brezza Aguzza, i sacchi di provviste destinati a Rezlak giacciono sparsi tra i posatoi delle arpie.",kw={"durotar","arpie dustwind","sparachiodi","canyon brezza aguzza","rezlak","sacca di provviste"},ang={["faction:Horde"]="Recuperare le provviste dai predatori locali permette ai lavori di costruzione alla frontiera intorno a Orgrimmar di proseguire senza costosi ritardi."},sec={{t="Una carovana saccheggiata",b="Rezlak ha bisogno di rifornimenti costanti per il suo lavoro fuori da Orgrimmar. Sparachiodi ha ingaggiato l'ingegnere goblin di Porto Paranco per costruire per l'Orda. Una carovana con un carico promesso è passata vicino alla strada del canyon a sud di Orgrimmar. Le arpie Dustwind le hanno teso un'imboscata e hanno trascinato il carico nei loro posatoi nel Canyon Brezza Aguzza, spargendo i sacchi tra terra e pietrisco accanto ai nidi."}},faq={{q="Cosa c'è dentro questi sacchi di rifornimenti?",a="I sacchi contengono materiali da costruzione e merci di scambio per i lavori d'ingegneria di Sparachiodi. Sono destinati a sostenere i progetti di costruzione degli Orchi vicino a Orgrimmar. Senza di essi, Rezlak non può portare a termine il suo lavoro.",al={"contenuto del sacco di rifornimenti","cosa c'è nei sacchi","rifornimenti di rezlak"}},{q="Chi ha rubato i rifornimenti?",a="Le arpie Dustwind hanno rubato le provviste. Questa selvaggia razza aviaria infesta gli alti anfratti e i burroni del Canyon Brezza Aguzza.",al={"chi ha preso i rifornimenti","chi ha rubato i sacchi"}},{q="Chi è Rezlak?",a="Rezlak è un ingegnere goblin che Sparachiodi ha inviato da Porto Paranco per aiutare l'Orda a costruire e mantenere le infrastrutture di linea a Durotar.",al={"chi è rezlak","storia di rezlak"}}},fx={["812e6d27"]={q="Da dove vengono questi sacchi di provviste?",a="Questi sacchi facevano parte di una spedizione inviata a Durotar per conto di Gazlowe e dei suoi ingegneri goblin. Destinati ad aiutare gli orchi a costruire e mantenere i loro insediamenti, la carovana che li trasportava è stata imboscata e saccheggiata lungo la strada prima che potesse raggiungere la sua destinazione.",al={"origine del sacco di provviste","da dove vengono le provviste","chi ha fatto il sacco di provviste"}},["55ee41bd"]={q="Perché Rezlak vuole questi sacchi di provviste?",a="Rezlak non può svolgere i lavori di costruzione assegnatigli da Gazlowe senza l'attrezzatura e i materiali adeguati. Le arpie del Canyon Brezza Aguzza hanno saccheggiato la carovana che trasportava i suoi attrezzi e le sue provviste, lasciando il caposquadra goblin completamente bloccato finché qualcuno non recupera il carico rubato.",al={"perché rezlak vuole le provviste","perché servono i sacchi di provviste","provviste nel deserto perché"}}},fp="16,156,19.381.0,34.197.0,23.118.0,14.122.0"}
P.entries["item:salty-scorpid-venom"] = {n="Veleno Salato di Scorpide",s="A Millepicchi, il Veleno Salato di Scorpide attira gli gnomi in una pericolosa corsa alla velocità. Gli scorpidi delle Distese Salate hanno nel veleno i sali minerali del suolo desertico, e i piloti gnomi li cercano per ricavarne carburante.",h="A Millepicchi, il Veleno Salato di Scorpide attira gli gnomi in una pericolosa corsa alla velocità.",kw={"fizzle brassbolts","pista dei miraggi","veleno salato di scorpide","scorpid reaver","scorpid terror","veleno di scorpide","distese salate","millepicchi"},ang={["profession:Engineering"]="Come ingegnere, vedi gli inventori delle Distese Salate cercare alternative al petrolio e al carbone. Sperimentano tossine organiche come acceleranti volatili.",["race:Gnome"]="Come gnomo, conosci i rischi di trasformare il letale veleno del deserto in carburante per razzi usando negacatalizzatori, pur di guadagnare qualche secondo sul giro."},sec={{t="Un agente di combustione volatile",b="Gli scorpidi delle Distese Salate, ricche di minerali, hanno sale nel veleno. Gli Scorpid Reavers e gli Scorpid Terrors hanno assorbito questi sali locali nel corso delle generazioni. Fizzle Brassbolts e altri meccanisti gnomi apprezzano il veleno caustico come possibile additivo per carburanti da motore ad alta combustione, non per antidoti o veleni comuni."},{t="Alimentare la rivalità della pista",b="Alla Pista dei Miraggi, gnomi e goblin provano materiali sempre più pericolosi nelle loro auto a razzo. Fizzle Brassbolts crede che concentrare il veleno salato facendolo bollire, trattarlo con catalizzatori specializzati e mescolarlo nei serbatoi del propellente darà alla sua auto il calore intenso necessario per superare i piloti goblin sulle distese di sale."}},faq={{q="Quali creature producono il Veleno Salato di Scorpide?",a="Gli Scorpid Reavers e gli Scorpid Terrors delle distese saline di Millepicchi producono il Veleno Salato di Scorpide.",al={"chi rilascia il veleno salato di scorpide","dove trovare il veleno di scorpide","fonte del veleno di scorpide"}},{q="Perché il veleno è così salato?",a="Gli scorpidi vivono sul terreno incrostato di minerali delle Distese Salate. I loro corpi assorbono i sali concentrati del letto lacustre prosciugato, conferendo al veleno un'elevata concentrazione salina.",al={"perché è salato","spiegazione del salt flat venom","storia del sale dello scorpide"}},{q="Chi vuole questo veleno e perché?",a="Fizzle Brassbolts, un ingegnere gnomo della Pista dei Miraggi, cerca il veleno per una miscela di carburante sperimentale. Crede che brucerà a una temperatura abbastanza alta da spingere la sua auto a razzo alla vittoria.",al={"chi ha bisogno del veleno di scorpide","perché fizzle vuole il veleno","oggetto di missione di fizzle brassbolts"}}},fx={["9840b612"]={q="Cos'è il Veleno Salato di Scorpide?",a="È un fluido potente e ricco di minerali raccolto dagli scorpidi che si aggirano per le Distese Salate. Il duro bacino salino prosciugato ha causato agli orrori e ai saccheggiatori scorpidi locali lo sviluppo di un veleno insolitamente saturo di sale. Sebbene letale come tossina naturale, le sue proprietà chimiche reattive lo rendono molto più interessante per gli armaioli come reagente grezzo volatile che come semplice veleno.",al={"cos'è il veleno salato di scorpide","veleno salato di scorpide","veleno di scorpide distese salate"}}},fp="19,215,27.321.0,27.317.0,43.99.0,26.173.0,29.181.0"}
P.entries["item:samophlange-item"] = {n="Samoflago",s="Nelle Savane, il samophlange rimane nascosto in una console di controllo automatizzata. I meccanici goblin non sanno spiegare a cosa serva lo strano componente.",h="Nelle Savane, il samophlange rimane nascosto in una console di controllo automatizzata.",kw={"savane","console","porto paranco","samophlange","sputavalvole","tinkers' union","undermine"},ang={["profession:Engineering"]="Se sei un ingegnere, potresti riconoscere nel samophlange un progetto eccessivamente complicato. Il suo intricato involucro nasconde un meccanismo così fragile da rompersi quando viene appoggiato a terra."},sec={{t="Un marchingegno sconcertante",b="Il samophlange si trova in una console di controllo nelle Savane, dietro un labirinto di cavi e tubi cavi. Occorre cercare con cura per liberarlo dal suo alloggiamento. Sembra essenziale per i macchinari a ingranaggi e a vapore, eppure gli inventori goblin non riescono a scoprirne la funzione. Progettano di inviarlo alla Tinkers' Union a Undermine, anche se maneggiarlo senza riguardo potrebbe rompere il fragile pezzo."},{t="Curiosità e catastrofe",b="Sputavalvole, un ingegnere di Porto Paranco, progetta di inviare il samophlange alle menti più esperte della Tinkers' Union perché lo studino. Eppure la curiosità dei goblin manda spesso all'aria quel piano. Quando Sputavalvole appoggia il delicato dispositivo per esaminarne i meccanismi interni, questo si frantuma, riducendosi a rottami."}},faq={{q="Cos'è un samophlange?",a="Il samophlange è uno strano componente meccanico prelevato da una console di controllo nelle Savane. La sua funzione è sconosciuta, e la console che lo circonda è piena di tubi e cavi che sembrano non servire a nulla.",al={"cosa fa un samophlange","scopo del samophlange","cos'è questo oggetto"}},{q="Chi vuole il samophlange?",a="Sputavalvole, un ingegnere di Porto Paranco, vuole che gli venga portato il samophlange per studiarlo. Progetta di inviarlo alla Tinkers' Union.",al={"a chi serve il samophlange","a chi devo dare il samophlange"}},{q="Cosa ne fa Sputavalvole?",a="Sputavalvole progetta di inviare il samophlange a Undermine perché la Tinkers' Union lo studi. Prima, però, lo appoggia per ispezionarlo, e il fragile meccanismo si rompe.",al={"sputavalvole samophlange","cosa succede al samophlange"}},{q="Da dove viene il samophlange?",a="Il samophlange è alloggiato in una console operativa nelle Savane settentrionali, dietro strati di macchinari incomprensibili che sembrano non servire a nulla.",al={"posizione del samophlange","dove si trova"}}},fp="18,140,22.353.0,25.264.1,22.204.0,26.124.0,34.156.1,36.142.0"}
P.entries["item:samophlange-manual"] = {n="Manuale per Samoflago",s="A Orgrimmar, Rilli Greasygob cerca le pagine sparse del Manuale per Samoflago. Il manuale spiega come riparare e azionare il samoflago della S.P.R. & Co.",h="A Orgrimmar, Rilli Greasygob cerca le pagine sparse del Manuale per Samoflago.",kw={"savane","boss copperplug","miniera di pietravera","ingegneria","manuale","rilli greasygob","samoflago","sputavalvole","s.p.r. & co."},ang={["faction:Horde"]="Il manuale permette ai goblin di Orgrimmar alleati dell'Orda di studiare e riadattare i macchinari di perforazione della compagnia sotto il naso della S.P.R. & Co.",["profession:Engineering"]="Il manuale rivela tecnologie di proprietà della S.P.R. & Co. Mostra anche come gli inventori goblin proteggano i segreti del mestiere e gli schemi di funzionamento dai loro colleghi."},sec={{t="I segreti del congegno",b="Boss Copperplug custodiva gelosamente le conoscenze della S.P.R. & Co. sul samoflago. L'ambizioso sovrintendente teneva le pagine del manuale nascoste alla maggior parte dei lavoratori. Consegnava fogli sciolti solo ai suoi subordinati più fedeli. Quando il congegno sfuggì al controllo della compagnia, nessuno poté ripararlo senza recuperare le pagine strappate da Copperplug e dalla sua squadra alla Miniera di Pietravera."},{t="L'ambizione di un rivale",b="Rilli Greasygob lasciò la S.P.R. & Co. e si stabilì a Orgrimmar per scoprire come fosse costruito il samoflago. Copperplug non lo aveva mai visto di buon occhio, perciò Rilli si affida a viaggiatori intraprendenti per recuperare la copertina e i fogli sciolti del manuale. Una volta ricomposto, il manuale offre agli inventori goblin che lavorano con l'Orda una rara occasione per studiare l'ingegneria della S.P.R. & Co."}},faq={{q="Che cos'è il Manuale per Samoflago?",a="Il Manuale per Samoflago spiega come azionare e riparare il complesso e bizzarro congegno meccanico della S.P.R. & Co.",al={"cos'è il manuale per samoflago","libro del samoflago","guida al samoflago"}},{q="Chi possedeva originariamente il manuale?",a="Boss Copperplug, un sovrintendente della S.P.R. & Co. alla Miniera di Pietravera, nelle Savane nordorientali, custodiva il manuale. Ne proteggeva i segreti e consegnava singole pagine solo ai suoi lavoratori più fidati.",al={"chi ha il manuale","manuale di boss copperplug","chi ha scritto il manuale"}},{q="Perché il manuale è diviso in pagine?",a="Boss Copperplug smembrò il manuale per impedire ai rivali e ai subordinati di cui non si fidava di comprendere l'intero congegno. Tenne la copertina e consegnò cinque pagine specifiche ai suoi minatori e operatori.",al={"perché trovare le pagine del manuale","pagine del manuale sparse","perché mancano le pagine"}},{q="Chi vuole leggere il manuale completo?",a="Rilli Greasygob, un ingegnere di Orgrimmar, vuole il manuale ricomposto per comprendere e riparare il samoflago rotto recuperato nelle Savane.",al={"a chi serve il manuale","rilli greasygob","chi vuole il manuale per samoflago"}},{q="A cosa serve un samoflago?",a="Nessuno al di fuori della S.P.R. & Co. sembra sapere a cosa serva un samoflago. La compagnia ne sperimentò uno in un piccolo sito di ricerca a sud-ovest della Palude Fangosa, nelle Savane, ma persino gli ingegneri che lo studiarono riuscirono a capirci ben poco.",al={"cosa fa il samoflago","scopo del samoflago","a cosa serve il samoflago"}}},fp="18,165,26.354.0,18.351.0,31.117.0,32.197.0,34.191.0,39.147.0,31.252.0"}
P.entries["item:sample-ichor"] = {n="Icore Campione"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="Campione di Mistura di Zanzil Alterata",s="Oltre il mare, il Campione di Mistura di Zanzil Alterata è diretto a Mulino di Tarren. L'intruglio proviene dal fattucchiere Zanzil e debilita chi lo trasporta. Serge Hinott potrebbe trovare una cura e scoprire come agisce il veleno.",h="Oltre il mare, il Campione di Mistura di Zanzil Alterata è diretto a Mulino di Tarren.",kw={"mistura alterata","colletorto","veleni","ladro","serge hinott","palude fangosa","mulino di tarren","zanzil"},ang={["class:Rogue"]="Come ladro dell'Orda, porti questo pericoloso campione a Serge Hinott, le cui lezioni trattano la preparazione, la manipolazione e l'applicazione di veleni letali.",["faction:Horde"]="Come viaggiatore dell'Orda, trasporti l'intruglio attraverso un continente, in zeppelin e su strada, seguendo le rotte da Kalimdor ai territori dei Reietti a Lordaeron."},sec={{t="Un pegno tossico",b="Un agente trasporta la mistura dopo essersi introdotto nella torre della S.P.R. & Co. vicino alla Palude Fangosa, nelle Savane. Il campione proviene da una scorta nella cassetta di sicurezza di Gallywix, e l'intruglio di Zanzil ha colpito l'agente. Shenthul invia l'agente sofferente oltre il Grande Mare con il campione. A Mulino di Tarren, nelle Alture di Colletorto, lo speziale Serge Hinott può isolare la tossina e scoprirne i componenti."},{t="Segreti della creazione di veleni",b="Serge Hinott studia la mistura alterata per aiutare il corriere colpito e imparare a preparare e maneggiare potenti veleni sul campo. I ladri dell'Orda cercano queste conoscenze per padroneggiare le arti più oscure del loro mestiere."}},faq={{q="Cos'è questa mistura?",a="La mistura è un preparato alchemico legato al fattucchiere Zanzil, recuperato dalla torre della S.P.R. & Co. vicino alla Palude Fangosa, nelle Savane. La sua potente tossina provoca effetti persistenti e debilitanti su chiunque la tocchi direttamente.",al={"cos'è la mistura di zanzil","campione di mistura alterata di zanzil","campione di veleno di zanzil"}},{q="Perché devo portarla a Serge Hinott?",a="Serge Hinott è uno speziale di Mulino di Tarren, nelle Alture di Colletorto. Le sue conoscenze possono contrastare gli effetti dell'intruglio e fornire una cura affidabile prima che la tossina provochi danni permanenti.",al={"chi è serge hinott","perché portare a mulino di tarren","cura per la mistura di zanzil"}},{q="Chi è Zanzil?",a="Zanzil the Outcast è un fattucchiere troll della giungla noto per creare elisir che inducono la follia, veleni e mutageni. Le sue ricette tossiche si sono diffuse oltre le giungle da cui proviene, raggiungendo organizzazioni mercenarie e industriali come la S.P.R. & Co.",al={"chi è zanzil","zanzil il reietto","storia di zanzil"}},{q="Come si raggiunge Mulino di Tarren per consegnarla?",a="Prendi lo zeppelin da Durotar a Sepulcra, nelle Radure di Tirisfal. Poi segui la strada principale verso sud attraverso la Selva Pinargento e le indicazioni verso est, nelle Alture di Colletorto, fino a Mulino di Tarren.",al={"come raggiungere mulino di tarren","viaggiare verso colletorto","indicazioni per mulino di tarren"}}},fp="34,213,13.394.0,22.207.1,21.236.0,41.185.0,14.243.0,43.189.0"}
P.entries["item:sample-snapjaw-shell"] = {n="Campione di Carapace di Tartarabbia",s="Nelle Savane, i carapaci delle tartarabbia custodiscono una scintilla di vita delle oasi d'acqua dolce. I druidi tauren li inviano oltre il Grande Mare per aiutare la Selva Pinargento.",h="Nelle Savane, i carapaci delle tartarabbia custodiscono una scintilla di vita delle oasi d'acqua dolce.",kw={"savane","mura runetotem","oasi","campione di carapace di tartarabbia","mausolea","selva pinargento","tartarabbia","guscio di tartaruga"},ang={["class:Druid"]="Per i druidi del Circolo Cenariano, studiare le tartarabbia delle oasi insegna come la vita resista e come si possa risanare il terreno corrotto.",["race:Tauren"]="Come tauren, puoi vedere il viaggio di questo carapace come un impegno verso la Earth Mother. Il tuo popolo porta aiuto e cure naturali oltre il mare, persino ai suoi alleati non morti."},sec={{t="Una scintilla di vita delle oasi",b="Le tartarabbia prosperano nelle strane e rigogliose oasi delle Savane. I loro resistenti carapaci conservano un tenue bagliore e pulsano di energia molto tempo dopo la morte della creatura. I druidi tauren osservano i rapidi mutamenti della terra e vedono in questi carapaci una tenace scintilla della natura selvaggia di Kalimdor. Il loro vigore mostra come la vita possa prosperare anche in terre aspre e aride."},{t="Curare terre lontane",b="I naturalisti tauren inviano corrieri oltre il mare con carapaci destinati a Mura Runetotem, a Mausolea. Si trova nelle distese corrotte della Selva Pinargento, dove cerca modi per aiutare i Reietti a risanare le terre del nord. Mura studia la forza vitale custodita nella corazza delle tartarabbia, sperando che riveli cosa possa rigenerare una foresta malata e riportare la crescita nel suolo morente."}},faq={{q="Cosa rende speciale questo carapace di tartarabbia?",a="Un Campione di Carapace di Tartarabbia conserva un tenue bagliore e un palpito di vita molto tempo dopo la raccolta. Proviene dalle tartarabbia che vivono attorno alle strane oasi d'acqua dolce delle Savane, dove le energie naturali sono insolitamente intense.",al={"perché il carapace è speciale","cos'è il carapace di tartarabbia","carapace luminoso"}},{q="Chi ha bisogno di questo campione?",a="Mura Runetotem, una druida tauren, ha bisogno del carapace a Mausolea, nella Selva Pinargento. Cerca modi per aiutare i Reietti a risanare le terre morenti.",al={"chi vuole il carapace","dove porto il carapace","missione mura runetotem"}},{q="Perché inviare un carapace delle Savane fino alla Selva Pinargento?",a="I boschi della Selva Pinargento sono corrotti e malati, mentre nelle oasi delle Savane la vita è esplosa e ha resistito. I druidi sperano che la vitalità delle bestie di Kalimdor possa insegnare loro come risanare il suolo danneggiato di Lordaeron.",al={"perché inviare a selva pinargento","collegamento del carapace con selva pinargento"}},{q="Il carapace è pericoloso o contaminato?",a="No. Il carapace custodisce pura vitalità, non magia oscura. I druidi vedono nell'energia che persiste tra l'improvvisa crescita delle Savane una tenacia naturale che vale la pena coltivare.",al={"il carapace è malvagio","il carapace è corrotto"}}},fx={["6161673b"]={q="Cos'è il Campione di Carapace di Tartarabbia?",a="È un esemplare prelevato dal carapace di una tartaruga tartarabbia trovata nelle aride distese delle Barrens. Infuso di una strana vitalità pulsante, questo guscio viene conservato con cura in modo che la sua insolita energia vitale possa essere esaminata lontano dalle pianure di Kalimdor.",al={"cos'è il campione di carapace di tartarabbia","oggetto carapace di tartarabbia","identità campione di carapace di tartarabbia"}},c3ef5b23={q="Da dove proviene il Campione di Carapace di Tartarabbia?",a="Proviene dalle tartarabbia selvatiche che dimorano attorno alle oasi e ai corsi d'acqua delle Barrens. Il guscio naturale è stato raccolto dagli avventurieri dell'Orda a Kalimdor e scelto dai druidi tauren come campione rappresentativo della fiorente forza vitale presente all'interno della terra desolata baciata dal sole.",al={"origine carapace di tartarabbia","da dove proviene il carapace di tartarabbia","chi ha fatto il campione di carapace di tartarabbia"}}},fp="20,149,21.326.0,21.350.0,38.194.0,22.140.0,51.200.0,34.157.0"}
P.entries["item:samuel-s-remains"] = {n="Resti di Samuel",s="Vicino ad Albamorta, le ossa di Samuel vengono recuperate da un servo del Flagello e deposte accanto a Marla.",h="Vicino ad Albamorta, le ossa di Samuel vengono recuperate da un servo del Flagello e deposte accanto a Marla.",kw={"albamorta","marla fipps","tomba di marla","marla's last wish","novizia elreth","samuel fipps","resti di samuel"},ang={["race:Undead"]="Come non morto, impari presto che onorare i morti dalla sorte tragica segna il confine morale tra i Reietti liberi e i servi senza volontà del Flagello."},sec={{t="Una tragica riunione",b="Samuel Fipps e sua moglie Marla vivevano in pace nelle Radure di Tirisfal prima che la piaga della non morte dilagasse per Lordaeron. Samuel soccombette e divenne un servo senza volontà del Flagello. Marla sfuggì alla non morte, ma Samuel la uccise. In punto di morte, chiese di essere sepolta accanto a lui una volta che la sua forma maledetta avesse trovato riposo.\n\nLa Novizia Elreth ad Albamorta manda i Reietti appena risvegliati a nord-est dell'insediamento. Lì devono trovare la forma errante di Samuel, recuperarne le ossa e seppellirle nella prima fila del cimitero locale."}},faq={{q="Chi era Samuel Fipps?",a="Samuel Fipps era un umano che viveva nelle Radure di Tirisfal prima della Third War. La piaga del Flagello lo uccise e lo rianimò come servo non morto del Lich King, privo di volontà. Spinto da una fame cieca, finì per uccidere sua moglie Marla.",al={"samuel fipps","chi è samuel","storia di samuel"}},{q="Dove si trovano i resti di Samuel?",a="I resti di Samuel vengono recuperati dalla sua forma errante presso un accampamento in rovina lungo la strada a nord-est di Albamorta. Porre fine alla sua esistenza priva di volontà permette di recuperarne le ossa.",al={"trovare i resti di samuel","dove si trova samuel fipps","posizione di samuel"}},{q="Perché i Reietti lo seppelliscono accanto a sua moglie?",a="L'ultimo desiderio di Marla era riposare accanto al suo amato marito, benché fosse stato lui a ucciderla. La Novizia Elreth esaudisce la sua richiesta per mostrare che i Reietti appena liberati conservano compassione, rispetto per i morti e l'umanità che li distingue dal Flagello.",al={"perché seppellire samuel","tomba di marla","ultimo desiderio di marla"}}},fx={["29aac9a9"]={q="Da dove vengono i Resti di Samuel?",a="Questi sono i resti fisici mortali di Samuel Fipps, un ex residente delle Radure di Tirisfal che cadde vittima della piaga della non morte e divenne una pedina senza mente del Flagello. Dopo aver vagato per la natura selvaggia a nord-est di Albamorta, il suo corpo non morto viene abbattuto in modo che i suoi resti possano finalmente essere raccolti e sepolti.",al={"origine resti di samuel","da dove vengono i resti di samuel","chi ha fatto i resti di samuel"}}},fp="16,88,16.522.0,21.221.0,33.177.0,45.258.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="Zaffiro di Aku'mai",s="Lungo gli Abissi di Fondocupo, i naga estraggono gli Zaffiri di Aku'mai. Gli spiriti dell'acqua sono legati ai cristalli, e Je'neu Sancrea cerca aiuto per impadronirsene prima che il loro potere arcano venga usato.",h="Lungo gli Abissi di Fondocupo, i naga estraggono gli Zaffiri di Aku'mai.",kw={"aku'mai","abissi di fondocupo","cristalli","je'neu sancrea","naga","zaffiro","spiriti dell'acqua","spiaggia di zoram"},ang={["class:Mage"]="L'acqua impregna naturalmente gli zaffiri, rendendoli preziosi conduttori per potenti componenti arcani.",["class:Shaman"]="Come sciamano del Circolo della Terra, puoi percepire gli spiriti dell'acqua vincolati all'interno di queste gemme. L'estrazione da parte dei naga minaccia gli elementi."},sec={{t="Gemme degli Abissi",b="Presso gli ingressi allagati degli Abissi di Fondocupo, lungo la Spiaggia di Zoram a Valtetra, le pareti sono costellate di Zaffiri di Aku'mai. Gli spiriti dell'acqua sono legati ai cristalli, la cui energia elementale potenzia la magia. Quando gli esploratori riferirono che i naga estraevano le gemme nel sottosuolo, Je'neu Sancrea, uno sciamano, chiese aiuto ai viaggiatori per impadronirsene. Nelle mani dei naga, le pietre potrebbero alimentare devastanti riti arcani."}},faq={{q="Cos'è uno Zaffiro di Aku'mai?",a="Gli Zaffiri di Aku'mai costellano le pareti degli Abissi di Fondocupo. Gli spiriti dell'acqua sono legati ai cristalli e conferiscono loro un profondo potere arcano ed elementale.",al={"cos'è questo cristallo","storia dello zaffiro di aku'mai","cosa sono queste gemme"}},{q="Perché i naga stanno raccogliendo questi zaffiri?",a="Je'neu Sancrea sospetta che i naga intendano sfruttare le energie acquatiche e arcane dei cristalli per praticare pericolose stregonerie nel tempio sommerso. Le loro esatte intenzioni restano incerte.",al={"perché i naga vogliono gli zaffiri","raccolta dei cristalli da parte dei naga"}},{q="Chi sta cercando questi zaffiri?",a="Je'neu Sancrea, uno sciamano del Circolo della Terra all'Avamposto di Zoram'gar sulla Spiaggia di Zoram a Valtetra, chiede ai viaggiatori di raccogliere gli zaffiri e sottrarli ai naga.",al={"chi vuole gli zaffiri di aku'mai","chi consegna essenza di aku'mai"}},{q="Questi cristalli sono direttamente collegati alla bestia Aku'mai?",a="I cristalli prendono il nome da Aku'mai, la mostruosa idra degli abissi, ma crescono naturalmente nelle pareti delle caverne. Il loro nome riflette la vicinanza all'oscura presenza nelle rovine.",al={"legame con aku'mai","proviene da aku'mai"}}},fx={["12f03799"]={q="Da dove vengono gli Zaffiri di Aku'mai e chi li ha creati?",a="Questi grandi grappoli di zaffiri crescono naturalmente lungo le pareti delle caverne all'interno dei tunnel iniziali degli Abissi di Fondocupo. Non sono creati da mani mortali; piuttosto, sono formazioni minerali naturali intrise delle energie ambientali della caverna. Gli spiriti dell'acqua si aggrappano naturalmente ai cristalli, conferendo loro un'intrinseca potenza elementale.",al={"origine dello zaffiro di aku'mai","chi ha fatto lo zaffiro di akumai","da dove vengono gli zaffiri di aku'mai"}}},fp="19,179,16.380.0,30.139.0,44.176.0,35.158.0,54.186.0"}
P.entries["item:sapphire-of-sky"] = {n="Zaffiro del Cielo",s="Nell'Eremo di Ban'ethil, lo Zaffiro del Cielo aiuta a richiamare i Druidi dell'Unghia dormienti dal Sogno di Smeraldo. Gli elfi della notte lo custodiscono come una delle quattro sacre Relics of Wakening.",h="Nell'Eremo di Ban'ethil, lo Zaffiro del Cielo aiuta a richiamare i Druidi dell'Unghia dormienti dal Sogno di...",kw={"athridas orsomanto","eremo di ban'ethil","chest of the sky","druido dell'unghia","sogno di smeraldo","relics of wakening","zaffiro del cielo"},ang={["class:Druid"]="Come druido, puoi capire perché gli ancoraggi sacri sono importanti quando il tuo spirito entra nel Sogno di Smeraldo. Senza di essi, la comunione può diventare fatale.",["race:NightElf"]="Come elfo della notte, sai che proteggere le sacre reliquie nell'Eremo di Ban'ethil aiuta a preservare il fragile ordine di Teldrassil mentre la corruzione dilaga."},sec={{t="Il Rituale del Risveglio",b="I Druidi dell'Unghia dormono in letargo nell'Eremo di Ban'ethil, nelle profondità delle radici di Teldrassil. Lì, entrano in comunione con la natura selvaggia. Risvegliarsi da quella profonda trance è pericoloso, perciò quattro sacre reliquie proteggono il passaggio: la Piuma Nera, il Talismano Artiglio del Corvo, la Runa della Nidificazione e lo Zaffiro del Cielo. La gemma completa l'armonia necessaria a richiamare gli spiriti dormienti dal Sogno di Smeraldo. Senza di essa, potrebbero rimanervi intrappolati per sempre."},{t="La Minaccia a Ban'ethil",b="I furbolg Gnarlpine corrotti hanno invaso l'Eremo di Ban'ethil, lasciando le sacre reliquie nei loro ricettacoli. Lo Zaffiro del Cielo si trova all'interno del Chest of the Sky, lungo i tortuosi corridoi sotterranei. I druidi dormono ancora mentre i furbolg imperversano intorno a loro. Ad Athridas Orsomanto, a Dolanaar, servono lo zaffiro e le altre reliquie per risvegliare i dormienti prima che siano perduti per sempre."}},faq={{q="Cos'è lo Zaffiro del Cielo?",a="Lo Zaffiro del Cielo è una gemma sacra e una delle quattro Relics of Wakening custodite nell'Eremo di Ban'ethil. Agisce insieme a tre talismani aviari per guidare i Druidi dell'Unghia fuori dal Sogno di Smeraldo in sicurezza.",al={"storia dello zaffiro del cielo","cos'è questa gemma","zaffiro del cielo"}},{q="Dove è custodito lo Zaffiro del Cielo?",a="Lo Zaffiro del Cielo è custodito all'interno del Chest of the Sky, nel labirinto sotterraneo dell'Eremo di Ban'ethil, nella parte centrale di Teldrassil.",al={"dove trovare lo zaffiro del cielo","posizione del chest of the sky","posizione dello zaffiro"}},{q="Perché lo zaffiro è necessario proprio ora?",a="I furbolg Gnarlpine corrotti hanno invaso l'Eremo di Ban'ethil e messo in grave pericolo i druidi dormienti. Immersi in una profonda trance, non possono semplicemente risvegliarsi da soli. Ad Athridas Orsomanto servono lo zaffiro e le altre reliquie per il delicato rituale di risveglio, prima che i dormienti siano perduti per sempre.",al={"perché recuperare lo zaffiro","scopo delle relics of wakening"}},{q="Chi usa questo manufatto?",a="I Druidi dell'Unghia e i custodi dei rituali come Athridas Orsomanto usano lo zaffiro per risvegliare i loro fratelli dormienti dalla profonda comunione con la natura.",al={"chi usa lo zaffiro del cielo","gemma rituale dei druidi"}}},fp="15,171,19.457.0,23.394.0,28.199.0,34.132.0,37.295.0,23.152.0"}
P.entries["item:sara-balloo-s-plea"] = {n="Supplica di Sara Balloo",s="Nel suo dolore, Sara Balloo chiede a un campione dell'Alleanza di portare il suo appello scritto a mano a Re Magni Barbabronzea.",h="Nel suo dolore, Sara Balloo chiede a un campione dell'Alleanza di portare il suo appello scritto a mano a Re...",kw={"a king's tribute","high seat","forgiardente","magni barbabronzea","sara balloo","supplica di sara balloo"},ang={["faction:Alliance"]="Come campione dell'Alleanza, porti la supplica di Sara al cospetto del sovrano. Sara si fida di te per il tuo servizio all'Alleanza.",["race:Dwarf"]="Come nano, porti il messaggio di Sara all'High Seat affinché Re Magni ascolti ogni montanaro o cittadino, anche nel dolore."},sec={{t="L'appello di una vedova",b="Il dolore impedisce a Sara di presentarsi all'High Seat, così affida le sue parole a un avventuriero fedele all'Alleanza. Chiede a Re Magni di ricordare il lutto privato e i sacrifici delle comuni famiglie naniche al servizio del regno."}},faq={{q="Cos'è la Supplica di Sara Balloo?",a="La Supplica di Sara Balloo è una lettera scritta a mano per Re Magni Barbabronzea. Sara chiede la sua attenzione mentre vive il proprio lutto in privato.",al={"supplica di sara balloo","nota della vedova forgiardente","nota di sara"}},{q="Perché Sara Balloo ha bisogno che qualcun altro la consegni?",a="Sara è sopraffatta dal dolore e crede che presentarsi al Re di Forgiardente in quello stato ostacolerebbe la sua supplica. Così si affida a un campione dell'Alleanza perché la consegni.",al={"perché consegnare la nota","perché sara non può andare","dolore di sara"}},{q="Chi riceve questo messaggio?",a="Re Magni Barbabronzea riceve la lettera di Sara all'High Seat di Forgiardente.",al={"chi riceve la supplica","a chi consegnare","lettera per magni"}},{q="A cosa porta la consegna della lettera?",a="La consegna della lettera porta il lutto di Sara Balloo all'attenzione di Re Magni e dà avvio a una risposta della corona in onore dei suoi familiari caduti.",al={"serie di missioni della supplica","collegamento a kings tribute","cosa succede dopo"}}},fx={["2b83ea9f"]={q="Da dove proviene la Supplica di Sara Balloo e chi l'ha scritta?",a="Questa nota scritta è stata redatta direttamente da Sara Balloo, una donna nana in lutto a Forgiardente. Devastata dalla perdita, ha preparato personalmente il messaggio per presentare petizione al trono di Forgiardente, affidandolo a un campione dell'Alleanza invece di tentare da sola l'emotivo viaggio verso l'High Seat.",al={"chi ha scritto la supplica di sara balloo","da dove viene la supplica di sara balloo","chi ha fatto la supplica di sara balloo"}},["4ac5e6cf"]={q="Perché qualcuno vuole la Supplica di Sara Balloo?",a="Re Magni Barbabronzea necessita della lettera per ascoltare la petizione di uno dei suoi sudditi in lutto. Sara Balloo non riesce a presentarsi davanti al monarca nel suo stato di dolore, quindi conta su di te per presentare l'appello direttamente nelle mani del sovrano di Forgiardente.",al={"perché serve la supplica di sara balloo","chi vuole la supplica di sara balloo","perché consegnare la supplica di sara balloo"}}},fp="18,110,16.229.0,27.127.0,53.166.0,26.76.0,40.136.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="Testa di Sarilus Malonato",s="Oltre il confine delle Savane, la Testa di Sarilus Malonato giunge a Valtetra come prova della morte dello stregone. Aveva profanato le acque di Valtetra, e le Sentinelle avevano preteso la sua testa.",h="Oltre il confine delle Savane, la Testa di Sarilus Malonato giunge a Valtetra come prova della morte dello...",kw={"savane","picco di brumafunesta","testa","mage summoner","sarilus foulborne","rifugio vento argentato","velene tagliastelle","elementali dell'acqua"},ang={["faction:Alliance"]="Questo attacco richiede di infiltrarsi in profondità nelle ostili terre dell'Orda nelle Savane per eliminare un pericoloso incantatore rinnegato.",["race:NightElf"]="Prendere la testa di Foulborne soddisfa la sete di vendetta delle Sentinelle contro un profanatore arcano che ha dissacrato gli spiriti della terra."},sec={{t="Un Profanatore Messo a Tacere",b="Sarilus Foulborne era un incantatore dei Reietti che si era insediato in cima al Picco di Brumafunesta, nelle Savane settentrionali. Aveva suscitato l'ira degli elfi della notte corrompendo e assoggettando sciami di elementali dell'acqua.\n\nDal Rifugio Vento Argentato, la Sentinella Velene Tagliastelle riconobbe la sua opera e inviò campioni oltre la frontiera, nel territorio dell'Orda, per porre fine ai suoi esperimenti. Tagliastelle avrebbe accettato soltanto la sua testa mozzata come prova che il mago beffardo fosse morto e che le tormentate acque di Valtetra potessero trovare un po' di pace."}},faq={{q="Chi era Sarilus Foulborne?",a="Sarilus Foulborne era un mago non morto che si era insediato in cima al Picco di Brumafunesta, nelle Savane settentrionali. Aveva suscitato l'ira degli elfi della notte distorcendo ed evocando un gran numero di elementali dell'acqua, così la Sentinella Velene Tagliastelle ne ordinò la morte.",al={"chi è sarilus","storia di sarilus foulborne","chi è foulborne"}},{q="Perché la Sentinella Velene Tagliastelle vuole la sua testa?",a="Velene Tagliastelle voleva la certezza che l'arrogante stregone fosse morto. Sarilus la scherniva mentre profanava gli spiriti dell'acqua della regione, e la sua testa mozzata era l'unica prova che avrebbe accettato della fine della minaccia.",al={"perché prendere la sua testa","testa velene tagliastelle","prova della morte"}},{q="Dove si trova Sarilus Foulborne?",a="Sarilus Foulborne ha il suo covo in cima al Picco di Brumafunesta, nelle Savane settentrionali, appena a sud del confine con Valtetra.",al={"dove trovare foulborne","posizione di sarilus","mago di picco di brumafunesta"}},{q="Perché Foulborne profanava gli elementali dell'acqua?",a="Sarilus Foulborne usava evocazioni arcane per piegare numerosi elementali dell'acqua alla propria volontà e corromperli. La sua sconsiderata manipolazione sconvolse l'equilibrio naturale delle acque che scorrevano vicino a Valtetra, provocando una rapida rappresaglia delle Sentinelle.",al={"perché corrompere gli elementali","corruzione degli elementali dell'acqua","motivazioni di foulborne"}}},fx={a996e76e={q="Da dove proviene la Testa di Sarilus Malonato?",a="Questa testa mozzata è presa direttamente da Sarilus Malonato, un mago Reietti che si è stabilito in cima al Picco di Brumafunesta nelle Barrens settentrionali. Operando vicino ai confini di Valtetra, Malonato passava le sue giornate a profanare i Water Elementals e a provocare gli elfi della notte finché la Sentinella Velene Tagliastelle non ha inviato un avventuriero nel territorio nemico per porre fine alla sua derisione.",al={"origine della testa di sarilus","origine della testa di malonato","da dove viene la testa di malonato"}}},fp="24,177,18.497.1,26.241.1,50.217.0,35.104.1,44.240.0"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="Chela Mutilata di Sarkoth",s="Tra i dirupi meridionali della Valle delle Sfide, la Chela Mutilata di Sarkoth reca il segno di un cacciatore ferito. Hana'zua schiacciò la chela dello scorpide prima che il suo pungiglione velenoso lo abbattesse.",h="Tra i dirupi meridionali della Valle delle Sfide, la Chela Mutilata di Sarkoth reca il segno di un cacciatore...",kw={"chela","durotar","hana'zua","chela mutilata","sarkoth","scorpide","valle delle sfide"},ang={["faction:Horde"]="Per un membro dell'Orda, conquistare il trofeo nella Valle delle Sfide rappresenta una delle prime prove di coraggio e forza marziale nelle aspre terre selvagge di Durotar.",["race:Troll"]="Per un troll, portare la chela a Hana'zua dona un po' di dignità a un consanguineo Puntascura morente. Scopre così che il suo ultimo colpo ha lasciato un segno sulla bestia prima della fine."},sec={{t="Un trofeo di vendetta",b="Hana'zua, un giovane troll Puntascura, incontrò Sarkoth mentre cacciava nella Valle delle Sfide. L'enorme scorpide gli trafisse il petto con il pungiglione velenoso, lasciandolo sanguinante sotto un albero vicino.\n\nPrima di essere punto, Hana'zua schiacciò la chela della bestia. La chela martoriata dimostra che Sarkoth è stato ucciso. Per il cacciatore ferito, il segno sulla chela dimostra che il suo colpo disperato è andato a segno e preserva il suo onore di guerriero mentre il veleno gli scorre nelle vene."}},faq={{q="Perché la chela è mutilata?",a="La chela di Sarkoth fu schiacciata in un duello disperato con Hana'zua, un cacciatore troll. Sarkoth punse Hana'zua al petto, ma il troll colpì prima che la chela della bestia potesse chiudersi attorno alla sua gamba.",al={"perché la chela è rotta","chi ha frantumato la chela di sarkoth","storia della chela mutilata"}},{q="Chi vuole la Chela Mutilata di Sarkoth?",a="Hana'zua chiede che gli venga portata la chela. Gravemente ferito sotto un albero nella Valle delle Sfide, teme di morire lì. Vuole che Sarkoth venga ucciso per preservare il proprio onore; vedere l'impresa compiuta gli dà la forza di resistere finché Gornek non manderà aiuto.",al={"a chi serve la chela di sarkoth","a chi si consegna","chela di hanazua"}},{q="Da dove proviene questa chela?",a="La chela proviene da Sarkoth, un grosso scorpide aggressivo che si aggira sull'altopiano lungo le scogliere meridionali della Valle delle Sfide, a Durotar.",al={"posizione di sarkoth","dove si trova sarkoth","dove trovare la chela mutilata"}}},fx={["5a9dc5fc"]={q="Cos'è la Chela Mutilata di Sarkoth?",a="È la chela mozzata di Sarkoth, uno scorpide insolitamente grande e feroce che si aggira sull'altopiano meridionale sopra la Valle delle Sfide. La chela presenta gravi danni, con schegge inflitte dal troll dei Durepi Hana'zua, gravemente ferito, durante il loro disperato scontro, servendo come prova innegabile che la bestia mostruosa è stata finalmente uccisa.",al={"cos'è la chela mutilata di sarkoth","identità della chela di sarkoth","chela mutilata"}}},fp="22,191,21.449.0,24.189.0,33.219.0,30.147.0"}
P.entries["item:sarltooth-s-talon"] = {n="Artigli di Dentesauro",s="Sopra gli Scavi di Whelgar, gli Artigli di Dentesauro sono tutto ciò che resta dell'attacco del raptor. Ormer Trecciaferro vuole l'artiglio come prova della morte della bestia.",h="Sopra gli Scavi di Whelgar, gli Artigli di Dentesauro sono tutto ciò che resta dell'attacco del raptor.",kw={"scavo","ormer trecciaferro","raptor","dentesauro","artiglio","paludi grigie","whelgar"},ang={["class:Hunter"]="Come cacciatore, seguire le tracce di un capobranco astuto come Dentesauro e prenderne un artiglio come trofeo mette alla prova la tua mira e il tuo dominio sulle bestie.",["race:Dwarf"]="Come nano, recuperare questo artiglio significa vendicare gli archeologi nani morti al servizio della Lega degli Esploratori per volere di Re Magni Barbabronzea."},sec={{t="Un trofeo di vendetta",b="Ormer Trecciaferro osservò dalla cresta mentre i raptor invadevano gli Scavi di Whelgar e massacravano la spedizione nanica. Non poté fermarli. Un raptor enorme, Dentesauro, gli sembrò il capobranco. In cerca di vendetta per i suoi congiunti caduti, Ormer pretese la morte della bestia e uno dei suoi artigli come prova. L'artiglio segna la fine del dominio di Dentesauro sulle antiche rovine naniche."}},faq={{q="Da dove provengono gli Artigli di Dentesauro?",a="Gli Artigli di Dentesauro provengono da Dentesauro, un grosso raptor alfa che si aggira sulle creste occidentali sopra gli Scavi di Whelgar, nelle Paludi Grigie.",al={"chi rilascia gli artigli di dentesauro","posizione di dentesauro","come ottenere l'artiglio"}},{q="Chi vuole gli Artigli di Dentesauro?",a="Ormer Trecciaferro vuole l'artiglio. Il nano sorveglia gli Scavi di Whelgar dall'osservatorio soprastante e chiede una prova della morte della bestia che ha massacrato la sua squadra.",al={"chi accetta l'artiglio","dove consegnare l'artiglio","missione di ormer trecciaferro"}},{q="Perché Ormer Trecciaferro ha bisogno di una prova della morte di Dentesauro?",a="Ormer crede che Dentesauro guidasse il branco di raptor che scacciò e uccise gli scavatori nani. Vede nell'artiglio un segno di giustizia e un po' di pace per i suoi colleghi caduti.",al={"perché uccidere dentesauro","cosa ha fatto dentesauro"}},{q="Cosa è successo ai nani al sito di scavo?",a="La spedizione nanica cercava antichi manufatti per la Lega degli Esploratori. I raptor selvaggi tesero un'imboscata ai lavoratori, massacrandone la maggior parte e costringendo i superstiti a rifugiarsi sulla cresta vicina.",al={"storia degli scavi di whelgar","perché ci sono raptor allo scavo"}}},fx={["28fc0e8a"]={q="Cos'è l'Artiglio di Dentesauro?",a="È un artiglio mozzato preso da Dentesauro, il feroce raptor sospettato di guidare il branco selvaggio che ha invaso gli Scavi di Whelgar. Ormer Trecciaferro richiede l'artiglio come prova innegabile che la bestia è stata uccisa e che i nani scavatori caduti sono stati vendicati.",al={"cos'è l'artiglio di dentesauro","lore dell'artiglio di dentesauro"}}},fp="17,153,21.384.0,39.137.0,28.174.0,57.173.0,52.167.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="Sacrificio di Sathrah",s="Al Temple of the Moon, il Sacrificio di Sathrah offre allo spirito di Lady Sathrah una possibilità di pace. La sua Filatura Argentea proviene dal possente ragno che dimora a Teldrassil.",h="Al Temple of the Moon, il Sacrificio di Sathrah offre allo spirito di Lady Sathrah una possibilità di pace.",kw={"darnassus","elune","lady sathrah","sacerdotessa a'moora","sacrificio di sathrah","filatura argentea","ragno","teldrassil","temple of the moon"},ang={["class:Priest"]="Come sacerdote, puoi vedere il rito come un atto di misericordia divina. La Sisterhood of Elune usa le acque sante per purificare la contaminazione, anziché limitarsi a disfarsi della bestia uccisa.",["race:NightElf"]="Come Elfo della Notte, sai che abbattere gli animali corrotti è un triste dovere. Riportare lo spirito di Lady Sathrah nella grazia di Elune onora quel dovere."},sec={{t="Purificazione nelle Acque Sacre",b="Lady Sathrah era una venerabile creatura di Teldrassil. Poi una follia strisciante e la corruzione si diffusero tra i rami del Grande Albero e si impadronirono di lei. La Sisterhood of Elune ti chiede di riportare la sua Filatura Argentea come offerta consacrata. Non è un trofeo.\n\nAlla fontana del Temple of the Moon, i suoi resti vengono immersi nell'acqua santa. Il rito lava via la contaminazione che avvelenava la mente di Sathrah e libera la sua anima tormentata. Il suo spirito appare sereno nel santuario, con la promessa di rinascere nella grazia di Elune."}},faq={{q="Cos'è il Sacrificio di Sathrah?",a="Il Sacrificio di Sathrah offre la Filatura Argentea prelevata da Lady Sathrah, un possente ragno corrotto a Teldrassil. La Sisterhood of Elune la usa in un rito per purificare la sua anima.",al={"cos'è la filatura argentea","oggetto sacrificio di sathrah","offerta di lady sathrah"}},{q="Perché bisogna deporre la Filatura Argentea nella fontana?",a="La fontana del Temple of the Moon di Darnassus contiene acqua santa consacrata a Elune. Immergere i resti di Sathrah lava via la corruzione che l'ha fatta impazzire e libera il suo spirito dal tormento.",al={"perché la fontana del tempio","perché sacrificare sathrah","cosa fa la fontana"}},{q="Cosa succede quando viene presentata l'offerta?",a="Quando deponi l'offerta nelle acque sacre, la corruzione viene purificata e appare la forma spettrale di Lady Sathrah. Cammina serenamente intorno alla vasca, mostrando che la sua anima è in pace.",al={"cosa accade alla fontana","apparizione dello spirito di sathrah","evento della fontana"}},{q="Chi sovrintende a questo rituale?",a="La Sacerdotessa A'moora sovrintende al rito. Al servizio della Sisterhood of Elune e di stanza nel Temple of the Moon, ti incarica di dare pace a Sathrah e offrire i suoi resti alla dea.",al={"chi affida sacrificio di sathrah","missione sacerdotessa a'moora","chi purifica sathrah"}}},fx={c7289e92={q="Da dove proviene il Sacrificio di Sathrah?",a="La Sacerdotessa A'moora ha preparato questa offerta direttamente dalle filatura argentea prese da Lady Sathrah, un grande ragno abbattuto a Teldrassil dopo essere caduto nella follia e nella corruzione.",al={"origine del sacrificio di sathrah","da dove viene il sacrificio di sathrah","chi ha creato il sacrificio di sathrah"}},b18748b3={q="Perché la Sacerdotessa A'moora vuole il Sacrificio di Sathrah?",a="La Sacerdotessa A'moora richiede il sacrificio affinché possa essere adagiato nelle acque sacre del The Temple of the Moon. Attraverso questa offerta a Elune, la corruzione che ha distorto Lady Sathrah in vita può finalmente essere purificata, dando pace alla grande bestia e permettendo al suo spirito di rinascere rinnovato.",al={"perché è richiesto il sacrificio di sathrah","perché offrire il sacrificio di sathrah","a cosa serve il sacrificio di sathrah"}}},fp="19,171,31.542.0,28.176.0,50.196.0,44.187.1,25.187.0"}
P.entries["item:satyr-horns"] = {n="Corna di Satiro",s="A Valtetra, le Corna di Satiro attirano driadi in cerca di vendetta e mercanti diretti a Porto Paranco. Provengono da satiri la cui corruzione ha messo radici nell'antica foresta.",h="A Valtetra, le Corna di Satiro attirano driadi in cerca di vendetta e mercanti diretti a Porto Paranco.",kw={"anilia","cantaselva","illiyana","jorxian","pixel","corna di satiro","satirnaar","avamposto di troncorotto","xavian"},ang={["faction:Horde"]="Dall'Avamposto di Troncorotto, i guerrieri dell'Orda eliminano i satiri che minacciano le loro attività di taglio del legname, poi vendono le corna ad acquirenti goblin diretti a Porto Paranco.",["race:NightElf"]="Per i kaldorei, prendere le corna dei satiri è un amaro dovere. Libera la loro foresta ancestrale dai cugini che hanno rinunciato alla propria eredità per servire i demoni."},sec={{t="Trofei di vendetta e commercio",b="I satiri di Valtetra portano corna che ne rivelano la corruzione demoniaca. Al Santuario di Aessina, la driade Illiyana le raccoglie per vendicare la sorella perduta, Anilia. Pixel, una goblin viaggiatrice che riposa all'Avamposto di Troncorotto, le vuole per commerciare. La domanda è aumentata a Porto Paranco, dove i cacciatori vendono questi resti di demoni uccisi."},{t="L'epurazione delle enclavi corrotte",b="Le Corna di Satiro devono essere recise direttamente ai satiri; i normali fornitori non le vendono. I satiri occupano roccaforti in tutta Valtetra, dai boschetti corrotti di Xavian agli anfratti di Satirnaar e alle rovine di Jorxian. Ripulire queste enclavi respinge la persistente contaminazione demoniaca. Fornisce anche ai guardiani in lutto e ai mercanti impazienti la prova dell'abbattimento dei satiri."}},faq={{q="Perché Illiyana vuole le Corna di Satiro?",a="Illiyana cerca le Corna di Satiro per vendicare sua sorella Anilia, assassinata dai satiri di Valtetra. Le corna dimostrano che il loro numero sta diminuendo e portano pace allo spirito di Anilia.",al={"corna illiyana","satiri anilia","missione cantaselva"}},{q="Perché Pixel raccoglie le Corna di Satiro?",a="Pixel, un'intraprendente viaggiatrice che soggiorna all'Avamposto di Troncorotto, raccoglie Corna di Satiro per il viaggio verso Porto Paranco. Sa che nel porto dei goblin si vendono a caro prezzo, quindi assolda cacciatori che affrontino il pericolo prima della sua partenza.",al={"pixel troncorotto","perché pixel vuole le corna","corna di satiro porto paranco"}},{q="Quali sono i posti migliori per trovare satiri con queste corna?",a="I satiri dimorano in diverse zone corrotte di Valtetra. Molti si trovano a Xavian e Satirnaar, nel nord-est, e a Jorxian, nella parte centro-orientale della foresta.",al={"posizioni satiri valtetra","dove sono i satiri","accampamenti di satiri"}},{q="Cosa sono i satiri e perché hanno le corna?",a="I satiri sono antichi elfi della notte trasformati in esseri demoniaci e bestiali attraverso patti stretti durante la Guerra degli Antichi. I loro zoccoli, le code e le corna sono segni della corruzione demoniaca concessa dalla Legione Infuocata.",al={"cos'è un satiro","perché i satiri hanno le corna"}}},fx={["2131c67f"]={q="Cosa sono le Corna di Satiro?",a="Le Corna di Satiro sono le corna ricurve e diaboliche mozzate dalle teste dei satiri uccisi che si nascondono a Valtetra. Come corruzioni demoniache degli antichi elfi della notte, i satiri portano queste escrescenze minacciose come segni della loro afflizione maledetta. Nelle mani degli avventurieri, servono principalmente come macabra prova della morte di un satiro o come pregiate curiosità esotiche scambiate in tutta Kalimdor.",al={"cosa sono le corna di satiro","oggetto corna di satiro","identità delle corna di satiro"}},["8a39621c"]={q="Perché qualcuno vuole le Corna di Satiro?",a="Diverse fazioni cercano le corna di satiro per ragioni molto diverse. Per la driade Illiyana a Cantaselva, servono come innegabili trofei di vendetta contro i demoni corrotti che hanno ucciso sua sorella Anilia. Nel frattempo, mercanti opportunisti come Pixel le collezionano per venderle nel vivace porto di Porto Paranco, dove la domanda prospera per reagenti alchemici esotici, curiosità e parti di bestie.",al={"chi vuole le corna di satiro","perché raccogliere corna di satiro","perché sono richieste le corna di satiro"}}},fp="11,163,34.327.0,30.359.0,35.170.0,36.223.0,58.155.0,44.212.0"}
P.entries["item:savannah-lion-tusk"] = {n="Zanna di Leone delle Savane",s="Nelle Savane, le Zanne di Leone delle Savane passano da trofei di caccia alla leggendaria birra di Chen Birra Triplo Malto.",h="Nelle Savane, le Zanne di Leone delle Savane passano da trofei di caccia alla leggendaria birra di Chen Birra...",kw={"savane","mastro birraio drohn","chen birra triplo malto","dishu","humar","porto paranco","zanna di leone delle savane"},ang={["class:Hunter"]="Come cacciatore, seguire le tracce dei feroci branchi delle Savane mette alla prova la tua abilità. Le loro pericolose zanne possono rivelarsi letali in battaglia e preziose per i birrai locali."},sec={{t="Un curioso ingrediente di birrificazione",b="I grandi felini delle Savane hanno zanne affilate e pesanti. Predatori, cacciatrici, branchi guidati da patriarchi e bestie come Humar the Pridelord ne sono tutti provvisti. I viaggiatori raccolgono questi denti come prova di una caccia riuscita. A Porto Paranco, il Mastro Birraio Drohn usa le zanne con reni di falcatore e corni di lucertola del tuono per ricreare la celebre birra di Chen Birra Triplo Malto. Questa birra potente ha una forza leggendaria che poche gole mortali possono sopportare."}},faq={{q="Perché il Mastro Birraio Drohn ha bisogno di Zanne di Leone delle Savane?",a="A Porto Paranco, il Mastro Birraio Drohn usa le Zanne di Leone delle Savane per ricreare la birra che porta il nome di Chen Birra Triplo Malto. Il suo mentore gli ha tramandato la ricetta, e le zanne sono uno dei tre ingredienti delle Savane necessari al sapore e alla forza inconfondibili della birra scura.",al={"perché zanne per la birra","zanne di leone drohn","ricetta mastro birraio drohn"}},{q="Quali bestie possiedono le Zanne di Leone delle Savane?",a="I branchi di leoni della savana sparsi per le Savane sono provvisti di queste zanne. Tra loro figurano Savannah Highmanes, Patriarchi, Matriarchs, Cacciatrici, Predatori e bestie rare come Dishu e Humar the Pridelord.",al={"dove si trovano le zanne di leone","chi rilascia le zanne di leone","fonte zanna di leone delle savane"}},{q="I leoni hanno davvero le zanne?",a="I grandi felini della savana hanno canini smisurati che crescono sporgenti e spessi nelle aspre terre selvagge di Kalimdor. I cacciatori e gli abitanti della frontiera locali li chiamano zanne.",al={"perché i denti di leone sono chiamati zanne","zanne di leone vs zanne","anatomia della zanna di leone"}}},fx={["98d362c4"]={q="Cos'è una Zanna di Leone delle Savane?",a="Una Zanna di Leone delle Savane è un dente canino affilato raccolto dai felini predatori che si aggirano nelle pianure bruciate dal sole delle The Barrens. Sebbene chiamate zanne, sono le formidabili zanne dei leoni delle savane che dominano i terreni di caccia locali. Oltre a servire come macabri trofei di sopravvivenza nel deserto, queste parti resistenti trovano usi peculiari tra i locali che sanno come estrarne le qualità essenziali.",al={"cos'è la zanna di leone delle savane","lore zanna di leone delle savane","zanna di leone"}},ea601034={q="Da dove proviene una Zanna di Leone delle Savane?",a="Queste zanne vengono prese direttamente dai feroci felini del branco che cacciano le savane centrali di Kalimdor. Ogni razza di leone che si aggira per le The Barrens, dai vagabondi e cacciatrici ai potenti patriarchi e ai crini alti, possiede queste zanne affilate, affidandosi a esse per abbattere gli striduli delle pianure e difendere il proprio territorio contro i predatori concorrenti.",al={"da dove vengono le zanne di leone","chi lascia le zanne di leone","fonte della zanna di leone"}}},fp="18,104,28.414.0,51.240.0,39.188.0,29.151.0"}
P.entries["item:scaber-stalk"] = {n="Gambo Scabro",s="A Rivafosca, Barithras Ombraluna cerca Gambi Scabri in una grotta dietro le Cascate di Altafonte.",h="A Rivafosca, Barithras Ombraluna cerca Gambi Scabri in una grotta dietro le Cascate di Altafonte.",kw={"auberdine","barithras ombraluna","cave mushrooms","cascate di altafonte","rivafosca","cappella mortifera","gambo scabro"},ang={["profession:Herbalism"]="Questi gambi sotterranei non sono un'erba comunemente commerciata. Permettono di capire come gli insoliti climi delle caverne e le ombre incombenti influenzino i funghi locali.",["race:NightElf"]="Come Elfo della Notte, dai ascolto all'avvertimento del Bosco degli Antichi e ti avvicini con cautela a questi funghi delle caverne. Una presenza corruttrice si annida nei pressi delle Cascate di Altafonte."},sec={{t="Un raro esemplare di fungo",b="Dietro le Cascate di Altafonte, i Gambi Scabri crescono in una grotta tra le montagne nordorientali di Rivafosca. Questi pallidi funghi prosperano nei suoi cunicoli umidi e appartati, lontano dalla vegetazione della foresta soprastante. Pochi li raccolgono in un luogo tanto remoto. Barithras Ombraluna, ad Auberdine, invia esploratori nell'oscurità in cerca dei rari gambi."},{t="Un'ombra nelle cascate",b="Il Bosco degli Antichi ha esortato gli elfi della notte del posto a stare lontani dalla grotta dove crescono i Gambi Scabri. I suoi spiriti degli alberi hanno percepito un male oscuro e crescente che si sta radicando all'interno delle Cascate di Altafonte. Gli alchimisti apprezzano i gambi insieme alle rare Cappelle Mortifere per preparare pozioni sperimentali. Chi li cerca potrebbe imbattersi nella malvagità che si va addensando sotto le montagne."}},faq={{q="Dove crescono i Gambi Scabri?",a="I Gambi Scabri crescono in una grotta umida dietro le Cascate di Altafonte, tra le montagne nordorientali di Rivafosca.",al={"posizione del gambo scabro","dove si trovano i gambi scabri","caverna dei gambi scabri"}},{q="Chi vuole i Gambi Scabri?",a="Barithras Ombraluna, ad Auberdine, cerca Gambi Scabri e una Cappella Mortifera per preparare una pozione particolare.",al={"chi usa il gambo scabro","funghi di barithras ombraluna","chi ha bisogno dei gambi scabri"}},{q="Perché Barithras Ombraluna non ha raccolto i gambi da solo?",a="Il Bosco degli Antichi ha esortato Barithras a stare lontano dalla grotta dietro la cascata, dopo che i suoi spiriti vi hanno percepito un nuovo male pericoloso che vi si era rifugiato.",al={"perché non li raccoglie lui stesso","avvertimento per barithras","avvertimento sulla caverna di altafonte"}},{q="Cos'altro cresce insieme ai Gambi Scabri?",a="La caverna ospita anche il letale fungo Cappella Mortifera, un altro raro esemplare di cui Barithras ha bisogno per le sue ricerche alchemiche.",al={"altri funghi nella caverna","cappella mortifera e gambo scabro","funghi di altafonte"}}},fx={f5b84e96={q="Cos'è un Gambo Scabro?",a="Un Gambo Scabro è una rara specie di fungo cavernicolo nativo della caverna ombrosa nascosta dietro le Cascate di Altafonte a Darkshore. Sebbene i funghi sotterranei siano comuni in tutta la Kalimdor settentrionale, questa particolare varietà prospera in grotte umide e scure che ospitano energie sinistre.",al={"cos'è un gambo scabro","informazioni sul gambo scabro","fungo gambo scabro"}},["053fa90e"]={q="Perché qualcuno vuole i Gambi Scabri?",a="Barithras Ombraluna ad Auberdine cerca Gambi Scabri come ingrediente vitale per preparare pozioni specializzate. Poiché questi funghi potenti crescono solo nella grotta appartata vicino alle Cascate di Altafonte, gli erboristi e gli alchimisti devono affidarsi ai viaggiatori avventurosi per raccoglierli.",al={"perché raccogliere il gambo scabro","uso del gambo scabro","a cosa servono i gambi scabri"}}},fp="12,91,22.313.0,21.337.1,28.101.0,24.98.0,58.141.0,40.122.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="Scaglia di Vecchio Occhiobuio",s="Lungo la costa delle Marche Occidentali, il Capitano Grayson cerca la prova che il Vecchio Occhiobuio sia morto. Il fantasma infesta il Faro delle Marche Occidentali, dove gli attacchi del murloc hanno lasciato il faro spento.",h="Lungo la costa delle Marche Occidentali, il Capitano Grayson cerca la prova che il Vecchio Occhiobuio sia...",kw={"capitano grayson","minaccia costiera","murloc","vecchio occhiobuio","scaglia di vecchio occhiobuio","marche occidentali","faro delle marche occidentali"},ang={["faction:Alliance"]="Se sei un marinaio dell'Alleanza in viaggio sul Great Sea verso Roccavento, contribuire a porre fine agli attacchi del Vecchio Occhiobuio può mantenere acceso il faro delle Marche Occidentali e impedire alle navi di schiantarsi contro gli scogli."},sec={{t="Trofeo di un flagello costiero",b="Il Vecchio Occhiobuio trasformò la costa delle Marche Occidentali in un luogo di massacri. Il Capitano Grayson, il fantasma vincolato al Faro delle Marche Occidentali, racconta che l'astuto murloc radunò i murloc più suggestionabili per razziare la costa. Occhiobuio scacciò la famiglia del guardiano, lasciando il faro spento quando la nave di Grayson si schiantò contro gli scogli.\n\nQuando la famiglia tornò per riaccendere la fiamma, Occhiobuio attaccò di nuovo e li massacrò. Grayson cerca una scaglia della creatura come prova che la costa sia libera dal suo predatore più feroce."}},faq={{q="A cosa serve la Scaglia di Vecchio Occhiobuio?",a="Al Capitano Grayson serve la scaglia come prova che il Vecchio Occhiobuio sia morto. Il fantasma infesta il Faro delle Marche Occidentali e cerca vendetta perché Occhiobuio lasciò il faro spento quando la nave di Grayson naufragò, poi massacrò la famiglia del guardiano del faro.",al={"chi vuole la scaglia","consegna scaglia di occhiobuio","uso della scaglia di vecchio occhiobuio"}},{q="Chi è il Vecchio Occhiobuio?",a="Il Vecchio Occhiobuio è un capo murloc feroce e astuto che si aggira sulle coste sabbiose delle Marche Occidentali. Sa organizzare e costringere i suoi simili a compiere incursioni letali e coordinate contro gli avamposti costieri.",al={"chi è occhiobuio","storia di occhiobuio","vecchio occhiobuio"}},{q="Perché il Vecchio Occhiobuio prese di mira il faro?",a="Il Vecchio Occhiobuio attaccò il faro una prima volta per scacciare il guardiano e la sua famiglia, lasciando la costa al buio. Quando tornarono per riaccendere la fiamma, radunò i suoi simili per un altro attacco e uccise l'intera famiglia. Le navi rimasero senza una luce che le guidasse tra le pericolose secche costiere.",al={"perché attaccare il faro","incursione al faro","occhiobuio faro"}}},fx={["6e72b95e"]={q="Cos'è la Scaglia di Vecchio Occhiobuio?",a="È una scaglia dura e distintiva presa direttamente dalla pelle di Vecchio Occhiobuio, il famigerato capo murloc che terrorizza la costa delle Marche Occidentali. Portarla serve come prova inconfutabile che il mortale predatore costiero è stato finalmente ucciso.",al={"cos'è la scaglia di vecchio occhiobuio","oggetto scaglia di vecchio occhiobuio","scaglia di occhiobuio"}},["383f15e9"]={q="Da dove proviene la Scaglia di Vecchio Occhiobuio?",a="La scaglia proviene dalla pelle naturale di Vecchio Occhiobuio, un murloc insolitamente astuto e feroce che si aggira sulla costa delle Marche Occidentali. Non è stata forgiata o creata da mani mortali, ma raccolta dalla sua carcassa dopo averlo sconfitto in battaglia.",al={"origine della scaglia di vecchio occhiobuio","dove trovare la scaglia di vecchio occhiobuio","chi ha creato la scaglia di vecchio occhiobuio"}},e7059369={q="Perché il Capitano Grayson vuole la Scaglia di Vecchio Occhiobuio?",a="Il Capitano Grayson, il fantasma di un capitano di mare che indugia presso il Faro delle Marche Occidentali, cerca vendetta e chiusura. Vecchio Occhiobuio ha spaventato la famiglia del guardiano del faro, lasciando il faro al buio la notte in cui la nave di Grayson ha colpito le rocce, e quando la famiglia è tornata, ha fatto un'altra incursione e li ha massacrati. Grayson richiede la scaglia come prova innegabile che la bestia è morta e la costa è più sicura.",al={"perché grayson vuole la scaglia","perché è richiesta la scaglia di vecchio occhiobuio","chi vuole la scaglia di vecchio occhiobuio"}}},fp="21,165,27.481.0,43.240.0,20.178.0,43.277.0"}
P.entries["item:scarlet-armband"] = {n="Bracciali Scarlatti",s="Ad Albamorta, i Bracciali Scarlatti contraddistinguono gli zeloti che avanzano nel territorio dei Reietti. L'Esecutore Arren li raccoglie come prova che i nuovi risorti hanno contrattaccato.",h="Ad Albamorta, i Bracciali Scarlatti contraddistinguono gli zeloti che avanzano nel territorio dei Reietti.",kw={"albamorta","esecutore arren","bracciali scarlatti","scarlet convert","crociata scarlatta","scarlet initiate","radure di tirisfal"},ang={["race:Undead"]="Come Reietto appena risorto, raccogliere i Bracciali Scarlatti ti mette faccia a faccia con l'odio del mondo dei vivi. La tua sopravvivenza dipende dalla tua capacità di difenderti dalla Crociata."},sec={{t="Un emblema di fanatismo",b="I Bracciali Scarlatti contraddistinguono i seguaci della Crociata Scarlatta, dagli Initiates ai nuovi convertiti. Le loro insegne rosse avvertono i Reietti appena risorti ad Albamorta che il pericolo è vicino. I crociati non fanno distinzione tra i servi senza volontà del Flagello e i sudditi della Dark Lady dotati di libero arbitrio. Per loro, ogni cadavere che cammina deve bruciare.\n\nL'Esecutore Arren raccoglie i bracciali per confermare la morte degli esploratori nemici a sudest di Albamorta. Gli serve la prova che i nuovi Reietti sappiano difendere la loro nazione appena nata."}},faq={{q="Perché l'Esecutore Arren vuole i Bracciali Scarlatti?",a="L'Esecutore Arren vuole i Bracciali Scarlatti come prova che le forze dell'accampamento della Crociata Scarlatta a sudest di Albamorta vengono decimate. La Crociata minaccia i Reietti appena risvegliati, e queste insegne dimostrano che i suoi esploratori avanzati e le sue reclute sono stati eliminati.",al={"perché raccogliere i bracciali","missione bracciali arren","scopo bracciali scarlatti"}},{q="Chi indossa questi bracciali?",a="Gli Scarlet Initiates, gli Scarlet Converts e il messaggero Meven Korgal indossano questi bracciali. Sono membri di basso rango della Crociata Scarlatta di stanza nei pressi di Albamorta.",al={"chi rilascia bracciali scarlatti","dove trovare i bracciali"}},{q="Perché la Crociata Scarlatta odia i Reietti?",a="La Crociata Scarlatta odia i Reietti perché i suoi zeloti non distinguono tra il Flagello senza volontà del Lich King e i Reietti dotati di libero arbitrio. Considerano tutti i non morti abomini da sterminare.",al={"perché gli scarlatti attaccano i non morti","crociata contro reietti","zeloti scarlatti"}},{q="Dov'è l'accampamento in cui si possono trovare questi bracciali?",a="L'accampamento si trova poco a sudest di Albamorta, nelle Radure di Tirisfal, sulle colline oltre il perimetro dell'insediamento.",al={"posizione accampamento scarlatto","accampamento scarlatto albamorta","dove sono i convertiti scarlatti"}}},fx={["365b2391"]={q="Cos'è un Bracciale Scarlatto?",a="Un Bracciale Scarlatto è un pezzo di stoffa cremisi indossato dagli iniziati e dai convertiti della Crociata Scarlatta. Serve come insegna identificativa per l'ordine umano zelante, segnando i suoi membri come crociati votati dedicati a sradicare tutti i non morti da Lordaeron, indipendentemente dal fatto che quei non morti servano il Flagello o possiedano il libero arbitrio come i Reietti.",al={"cos'è il bracciale scarlatto","significato del bracciale scarlatto","lore del bracciale scarlatto"}}},fp="15,158,21.513.0,46.244.0,25.169.0,47.204.0,52.110.0"}
P.entries["item:scarlet-crusade-documents"] = {n="Documenti della Crociata Scarlatta",s="All'accampamento della Crociata vicino ad Albamorta, i Documenti della Crociata Scarlatta attraversano Tirisfal nelle mani di un messaggero. Gli ordini indicano i comandanti sul campo e dirigono le loro forze, fornendo ai Reietti informazioni sulle posizioni scarlatte nelle Radure.",h="All'accampamento della Crociata vicino ad Albamorta, i Documenti della Crociata Scarlatta attraversano...",kw={"brill","albamorta","esecutore arren","esecutore zygand","meven korgal","documenti della crociata scarlatta","the red messenger","vital intelligence"},ang={["race:Undead"]="Come Reietto risvegliato, porti questi documenti dalle prove nel cimitero di Albamorta al più ampio sforzo bellico diretto da Brill."},sec={{t="Ordini Intercettati",b="Meven Korgal trasportava i documenti dall'accampamento della Crociata a sudest di Albamorta. Gli ordini dell'Highlord impartiscono direttive ai capitani del Tirisfal Regional Command della Crociata. Captain Perrine deve fortificare la torre sudoccidentale e raccogliere informazioni sui non morti a Brill.\n\nCaptain Vachon deve stroncare i movimenti dei non morti vicino alla torre settentrionale, mentre Captain Melrose sorveglia i confini delle Plaguelands. Gli ordini indicano gli ufficiali scarlatti sul campo, le loro postazioni e i loro compiti nelle Radure di Tirisfal."},{t="Consegna a Brill",b="L'Esecutore Arren si rende conto che le forze locali di Albamorta non possono sfruttare appieno queste informazioni. I documenti catturati diventano il lasciapassare di un Reietto appena risvegliato per lasciare Albamorta. Portali a nordest, oltre il Maniero Cuorduro, fino a Brill, e consegnali all'Esecutore Zygand all'esterno del Municipio di Brill. Con gli ordini in mano, i capi militari dei Reietti possono pianificare rapidi attacchi contro i comandanti scarlatti trincerati nelle Radure."}},faq={{q="Chi trasportava questi documenti?",a="Meven Korgal, un corriere della Crociata Scarlatta, trasportava i documenti presso l'accampamento della Crociata a sudest di Albamorta.",al={"chi li ha lasciati cadere","messaggero scarlatto","meven korgal"}},{q="Quali informazioni ci sono nei documenti?",a="Gli ordini dell'Highlord impartiscono direttive al Tirisfal Regional Command della Crociata. Captain Perrine deve fortificare la torre sudoccidentale e raccogliere informazioni sui non morti a Brill. Captain Vachon deve stroncare i movimenti dei non morti vicino alla torre settentrionale, e Captain Melrose deve sorvegliare i confini delle Plaguelands.",al={"cosa dicono i documenti","contenuto dei documenti"}},{q="Chi deve vedere questi documenti?",a="Recuperi i documenti per l'Esecutore Arren ad Albamorta. Te li affida perché tu li consegni all'Esecutore Zygand, che dirige le operazioni militari regionali dall'esterno del Municipio di Brill.",al={"dove li porto","a chi consegno i documenti"}},{q="Perché questi documenti sono importanti per i Reietti?",a="Gli ordini rivelano dove sono schierati gli ufficiali scarlatti nelle Radure di Tirisfal. I Reietti possono usarli per eliminare i capi nemici e fiaccare il morale dei fanatici nella regione.",al={"perché i reietti li vogliono","importanza dei documenti scarlatti"}}},fx={b6ac443b={q="Cosa sono i Documenti della Crociata Scarlatta?",a="Sono un fascicolo di documenti militari riservati, rapporti di battaglia e ordini portati da un corriere della Crociata Scarlatta. Sebbene gran parte del fascicolo consista in normali resoconti di esplorazione e propaganda sulle scaramucce con i Reietti, contiene anche istruzioni operative dettagliate destinate agli ufficiali della Crociata di stanza in tutte le Radure di Tirisfal.",al={"cosa sono i documenti","info documenti crociata scarlatta","oggetto documenti scarlatti"}},["5f5d9cee"]={q="Da dove provengono i Documenti della Crociata Scarlatta?",a="Sono direttive emesse per ordine dell'Alto Lord della Crociata ai capitani del suo Comando Regionale di Tirisfal. Sono stati affidati a un corriere di nome Meven Korgal, che i Reietti hanno trovato al campo della Crociata a sud-est di Albamorta.",al={"chi ha scritto i documenti della crociata scarlatta","fonte dei documenti scarlatti","da dove vengono i documenti"}}},fp="25,243,18.495.0,17.427.0,33.115.0,41.295.0,33.180.0,50.172.0"}
P.entries["item:scarlet-insignia-ring"] = {n="Anello con Fregi Scarlatto",s="Nelle Radure di Tirisfal, gli Anelli con Fregi Scarlatti identificano i membri della Crociata Scarlatta. A Brill, i Reietti li raccolgono come prova che un altro zelota è caduto.",h="Nelle Radure di Tirisfal, gli Anelli con Fregi Scarlatti identificano i membri della Crociata Scarlatta.",kw={"brill","guardiamorte burgess","esecutore zygand","proof of demise","crociata scarlatta","anello con fregi scarlatto","radure di tirisfal","varimathras"},ang={["faction:Horde"]="Come membro dell'Orda, raccogliere questi anelli ti aiuta ad assicurare una testa di ponte nei Regni Orientali. Ognuno indebolisce i fanatici crociati nei dintorni di Sepulcra.",["race:Undead"]="Come Reietto, strappare questi anelli ai crociati morti è un modo per dichiarare che Tirisfal appartiene ai morti. Così esegui anche gli ordini della Dark Lady e di Varimathras."},sec={{t="Emblemi dello Zelotismo",b="Ogni combattente della Crociata Scarlatta nelle Radure di Tirisfal indossa un anello con fregi. Li indossano i neofiti e i frati zelanti, così come i capitani Melrache e Perrine. Il sigillo fiammeggiante della Crociata contraddistingue ogni anello. Identifica i membri di un ordine consumato dalla paranoia. Agli occhi degli estranei, gli anelli distinguono ciò che resta degli umani più fanatici di Lordaeron."},{t="Taglia del Signore del Terrore",b="Il Guardiamorte Burgess a Brill raccoglie gli anelli su ordine di Varimathras. Quest'ultimo è il luogotenente signore del terrore di Dama Sylvanas. I Reietti considerano la Crociata Scarlatta una pestilenza che infesta la patria appena rivendicata. Le reclute riportano gli anelli a Brill come prova della morte di un crociato e della propria lealtà al trono di Sepulcra."}},faq={{q="Chi indossa questi anelli con fregi?",a="Quasi ogni membro della Crociata Scarlatta di stanza nelle Radure di Tirisfal indossa un anello con fregi. Li indossano neofiti, missionari, zeloti e avanguardie, insieme agli ufficiali sul campo Captain Perrine, Captain Melrache e Captain Vachon.",al={"chi rilascia gli anelli","quali crociati hanno gli anelli","proprietari degli anelli"}},{q="Perché la Guardiamorte Burgess vuole gli Anelli con Fregi Scarlatto?",a="Il Guardiamorte Burgess raccoglie gli anelli come prova dell'uccisione dei crociati scarlatti. Esegue gli ordini di Varimathras e della Dark Lady. A Brill, la guarnigione dei Reietti usa gli anelli per valutare la lealtà delle reclute e i loro successi nello scacciare gli umani da Lordaeron.",al={"perché raccogliere gli anelli","motivo di proof of demise","anelli burgess"}},{q="Cosa rappresenta il fregio sull'anello?",a="L'anello reca il marchio della Crociata Scarlatta e rappresenta la sua guerra santa per estirpare ogni forma di non morte da Lordaeron. I crociati lo indossano con fiero orgoglio come simbolo di rettitudine. La loro ossessione li spinge a massacrare chiunque non appartenga al loro ordine.",al={"simbolo scarlatto","cos'è il fregio","emblema dell'anello"}},{q="Quale ruolo ha Varimathras nella raccolta di questi anelli?",a="Varimathras è il luogotenente principale di Sylvanas Ventolesto a Sepulcra. Sovrintende alle operazioni militari contro gli umani viventi ostili nelle Radure di Tirisfal. La Crociata Scarlatta è una priorità per i comandanti dei Reietti come l'Esecutore Zygand e il Guardiamorte Burgess.",al={"ordini di varimathras","perché varimathras vuole gli anelli","coinvolgimento del signore del terrore"}}},fx={d4097e42={q="Cos'è un Anello con Fregi Scarlatto?",a="Un Anello con Fregi Scarlatto è una fascia identificativa portata dai membri della Crociata Scarlatta attraverso le Radure di Tirisfal. Portando l'emblema dell'ordine militante, segna l'alleanza di chi lo indossa con la loro crociata fanatica per sradicare la non morte. Per i Reietti che difendono i loro nuovi confini, questi anelli servono come prova indiscutibile che un soldato o un ufficiale nemico è stato eliminato.",al={"cos'è l'anello con fregi scarlatto","lore anello con fregi scarlatto","cosa sono questi anelli"}}},fp="21,155,18.319.0,23.321.0,31.226.0,56.262.0,45.244.0,58.256.0"}
P.entries["item:scavenged-goods"] = {n="Beni Recuperati",s="Nei dintorni di Albamorta, i Reietti raccolgono Beni Recuperati dalle casse di equipaggiamento. I non morti appena risorti dipendono dalle scorte scartate per armare e vestire le reclute che verranno dopo di loro.",h="Nei dintorni di Albamorta, i Reietti raccolgono Beni Recuperati dalle casse di equipaggiamento.",kw={"guardiamorte saltain","albamorta","casse di equipaggiamento","scorte dei reietti","beni recuperati","scavenging deathknell"},ang={["race:Undead"]="In quanto Reietto, hai bisogno di equipaggiamento scartato per sopravvivere. I vivi non ti offrono né aiuto né pietà."},sec={{t="Cavarsela da soli",b="I nuovi Reietti risorgono nel cimitero di Albamorta con indosso poco più che sudari funebri marcescenti. Gli insediamenti e i regni vicini non offrono loro alcun aiuto, così devono recuperare ciò di cui hanno bisogno. Il Guardiamorte Saltain raccoglie armi, attrezzi e indumenti scartati dalle casse sparse per il villaggio. Distribuisce quelle scorte alle prossime reclute che risorgeranno."}},faq={{q="A cosa servono i beni recuperati?",a="Il Guardiamorte Saltain raccoglie Beni Recuperati per equipaggiare i nuovi Reietti che risorgono dal cimitero. Senza le scorte delle casse vicine, si avventurerebbero nelle Radure di Tirisfal disarmati e senza vestiti.",al={"scopo dei beni recuperati","perché raccogliere beni recuperati","cosa fa saltain con i beni recuperati"}},{q="Dove si trovano questi beni?",a="I beni si trovano nelle casse di equipaggiamento all'esterno delle casette e intorno agli edifici in rovina sparsi per Albamorta.",al={"dove trovare beni recuperati","posizione beni recuperati","dove si trovano le casse di equipaggiamento"}},{q="Chi richiede i beni recuperati?",a="Il Guardiamorte Saltain, un ufficiale di Albamorta, chiede ai Reietti appena risvegliati di raccogliere le scorte. Insegna loro a contare sulle proprie forze e si prepara all'arrivo delle prossime reclute.",al={"chi vuole i beni recuperati","missione guardiamorte saltain"}}},fx={f565021a={q="Cosa sono i Beni Recuperati?",a="Si tratta di pezzi assortiti di equipaggiamento, vestiario e attrezzature riutilizzabili, recuperati da vecchie casse sparse per Albamorta. Piuttosto che armamenti immacolati, sono resti scartati della vita passata della città che possono ancora servire a uno scopo pratico per i Forsaken appena risvegliati.",al={"beni recuperati cosa sono","cosa sono i beni recuperati"}},["0b2267aa"]={q="Da dove provengono i Beni Recuperati?",a="Provengono da casse di equipaggiamento abbandonate tra le strutture in rovina di Albamorta. Appartenute un tempo agli abitanti vivi di Lordaeron prima che il regno cadesse sotto la piaga, queste provviste sono rimaste dimenticate tra le rovine finché i Forsaken non hanno iniziato a reclamare la città come propria base operativa.",al={"origine beni recuperati","chi ha creato i beni recuperati","da dove provengono i beni recuperati"}},["36f8df02"]={q="Perché il Guardiamorte Saltain vuole i Beni Recuperati?",a="I Forsaken continuano a risvegliare i nuovi morti dal cimitero e queste nuove reclute entrano nel mondo con poco o nulla. Il Guardiamorte Saltain raccoglie questi oggetti recuperati in modo che i non morti appena emersi abbiano vestiti ed equipaggiamento di base, invece di iniziare il servizio disarmati ed esposti.",al={"perché saltain vuole i beni recuperati","perché raccogliere beni recuperati","perché servono i beni recuperati"}}},fp="15,161,22.332.0,34.183.0,28.96.0,33.170.0"}
P.entries["item:scavenger-paw"] = {n="Zampa di Saprofago",s="Ad Albamorta, la Zampa di Saprofago si ricava dai lupi giovani e cenciosi delle colline. I Reietti appena risvegliati raccolgono le zampe affinché i custodi locali possano cucirle per creare un equipaggiamento protettivo rudimentale.",h="Ad Albamorta, la Zampa di Saprofago si ricava dai lupi giovani e cenciosi delle colline.",kw={"albamorta","novizia elreth","ragged scavenger","zampa di saprofago","the damned","young scavenger"},ang={["profession:Tailoring"]="Come sarto, puoi vedere come la Novizia Elreth cuce zampe di lupo e ali di pipistrello per creare equipaggiamento rudimentale per i nuovi insediamenti dei Reietti.",["race:Undead"]="Come Reietto appena risvegliato, con la carne in decomposizione e poco equipaggiamento, puoi raccogliere parti dai predatori locali per creare un'armatura sufficiente ad affrontare i pericoli di Tirisfal."},sec={{t="Armature rabberciate ad Albamorta",b="I Reietti tornati da poco ad Albamorta hanno ben poco a disposizione. Il Flagello e la Crociata Scarlatta premono su Tirisfal, così ogni scarto di pelle e ossa trova un impiego pratico. La Novizia Elreth assiste il Sacerdote dell'Ombra Sarvis raccogliendo zampe di lupi saprofagi e ali di pipistrello.\n\nConfeziona indumenti e armature funzionali per i Reietti appena risorti dalle loro tombe. Sono ancora disorientati dal loro ritorno."}},faq={{q="A cosa servono le Zampe di Saprofago?",a="La Novizia Elreth raccoglie Zampe di Saprofago ad Albamorta e cuce parti di animali per creare semplici indumenti e armature per i Reietti appena risorti.",al={"scopo zampa di saprofago","uso delle zampe","perché raccogliere zampe"}},{q="Dove si trovano?",a="Le trovi sui Young Scavengers e sui Ragged Scavengers, lupi selvatici che vagano per i boschi e i campi intorno ad Albamorta.",al={"luogo rilascio zampe","dove trovare le zampe","quali lupi rilasciano zampe"}},{q="Chi richiede queste zampe?",a="La Novizia Elreth chiede le zampe. Assiste il Sacerdote dell'Ombra Sarvis curando le reclute ferite, confezionando equipaggiamento e dotando del necessario chi viene mandato sul campo.",al={"chi vuole le zampe di saprofago","chi assegna la missione delle zampe","novizia elreth zampe"}}},fx={["41bb56d4"]={q="Cos'è una Zampa di Saprofago?",a="Una Zampa di Saprofago è la zampa mozzata di un lupo saprofago che vaga per i boschi infestati delle Radure di Tirisfal attorno ad Albamorta. Sebbene sembrino trofei macabri, queste parti animali resistenti servono come materia prima per i Forsaken appena risvegliati, che devono utilizzare ogni frammento della fauna locale per creare ciò che è necessario e sopravvivere.",al={"identità zampa di saprofago","cosa sono le zampe di saprofago","cos'è la zampa di saprofago"}},["366465d3"]={q="Da dove proviene una Zampa di Saprofago?",a="Queste zampe vengono raccolte dai giovani e spelacchiati lupi saprofagi che si aggirano per il perimetro di Albamorta. Aggirandosi per le radure avvizzite appena oltre le mura del villaggio, queste bestie feroci setacciano la campagna flagellata in cerca di carogne, diventando facili prede per le nuove reclute Forsaken che cercano di dimostrare la propria forza.",al={"fonte zampa di saprofago","dove trovare la zampa di saprofago","zampe di lupo saprofago"}},f83538b8={q="Perché qualcuno vuole le Zampe di Saprofago?",a="La Novizia Elreth ad Albamorta le raccoglie per confezionare armature e vestiti robusti per i soldati Forsaken appena risvegliati. Le risorse sono disperatamente scarse per i non morti liberi appena nati ed Elreth unisce pelli, ali e zampe per rattoppare equipaggiamento che possa proteggerti dai non morti senza cervello e dalla Crociata Scarlatta che minacciano il rifugio.",al={"perché raccogliere zampe di saprofago","chi ha bisogno di zampe di saprofago","uso zampe di saprofago lore"}}},fp="13,178,27.408.0,33.132.0,23.117.0,24.158.0"}
P.entries["item:scorched-spider-fang"] = {n="Zanna di Ragno Bruciata",s="Nelle Paludi Grigie, i Cave Stalkers e i Leech Stalkers hanno Zanne di Ragno Bruciate. A Roccavento, Furen Barbalunga ne richiede cinquanta per rinforzare le armature di maglia dei guerrieri dell'Alleanza.",h="Nelle Paludi Grigie, i Cave Stalkers e i Leech Stalkers hanno Zanne di Ragno Bruciate.",kw={"cave stalker","fire hardened mail","furen barbalunga","leech stalker","zanna di ragno bruciata","roccavento","paludi grigie"},ang={["class:Warrior"]="Come guerriero, affronti la prova di Furen Barbalunga: raccogliere cinquanta zanne. Il lavoro mette alla prova la tua resistenza e fornisce i materiali grezzi per la tua armatura di maglia.",["profession:Blacksmithing"]="Come fabbro, puoi osservare come Furen incorpora chitina bruciata e zanne negli anelli della maglia, seguendo rare tradizioni naniche di fabbricazione delle armature che vanno oltre la normale fusione."},sec={{t="La formula di un fabbro nanico",b="A Roccavento, il fabbro Furen Barbalunga rinforza le armature di maglia con metodi insoliti. Gli servono cinquanta zanne bruciate dei ragni giganti delle Paludi Grigie. La sostanza densa e velenosa di cui sono composte si è indurita al calore. Furen la incorpora negli anelli della maglia mentre li tempra."},{t="Predatori delle Paludi Grigie",b="I Cave Stalkers e i Leech Stalkers hanno le zanne che servono a Furen. Vivono nelle valli sprofondate e nelle tane delle Paludi Grigie, tra umidità e marciume. Le loro mandibole sono indurite e bruciate. Raccoglierne cinquanta significa avventurarsi in profonde cavità e affrontare sciami di ragni."}},faq={{q="A cosa servono le Zanne di Ragno Bruciate?",a="A Roccavento, Furen Barbalunga richiede cinquanta Zanne di Ragno Bruciate per forgiare una resistente corazza di maglia per i guerrieri dell'Alleanza. Il lavoro richiede anche componenti provenienti da Stonetalon e dalle Gallerie di Lamaspina.",al={"cosa fare con le zanne di ragno bruciate","scopo della zanna di ragno bruciata","chi ha bisogno di zanne di ragno bruciate"}},{q="Dove posso trovare le Zanne di Ragno Bruciate?",a="I Cave Stalkers e i Leech Stalkers delle Paludi Grigie hanno Zanne di Ragno Bruciate. Cercali nelle loro tane umide, sui pendii e nelle caverne degli scavi.",al={"posizione di rilascio zanna di ragno bruciata","quali ragni rilasciano la zanna di ragno bruciata","dove trovare zanne di ragno bruciate"}},{q="Perché un fabbro ha bisogno di così tante zanne di ragno per creare un'armatura?",a="Furen Barbalunga usa insoliti metodi nanici per rinforzare le armature di maglia. Tratta gli anelli con zanne indurite, flogisto e corna di bestie.",al={"perché 50 zanne","perché furen ha bisogno di zanne di ragno"}},{q="Qualsiasi avventuriero può raccogliere e consegnare queste zanne?",a="Chiunque attraversi le Paludi Grigie può uccidere i ragni e prenderne le mandibole. Furen realizza l'armatura solo per gli aspiranti guerrieri che cercano di guadagnarsi una maglia temprata dal fuoco.",al={"zanna di ragno bruciata solo per guerrieri","chi può consegnare le zanne di ragno bruciate"}}},fx={a7a99cbb={q="Cos'è una Zanna di Ragno Bruciata?",a="Una Zanna di Ragno Bruciata è un dente velenoso indurito e trattato termicamente, raccolto dagli aracnidi predatori come i Cacciatori delle Caverne e i Cacciatori Sanguisuga che si annidano nelle Wetlands. Il loro aspetto annerito e fragile cela una straordinaria densità, rendendole ambite tra gli armaioli esperti che cercano componenti rari per tecniche di forgiatura avanzate.",al={"cos'è la zanna di ragno bruciata","zanne di ragno bruciate","zanna bruciata"}},c6d8f632={q="Da dove provengono le Zanne di Ragno Bruciate?",a="Queste zanne non sono create da mani mortali; sono raccolte direttamente dagli aracnidi giganti delle Wetlands, specificamente dai Cacciatori Sanguisuga e dai Cacciatori delle Caverne. La costante esposizione agli elementi sotterranei e l'alchimia naturale del loro veleno conferisce a queste zanne la loro resistenza annerita e trattata col fuoco.",al={"da dove provengono le zanne di ragno bruciate","origine zanna di ragno bruciata","fonte zanna di ragno bruciata"}}},fp="20,165,25.253.0,24.267.0,40.185.0,39.138.0,62.133.0,51.175.0"}
P.entries["item:scroll-of-messaging"] = {n="Pergamena Scritta",s="A Petrartiglio, Gaxim Scoppiarame si prepara a inviare un messaggio che farà esplodere delle cariche a distanza.",h="A Petrartiglio, Gaxim Scoppiarame si prepara a inviare un messaggio che farà esplodere delle cariche a...",kw={"esplosivi","gaxim scoppiarame","ng-5","detonatore a distanza","pergamena scritta","vette di petrartiglio","s.p.r. & co."},ang={["faction:Alliance"]="Per gli agenti dell'Alleanza, la pergamena aiuta a sabotare i macchinari della S.P.R. & Co. e a ostacolare la distruzione della foresta di Petrartiglio.",["profession:Engineering"]="La pergamena mostra come l'ingegneria gnomesca possa usare la magia arcana per ricevere un segnale e innescare esplosivi a distanza."},sec={{t="Un messaggio volatile",b="Presso il sito di disboscamento della S.P.R. & Co., Gaxim Scoppiarame trasformerà un messaggio in un'esplosione. Intende combinare l'incantesimo di trasmissione della pergamena con le instabili cariche NG-5. L'esplosione attirerà le guardie lontano dal sito. Gli agenti potranno quindi intrufolarsi e rubare schemi ingegneristici e corrispondenza riservata."}},faq={{q="A cosa serve la Pergamena Scritta?",a="Gaxim Scoppiarame usa la magia di trasmissione della Pergamena Scritta per innescare l'NG-5 da lontano. Insieme, gli permettono di provocare un'esplosione a distanza.",al={"uso pergamena scritta","cosa fa la pergamena scritta","perché gaxim vuole la pergamena"}},{q="Chi riceve questa pergamena?",a="Gaxim Scoppiarame, un ingegnere gnomo nelle Vette di Petrartiglio, riceve la pergamena.",al={"chi riceve la pergamena scritta","dove portare la pergamena scritta","destinatario pergamena"}},{q="Perché Gaxim ha bisogno di un esplosivo a distanza?",a="Gaxim ha bisogno di un grande diversivo presso il sito della S.P.R. & Co. Il caos coprirà un'infiltrazione, il furto di progetti ingegneristici e il recupero di documenti destinati a fermare il disboscamento indiscriminato della foresta da parte della compagnia.",al={"motivo esplosivo gaxim","perché far saltare in aria la s.p.r. & co.","distrazione vette di petrartiglio"}},{q="Cos'è l'NG-5?",a="L'NG-5 è una carica chimica esplosiva usata da Gaxim Scoppiarame. Combinata con il segnale magico della pergamena, forma un detonatore a distanza.",al={"ng-5","cos'è ng-5","esplosivo ng5"}}},fx={["2071477e"]={q="Cos'è la Pergamena Scritta?",a="La Pergamena Scritta è una pergamena incantata che porta con sé un incantesimo arcano. Gaxim Scoppiarame l'ha cercata come catalizzatore non convenzionale da combinare con il suo composto esplosivo volatile, NG-5, permettendogli di creare una carica innescata a distanza contro le operazioni della S.P.R. & Co. a Stonetalon.",al={"cos'è la pergamena scritta","lore pergamena scritta","informazioni sulla pergamena scritta"}}},fp="19,98,18.314.0,41.152.0,25.84.0,39.220.0,13.130.0"}
P.entries["item:sea-creature-bones"] = {n="Ossa di Creature Marine",s="A Rivafosca, le Ossa di Creature Marine vengono trascinate a riva insieme ai corpi di enormi creature marine. Gwennyth Bly'leggonde raccoglie campioni per il Temple of the Moon a Darnassus, dove si indaga sulla causa degli spiaggiamenti.",h="A Rivafosca, le Ossa di Creature Marine vengono trascinate a riva insieme ai corpi di enormi creature marine.",kw={"auberdine","beached sea creature","rivafosca","murloc foscarovina","gwennyth bly'leggonde","costa bruma","ossa di creature marine","temple of the moon"},ang={["class:Druid"]="Come druido, vedi nelle morti inspiegabili di antichi predatori marini il segno di un profondo turbamento nelle acque al largo di Kalimdor. Un simile turbamento preoccupa ogni guardiano devoto all'equilibrio ecologico.",["race:NightElf"]="Come Elfo della Notte, sai che questi improvvisi spiaggiamenti di massa turbano profondamente il tuo popolo, che venera l'armonia del mondo naturale. Il tuo popolo considera gli spiaggiamenti un oscuro presagio che richiede l'attenzione del Temple of the Moon."},sec={{t="Un presagio sulla riva",b="Enormi creature marine ora si gettano nelle secche di Rivafosca e vi muoiono. Tra loro ci sono trebbiatori giganti molto più grandi di quelli originari di queste acque. Per gli Elfi della Notte, questo improvviso aumento è un presagio funesto. Gwennyth Bly'leggonde è stata inviata dal Temple of the Moon ad Auberdine per raccogliere ossa dalle creature spiaggiate. Gli ippogrifi trasportano i campioni a Darnassus per un esame approfondito."},{t="Carogne e spazzini",b="Le immense carcasse attirano gli spazzini locali. I murloc Greymist si radunano per nutrirsi delle creature morte e morenti, poi difendono strenuamente le zone in cui si nutrono. Sono troppo deboli per cacciare bestie di queste dimensioni. Investigatori e avventurieri devono quindi farsi strada combattendo tra i loro branchi lungo Costa Bruma per recuperare frammenti ossei da studiare."}},faq={{q="Perché queste creature si spiaggiano?",a="La causa esatta rimane sconosciuta. Gli spiaggiamenti occasionali sono un rischio naturale, ma l'improvviso e drastico aumento allarma le sacerdotesse di Elune, che lo ritengono innaturale e hanno avviato un'indagine ufficiale.",al={"perché i trebbiatori si spiaggiano","balene morte rivafosca","perché le creature si spiaggiano a rivafosca"}},{q="Chi vuole queste ossa?",a="Gwennyth Bly'leggonde raccoglie le ossa ad Auberdine per il Temple of the Moon a Darnassus. Gli studiosi e le sacerdotesse del tempio sperano di scoprire cosa stia turbando il mare.",al={"chi prende le ossa","a chi consegnare le ossa di creature marine","gwennyth rivafosca"}},{q="I murloc hanno ucciso queste bestie giganti?",a="No. I murloc Greymist sono troppo deboli per abbattere bestie marine di quelle dimensioni. Si radunano numerosi per nutrirsi dopo che le creature vengono trascinate a riva.",al={"i murloc hanno ucciso il trebbiatore","i murloc foscarovina hanno ucciso il mostro marino"}},{q="Da dove vengono recuperate le ossa?",a="Le ossa provengono dalle enormi carcasse spiaggiate lungo Rivafosca, soprattutto sulle sabbie a sud di Auberdine e lungo Costa Bruma.",al={"dove trovare le ossa di creature marine","posizioni di beached sea creature"}}},fx={["90a4db20"]={q="Cosa sono queste Ossa di Creature Marine?",a="Sono resti scheletrici recuperati dalla carcassa massiccia di una creatura marina spiaggiata—nello specifico uno squalo trebbiatore insolitamente grande—arenatosi lungo la nebbiosa costa di Darkshore. Saccheggiati dai murloc Nebbiagrigia locali, questi resti massicci servono come prova fisica vitale per i ricercatori che cercano di capire perché i behemoth dell'oceano stiano morendo a riva.",al={"cosa sono le ossa di creature marine","lore ossa di creature marine","ossa giganti darkshore"}},cb40613a={q="Da dove provengono le Ossa di Creature Marine?",a="Queste ossa provengono da un colossale squalo trebbiatore, molto più grande di chiunque si aspettasse nelle acque di Darkshore, che si è inspiegabilmente gettato sulle spiagge di Costa Bruma a sud di Auberdine. Piuttosto che essere state create o uccise dai predatori locali, le ossa appartengono naturalmente a bestie di acque profonde che si sono misteriosamente spinte a riva per morire.",al={"da dove provengono le ossa di creature marine","origine ossa di creature marine","origine creatura marina spiaggiata"}}},fp="18,223,22.411.0,22.319.0,39.208.0,22.166.0,40.143.0,35.129.0"}
P.entries["item:sea-turtle-remains"] = {n="Resti di Tartaruga di Mare",s="Lungo Rivafosca, i Resti di Tartaruga di Mare si accumulano sulla costa e sotto le onde. I ricercatori di Auberdine studiano il crescente numero di tartarughe di mare morte.",h="Lungo Rivafosca, i Resti di Tartaruga di Mare si accumulano sulla costa e sotto le onde.",kw={"auberdine","beached sea turtle","rivafosca","gwennyth bly'leggonde","resti di tartaruga di mare","teldrassil","temple of the moon","washed ashore"},ang={["class:Druid"]="Le morti innaturali di grandi creature marine indicano una corruzione più profonda che turba l'equilibrio della natura lungo la costa di Kalimdor.",["race:NightElf"]="Lo spiaggiamento di massa delle creature marine lungo la costa dei tuoi antenati è un segno infausto. La causa sospetta si trova nelle acque che circondano Teldrassil."},sec={{t="Uno spiaggiamento inquietante",b="Gigantesche creature marine si arenano lungo Rivafosca, mentre altre giacciono sott'acqua vicino a relitti sommersi. Ad Auberdine, Gwennyth Bly'leggonde raccoglie frammenti ossei e tessuti dai loro corpi. Il Temple of the Moon a Darnassus richiede con urgenza questi campioni. I suoi studiosi e le sue sacerdotesse temono che le creature stiano fuggendo da una perturbazione innaturale nelle acque attorno a Teldrassil."},{t="Spazzini dei bassifondi",b="Recuperare i resti è pericoloso. Le tribù di murloc lungo la costa si radunano attorno alle enormi carcasse, spolpandone le ossa e nidificando accanto a esse. Agli studiosi servono frammenti ossei e tessuti freschi prima che gli animali saprofagi distruggano le prove che potrebbero spiegare la migrazione fatale delle creature."}},faq={{q="A cosa servono questi resti?",a="Ad Auberdine, Gwennyth Bly'leggonde raccoglie resti per gli studiosi e le sacerdotesse del Temple of the Moon a Darnassus. Cercano di scoprire perché tante creature oceaniche stiano morendo lungo Rivafosca.",al={"perché raccogliere i resti di tartaruga","uso delle ossa di tartaruga","missione tartaruga di mare rivafosca"}},{q="Perché le tartarughe di mare si spiaggiano a Rivafosca?",a="I ricercatori non hanno trovato la causa, ma temono che le creature marine stiano fuggendo da una presenza inquietante nelle acque attorno a Teldrassil. Questi spiaggiamenti indicano un malessere diffuso tra le creature marine.",al={"perché le tartarughe stanno morendo","spiaggiamenti tartarughe rivafosca","creature marine spiaggiate"}},{q="Dove si trovano queste carcasse?",a="Carcasse di gigantesche tartarughe di mare giacciono lungo la costa di Rivafosca. Alcune si trovano nelle acque poco profonde vicino a navi affondate a ovest di Auberdine, mentre altre costellano spiagge circondate da accampamenti di murloc.",al={"posizioni dei resti di tartaruga","dove trovare tartaruga di mare scheletrica"}},{q="Chi sta studiando questi resti?",a="Ad Auberdine, Gwennyth Bly'leggonde raccoglie i resti e invia resoconti dettagliati alla Sisterhood of Elune presso il Temple of the Moon a Darnassus.",al={"chi vuole i resti","gwennyth blyleggonde"}}},fx={dfe0d6c5={q="Cosa sono questi Resti di Tartaruga di Mare?",a="Questi resti sono campioni scheletrici recuperati da tartarughe di mare giganti che sono state spinte a riva lungo la costa di Darkshore o che sono morte nelle sue acque poco profonde. Sebbene saccheggiati da predatori locali e murloc, rimangono ossa e tessuti recuperabili, che offrono indizi fisici sugli ultimi momenti delle creature.",al={"cosa sono i resti di tartaruga di mare","lore resti di tartaruga di mare","cos'è il resto di tartaruga di mare"}},be90da46={q="Da dove provengono i Resti di Tartaruga di Mare?",a="Vengono raccolti direttamente da enormi carcasse scheletriche giacenti lungo le coste e le acque costiere di Darkshore, inclusi esemplari vicino ad Auberdine. Sono resti naturali di bestie marine piuttosto che oggetti creati, lasciati lì quando le tartarughe morenti nuotano verso terra e periscono.",al={"da dove provengono i resti di tartaruga di mare","origine resti di tartaruga di mare","fonte resti di tartaruga di mare"}}},fp="18,149,19.379.0,26.287.0,32.199.0,53.195.0,32.181.0,30.150.0"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="Descrizione Sigillata del Visitatore di Thredd",s="Il Custode Cuorsaldo sigilla un rapporto sull'uomo che visita Bazil Thredd nelle Segrete di Roccavento. Il resoconto riservato potrebbe aiutare gli investigatori a seguire qualcuno che si muove negli ambienti politici e criminali di Roccavento.",h="Il Custode Cuorsaldo sigilla un rapporto sull'uomo che visita Bazil Thredd nelle Segrete di Roccavento.",kw={"baros alexston","bazil thredd","maelik","mathias shaw","descrizione sigillata","segrete di roccavento","custode cuorsaldo"},ang={["class:Rogue"]="Come ladro, puoi capire come falsi nomi, documenti contraffatti e visite in prigione abbiano attirato l'attenzione di Mathias Shaw quando ha confrontato l'aspetto dell'uomo con le informazioni del SI:7.",["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere il punto debole nella sicurezza di Roccavento: i cospiratori possono varcare i cancelli delle Segrete di Roccavento con credenziali falsificate."},sec={{t="Un Patrono Misterioso",b="Per anni, il prigioniero Bazil Thredd non ha ricevuto visite nelle Segrete di Roccavento. Poi un uomo taciturno ha iniziato a presentarsi una o due volte alla settimana con documenti validi a nome di Maelik. Il Custode Cuorsaldo lo ha notato e ha annotato l'aspetto dell'uomo. Ha sigillato la descrizione affinché occhi indiscreti non potessero leggerla prima dell'intervento degli investigatori competenti."},{t="Dai Muratori alle Spie",b="L'architetto cittadino Baros Alexston non ha trovato alcuna corrispondenza chiara nella descrizione. Sospettando che il visitatore fosse legato alla ribellione dei Defias, ha inviato la Busta Sigillata al Maestro Mathias Shaw, capo del servizio di intelligence di Roccavento, il SI:7. Shaw ha riconosciuto nell'uomo un mercenario letale che usa vari nomi, tra cui Marzon. Ora il mercenario svolge il lavoro sporco per Lord Gregor Lescovar."}},faq={{q="Chi ha scritto questa descrizione?",a="Il Custode Cuorsaldo, responsabile delle Segrete di Roccavento, ha scritto e sigillato il documento. Si è insospettito quando uno sconosciuto ha iniziato a visitare regolarmente il capo dei Defias imprigionato, Bazil Thredd.",al={"chi l'ha scritto","autore della descrizione","chi ha redatto la nota"}},{q="Chi è il visitatore descritto nel documento?",a="Il visitatore portava documenti a nome di Maelik. Il Custode Cuorsaldo ha annotato il suo aspetto affinché gli investigatori potessero identificarlo.",al={"chi faceva visita a thredd","chi è maelik","identità del visitatore"}},{q="Perché il visitatore si incontrava con Bazil Thredd?",a="Dopo anni senza visite, Bazil Thredd ha iniziato a riceverne regolarmente. La descrizione sigillata è al vaglio degli investigatori per scoprire lo scopo del visitatore.",al={"perché visitare thredd","scopo del visitatore di thredd"}},{q="Dove deve essere portato questo documento sigillato?",a="Porta prima il documento all'architetto cittadino Baros Alexston a Roccavento. Dopo aver esaminato la descrizione dell'uomo a lui sconosciuto, Alexston ti incarica di consegnarla al Maestro Mathias Shaw presso il quartier generale del SI:7 nella Città Vecchia.",al={"dove portarlo","chi vuole la descrizione"}}},fx={["7193ccc9"]={q="Perché la descrizione del visitatore di Thredd è così importante?",a="Per anni, Bazil Thredd è rimasto abbandonato nelle Segrete di Roccavento senza un singolo visitatore. Quando una figura misteriosa che portava documenti sotto il nome di 'Maelik' ha iniziato improvvisamente a visitarlo ogni settimana, il Custode Cuorsaldo è diventato sospettoso di una cospirazione più profonda. Smascherare questo visitatore è vitale per scoprire chi a Roccavento stia attivamente coordinandosi con la leadership incarcerata della Fratellanza dei Defias, spingendo gli investigatori a cercare la rete di intelligence di Mathias Shaw per identificare l'oscuro intermediario.",al={"perché vogliono la descrizione","descrizione sigillata thredd perché richiesta","perché la descrizione del visitatore è importante"}}},fp="38,215,19.325.0,25.380.1,27.196.0,42.127.2,46.153.2,49.206.1"}
P.entries["item:sealed-envelope"] = {n="Busta Sigillata",s="A Stonetalon, Fizziks ha racchiuso nella Busta Sigillata i segreti della S.P.R. & Co. per Sputavalvole a Porto Paranco.",h="A Stonetalon, Fizziks ha racchiuso nella Busta Sigillata i segreti della S.P.R.",kw={"progetti","fizziks","porto paranco","busta sigillata","sputavalvole","petrartiglio","super reaper 6000","s.p.r. & co."},ang={["faction:Horde"]="Come membro dell'Orda, portando queste carte a sud da Stonetalon aiuti i goblin neutrali di Porto Paranco a ostacolare il disboscamento aggressivo e predatorio della S.P.R. & Co.",["profession:Engineering"]="Per un ingegnere, la busta contiene disegni tecnici del Super Reaper 6000, una macchina distruttiva e redditizia ideata dai goblin."},sec={{t="Spionaggio industriale",b="Cacciato dalle attività di disboscamento della S.P.R. & Co. nelle Vette di Petrartiglio, l'ingegnere goblin Fizziks ne ha trafugato i segreti. La busta contiene manuali aziendali, procedure operative e progetti tecnici. Tra questi ci sono gli schemi del Super Reaper 6000, una macchina costruita per il disboscamento industriale su vasta scala."},{t="Consegna a Porto Paranco",b="Fizziks invia i documenti a sud, a Sputavalvole, un ingegnere del porto goblin neutrale di Porto Paranco. I rivali del Cartello degli Spargifumo nutrono poco affetto o fiducia per Fizziks. Eppure i progetti hanno un chiaro valore ingegneristico. Rivelano l'abilità meccanica della S.P.R. & Co. e offrono agli ingegneri indipendenti la possibilità di usarne i metodi avanzati di disboscamento."}},faq={{q="Cosa c'è all'interno della Busta Sigillata?",a="La Busta Sigillata contiene manuali della S.P.R. & Co., documenti tecnici e schemi del Super Reaper 6000, una macchina per il disboscamento. Fizziks li ha rubati quando ha lasciato in fretta la compagnia.",al={"contenuto della busta","cosa c'è nella busta sigillata","oggetti della busta sigillata"}},{q="Chi ha preparato questo plico?",a="L'ingegnere goblin Fizziks ha preparato la busta dopo essere stato cacciato dalle attività di disboscamento della S.P.R. & Co. nelle Vette di Petrartiglio.",al={"chi ha preparato la busta","chi ha dato la busta sigillata","busta di fizziks"}},{q="Chi dovrebbe riceverlo?",a="La busta è destinata a Sputavalvole, un inventore goblin di Porto Paranco, la città portuale nelle Savane.",al={"chi riceve la busta","dove va la busta","consegna a sputavalvole"}},{q="Perché Sputavalvole vuole questi documenti?",a="Sputavalvole non vede di buon occhio la S.P.R. & Co., e i documenti offrono migliorie e schemi preziosi. Permettono agli inventori esterni di comprendere e adottare i suoi potenti progetti meccanici.",al={"perché sputavalvole la vuole","tecnologia della s.p.r. & co. porto paranco"}}},fp="15,109,19.315.0,19.342.0,35.192.0,25.138.0,30.99.0,43.185.0"}
P.entries["item:sealed-note-to-elling"] = {n="Messaggio Sigillato per Elling",s="A Roccavento, Jorgen invia un dispaccio sigillato a Elling Trias, proprietario di Trias' Cheese. Il messaggio del pescatore coinvolge Trias in una discreta indagine su un diplomatico scomparso.",h="A Roccavento, Jorgen invia un dispaccio sigillato a Elling Trias, proprietario di Trias' Cheese.",kw={"elling trias","jorgen","messaggio sigillato per elling","roccavento","the missing diplomat","distretto commerciale","formaggi di trias"},ang={["class:Rogue"]="Come ladro che conosce le reti clandestine di Roccavento, potresti riconoscere in Elling Trias ben più di un mercante di formaggi. Questa corrispondenza riservata rientra nelle attività di quelle reti.",["faction:Alliance"]="Come membro dell'Alleanza, porti il messaggio di Jorgen al servizio della Corona. In questo modo, contribuisci a far progredire un'indagine vitale per la stabilità politica di Roccavento."},sec={{t="Un passaggio di consegne discreto",b="A Roccavento, Jorgen dà istruzioni rigorose per il Messaggio Sigillato: consegnarlo nelle mani di Elling Trias e mantenere il silenzio. La posta in gioco non ammette chiacchiere avventate. Trias gestisce un negozio di formaggi nel Distretto Commerciale. Lì, il messaggio di Jorgen porta l'indagine sulla scomparsa del diplomatico al suo bancone."}},faq={{q="Cosa c'è scritto all'interno del messaggio sigillato?",a="Il messaggio resta sigillato finché non raggiunge Elling Trias. Contiene il rapporto di Jorgen e indirizza il corriere a Trias per ulteriori indagini sulla scomparsa del diplomatico.",al={"contenuto del messaggio","cosa dice il messaggio","testo della lettera"}},{q="Perché un venditore di formaggi riceve informazioni segrete?",a="Elling Trias gestisce un modesto negozio di formaggi nel Distretto Commerciale come copertura. Dietro quell'apparenza, dispone di una vasta rete clandestina di occhi e orecchie in tutta la città. Questo lo rende prezioso nelle indagini delicate.",al={"perché elling trias","perché negozio di formaggi","trias è una spia"}},{q="Chi è Jorgen?",a="Jorgen è un pescatore che si trova vicino all'acqua nella Valle degli Eroi di Roccavento. Ha dei trascorsi con Elling Trias e il Vescovo DeLavey, che ricorre a lui per questioni riservate, lontano da occhi indiscreti.",al={"chi ha scritto il messaggio","storia di jorgen","guardiano jorgen"}},{q="Di cosa tratta il caso del diplomatico scomparso?",a="Un diplomatico di Roccavento inviato a Theramore per incontrare Jaina Marefiero non è mai arrivato. Le autorità reali indagano con discrezione su ogni pista sospetta per evitare di seminare il panico nelle strade.",al={"storia del diplomatico scomparso","chi è il diplomatico","perché diplomatico scomparso"}}},fx={["76232759"]={q="Cos'è il Messaggio Sigillato per Elling?",a="È un messaggio riservato che ti è stato dato da Jorgen, destinato specificamente alle orecchie—e agli occhi—di Elling Trias. Sigillato con cera per garantire la segretezza, trasporta informazioni urgenti riguardanti l'indagine sulla Diplomatica scomparsa, affidato a te per una consegna a mano sicura attraverso Roccavento.",al={"cos'è il messaggio sigillato per elling","oggetto messaggio sigillato per elling","cos'è il messaggio di jorgen"}},["2cd529f3"]={q="Da dove proviene il Messaggio Sigillato per Elling?",a="Il messaggio è stato scritto e sigillato da Jorgen. Dopo aver interrogato e valutato le tracce riguardanti la Diplomatica scomparsa del regno, Jorgen scrive questo dispaccio discreto e lo mette direttamente nelle tue mani affinché tu lo porti a Elling Trias.",al={"chi ha scritto il messaggio sigillato per elling","da dove proviene il messaggio sigillato","chi ha dato il messaggio sigillato per elling"}},["92e95eae"]={q="Perché serve il Messaggio Sigillato per Elling?",a="La scomparsa della Diplomatica è una questione di massima delicatezza e sicurezza di stato. Jorgen non può parlare apertamente per strada, quindi il messaggio funge da introduzione silenziosa e consegna di informazioni a Elling Trias, coinvolgendo Trias nell'indagine senza allertare occhi indiscreti.",al={"perché consegnare il messaggio sigillato","perché elling trias ha bisogno del messaggio","perché il messaggio di jorgen è importante"}}},fp="21,176,16.297.0,39.169.0,53.235.0,14.197.0,40.177.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="Messaggio Sigillato per il Guardiano Backus",s="A Roccavento, Elling Trias invia un messaggio sigillato al Guardiano Backus a Boscovespro. Chiede alla guardia della Night Watch di riferire sulle attività dei Defias nei pressi di Borgoscuro.",h="A Roccavento, Elling Trias invia un messaggio sigillato al Guardiano Backus a Boscovespro.",kw={"borgoscuro","boscovespro","elling trias","the night watch","messaggio sigillato","the missing diplomat","guardiano backus"},ang={["class:Rogue"]="Come ladro, puoi vedere come Trias si affidi a una semplice guardia per ottenere informazioni locali. Questo gli permette di raccogliere informazioni ben oltre le mura della città.",["faction:Alliance"]="Come membro dell'Alleanza, puoi vedere come i legami personali e le informazioni raccolte per vie informali aiutino a tenere uniti i territori frammentati della fazione quando i canali ufficiali falliscono."},sec={{t="Una parola per i Guardiani",b="Elling Trias accetta di usare i suoi contatti per aiutare a trovare il diplomatico scomparso. Sigilla un messaggio per il Guardiano Backus, una guardia della Night Watch di stanza a Boscovespro.\n\nTrias manda un viaggiatore a sud attraverso la foresta per consegnarlo a mano. Spera che Backus riferisca di eventuali Defias avvistati nei pressi di Borgoscuro."},{t="Gli occhi lungimiranti di Trias",b="Elling Trias vende formaggi nel Distretto Commerciale di Roccavento e mantiene contatti al di fuori della città. Il suo messaggio raggiunge il Guardiano Backus, una guardia della diffidente Night Watch di Borgoscuro.\n\nBorgoscuro affronta le minacce dei non morti e delle bestie feroci. Backus accoglie con favore il messaggio di Trias, segno che Trias si è guadagnato rispetto anche oltre Roccavento."}},faq={{q="Chi ha scritto questo messaggio?",a="Elling Trias ha scritto il messaggio. È il proprietario di Trias' Cheese nel Distretto Commerciale di Roccavento e lavora in segreto come spia e intermediario di informazioni.",al={"chi ha scritto il messaggio sigillato per il guardiano backus","autore del messaggio","chi consegna il messaggio"}},{q="Perché viene inviato al Guardiano Backus?",a="Il Guardiano Backus presta servizio nella Night Watch di Borgoscuro ed è un contatto fidato di Elling Trias. Trias gli chiede di riferire avvistamenti locali o voci sulle attività della Fratellanza dei Defias nella zona di Boscovespro.",al={"chi è il guardiano backus","perché inviare a backus","qual è il ruolo di backus"}},{q="Dove si trova il Guardiano Backus?",a="Il Guardiano Backus pattuglia la strada appena a nord di Borgoscuro, a Boscovespro. Sorveglia gli accessi alla cittadina dalla foresta.",al={"dove si trova backus","posizione del guardiano backus","trovare il guardiano backus"}},{q="Cosa succede dopo che il messaggio viene consegnato?",a="Backus riconosce il nome di Trias e si fida della sua richiesta. Mette da parte la sua consueta cautela verso i viaggiatori e accetta di indagare sulle attività sospette nei boschi.",al={"cosa dice backus","dopo aver consegnato il messaggio"}}},fx={["8647b8fc"]={q="Cos'è il Messaggio Sigillato per il Guardiano Backus?",a="È un messaggio riservato scritto da Elling Trias, il mastro mercante di formaggi di Roccavento, destinato al Guardiano Backus a Boscovespro. Trias lo manda tramite te per richiedere l'aiuto di Backus nel raccogliere informazioni sull'attività locale della Fratellanza dei Defias come parte dell'indagine in corso sulla Diplomatica scomparsa.",al={"cos'è il messaggio sigillato per il guardiano backus","scopo messaggio sigillato per il guardiano backus","messaggio di trias per backus"}}},fp="29,149,20.285.0,25.309.1,20.137.0,39.189.0,34.110.0,41.163.0"}
P.entries["item:searing-collar"] = {n="Collare Rovente",s="A Roccia del Teschio, a Durotar, i Collari Roventi bruciano i cultisti delle Lame Ardenti che li indossano. Questi torque riscaldati li aiutano a sintonizzarsi con il potere demoniaco.",h="A Roccia del Teschio, a Durotar, i Collari Roventi bruciano i cultisti delle Lame Ardenti che li indossano.",kw={"lame ardenti","demone","durotar","vilmagia","margoz","collare rovente","roccia del teschio"},ang={["class:Warlock"]="Come stregone, potresti conoscere i Collari Roventi come rozzi condotti che incanalano la corruzione vile nella carne mortale.",["race:Orc"]="Come orco, trovare cultisti che usano questi collari alle porte di Durotar ti ricorda amaramente che l'ombra della servitù demoniaca persiste ancora."},sec={{t="Strumenti di corruzione",b="Le Lame Ardenti si radunano a Roccia del Teschio, appena a est di Orgrimmar, per celebrare riti oscuri. Cultisti, neofiti e sgherri portano al collo i Collari Roventi. Il metallo marchia e ustiona la loro pelle mentre ne sopportano il calore.\n\nMargoz, un eremita, studia questi crudeli dispositivi. Sospetta che il bruciore e gli incantamenti sintonizzino chi li indossa con le energie demoniache. Quale ruolo hanno i collari nella corruzione che si diffonde nella società degli orchi sotto il naso dell'Orda?"}},faq={{q="Che cos'è un Collare Rovente?",a="I cultisti delle Lame Ardenti portano al collo i Collari Roventi durante i rituali. Il metallo riscaldato brucia la loro carne e li aiuta a sintonizzarsi con il potere demoniaco.",al={"cosa sono i collari roventi","lore del collare rovente","cosa fa il collare"}},{q="Chi indossa questi collari?",a="I membri delle Lame Ardenti nascosti all'interno di Roccia del Teschio indossano i collari. Tra loro ci sono cultisti, fanatici, sgherri, apprendisti e neofiti.",al={"chi li usa","chi rilascia i collari roventi","collari delle lame ardenti"}},{q="Perché i cultisti si bruciano la carne?",a="Le Lame Ardenti usano il metallo rovente nei loro rituali. Sopportando le ustioni e l'incantamento demoniaco, i cultisti sintonizzano il corpo e lo spirito con il potere demoniaco.",al={"perché bruciarsi le carni","perché indossare il collare rovente","scopo del collare"}},{q="Chi vuole esaminare i Collari Roventi?",a="Margoz, un investigatore accampato a Durotar, raccoglie Collari Roventi per studiarne gli incantamenti e scoprire l'influenza delle Lame Ardenti.",al={"a chi servono i collari roventi","chi sta studiando i collari","collari di margoz"}}},fp="14,140,25.448.0,25.149.0,24.139.0,41.162.0,41.141.0"}
P.entries["item:searing-coral"] = {n="Corallo Rovente",s="Lungo la costa delle Paludi Grigie, il Corallo Rovente si raccoglie dall'Iron Coral vivente sul fondo del mare. Inventori e fabbri ne apprezzano il minerale resistente al calore, usato per rinforzare le armature.",h="Lungo la costa delle Paludi Grigie, il Corallo Rovente si raccoglie dall'Iron Coral vivente sul fondo del...",kw={"furen barbalunga","iron coral","forgiardente","klockmort spannerspan","porto di menethil","corallo rovente","armatura da guerriero","paludi grigie"},ang={["class:Warrior"]="Come guerriero, raccogliere il Corallo Rovente dimostra la tua dedizione ai maestri armaioli di Forgiardente. Forgiano per te una corazza su misura per i duri combattimenti in prima linea.",["profession:Blacksmithing"]="Come fabbro, puoi vedere come l'ingegno gnomesco si unisce alla tradizionale lavorazione nanica dei metalli per trasformare i minerali oceanici in piastre temprate."},sec={{t="Una rara risorsa costiera",b="Il Corallo Rovente cresce nel mare freddo a sud di Porto di Menethil. L'Iron Coral vivente prospera nell'acqua salata e fornisce materiale ricco di minerali che resiste al calore estremo. I raccoglitori devono staccare le escrescenze indurite facendo leva, mentre murloc selvaggi e altre bestie acquatiche si aggirano nelle vicinanze."},{t="Applicazione nella forgiatura",b="La lavorazione del Corallo Rovente non fa parte della tradizione dei fabbri nani. A Forgiardente, artigiani gnomi curiosi come Klockmort Spannerspan seguono i metodi del veterano forgiatore d'armature Furen Barbalunga. Fondono il corallo e lo incorporano nelle leghe metalliche a colpi di martello, creando armature leggere e resistenti per aspiranti guerrieri."}},faq={{q="Dove cresce il Corallo Rovente?",a="Il Corallo Rovente cresce nei banchi di Iron Coral sotto le acque costiere poco profonde a sud di Porto di Menethil, nelle Paludi Grigie.",al={"posizione del corallo rovente","dove trovare il corallo rovente","posizione di iron coral"}},{q="Chi vuole il Corallo Rovente a Forgiardente?",a="Klockmort Spannerspan, un artificiere gnomo di Tinkertown a Forgiardente, cerca il Corallo Rovente. Sperimenta tecniche di forgiatura apprese dal leggendario armaiolo nano Furen Barbalunga.",al={"chi usa il corallo rovente","corallo di klockmort spannerspan","corallo di furen barbalunga"}},{q="Come si può forgiare il corallo in un'armatura?",a="Il Corallo Rovente ha una struttura insolitamente densa e resistente al calore. Fuso in una fornace e incorporato nelle leghe metalliche a colpi di martello, rinforza le piastre composite e rende l'equipaggiamento protettivo eccezionalmente resistente.",al={"forgiatura del corallo","si può fondere il corallo","metallurgia del corallo rovente"}},{q="È pericoloso raccogliere il Corallo Rovente?",a="Il corallo in sé si può raccogliere senza pericolo, una volta trovato. Per raggiungerlo bisogna nuotare in mare aperto al largo della costa delle Paludi Grigie, dove si aggirano murloc selvaggi e bestie acquatiche aggressive.",al={"il corallo rovente è caldo","raccolta di iron coral"}}},fx={["3e3d13aa"]={q="Cos'è il Corallo Rovente?",a="Il Corallo Rovente è una rara crescita marina ricca di minerali raccolta dalle formazioni di Iron Coral sotto le onde lungo la costa delle Wetlands, a sud di Porto di Menethil. Nonostante sia un esemplare oceanico, le sue proprietà dense e peculiari gli permettono di essere fuso, martellato e lavorato come metallo da esperti fabbri.",al={"cos'è il corallo rovente","informazioni corallo rovente","lore corallo rovente"}},["1c0d8f00"]={q="Da dove proviene il Corallo Rovente?",a="Il Corallo Rovente è una crescita acquatica naturale piuttosto che un manufatto creato. Cresce esclusivamente in un unico luogo conosciuto al mondo: tra i letti di corallo ferroso sommersi lungo le acque costiere a sud di Porto di Menethil nelle Wetlands.",al={"origine corallo rovente","da dove proviene il corallo rovente","chi ha creato il corallo rovente"}}},fp="13,170,23.267.0,23.290.0,30.115.0,37.187.0,35.198.0,38.167.0"}
P.entries["item:secure-crate"] = {n="Cassa Sicura",s="Nelle Savane, una Cassa Sicura è diretta a Porto Paranco. Le pozioni e le merci alchemiche al suo interno sono destinate ai Regni Orientali, al di là del mare.",h="Nelle Savane, una Cassa Sicura è diretta a Porto Paranco.",kw={"savane","baia degli acquanera","pozioni","porto paranco","reagenti","cassa sicura","spedizione","wharfmaster dizzywig"},ang={["faction:Horde"]="Come viaggiatore dell'Orda, sai che il porto neutrale di Porto Paranco collega Kalimdor e i Regni Orientali grazie alle navi dei goblin.",["profession:Herbalism"]="Come erborista, sai che alchimisti ed erboristi ai due lati del mare si affidano alle rotte commerciali di frontiera per scambiarsi ingredienti grezzi."},sec={{t="Il carico di un corriere",b="Corrieri, carovane e navi dei goblin trasportano merci tra Kalimdor e i Regni Orientali. Quando una carovana delle Savane manca la partenza, i viaggiatori portano carichi delicati come questa Cassa Sicura fino alla costa. All'interno ci sono pozioni, merci alchemiche e reagenti per gli associati al di là del Grande Mare. Il sigillo protegge la cassa lungo i sentieri delle Savane e durante il viaggio in mare."},{t="Attraverso Porto Paranco",b="Il viaggio via terra della cassa termina ai moli di Porto Paranco, dove Wharfmaster Dizzywig sovrintende alle spedizioni. Porto Paranco è un porto neutrale per le merci che attraversano il mare, compresi i carichi diretti alla Baia degli Acquanera. Dizzywig tiene i conti per il Cartello degli Spargifumo, registrando pacchi e merci prima di caricarli sulla prossima nave in partenza. Porto Paranco collega il Vecchio Mondo alla frontiera."}},faq={{q="Cosa c'è dentro la Cassa Sicura?",a="La Cassa Sicura contiene pozioni, reagenti alchemici e altre provviste per gli associati nei Regni Orientali.",al={"contenuto della cassa","cosa c'è nella cassa","oggetti della cassa sicura"}},{q="Dove viene inviata la cassa?",a="Porta la Cassa Sicura a Wharfmaster Dizzywig ai moli di Porto Paranco. Le riserverà un posto su una nave mercantile diretta alla Baia degli Acquanera, nel Vecchio Mondo.",al={"destinazione della cassa","dove va la cassa sicura"}},{q="Perché la cassa è stata affidata a un avventuriero invece che a una carovana?",a="Il mittente non è riuscito a raggiungere Porto Paranco in tempo e la carovana commerciale prevista era già partita. Un corriere assoldato deve portare la cassa ai moli in tempo per la marea.",al={"perché ho la cassa","carovana persa"}},{q="Chi prende la cassa a Porto Paranco?",a="Wharfmaster Dizzywig riceve la cassa ai moli di Porto Paranco. La annota nel suo registro delle spedizioni prima di caricarla sulla prossima nave che salperà con la marea.",al={"chi riceve la cassa","cassa di dizzywig"}}},fx={e5dd21c1={q="Cos'è la Cassa Sicura?",a="La Cassa Sicura è una spedizione imballata ermeticamente contenente un assortimento di pozioni, reagenti e altre provviste di valore. È imballata in modo sicuro affinché il suo delicato contenuto sopravviva a un lungo viaggio su carovana e nave attraverso il mare fino ai Regni Orientali.",al={"cos'è la cassa sicura","storia cassa sicura","informazioni cassa sicura"}},["4df2d75b"]={q="Da dove proviene la Cassa Sicura e chi l'ha realizzata?",a="La cassa ha origine nelle The Barrens, imballata e sigillata da uno speziale o uno studioso che aveva urgente bisogno di esportare le proprie provviste alchemiche. Non avendo il tempo di recarsi personalmente alla costa dopo aver perso la carovana commerciale regolare, ha preparato la cassa affinché venisse trasportata a mano direttamente al porto di Porto Paranco.",al={"chi ha creato la cassa sicura","da dove viene la cassa sicura","origine cassa sicura"}},b7ad6ca4={q="Perché la Cassa Sicura è ricercata?",a="Alcuni associati nei Regni Orientali, al di là del mare, attendono questi reagenti e pozioni essenziali. Il Wharfmaster Dizzywig a Porto Paranco deve consegnare la cassa ai suoi moli per poterla registrare sul suo libro mastro commerciale e stivarla a bordo della prossima nave in partenza per Baia degli Acquanera.",al={"perché cercare la cassa sicura","chi ha bisogno della cassa sicura","perché dizzywig vuole la cassa sicura"}}},fp="12,139,17.376.0,27.382.0,32.111.0,30.151.0,62.163.0,31.158.0"}
P.entries["item:senir-s-report"] = {n="Rapporti di Senir",s="Sulle fredde pendici di Dun Morogh, Senir Barbabianca invia le sue scoperte sui troll Frostmane al Senatore Barin Pietrarossa a Forgiardente.",h="Sulle fredde pendici di Dun Morogh, Senir Barbabianca invia le sue scoperte sui troll Frostmane al Senatore...",kw={"barin pietrarossa","frostmane","forgiardente","magni barbabronzea","senato","senir barbabianca","rapporti di senir","i rapporti"},ang={["faction:Alliance"]="Come membro dell'Alleanza, portando i Rapporti di Senir contribuisci a difendere Dun Morogh mentre ti destreggi nella spinosa politica dei governanti di Forgiardente.",["race:Dwarf"]="Come nano, portando i Rapporti di Senir ti ritrovi nella frattura che divide Forgiardente tra i decreti di Re Magni Barbabronzea e l'autorità rivendicata dal Senato."},sec={{t="Una direttiva reale",b="Il rapporto di Senir raccoglie le osservazioni dei montanari durante le ricognizioni sui troll Frostmane tra i dirupi di Dun Morogh. Include anche il resoconto di suo fratello Grelin sulla Valle Crestafredda. Grelin vi ha agito con l'approvazione di Re Magni Barbabronzea.\n\nSenir invia le scoperte al Senatore Barin Pietrarossa nell'High Seat di Forgiardente. Raccomanda ai corrieri di omettere quanto aiuto esterno gli sia servito per raccoglierle."},{t="Attriti nell'High Seat",b="Il resoconto di Senir Barbabianca giunge alla corte reale e suscita un tumulto. Il Senatore Barin Pietrarossa è adirato per la minaccia dei troll e per l'autorità impressa sul rapporto. Magni ha scavalcato la supervisione legislativa, mentre Barbabianca ha agito in base a ordini reali senza alcun controllo.\n\nLa mossa accresce il risentimento tra i senatori che esigono il controllo sulle procedure. Si acuisce la tensione tra il governo risoluto di Magni e le rivendicazioni di autorità del Senato."}},faq={{q="Cos'è Rapporti di Senir?",a="Il rapporto di Senir Barbabianca documenta le sue indagini sui troll Frostmane a Dun Morogh. Lo invia al Senato nanico a Forgiardente.",al={"rapporti di senir","cos'è questo rapporto","il rapporto"}},{q="Chi dovrebbe ricevere il rapporto?",a="Senir Barbabianca indirizza il rapporto al Senatore Barin Pietrarossa nell'High Seat di Forgiardente, vicino al trono di Re Magni Barbabronzea.",al={"chi riceve il rapporto","a chi consegno il rapporto","destinatario del rapporto"}},{q="Perché il Senatore Pietrarossa si arrabbia così tanto quando lo legge?",a="Il Senatore Pietrarossa è furioso perché il rapporto allegato di Grelin Barbabianca dichiara che Grelin ha agito per autorità di Re Magni senza consultare il Senato. Pietrarossa mal sopporta che la corona agisca unilateralmente sulle questioni di difesa senza l'approvazione del Senato.",al={"perché barin è arrabbiato","perché il senatore è arrabbiato","reazione di pietrarossa"}},{q="Perché Senir ti chiede di non menzionare di averlo aiutato?",a="Senir Barbabianca ti chiede di tacere il tuo aiuto affinché i suoi superiori credano che abbia condotto da solo le pericolose ricognizioni sulle colline innevate. Vuole proteggere la sua reputazione di montanaro diligente e capace.",al={"perché tacere","segreto di senir","merito di senir"}}},fx={["078e838e"]={q="Da dove provengono i Rapporti di Senir e chi li ha scritti?",a="Senir Barbabianca ha redatto questo dispaccio di persona a Dun Morogh dopo aver esplorato le minacce locali dei troll Mantogelido e aver ottenuto aiuto per gestire il Covo dei Mantogelido. Insieme alle sue scoperte, include il Rapporto di Grelin sulla Valle Crestafredda, che Grelin ha scritto sotto la sanzione di Re Magni Barbabronzea, e trasporta entrambi dai confini innevati fino alle grandi sale della capitale.",al={"chi ha scritto i rapporti di senir","da dove vengono i rapporti di senir","autore dei rapporti di senir"}},e0c0da53={q="Perché qualcuno vuole i Rapporti di Senir?",a="Il Senatore Barin Pietrarossa e il Senato di Forgiardente richiedono valutazioni ufficiali sul campo per seguire gli sviluppi regionali e le azioni militari a Dun Morogh. Tuttavia, poiché questo specifico dispaccio afferma l'autorità unilaterale di Re Magni sulle manovre locali, ha un peso politico notevole, informando il Senato di azioni della corona che ritengono aggirino la loro supervisione.",al={"perché consegnare i rapporti di senir","perché pietrarossa ha bisogno dei rapporti di senir","scopo dei rapporti di senir"}}},fp="14,133,17.399.0,25.430.1,23.143.0,38.131.0,56.253.1,50.210.0"}
P.entries["item:serena-s-head"] = {n="Testa di Serena",s="Ai Colli Aridi, Darsok Dagalesta cerca la testa di Serena Bloodfeather come prova della sua morte. Intende esporla su un carro di rifornimenti dell'Orda come monito contro ulteriori incursioni delle arpie.",h="Ai Colli Aridi, Darsok Dagalesta cerca la testa di Serena Bloodfeather come prova della sua morte.",kw={"crocevia","darsok dagalesta","colli aridi","arpia","rexxar","serena bloodfeather","testa di serena","witchwing"},ang={["class:Rogue"]="Darsok Dagalesta apprezza il lavoro pulito e spietato. Loda i mercenari che si insinuano dietro i posatoi nemici e giustiziano un bersaglio senza esitare.",["faction:Horde"]="Le carovane dell'Orda collegano Durotar a Mulgore e agli avamposti lontani. Esporre la testa di Serena su un carro di rifornimenti proclama il dominio dell'Orda sulle distese selvagge."},sec={{t="Un avvertimento sulla strada",b="Serena Bloodfeather guidava le arpie Witchwing dei Colli Aridi negli attacchi ai commerci attraverso le Savane settentrionali. I suoi assalti alle linee di rifornimento dell'Orda divennero feroci dopo che il signore delle bestie Rexxar uccise sua sorella.\n\nDarsok Dagalesta, un ladro orco, ordinò di dare la caccia a Serena per spezzare il morale dello stormo. Intende esporre la sua testa mozzata su una carovana in partenza, dove le arpie che osservano dai dirupi vedranno il monito."}},faq={{q="Perché Darsok Dagalesta vuole la testa di Serena?",a="Darsok vuole la prova che Serena Bloodfeather sia morta. Intende esporre la sua testa su una carovana di rifornimenti dell'Orda e spera che il trofeo spaventi le arpie Witchwing superstiti, tenendole lontane dai viaggiatori.",al={"perché prendere la testa di serena","darsok testa serena","cosa fa darsok con la testa"}},{q="Perché Serena Bloodfeather attaccava le carovane dell'Orda?",a="Serena Bloodfeather attaccava le carovane dell'Orda per vendicare sua sorella, uccisa dal campione mezzogre Rexxar. Colpiva le linee di rifornimento dell'Orda e i viandanti in tutte le Savane.",al={"perché serena attaccava le carovane","movente di serena bloodfeather","attacchi delle arpie nelle savane"}},{q="Da dove proviene questo trofeo?",a="Il trofeo proviene da Serena Bloodfeather, la matriarca che nidifica tra i dirupi dei Colli Aridi, nell'estremo nordovest delle Savane.",al={"dove trovare la testa di serena","posizione serena bloodfeather","come ottenere la testa di serena"}}},fx={["29e11954"]={q="Cos'è la Testa di Serena?",a="La Testa di Serena è la testa mozzata di Serena Bloodfeather, la vendicativa matriarca dello stormo di arpie Witchwing nelle The Barrens settentrionali. Prenderla segna la fine delle sue incursioni contro le rotte di rifornimento di Crossroads e serve come prova inconfutabile che la minaccia delle arpie è stata colpita alla radice.",al={"cos'è la testa di serena","testa di serena bloodfeather","oggetto testa di serena"}}},fp="13,176,21.411.1,47.194.0,53.175.1,33.126.0"}
P.entries["item:serpentbloom"] = {n="Bocciolo di Serpente",s="Nelle profondità della Caverna dei Lamenti, il Bocciolo di Serpente ha suscitato il vivo interesse della Royal Apothecary Society per le sue potenti proprietà naturali.",h="Nelle profondità della Caverna dei Lamenti, il Bocciolo di Serpente ha suscitato il vivo interesse della...",kw={"apothecary zamah","savane","erba","royal apothecary society","bocciolo di serpente","picco del tuono","caverna dei lamenti"},ang={["profession:Herbalism"]="Come erbalista, il tuo occhio esperto può scovare rari fiori delle caverne dove gli altri vedono solo pietra umida.",["race:Undead"]="Come non morto, raccogliendo il Bocciolo di Serpente aiuti Apothecary Zamah e la Royal Apothecary Society nella ricerca di risorse botaniche in terre straniere per rafforzare i Reietti."},sec={{t="Una rara flora sotterranea",b="Nelle Savane, il Bocciolo di Serpente prospera nei cunicoli bui e umidi della Caverna dei Lamenti. Le energie incontrollate del Sogno di Smeraldo hanno stravolto l'ecosistema delle caverne. Serpenti velenosi nidificano spesso tra gli steli dell'erba.\n\nBestie ostili e druidi corrotti infestano le caverne. Pochi di coloro che si avventurano al loro interno tornano con esemplari utilizzabili."},{t="L'interesse degli speziali",b="Presso le Pozze delle Visioni, sotto Picco del Tuono, Apothecary Zamah raccoglie il Bocciolo di Serpente per la Royal Apothecary Society di Sepulcra. I Reietti cercano piante virulente, insolite e dalle potenti proprietà chimiche in tutta Kalimdor per alimentare le ricerche al servizio della Dark Lady.\n\nZamah ritiene che raccogliere il Bocciolo di Serpente in quantità significative potrebbe portare a preziose scoperte nell'alchimia dei Reietti."}},faq={{q="Dove cresce il Bocciolo di Serpente?",a="Il Bocciolo di Serpente cresce solo nelle profondità della Caverna dei Lamenti, una rete labirintica di cunicoli a sud-ovest di Crocevia, nelle Savane. Si aggrappa al terreno negli anfratti bui e umidi della caverna.",al={"dove trovare il bocciolo di serpente","posizione del bocciolo di serpente","erba della caverna dei lamenti"}},{q="Perché la Royal Apothecary Society vuole il Bocciolo di Serpente?",a="Apothecary Zamah, agente della Royal Apothecary Society di stanza a Picco del Tuono, cerca il Bocciolo di Serpente per le ricerche. I Reietti studiano la flora insolita e pericolosa di tutta Kalimdor per sviluppare nuovi composti chimici e perseguire gli obiettivi più ampi della Society al servizio di Sylvanas Ventolesto.",al={"chi vuole il bocciolo di serpente","erba di apothecary zamah","perché raccogliere il bocciolo di serpente"}},{q="Perché la raccolta del Bocciolo di Serpente è pericolosa?",a="La Caverna dei Lamenti pullula di raptor, crocolischi e druidi corrotti. Il Bocciolo di Serpente ospita spesso serpenti velenosi, che possono attaccare quando l'erba viene smossa.",al={"pericolo del bocciolo di serpente","serpente del bocciolo di serpente"}},{q="Gli erboristi possono trovare il Bocciolo di Serpente più facilmente?",a="Sì. Gli erbalisti hanno una naturale predisposizione a individuare la vegetazione e possono localizzare i gruppi di Bocciolo di Serpente negli angoli bui della caverna.",al={"trovare il bocciolo di serpente con erboristeria","tracciare il bocciolo di serpente"}}},fx={bee22cd2={q="Cos'è il Bocciolo di Serpente?",a="Il Bocciolo di Serpente è un esemplare estremamente raro di flora nativa dei recessi più oscuri della Caverna dei Lamenti nelle The Barrens. Radicata all'interno delle umide profondità sotterranee, quest'erba insolita si distingue per le sue qualità serpentine: disturbarla spesso attira serpenti aggressivi annidati attorno alle sue radici.",al={"cos'è il bocciolo di serpente","erba bocciolo di serpente","info bocciolo di serpente"}}},fp="12,133,25.327.0,19.368.0,29.186.0,56.295.0,41.163.0,45.131.0"}
P.entries["item:sethir-s-journal"] = {n="Diario di Sethir",s="A Teldrassil, il Diario di Sethir è stato recuperato furtivamente. Le sue pagine mostrano che la corruzione dalla terraferma di Kalimdor ha raggiunto l'Albero del Mondo.",h="A Teldrassil, il Diario di Sethir è stato recuperato furtivamente.",kw={"rivafosca","destiny calls","radura dell'oracolo","satiro","sethir the ancient","diario di sethir","syurna","teldrassil"},ang={["class:Rogue"]="Come Ladro, puoi usare la furtività e il borseggio per trovare informazioni vitali dove guerrieri e diplomatici hanno fallito.",["race:NightElf"]="Come Elfo della Notte, ti trovi davanti alla prova che Teldrassil non è immune all'antica contaminazione demoniaca che si diffonde sulla terraferma di Kalimdor."},sec={{t="Indizio sulla Corruzione",b="Il Diario di Sethir è stato sottratto furtivamente a Sethir the Ancient, un satiro solitario vicino alla Radura dell'Oracolo. Teldrassil fu innalzato nella speranza di ripristinare l'immortalità elfica, eppure una malattia ha messo radici tra i suoi rami.\n\nA Darnassus, Syurna sospettava che Sethir avesse delle risposte. I ricognitori che tentarono di trattare con lui o di attaccarlo trovarono la morte, così il diario fu sottratto dalle sue sacche. I suoi scritti mostrano che la piaga che avvelena i boschi e le acque oltre il mare, a Rivafosca, ha raggiunto Teldrassil."}},faq={{q="Cos'è il Diario di Sethir?",a="Il Diario di Sethir è custodito da Sethir the Ancient, un satiro ostile sui rami esterni vicino alla Radura dell'Oracolo. Le sue annotazioni descrivono la corruzione che si diffonde nella regione.",al={"cos'è il diario di sethir","lore diario di sethir","a chi appartiene il diario di sethir"}},{q="Come si ottiene il diario?",a="I ricognitori che tentarono di trattare con Sethir o di combatterlo andarono incontro al fallimento e alla morte. Il diario deve essere sottratto furtivamente dalle sue sacche.",al={"come ottenere il diario di sethir","dove trovare il diario di sethir","borseggiare sethir"}},{q="Cosa rivela il diario?",a="Syurna, l'istruttrice dei Ladri, afferma che il diario dimostra che la strana malattia che devasta le foreste e le acque di Rivafosca ha raggiunto Teldrassil.",al={"cosa dice il diario di sethir","cosa c'è nel diario di sethir"}},{q="Chi è Sethir the Ancient?",a="Sethir the Ancient è un satiro solitario su un ramo appartato vicino ai margini della Radura dell'Oracolo. Reagisce con violenza agli intrusi e possiede informazioni sulla corruzione che si diffonde nell'Albero del Mondo.",al={"chi è sethir","sethir the ancient"}}},fx={["3d18c972"]={q="Da dove proviene il Diario di Sethir e chi lo ha scritto?",a="Il diario appartiene a Sethir the Ancient, un satiro ostile in agguato su un alto ramo ai margini della Radura dell'Oracolo a Teldrassil. Portando con sé i suoi scritti e registri personali tra i suoi averi, ha tenuto il diario finché dei furfanti a Darnassus non hanno cercato di sottrarglielo silenziosamente per scoprire quale corruzione si stia diffondendo attraverso l'albero del mondo.",al={"chi ha scritto il diario di sethir","origine del diario di sethir","origine diario sethir"}}},fp="16,144,19.475.1,25.171.0,28.130.0,29.130.0,26.207.0"}
P.entries["item:sevren-s-orders"] = {n="Ordini di Sevren",s="A Brill, il Magistrato Sevren invia a sud, a Sepulcra, un agente dei Reietti che ha dimostrato il proprio valore. Gli ordini indirizzano l'agente da Bethor Scheggiafredda nel Magic Quarter.",h="A Brill, il Magistrato Sevren invia a sud, a Sepulcra, un agente dei Reietti che ha dimostrato il proprio...",kw={"bethor scheggiafredda","brill","magic quarter","magistrato sevren","lich prodigo","ordini di sevren","sepulcra"},ang={["class:Mage"]="Come Mago, consegnare gli ordini ti porta al cospetto di Bethor Scheggiafredda, uno dei più eminenti incantatori del regno dei Reietti.",["race:Undead"]="Come Non Morto, portare il sigillo di Sevren ti conduce dal servizio locale a Tirisfal a lavorare per l'élite arcana di Sepulcra."},sec={{t="Convocazione nella capitale",b="Gli agenti dei Reietti che dimostrano il proprio valore contro il Flagello nelle Radure di Tirisfal vengono convocati a sud mentre il loro popolo consolida il controllo su Lordaeron. Il Magistrato Sevren scrive questi ordini come presentazione e credenziali per Bethor Scheggiafredda, uno dei più eminenti praticanti delle arti arcane della Dama Oscura nel Magic Quarter. Sevren sa soltanto che l'incarico consiste nel prendere contatto con un lich errante. Gli alti maghi di Sepulcra conferiscono alla convocazione la loro piena autorità."}},faq={{q="Chi ha scritto questi ordini?",a="Il Magistrato Sevren, che sovrintende agli affari dei Reietti a Brill, ha scritto gli ordini.",al={"autore degli ordini di sevren","chi è sevren","chi dà gli ordini di sevren"}},{q="Chi è destinato a ricevere questi ordini?",a="Gli ordini sono indirizzati a Bethor Scheggiafredda, un mago di alto rango dei Reietti nel Magic Quarter di Sepulcra.",al={"chi riceve gli ordini","dove porto gli ordini di sevren","chi è bethor scheggiafredda"}},{q="Qual è la missione menzionata negli ordini?",a="Gli ordini richiedono di reclutare un lich errante affinché aiuti i Reietti. Il pericoloso incarico spetta a un agente che ha già dimostrato il proprio valore contro il Flagello.",al={"qual è la missione del lich","cosa vuole bethor","missione del lich prodigo"}},{q="Perché sono stato scelto per consegnarli?",a="Bethor ha richiesto un agente che avesse dimostrato il proprio valore contro il Flagello. Il Magistrato Sevren ha giudicato i tuoi sforzi nelle Radure di Tirisfal sufficienti a soddisfare la pericolosa richiesta di Bethor.",al={"perché io","perché sevren ha scelto me"}}},fx={["59d8f724"]={q="Cosa sono gli Ordini di Sevren?",a="Gli Ordini di Sevren sono un dispaccio ufficiale scritto dal Magistrato Sevren di Brill. Fungono da credenziali formali, identificandoti come un agente di provato valore che ha combattuto efficacemente contro il Flagello ed è pronto a intraprendere un incarico delicato.",al={"cosa sono gli ordini di sevren","oggetto ordini di sevren","cos'è questo documento"}},["680dc8a1"]={q="Perché Bethor Scheggiafredda vuole gli Ordini di Sevren?",a="Bethor Scheggiafredda, un importante mago nel Magic Quarter di Undercity, ha chiesto che Sevren fornisca un agente capace di gestire un compito pericoloso che coinvolge un lich rinnegato. Presentare questi ordini dimostra che sei l'operativo scelto da Sevren e che la tua interruzione del potente mago è giustificata.",al={"perché consegnare gli ordini di sevren","perché bethor vuole gli ordini","chi ha bisogno degli ordini di sevren"}}},fp="15,150,22.460.0,23.76.0,40.107.0,44.139.0,33.157.0"}
P.entries["item:shadowhide-pendant"] = {n="Pendente dei Mantombroso",s="A Crestarossa, i Pendenti dei Mantombroso contraddistinguono gli gnoll al servizio di Morganth. Borgolago ne accetta dieci come prova che la sua legge è stata rispettata.",h="A Crestarossa, i Pendenti dei Mantombroso contraddistinguono gli gnoll al servizio di Morganth.",kw={"bailiff conacher","gnoll","borgolago","lieutenant fangore","morganth","pendente","crestarossa","mantombroso","solomon's law"},ang={["class:Warrior"]="Come guerriero, affronti gli gnoll Mantombroso, aggressivi e fisicamente imponenti. Le loro schiere mettono alla prova chi difende le strade che conducono a Borgolago.",["faction:Alliance"]="Come avventuriero fedele all'Alleanza, potresti essere chiamato a far rispettare la legge del regno. Gli insediamenti di frontiera come Borgolago ricevono pochi aiuti dalla guarnigione di Roccavento, quindi i magistrati locali contano su di te."},sec={{t="Simboli di sfida",b="I Pendenti dei Mantombroso pendono dal collo dei guerrieri, dei bruti e degli incantatori Mantombroso. Nel cuore delle colline di Crestarossa, Lieutenant Fangore guida il clan, ormai sotto l'influenza di Morganth. Morganth è un manipolatore rinnegato dell'Arcano. Per gli abitanti di Borgolago, i rozzi amuleti contraddistinguono una minaccia organizzata che tormenta gli insediamenti per conto di un nemico della Corona."},{t="La giustizia di Borgolago",b="Il Magistrato Solomon fa rispettare la legge di Roccavento, che prevede la pena di morte per chi aiuta attivamente un noto criminale del regno. I rinforzi reali sono troppo pochi, quindi Bailiff Conacher, presso il Lakeshire Town Hall, si affida agli avventurieri per mantenere la pace. Dieci Pendenti dei Mantombroso provano che gli gnoll agli ordini di Morganth hanno affrontato la giustizia della frontiera."}},faq={{q="Che cos'è un Pendente dei Mantombroso?",a="I Pendenti dei Mantombroso sono indossati dai membri del clan di gnoll Mantombroso nelle Montagne Crestarossa. Il magistrato locale li accetta come prova che gli gnoll invasori sono stati uccisi in difesa della cittadina.",al={"cosa sono i pendenti dei mantombroso","storia del pendente dei mantombroso","pendente di crestarossa"}},{q="Perché Bailiff Conacher vuole questi pendenti?",a="Bailiff Conacher raccoglie i pendenti come prova che Solomon's Law è stata applicata. Il clan Mantombroso collabora con il mago rinnegato Morganth per terrorizzare la popolazione locale, quindi la cittadina considera ogni gnoll affiliato un nemico passibile della pena capitale.",al={"perché raccogliere pendenti","taglia di bailiff conacher","missione di conacher"}},{q="Chi porta questi pendenti?",a="I comuni predoni, i bruti e gli gnoll rabbiosi portano i pendenti. Anche Rohh the Silent e Lieutenant Fangore li indossano nelle terre selvagge di Crestarossa.",al={"chi rilascia i pendenti","quali gnoll hanno i pendenti","fonte del pendente dei mantombroso"}},{q="Qual è il rapporto tra il clan Mantombroso e Morganth?",a="Morganth è un praticante rinnegato dell'Arcano nelle propaggini collinari orientali. Piega gli gnoll Mantombroso alla propria volontà con poteri sinistri, poi li invia come soldati di fanteria per terrorizzare Borgolago e attuare i suoi piani.",al={"gnoll e morganth","perché gli gnoll collaborano con morganth","mantombroso morganth"}}},fp="18,127,18.341.0,19.340.0,29.212.0,46.256.0,27.145.0,66.218.0"}
P.entries["item:shaman-voodoo-charm"] = {n="Talismano Sciamanico Vudù",s="Nell'Eremo di Ban'ethil, gli sciamani Gnarlpine brandiscono il Talismano Sciamanico Vudù. La sua magia può separare lo spirito di un druido dormiente dal corpo.",h="Nell'Eremo di Ban'ethil, gli sciamani Gnarlpine brandiscono il Talismano Sciamanico Vudù.",kw={"eremo di ban'ethil","sogno di smeraldo","furbolg","pino nodoso","oben malartiglio","talismano sciamanico vudù","druido addormentato","teldrassil"},ang={["class:Druid"]="Come druido, vedi nel talismano un'orribile perversione del sonno sacro. La sua magia oscura intrappola il sognatore nel Sogno di Smeraldo e trasforma il corpo in una marionetta.",["race:NightElf"]="Come elfo della notte, sai che i talismani nell'Eremo di Ban'ethil rivelano quanto profondamente gli Gnarlpine abbiano profanato uno dei più sacri luoghi di riposo collettivo dei kaldorei."},sec={{t="Una magia perversa",b="A Teldrassil, la tribù Gnarlpine è caduta nella follia e nella corruzione. Nell'Eremo di Ban'ethil, i suoi sciamani brandiscono una magia che va oltre la comune stregoneria delle terre selvagge. I loro talismani strappano la coscienza di un druido dormiente dal regno mortale e la intrappolano nel Sogno di Smeraldo. I furbolg animano poi il corpo vuoto. I protettori elfi della notte diventano guardiani privi di senno che uccidono chiunque entri nei tumuli."},{t="Spezzare la maledizione",b="Oben Malartiglio cadde vittima del rituale. Il suo spirito rimane intrappolato nel Sogno di Smeraldo, mentre il suo corpo animato terrorizza le profondità dei tumuli. Protendendosi oltre il velo, Oben chiese agli avventurieri di uccidere gli sciamani Gnarlpine e di riportargli uno dei loro talismani. Sperava di studiarne il vile incantamento, comprendere l'arte contorta dei furbolg e trovare un modo per liberare la propria carne rubata."}},faq={{q="A cosa serve il Talismano Sciamanico Vudù?",a="Gli sciamani Gnarlpine usano il talismano per separare lo spirito di un druido dormiente dal corpo e intrappolarlo nel Sogno di Smeraldo. La sua magia anima la carne vuota perché attacchi gli intrusi.",al={"scopo del talismano vudù","cosa fa il talismano","uso del talismano sciamanico"}},{q="Chi trasporta questi talismani?",a="Gli sciamani Gnarlpine portano con sé questi talismani nelle profondità dell'Eremo di Ban'ethil, a Teldrassil.",al={"chi rilascia il talismano","dove trovare il talismano sciamanico vudù","talismano sciamano pino nodoso"}},{q="Perché Oben Malartiglio ne ha bisogno?",a="Oben Malartiglio è intrappolato nel Sogno di Smeraldo mentre il suo corpo animato si scatena senza controllo. Deve studiare l'aura nefasta e la magia del talismano per trovare un modo di spezzare l'incantamento dei furbolg.",al={"perché oben lo vuole","talismano di oben malartiglio","oggetto del druido addormentato"}},{q="Perché i furbolg possiedono la magia vudù?",a="La corruzione ha spinto gli sciamani Gnarlpine di Teldrassil a praticare la magia oscura. I loro talismani emanano un'aura nefasta e innaturale, estranea alla tradizionale venerazione dei furbolg per gli spiriti della natura e gli elementi.",al={"perché i furbolg usano il vudù","storia del vudù dei furbolg"}}},fx={["6bf5e1a6"]={q="Cos'è il Talismano Sciamanico Vudù?",a="È un talismano incantato dei furbolg brandito dagli sciamani Gnarlpine corrotti all'interno dell'Eremo di Ban'ethil. Emanando una vile aura magica, il talismano imbriglia oscuri rituali capaci di separare lo spirito di un druido Elfo della Notte addormentato dalla sua forma fisica, lasciando lo spirito indifeso mentre i furbolg animano e controllano il corpo dormiente.",al={"cos'è il talismano sciamanico vudù","storia talismano vudù","cosa sono questi talismani"}}},fp="19,134,17.393.0,20.378.1,41.170.0,25.89.0,32.180.0,34.204.0"}
P.entries["item:shard-of-water"] = {n="Scheggia d'Acqua",s="Lungo la costa delle Savane, Islen Scruta Lagune riceve la Scheggia d'Acqua da uno sciamano che ha affrontato la corruzione.",h="Lungo la costa delle Savane, Islen Scruta Lagune riceve la Scheggia d'Acqua da uno sciamano che ha affrontato...",kw={"savane","call of water","islen scruta lagune","scheggia d'acqua","selva pinargento","totem dell'acqua"},ang={["class:Shaman"]="Come sciamano, ottenere la scheggia completa la tua sintonia con gli spiriti dell'acqua e il lungo viaggio per ottenere il tuo Totem dell'Acqua."},sec={{t="Simbolo di Purezza Elementale",b="Per dominare l'acqua, uno sciamano deve comprendere l'equilibrio, la vita e la preservazione. Durante Call of Water, raggiungi sorgenti corrotte, attraversando il mare fino alla Selva Pinargento contaminata. Lì purifichi le acque contaminate e ricevi la Scheggia d'Acqua. Poi riporti il pegno di cristallo a Islen Scruta Lagune sulla riva rocciosa delle Savane. Dimostra il tuo valore e fornisce la chiave finale per forgiare un Totem dell'Acqua."}},faq={{q="A cosa serve la Scheggia d'Acqua?",a="Porti la scheggia a Islen Scruta Lagune sulla riva orientale delle Savane come testimonianza della tua prova. Consegnala per completare la tua comunione con l'acqua e ottenere un Totem dell'Acqua.",al={"scopo scheggia d'acqua","a cosa serve la scheggia d'acqua","perché ho la scheggia d'acqua"}},{q="Chi richiede questo oggetto?",a="Islen Scruta Lagune chiede la scheggia come conferma che hai purificato l'acqua contaminata. È una sciamana che vive in una capanna a sud di Porto Paranco, lungo la Costa dei Mercanti.",al={"chi vuole la scheggia d'acqua","dove consegnare la scheggia d'acqua","scheggia islen scruta lagune"}},{q="Perché la prova è stata ambientata fino a Selva Pinargento?",a="L'acqua rappresenta la guarigione e la preservazione, mentre la corruzione arresta la vita. Le acque contaminate di Silverpine mettono alla prova la tua capacità di ripristinare l'armonia elementale in mezzo a un profondo degrado.",al={"missione acqua selva pinargento","perché selva pinargento","sciamano selva pinargento"}}},fx={aaf07767={q="Cos'è la Scheggia d'Acqua?",a="La Scheggia d'Acqua è un frammento elementale sacro concesso agli sciamani che intraprendono le prove dell'acqua. Serve come prova tangibile che hai eseguito il rituale per purificare le acque corrotte e comprendere la vera natura dell'acqua come fonte e protettrice della vita.",al={"cos'è la scheggia d'acqua","oggetto scheggia d'acqua","cos'è questa scheggia"}},["47314211"]={q="Da dove proviene la Scheggia d'Acqua e chi l'ha creata?",a="Ricevi la scheggia al termine del tuo viaggio spirituale nella Selva Pinargento, donata dopo aver completato il rituale per purificare le acque corrotte della regione. Incarna il potere elementale dell'acqua pura risvegliato attraverso quel rito.",al={"dove si ottiene la scheggia d'acqua","chi dà la scheggia d'acqua","origine della scheggia d'acqua"}}},fp="14,108,25.403.0,36.165.0,23.141.0,48.163.0"}
P.entries["item:shaw-s-report"] = {n="Rapporto di Shaw",s="Nelle Marche Occidentali, il Rapporto di Shaw porta a Gryan Stoutmantle informazioni raccolte dal SI:7. Scritto dal Maestro Mathias Shaw, parla della Stonemasons Guild, di Edwin VanCleef e del loro rancore verso la corona dopo la ricostruzione di Roccavento.",h="Nelle Marche Occidentali, il Rapporto di Shaw porta a Gryan Stoutmantle informazioni raccolte dal SI:7.",kw={"defias","edwin vancleef","gryan stoutmantle","mathias shaw","rapporto di shaw","si:7","stonemasons guild","marche occidentali"},ang={["class:Rogue"]="Il Rapporto di Shaw mostra fin dove arriva l'influenza del Maestro Mathias Shaw. È a capo del SI:7, la rete di spionaggio di Roccavento.",["faction:Alliance"]="Il rapporto mette a nudo il marciume interno di Roccavento. Un debito mai saldato agli architetti del regno ha contribuito a scatenare un'insurrezione che minaccia le terre coltivate del reame."},sec={{t="Informazioni sulla Stonemasons Guild",b="Il Rapporto di Shaw giunge a Guardiacolle dal quartier generale segreto del SI:7 a Roccavento. Fornisce alla People's Militia il primo resoconto chiaro su chi guida i banditi che devastano le Marche Occidentali. Edwin VanCleef era un tempo a capo della Stonemasons Guild, i cui muratori ricostruirono Roccavento dopo la sua distruzione nella Prima Guerra.\n\nLa corona e la nobiltà si rifiutarono di pagarli equamente, e il risentimento mise radici. Le informazioni di Shaw collegano gli artigiani sfollati alla rivolta che ora si sta impadronendo dei territori periferici del regno."}},faq={{q="Cos'è il Rapporto di Shaw?",a="Il Rapporto di Shaw è un dossier sigillato di informazioni riservate che il Maestro Mathias Shaw ha preparato per Gryan Stoutmantle. Shaw dirige il SI:7, l'agenzia segreta di Roccavento, e il rapporto contiene le informazioni della corona sulla Stonemasons Guild e sul passato di Edwin VanCleef.",al={"rapporto di shaw","cosa scrive shaw","contenuto del rapporto di shaw"}},{q="Cosa rivela il rapporto su Edwin VanCleef?",a="Il rapporto indica Edwin VanCleef come l'ex capo della Stonemasons Guild. Supervisionò la ricostruzione di Roccavento dopo la Prima Guerra, poi lui e i suoi artigiani si ribellarono quando i governanti del regno negarono loro il giusto compenso.",al={"vancleef nel rapporto","cosa dice su vancleef"}},{q="Perché Gryan Stoutmantle ha bisogno di questo rapporto?",a="Gryan Stoutmantle ha bisogno del rapporto perché guida la People's Militia contro le incursioni coordinate dei banditi nelle Marche Occidentali. Senza truppe regolari del regno ad aiutarlo, si affida alle informazioni di Mathias Shaw per scoprire chi dirige i fuorilegge e cosa li spinge ad agire.",al={"perché inviare il rapporto a gryan","perché stoutmantle ha bisogno del rapporto"}},{q="Come reagisce Stoutmantle al rapporto?",a="Il rapporto lascia Gryan Stoutmantle profondamente turbato. Ricorda Edwin VanCleef come un artigiano operoso e abile e fatica a credere, senza ulteriori prove, che un costruttore tanto rispettato sia diventato un malfattore.",al={"reazione di gryan","reazione di stoutmantle"}}},fx={c86c6e50={q="Da dove proviene il Rapporto di Shaw e chi lo ha scritto?",a="Il rapporto è stato redatto dal Maestro Mathias Shaw, il capo del servizio di intelligence di Roccavento, l'SI:7. Lavorando dal suo quartier generale nella Città Vecchia, Shaw ha compilato le informazioni raccolte dall'SI:7 riguardanti la storia della Gilda dei Muratori e Edwin VanCleef per rimandarle a Gryan Stoutmantle a Guardiacolle.",al={"chi ha scritto il rapporto di shaw","chi ha creato il rapporto di shaw","da dove viene il rapporto di shaw"}}},fp="13,221,31.491.1,22.250.0,49.224.0,44.254.0,41.211.0"}
P.entries["item:shimmering-frond"] = {n="Fronda Scintillante",s="Nella Radura dell'Oracolo, una pianta proveniente da oltre il Grande Mare emana un'aura vorticosa e scintillante. Le sue fronde appartengono a una specie originaria della Palude del Dolore.",h="Nella Radura dell'Oracolo, una pianta proveniente da oltre il Grande Mare emana un'aura vorticosa e...",kw={"botanica","denalan","lago al'ameth","radura dell'oracolo","fronda scintillante","pianta frondosa bizzarra","palude del dolore","teldrassil"},ang={["class:Druid"]="Come druido, potresti trovare una curiosa anomalia una pianta palustre che prospera sui rami di Teldrassil, sorti da poco.",["profession:Herbalism"]="Come erborista, puoi apprezzare la tenacia che ha permesso a una pianta della Palude del Dolore di attraversare l'oceano e prosperare in terra straniera."},sec={{t="Un esemplare da lontano",b="Vicino alla Radura dell'Oracolo, una pianta radiosa cresce tra gli alberi. La sua aura pulsa e le sue fronde scintillano nella luce del bosco. Denalan si prende cura delle fioriere accanto al Lago Al'ameth. Riconosce nelle foglie una specie originaria della Palude del Dolore, nei Regni Orientali. Come i semi di quella lontana palude abbiano attraversato il Grande Mare e attecchito su Teldrassil rimane un mistero. Denalan coltiva alcuni esemplari nel proprio terreno per studiarli."}},faq={{q="Da dove proviene la Fronda Scintillante?",a="Una strana pianta nella Radura dell'Oracolo, su Teldrassil, produce la Fronda Scintillante. Le sue foglie scintillano nella luce della foresta, emanando un bagliore vorticoso e pulsante.",al={"dove posso ottenere la fronda scintillante","posizione fronda scintillante","pianta frondosa bizzarra"}},{q="Chi è interessato alla Fronda Scintillante?",a="Denalan, un naturalista Elfo della Notte che si trova accanto al Lago Al'ameth, vuole studiare la fronda. Studia le strane piante che attecchiscono in tutta Teldrassil.",al={"chi vuole la fronda scintillante","a chi dare la fronda scintillante","denalan fronda scintillante"}},{q="Cosa rende questa pianta così insolita su Teldrassil?",a="La pianta proviene dalla Palude del Dolore, nei Regni Orientali, molto lontano, oltre il Grande Mare. La sua presenza su Teldrassil è inattesa, poiché non è originaria né di Kalimdor né dell'Albero del Mondo.",al={"perché la fronda scintillante è speciale","origine della pianta","pianta della palude del dolore"}},{q="Cosa succede dopo aver consegnato la fronda a Denalan?",a="Denalan pianta l'esemplare nelle sue fioriere accanto al Lago Al'ameth. Ne studia la rapida crescita e le proprietà esotiche.",al={"cosa ne fa denalan","storia delle fronde germogliate"}}},fx={["7be1ca60"]={q="Cos'è la Fronda Scintillante?",a="È una foglia presa da un'insolita flora ricoperta di vegetazione nota come Strange Fronded Plant trovata nella Radura dell'Oracolo. La fronda brilla costantemente sotto la volta della foresta, irradiando un'aura contorta e pulsante non comune ai rami di Teldrassil.",al={"cos'è la fronda scintillante","oggetto fronda scintillante","cos'è questa fronda"}}},fp="16,152,20.421.0,42.151.0,42.139.0,47.183.0,47.116.0"}
P.entries["item:shimmerweed"] = {n="Erbaluce",s="Su Cresta Brillante, i troll Frostmane raccolgono l'erbaluce per i loro rituali. Rejold Maltorzo di Borgo Luppolo vuole provarne il sapore aspro nella sua birra scura.",h="Su Cresta Brillante, i troll Frostmane raccolgono l'erbaluce per i loro rituali.",kw={"borgo luppolo","dun morogh","frostmane","stout perfetta","rejold maltorzo","cresta brillante","shimmerweed"},ang={["profession:Herbalism"]="Come erborista, puoi vedere come le piante regionali trovino impiego nelle tradizioni birrarie locali e nell'alchimia rituale.",["race:Dwarf"]="Come nano, puoi vedere come l'ingegno trasformi una strana pianta di una rupe vicina in un esperimento birrario."},sec={{t="Una coltura dei troll",b="L'erbaluce cresce su rupi ghiacciate molto al di sopra dei bassopiani di Dun Morogh, coltivata dai troll Frostmane. Raccolgono la pianta e la conservano in cesti intrecciati sparsi nei loro accampamenti. Lì alimenta i loro rituali sacri. Al di fuori della società dei troll, pochi montanari prestano attenzione all'erba, anche se alcuni forestieri ingegnosi hanno iniziato a interessarsene."},{t="Un ingrediente segreto",b="A Borgo Luppolo, il mastro birraio Rejold Maltorzo sospetta che l'erbaluce sia il tassello mancante nel suo tentativo di produrre la Birra Scura Nanica definitiva. Ha individuato il sapore pungente e inconfondibile dell'erba e vuole provarla nei suoi tini di fermentazione. Così Rejold ingaggia viaggiatori perché si intrufolino negli accampamenti dei Frostmane, evitino i troll ostili e ne riportino intere staia."}},faq={{q="Dove cresce la shimmerweed?",a="L'erbaluce cresce su Cresta Brillante, un'altura ghiacciata a nordovest di Borgo Luppolo, a Dun Morogh. I troll Frostmane la coltivano e conservano il raccolto in cesti sparsi nei loro accampamenti.",al={"posizione di shimmerweed","dove trovare shimmerweed","pianta di cresta brillante"}},{q="Per cosa usano la shimmerweed i troll Frostmane?",a="I troll Frostmane usano l'erbaluce nei loro misteriosi riti e cerimonie tribali. I forestieri non ne conoscono i dettagli precisi, ma l'erba trova posto nelle loro pratiche culturali e spirituali su Cresta Brillante.",al={"uso di shimmerweed dei troll","perché i troll vogliono shimmerweed"}},{q="Perché Rejold Maltorzo vuole la shimmerweed?",a="Rejold Maltorzo vuole l'erbaluce per il suo tentativo di produrre la Birra Scura Nanica perfetta a Borgo Luppolo. Ne ha individuato il gusto unico e spera che nuove staia diano alla sua miscela sperimentale il carattere deciso necessario alla ricetta.",al={"missione di rejold maltorzo","chi vuole shimmerweed","perché brassare con shimmerweed"}},{q="La shimmerweed cresce da qualche parte al di fuori di Dun Morogh?",a="L'erbaluce è stata raccolta anche in terre aride come Durotar, dove veggenti come Drek'Thar la apprezzano per potenti preparati erboristici e infusi medicinali. La pianta cresce anche oltre le vette ghiacciate di Khaz Modan.",al={"shimmerweed durotar","shimmerweed fuori da dun morogh"}}},fx={["1978b4f9"]={q="Cos'è lo Shimmerweed?",a="Lo Shimmerweed è una pianta distintiva coltivata in alto sulle vette innevate di Dun Morogh dai troll Mantogelido, in particolare attorno a Cresta Brillante. Rilevante per il suo sapore e le sue proprietà insolite, l'erba viene raccolta in cesti dai troll e gioca un ruolo nei rituali tribali locali, sebbene ambiziosi birrai nanici abbiano recentemente mostrato interesse a testare le sue potenti qualità in birre sperimentali.",al={"cos'è lo shimmerweed","pianta shimmerweed","informazioni su shimmerweed"}},d2fd1cd1={q="Da dove proviene lo Shimmerweed e chi lo coltiva?",a="Lo Shimmerweed viene coltivato naturalmente dai troll Mantogelido a Dun Morogh, che curano e raccolgono la pianta in cesti su Cresta Brillante. Mentre i Mantogelido ne mantengono le coltivazioni per i loro rituali, varietà selvatiche della potente erba sono note per crescere anche in terre lontane come Durotar, dove erboristi e sciamani delle terre selvagge la apprezzano per la preparazione di pozioni.",al={"da dove viene lo shimmerweed","chi coltiva lo shimmerweed","origine shimmerweed"}}},fp="11,155,15.319.0,19.352.0,28.175.0,49.209.0,44.230.0,50.210.0"}
P.entries["item:shindrell-s-note"] = {n="Messaggio di Shindrell",s="Ad Astranaar, Shindrell Fuocolesto invia notizie di corruzione nei pressi dell'insediamento e lungo la costa di Valtetra. Il suo rapporto attraversa la foresta verso est per raggiungere Kayneth Stillwind.",h="Ad Astranaar, Shindrell Fuocolesto invia notizie di corruzione nei pressi dell'insediamento e lungo la costa...",kw={"valtetra","astranaar","cantaselva","kayneth stillwind","boschi del canto notturno","shindrell fuocolesto","messaggio di shindrell"},ang={["class:Druid"]="Le osservazioni di Shindrell aiutano Kayneth Stillwind e gli altri druidi a scoprire le radici del morbo innaturale che affligge Valtetra.",["race:NightElf"]="Le sentinelle che difendono gli insediamenti di Valtetra collaborano con i druidi Cenarion che studiano la malattia della foresta."},sec={{t="Una missiva attraverso i boschi",b="Sentinelle e druidi sorvegliano insieme i confini di Valtetra mentre i disordini si diffondono nella foresta. Da Astranaar, la Sentinella Shindrell Fuocolesto segnala preoccupanti anomalie lungo la costa occidentale e tra le chiome della foresta centrale.\n\nIl suo rapporto è indirizzato a Kayneth Stillwind, un druido presso il santuario di Cantaselva, nei Boschi del Canto Notturno a est. I corrieri portano le osservazioni dirette di Shindrell per aiutarlo a cercare tracce di corruzione nei boschi sacri."}},faq={{q="Che cos'è il Messaggio di Shindrell?",a="Il rapporto sul campo della Sentinella Shindrell Fuocolesto descrive anomalie e sospetta corruzione nei pressi di Astranaar e lungo la costa di Valtetra.",al={"cos'è questo messaggio","messaggio di shindrell","cosa dice il messaggio"}},{q="Chi dovrebbe ricevere il messaggio?",a="Il messaggio è indirizzato a Kayneth Stillwind, un druido Elfo della Notte a Cantaselva, nei Boschi del Canto Notturno nella parte orientale di Valtetra.",al={"a chi lo devo dare","dove va consegnato","per chi è il messaggio"}},{q="Perché è stato scritto il messaggio?",a="Kayneth Stillwind temeva che la corruzione stesse mettendo radici nelle foreste occidentali e chiese segnalazioni di eventi insoliti. Shindrell raccolse le proprie osservazioni per aiutarlo a valutare la minaccia.",al={"perché è stato scritto il messaggio","di quale corruzione parla shindrell","scopo del rapporto"}},{q="Dove risiede Shindrell Fuocolesto?",a="Shindrell Fuocolesto è una sentinella degli Elfi della Notte di stanza ad Astranaar, un insediamento nella parte centrale di Valtetra.",al={"dove si trova shindrell","posizione di shindrell fuocolesto","chi ha inviato questo"}}},fx={ed6c40b2={q="Da dove proviene il Messaggio di Shindrell e chi lo ha scritto?",a="Il messaggio è stato scritto dalla Sentinella Shindrell Fuocolesto ad Astranaar. Scritto come un rapporto ufficiale sul campo, descrive dettagliatamente gli eventi inquietanti che ha osservato lungo la costa di Valtetra e in tutti i boschi circostanti.",al={"chi ha scritto il messaggio di shindrell","chi ha creato il messaggio di shindrell","origine del messaggio di shindrell"}}},fp="16,162,26.450.0,25.139.0,33.121.0,25.183.0,38.102.0"}
P.entries["item:shipment-of-boots"] = {n="Spedizione di Stivali",s="Lungo la costa delle Savane, la Spedizione di Stivali si trova ancora in un accampamento dei Southsea a sud di Porto Paranco. Drizzlik ha inviato la cassa da Baia del Bottino per la rete commerciale di Sparachiodi, ma i pirati l'hanno sequestrata prima che raggiungesse il porto.",h="Lungo la costa delle Savane, la Spedizione di Stivali si trova ancora in un accampamento dei Southsea a sud...",kw={"baia del bottino","drizzlik","sparachiodi","porto paranco","spedizione di stivali","southsea freebooters","stolen booty"},ang={["class:Rogue"]="Come ladro, puoi muoverti furtivamente tra gli accampamenti dei Southsea lungo la costa. Le pattuglie dei pirati sono numerose, quindi un approccio silenzioso è il più sicuro per recuperare il carico rubato a Sparachiodi."},sec={{t="Un carico saccheggiato",b="Sparachiodi ha preso accordi con Drizzlik, un mercante di abbigliamento di Baia del Bottino, per inviare stivali a Porto Paranco. I Southsea Freebooters hanno teso un'imboscata alla nave mentre pattugliavano la Costa dei Mercanti. Hanno portato le casse negli accampamenti sulla spiaggia a sud del porto e sparso le merci rubate tra tende e baracche. La spedizione si trova ancora lì, lontano dai moli di Porto Paranco."}},faq={{q="Chi ha inviato questa spedizione di stivali?",a="Drizzlik, un mercante goblin di Baia del Bottino, ha inviato gli stivali dal porto meridionale.",al={"chi ha fatto gli stivali","da dove arrivano gli stivali","stivali di drizzlik"}},{q="Chi avrebbe dovuto ricevere gli stivali?",a="Sparachiodi ha ordinato gli stivali per Porto Paranco. È l'ingegnere capo e il sovrintendente del luogo, e la spedizione era destinata a sostenere i suoi lavoratori e i commerci locali.",al={"a chi appartengono gli stivali","spedizione di stivali di sparachiodi"}},{q="Come sono finiti gli stivali ai pirati?",a="I Southsea Freebooters hanno teso un'imboscata alla nave da carico lungo la costa delle Savane. L'hanno saccheggiata e hanno portato le casse nei loro accampamenti a sud di Porto Paranco.",al={"perché i pirati dei mari del sud hanno gli stivali","chi ha rubato gli stivali"}},{q="Dove si può trovare la spedizione?",a="La spedizione si trova tra le merci saccheggiate nell'accampamento dei pirati Southsea lungo la costa a sud di Porto Paranco.",al={"posizione degli stivali","dov'è la spedizione di stivali","trova la spedizione di stivali"}}},fx={["06b396e7"]={q="Cos'è la Spedizione di Stivali?",a="La Spedizione di Stivali è una cassa di calzature inviata attraverso il Grande Mare da Baia del Bottino a Porto Paranco. Spedita dal mercante goblin Drizzlik, era destinata direttamente a Sparachiodi prima che i Southsea Freebooters intercettassero la nave cargo che trasportava la sua merce.",al={"cos'è la spedizione di stivali","oggetto spedizione di stivali","cosa sono gli stivali"}}},fp="17,211,17.348.0,32.80.0,38.152.0,42.149.0,32.107.0"}
P.entries["item:shipment-of-iron"] = {n="Spedizione di Ferro",s="Una cassa di metallo grezzo conservata presso la fucina umana nei Campi di Colletorto. Funge da riserva vitale per la produzione bellica locale, rendendola un bersaglio prioritario per le forze dei Reietti che mirano a tagliare le linee di rifornimento che armano i cittadini di Colletorto.",h="Una cassa di metallo grezzo conservata presso la fucina umana nei Campi di Colletorto.",kw={"battle of hillsbrad","darthalia","campi di colletorto","spedizione di ferro","mulino di tarren","verringtan"},ang={["faction:Horde"]="Negare i rifornimenti a Colletorto paralizza la resistenza armata dei contadini prima che la campagna muova contro Riva del Sud.",["profession:Blacksmithing"]="La scorta rappresenta la linfa vitale della produzione bellica umana nella valle; senza lingotti di ferro grezzo, la forgia di Verringtan rimane del tutto inutile."},sec={{t="Alimentare la Resistenza",b="Nel conflitto in corso attraverso le Alture di Colletorto, i contadini umani hanno opposto una resistenza sorprendentemente tenace contro Mulino di Tarren. Gran parte di questa capacità combattiva proviene direttamente dalla fucina situata al margine sud-occidentale dei Campi di Colletorto, dove il Fabbro Verringtan e i suoi apprendisti lavorano giorno e notte producendo armi e armature a partire da pesanti spedizioni di ferro. Per spezzare la determinazione dei contadini, i comandanti dei Reietti ordinarono di spegnere la forgia, eliminare i suoi fabbri e requisire le scorte di metallo per lo sforzo bellico dell'Orda."}},faq={{q="Dove è custodita la spedizione di ferro?",a="La spedizione si trova direttamente all'interno dell'officina del fabbro, situata al margine sud-occidentale dei Campi di Colletorto, pesantemente sorvegliata dal Fabbro Verringtan e dai suoi apprendisti.",al={"posizione spedizione di ferro","dove si trova il ferro","posizione ferro colletorto"}},{q="Perché i Reietti vogliono questo ferro?",a="Impossessarsi del ferro interrompe la linea di rifornimento di armi destinata alla milizia umana locale. La Gran Esecutrice Darthalia intende inoltre reimpiegare le scorte di metallo per sostenere la macchina bellica dell'Orda, una volta che l'offensiva si sposterà per radere al suolo Riva del Sud.",al={"perché rubare il ferro","ferro mulino di tarren","scopo ferro battle of hillsbrad"}},{q="Chi stava usando originariamente questo ferro?",a="Il Fabbro Verringtan e i suoi quattro apprendisti fabbri utilizzavano il ferro per equipaggiare i cittadini e i braccianti, trasformando semplici contadini in una forza di difesa locale armata contro i non morti.",al={"chi possiede il ferro","ferro di verringtan","fabbri di colletorto"}},{q="Chi ordina il recupero della spedizione di ferro?",a="La Gran Esecutrice Darthalia, al comando delle operazioni dei Reietti da Mulino di Tarren, impartisce l'ordine diretto di uccidere i fabbri e reclamare il ferro durante la Battle of Hillsbrad.",al={"chi assegna la missione","missione del ferro di darthalia"}}},fx={["8a003d21"]={q="Cos'è la Spedizione di Ferro?",a="La Spedizione di Ferro è una scorta di metallo grezzo immagazzinata presso la bottega del fabbro umano nei Campi di Colletorto. Serve come materiale primario che il Fabbro Verringtan e i suoi apprendisti usano per forgiare armi e armature per la gente del posto di Colletorto che resiste ai Forsaken.",al={"cos'è la spedizione di ferro","spedizione di ferro","spedizione di ferro colletorto"}}},fp="16,240,22.546.0,35.179.0,37.231.0,35.193.0,46.173.0"}
P.entries["item:shipping-schedule"] = {n="Programma delle Spedizioni",s="Al Molo di Jerod, la Fratellanza dei Defias trasporta merci di contrabbando lungo i corsi d'acqua di Elwynn. Il suo capomolo custodisce un programma delle spedizioni tra Redridge e le Marche Occidentali, e il SI:7 vuole impadronirsene.",h="Al Molo di Jerod, la Fratellanza dei Defias trasporta merci di contrabbando lungo i corsi d'acqua di Elwynn.",kw={"defias","capomolo","foresta di elwynn","molo di jerod","mathias shaw","programma delle spedizioni","si:7","contrabbando"},ang={["class:Rogue"]="Come ladro, puoi mettere alla prova le capacità furtive e di borseggio richieste dal SI:7 agli aspiranti agenti sottraendo il programma dalle tasche del capomolo."},sec={{t="Contrabbando al Molo di Jerod",b="A sud di Borgodoro, il Molo di Jerod si trova sulla sponda del Fiume Nazferiti che costeggia Elwynn. La Fratellanza dei Defias se ne è impadronita per farne uno snodo del traffico fluviale. Da lì, i Defias trasportano merci di contrabbando tra Redridge e le Marche Occidentali lungo corsi d'acqua che sfuggono alle Guardie di Roccavento. Il loro capomolo tiene sempre con sé il Programma delle Spedizioni, annotando ogni carico."},{t="Nel mirino del SI:7",b="Il Maestro Mathias Shaw guida il SI:7, l'agenzia di spionaggio di Roccavento, e ha ordinato di rubare il programma. Può rivelare le linee di rifornimento dei Defias, e sottrarlo mette alla prova i nuovi agenti. Il furto deve avvenire nella casa del molo, prelevando il documento dalle tasche del capomolo. Se l'agente viene catturato, il SI:7 nega ogni legame. Nessuna traccia riconduce alla sua caserma a Roccavento."}},faq={{q="Cos'è il Programma delle Spedizioni?",a="Il Programma delle Spedizioni registra i carichi di contrabbando gestiti dal capomolo della Fratellanza dei Defias al Molo di Jerod. Tiene traccia delle merci trasportate tra Redridge e le Marche Occidentali attraverso le acque interne della Foresta di Elwynn.",al={"programma delle spedizioni defias","cos'è questo documento","programma del capomolo"}},{q="Chi vuole recuperare questo programma?",a="Il Maestro Mathias Shaw, capo del SI:7, vuole che il programma venga recuperato. Lo usa per seguire i traffici di contrabbando dei Defias e mettere alla prova sul campo i ladri promettenti.",al={"chi ha bisogno del programma","programma mathias shaw","chi prende il programma delle spedizioni"}},{q="Dove si trova il programma?",a="Il capomolo dei Defias porta con sé il programma nella casa del molo al Molo di Jerod. Il molo si trova sul Fiume Nazferiti, a sud di Borgodoro nella Foresta di Elwynn, e il documento deve essergli sottratto lì.",al={"posizione programma delle spedizioni","dov'è il capomolo","come ottenere il programma"}},{q="A cosa serve il Molo di Jerod?",a="La Fratellanza dei Defias si è impadronita del Molo di Jerod per farne un punto di transito per il contrabbando. L'accesso al fiume collega le loro operazioni a Redridge alle loro roccaforti nelle Marche Occidentali.",al={"molo di jerod defias","perché i defias hanno il molo di jerod","molo defias elwynn"}}},fx={["45ccd8c3"]={q="Da dove viene il Programma delle Spedizioni e chi l'ha redatto?",a="Il programma è custodito dal maestro di porto della Fratellanza dei Defias, di stanza al Molo di Jerod, a sud di Borgodoro. Descrive le operazioni fluviali del sindacato fuorilegge e tiene traccia del movimento di merci illecite e contrabbando tra le Montagne Crestarossa e le Marche Occidentali.",al={"chi ha scritto il programma delle spedizioni","origine del programma delle spedizioni","chi ha redatto il programma delle spedizioni dei defias"}}},fp="17,181,28.335.0,25.350.0,30.208.0,34.141.0,28.208.0,33.167.0"}
P.entries["item:sida-s-bag"] = {n="Sacca di Sida",s="Vicino al Sepolcro di Barbaferrea, la Sacca di Sida giace inghiottita da una melma. Sida è fuggita a Porto di Menethil dopo aver scagliato la sua sacca contro una delle melme durante la visita settimanale. Ora bisogna cercare i suoi averi dentro quelle creature acide.",h="Vicino al Sepolcro di Barbaferrea, la Sacca di Sida giace inghiottita da una melma.",kw={"dun modr","sepolcro di barbaferrea","porto di menethil","melma","sida","sacca di sida","paludi grigie"},ang={["faction:Alliance"]="I profughi e gli abitanti assediati di Porto di Menethil si affidano ai viaggiatori di passaggio per affrontare gli orrori predatori che avanzano dalle Paludi Grigie allagate."},sec={{t="Una difesa disperata",b="Ogni settimana, Sida visita il Sepolcro di Barbaferrea vicino a Dun Modr. Terribili melme gocciolanti le hanno teso un'imboscata e, in preda al panico, ha scagliato la sua sacca contro una di loro. La melma ha inghiottito la sacca. Questo ha dato a Sida il tempo di fuggire viva e tornare a Porto di Menethil, mentre i suoi averi restavano intrappolati in una melma sconosciuta."},{t="Recuperata dalla melma",b="Le melme attorno al Sepolcro di Barbaferrea vanno da cremisi a mostruose e si somigliano molto. Abbatti le melme della palude finché la Sacca di Sida non riemerge intatta. La fanghiglia acida ha impregnato la resistente sacca, ma il suo contenuto è rimasto intatto. Sida recupera i suoi averi, poi scarta l'involucro rovinato e ricoperto di melma e offre il contenitore ripulito a chi ha sfidato la palude per lei."}},faq={{q="Perché la sacca di Sida era dentro una melma?",a="Melme gocciolanti hanno attaccato Sida durante una visita al Sepolcro di Barbaferrea, e il panico ha preso il sopravvento. Ha scagliato la sua sacca contro una di loro per fuggire, e la melma l'ha inghiottita intera.",al={"come ha fatto la melma a prendere la sacca","perché la sacca è nella melma","come ha perso la sacca sida"}},{q="Quali melme contengono la Sacca di Sida?",a="Sida non sa distinguere le melme, quindi qualunque melma predatrice attorno al Sepolcro di Barbaferrea, nelle Paludi Grigie nordorientali, potrebbe aver inghiottito la sacca. Crimson Oozes, Black Oozes e Monstrous Oozes si aggirano tutte in quella zona.",al={"dove trovare la sacca di sida","chi rilascia la sacca di sida","quale melma ha la sacca"}},{q="Perché Sida visita il Sepolcro di Barbaferrea?",a="Ogni settimana, Sida parte da Porto di Menethil per visitare l'antica cripta nanica vicino a Dun Modr. Tiene per sé le ragioni personali di queste visite.",al={"collegamento sida barbaferrea","perché sepolcro di barbaferrea"}},{q="Cosa c'era dentro la sacca di Sida?",a="Sida rovescia a terra gli oggetti recuperati e li raccoglie senza mostrare di cosa si tratta. Dice soltanto che erano troppo importanti per lasciarli dissolvere dentro una melma.",al={"cosa tira fuori dalla sacca sida","contenuto della sacca"}}},fx={["113113dd"]={q="Che cos'è la Sacca di Sida?",a="La Sacca di Sida è una borsa personale appartenente a Sida, una residente di Porto di Menethil. Durante una delle sue visite abituali al Sepolcro di Barbaferrea nelle Paludi, è stata assalita da alcuni fanghi e ha lanciato il suo zaino contro uno di loro nel disperato tentativo di fuggire. La creatura l'ha inghiottito intero, intrappolandolo nel suo corpo gelatinoso.",al={"che cos'è la sacca di sida","sacca di sida","di chi è la sacca di sida"}},afbd2451={q="Perché Sida rivuole la sua sacca?",a="Sida ha un disperato bisogno del contenuto chiuso nella sua sacca smarrita, non della sacca in sé. Dopo averla estratta dai resti dei fanghi al Sepolcro di Barbaferrea e avergliela riportata a Porto di Menethil, rovescia subito a terra il contenuto viscido, lo raccoglie e ti consegna la borsa vuota, macchiata di melma.",al={"perché sida rivuole la sua sacca","perché la sacca di sida","perché qualcuno vuole la sacca di sida"}}},fp="10,224,18.300.0,24.369.0,34.160.0,29.204.0,37.154.0,27.179.0"}
P.entries["item:signed-recruitment-letter"] = {n="Lettera di Reclutamento Firmata",s="Dal Presidio Lungosguardo, Kargal Sfregiofondo invia a ovest una lettera firmata insieme alle reclute pronte per il servizio. Ordina loro di presentarsi a Sergra Darkthorn a Crocevia.",h="Dal Presidio Lungosguardo, Kargal Sfregiofondo invia a ovest una lettera firmata insieme alle reclute pronte...",kw={"coscrizione","crocevia","presidio lungosguardo","kargal sfregiofondo","sergra darkthorn","lettera di reclutamento firmata","le savane","thrall"},ang={["class:Shaman"]="Come sciamano, ti presenti a Sergra Darkthorn, una sciamana orchesca a cui Thrall ha affidato il compito di contribuire alla sicurezza delle Savane.",["faction:Horde"]="Come membro dell'Orda, porti questa lettera passando dal servizio iniziale a Durotar alle più ampie forze di frontiera dell'Orda."},sec={{t="Il trasferimento di un coscritto",b="Al Presidio Lungosguardo, Kargal Sfregiofondo prepara le reclute al servizio nelle Savane. Il presidio si trova a est del Fiume Furialunga, che i nuovi arrivati attraversano giungendo da Durotar. Quando un coscritto si dimostra pronto, Kargal timbra e firma una Lettera di Presentazione. Gli ordini indirizzano le reclute a ovest lungo la strada verso Crocevia, dove Sergra Darkthorn coordina i rifornimenti e la difesa delle aride pianure."},{t="Tensione agli avamposti",b="Gli ordini di Kargal esprimono il suo disprezzo per l'ufficiale che attende la recluta. Definisce Sergra Darkthorn una sciamana scontrosa che confonde i soldati con i suoi discorsi tortuosi. Kargal mette apertamente in dubbio l'alta considerazione che il Capoguerra Thrall ha di lei. Ciononostante, il dispaccio deve raggiungere Sergra prima che vengano assegnati altri incarichi a Crocevia."}},faq={{q="Qual è lo scopo della Lettera di Reclutamento Firmata?",a="La Lettera di Reclutamento Firmata ti trasferisce dal comando di Kargal Sfregiofondo al Presidio Lungosguardo al servizio nelle Savane. Dimostra a Sergra Darkthorn, a Crocevia, che Kargal ti ha giudicato pronto.",al={"a cosa serve questa lettera","uso lettera di reclutamento","lettera firmata savane"}},{q="Chi ha firmato la lettera?",a="Kargal Sfregiofondo firma la lettera. Il veterano orco sovrintende al Presidio Lungosguardo, sul confine tra Durotar e le Savane. Appone la firma dopo che una recluta vi ha completato i primi incarichi.",al={"chi ha scritto la lettera","lettera di kargal","chi l'ha firmata"}},{q="A chi consegno la lettera?",a="Consegni la lettera a Sergra Darkthorn, un'influente sciamana orchesca di stanza all'incrocio centrale di Crocevia.",al={"dove porto la lettera","a chi va la lettera","destinatario della lettera"}},{q="Perché Kargal parla male di Sergra Darkthorn?",a="Kargal definisce Sergra pungente e intrattabile, e pensa che perda tempo a parlare quando c'è del lavoro da fare. Il Capoguerra Thrall la tiene in grande considerazione, ma Kargal dubita delle sue capacità di comando.",al={"faida tra kargal e sergra","perché kargal odia sergra"}}},fx={ea3ee62a={q="Che cos'è la Lettera di Reclutamento Firmata?",a="È un documento ufficiale di coscrizione dell'Orda consegnato alle reclute che arrivano a The Barrens da Durotar. Redatto e approvato da Kargal Sfregiofondo al Presidio Lungosguardo, certifica formalmente che sei stato esaminato, arruolato e inviato ad aiutare l'insediamento di Crocevia.",al={"che cos'è la lettera di reclutamento firmata","lettera di reclutamento","che cos'è questa lettera"}},ea22ddb8={q="Perché Sergra Darkthorn vuole la Lettera di Reclutamento Firmata?",a="Sergra Darkthorn dirige le operazioni a Crocevia e conta sui rinforzi in arrivo per assicurare The Barrens all'Orda. La lettera conferma il tuo arruolamento sotto l'autorità di Kargal, dimostrando che sei pronto a ricevere ordini, a dimostrare il tuo valore e ad affrontare le urgenti minacce e i lavori che gravano sull'insediamento.",al={"perché sergra vuole la lettera","perché consegnare la lettera di reclutamento","chi ha bisogno della lettera di reclutamento"}}},fp="25,164,22.389.0,23.320.0,53.190.0,22.183.0,31.120.0,49.182.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="Uovo di Silitide",s="In tutto il Field of Giants, l'Uovo di Silitide giace sepolto sotto il terreno. I ricercatori dell'Orda raccolgono le uova per conoscere meglio lo sciame che si diffonde nelle Savane Meridionali.",h="In tutto il Field of Giants, l'Uovo di Silitide giace sepolto sotto il terreno.",kw={"crocevia","artiglio scavatore","egg hunt","field of giants","korran","tumuli","silitide","uovo di silitide","le savane"},ang={["faction:Horde"]="Per l'Orda, gli sciami di insetti intelligenti vicino al Crocevia minacciano le rotte commerciali e il territorio nel cuore di Kalimdor."},sec={{t="Uno Sciame Misterioso",b="I tumuli dei silitidi sorgono in tutto il Field of Giants, mentre strane creature simili a insetti smuovono la terra. Le loro uova giacciono sotto il terreno indurito, sorvegliate da silitidi territoriali. L'Orda sa poco di loro, ma gli esploratori al Crocevia hanno osservato segni di coordinazione e intelligenza superiori a quelli delle comuni bestie selvatiche. Le uova non ancora schiuse potrebbero aiutare gli studiosi di Orgrimmar a conoscere il ciclo vitale e la natura dei silitidi."},{t="Scavo e Pericolo",b="Per estrarre le Uova di Silitide dai tumuli serve un artiglio scavatore adattato allo scopo. Le creature difendono ferocemente i loro vivai sotterranei e assalgono in sciame chiunque minacci i loro piccoli non ancora nati. Korran, un ricercatore troll, ha bisogno di esemplari intatti da studiare prima che lo sciame si diffonda ulteriormente su Kalimdor."}},faq={{q="Cosa sono le Uova di Silitide?",a="Le Uova di Silitide sono covate non ancora schiuse, sepolte nei tumuli di terra delle Savane Meridionali, soprattutto attorno al Field of Giants.",al={"uovo di silitide","cos'è un uovo di silitide","tumuli di silitidi"}},{q="Chi richiede la raccolta di queste uova?",a="Korran, un ricercatore troll al Crocevia, raccoglie le uova per i suoi superiori a Orgrimmar. Vogliono studiare la biologia e il comportamento dei silitidi.",al={"chi ha bisogno delle uova","missione di korran","assegnatore della missione egg hunt"}},{q="Perché i silitidi vengono studiati?",a="L'Orda sa poco dei silitidi. Korran ha osservato segni di intelligenza e coordinazione superiori a quelli dei comuni animali selvatici. La loro comparsa nelle Savane preoccupa i capi dell'Orda.",al={"perché studiare i silitidi","minaccia dei silitidi","i silitidi sono intelligenti"}},{q="Come vengono raccolte le uova?",a="Un artiglio scavatore adattato allo scopo permette di estrarre le uova dai tumuli dei silitidi. Lo sciame aggressivo difende i propri nidi.",al={"come ottenere le uova","artiglio scavatore","raccogliere uova di silitide"}}},fx={["04f05afd"]={q="Da dove vengono le uova di silitide?",a="Queste uova vengono deposte dalle strane silitidi simili a insetti, nelle profondità dei loro tumuli di terra nelle Savane Meridionali, in particolare nel Field of Giants. Le silitidi seppelliscono e proteggono con cura le covate all'interno di questi imponenti tumuli, attaccando ferocemente chiunque osi disturbare i nidi.",al={"origine dell'uovo di silitide","da dove vengono le uova di silitide","chi ha deposto le uova di silitide"}}},fp="26,168,18.405.0,21.294.0,23.125.0,31.142.0,35.191.0,26.96.0"}
P.entries["item:silixiz-s-tower-key"] = {n="Silixiz's Tower Key",s="Alla torre della S.P.R. & Co. vicino alla Palude Fangosa, la Silixiz's Tower Key è nella tasca del Caposghigno Silixiz. Un agente della Shattered Hand deve rubarla senza farsi vedere nell'ambito di un incarico di sabotaggio sotto copertura.",h="Alla torre della S.P.R.",kw={"savane","caposghigno silixiz","the shattered hand","shenthul","silixiz","palude fangosa","chiave della torre","s.p.r. & co."},ang={["class:Rogue"]="Come ladro dell'Orda, sottrai la Silixiz's Tower Key come prova per entrare nella Shattered Hand. La prova richiede furtività e abilità nel borseggio.",["faction:Horde"]="Come membro dell'Orda, porti con te un trofeo della lotta contro lo sfruttamento e gli esperimenti chimici della S.P.R. & Co. nelle Savane settentrionali."},sec={{t="Una Prova di Scaltrezza",b="A nord della Palude Fangosa, la S.P.R. & Co. sorveglia attentamente la propria torre. Il Gran Caposghigno Puzik Gallywix supervisiona la torre di vedetta isolata, mentre mercenari goblin pattugliano il complesso. Il Caposghigno Silixiz porta con sé la chiave della torre all'esterno.\n\nUn agente della Shattered Hand proveniente da Orgrimmar deve rubare la chiave e conservarla. La forza non basta. L'agente deve entrare senza farsi vedere e borseggiare Silixiz, dimostrando le proprie doti furtive prima di salire ai livelli superiori tossici della torre."}},faq={{q="Dove trovo il Caposghigno Silixiz?",a="Il Caposghigno Silixiz si trova all'esterno della torre della S.P.R. & Co., direttamente a nord della Palude Fangosa, nelle Savane nordorientali.",al={"posizione di silixiz","dove si trova il caposghigno silixiz","trovare silixiz"}},{q="Posso ottenere la chiave uccidendo il Caposghigno Silixiz?",a="No. La chiave non può essere presa dal cadavere di Silixiz. Un agente deve borseggiarlo mentre è ancora vivo.",al={"bottino chiave di silixiz","posso uccidere silixiz","depredare la chiave di silixiz"}},{q="Chi richiede questa chiave?",a="I contatti della Shattered Hand richiedono che la chiave venga consegnata a Shenthul, l'istruttore dei ladri di Orgrimmar.",al={"chi vuole la chiave","consegnare la chiave di silixiz","missione silixiz's tower key"}},{q="A cosa serve la chiave?",a="La chiave dimostra che un agente è entrato nella torre della S.P.R. & Co. vicino alla Palude Fangosa. Va consegnata alla Shattered Hand insieme alla testa del Gran Caposghigno Puzik Gallywix e alla Cassa di Mistura di Zanzil Alterata.",al={"cosa apre la chiave di silixiz","scopo della chiave di silixiz","usare la chiave della torre"}}},fx={["163c94d7"]={q="Che cos'è Silixiz's Tower Key?",a="È una chiave custodita dal caposquadra Silixiz, fuori dalla torre della S.P.R. & Co. a nord della Palude Fangosa. All'agente è stato ordinato di rubarla e tenerla con sé, nel caso il contatto della Shattered Hand ne avesse bisogno in seguito.",al={"che cos'è silixiz's tower key","chiave di silixiz","chiave della torre della s.p.r. & co."}}},fp="19,195,18.451.0,32.115.0,48.103.0,22.94.0,25.198.1"}
P.entries["item:silver-dawning-s-lockbox"] = {n="Scrigno dell'Alba d'Argento",s="Al largo di Rivafosca, lo Scrigno dell'Alba d'Argento giace in un relitto a nord di Auberdine. I murloc costieri hanno affondato la nave, e lo scrigno contiene gli effetti personali del capitano e il diario di bordo.",h="Al largo di Rivafosca, lo Scrigno dell'Alba d'Argento giace in un relitto a nord di Auberdine.",kw={"auberdine","rivafosca","gorbold mandacciaio","scrigno","murloc","naufragio","alba d'argento"},ang={["race:Dwarf"]="Gorbold Mandacciaio si assume il compito di onorare i capitani caduti e restituire i loro averi ai compagni sopravvissuti.",["race:NightElf"]="Lo scrigno contiene gli ultimi scritti e gli averi di un capitano kaldorei morto difendendo la propria nave al largo delle coste settentrionali di Kalimdor."},sec={{t="Resti sommersi",b="La Silver Dawning navigava verso Auberdine quando i murloc costieri attaccarono. Fecero colare a picco la nave a nord del porto, e il capitano morì nell'assalto. Lo scafo allagato custodisce ancora lo scrigno del capitano, con il diario di bordo e i suoi effetti personali. Recuperarli potrebbe portare un po' di pace ai membri dell'equipaggio sopravvissuti che si trovano a terra."}},faq={{q="Dove si trova lo Scrigno dell'Alba d'Argento?",a="Lo scrigno si trova nel relitto sommerso della Silver Dawning, sul fondo del mare a nord di Auberdine, al largo di Rivafosca.",al={"posizione dello scrigno","dove si trova lo scrigno dell'alba d'argento","relitto dell'alba d'argento"}},{q="Cosa è successo alla Silver Dawning?",a="I murloc costieri attaccarono la Silver Dawning mentre navigava verso Auberdine. Sopraffecero la nave, che sprofondò tra le onde insieme al suo capitano.",al={"perché è affondata l'alba d'argento","storia dell'alba d'argento","come è avvenuto il naufragio"}},{q="Cosa c'è dentro lo scrigno?",a="Lo scrigno contiene gli effetti personali e il diario di bordo del capitano della Silver Dawning.",al={"contenuto dell'alba d'argento","cosa c'è nella scatola"}},{q="Chi sta cercando lo scrigno?",a="Gorbold Mandacciaio, un nano di stanza ad Auberdine, chiede a chi sa nuotare di recuperare lo scrigno dai relitti affinché l'equipaggio superstite possa onorare la memoria del capitano caduto.",al={"chi cerca lo scrigno","chi assegna la missione","consegnare lo scrigno"}}},fx={["9cc39920"]={q="Che cos'è lo Scrigno dell'Alba d'Argento?",a="È il forziere personale del defunto capitano dell'Alba d'Argento. Quando la nave fu assalita e affondata dai murloc al largo della costa settentrionale di Rivafosca, lo scrigno colò a picco insieme al relitto. Contiene il diario di bordo del capitano e gli effetti personali rimasti, sul fondo del mare, tra le creature in agguato.",al={"che cos'è lo scrigno dell'alba d'argento","storia dello scrigno dell'alba d'argento","scrigno del capitano dell'alba d'argento"}}},fp="24,179,15.344.0,46.130.0,36.149.0,27.76.0,27.167.0"}
P.entries["item:silvery-spinnerets"] = {n="Filatura Argentea",s="Vicino al Lago di Buonpozzo, la Filatura Argentea è ricercata per un rito in onore di Lady Sathrah. Un tempo le sue tele argentate raccoglievano rugiada serale curativa per la Sisterhood of Elune a Darnassus.",h="Vicino al Lago di Buonpozzo, la Filatura Argentea è ricercata per un rito in onore di Lady Sathrah.",kw={"lady sathrah","sacerdotessa a'moora","sacrificio di sathrah","filatura argentea","tears of the moon","temple of the moon","lago di buonpozzo"},ang={["class:Priest"]="Per i servitori di Elune, recuperare le filiere è un sacro rito funebre. Il rito chiede a Mother Moon di redimere una creatura, anziché trattarne la morte come una semplice opera di disinfestazione.",["race:NightElf"]="La tragica fine di Lady Sathrah ricorda ai Kaldorei che persino le creature amate da Elune possono soccombere al male che affligge Teldrassil."},sec={{t="Tessitura sacra e corruzione",b="Al chiaro di luna, vicino al Lago di Buonpozzo, Lady Sathrah tesseva tele scintillanti. La sua seta argentata raccoglieva la foschia serale in rugiada curativa, molto apprezzata dalla Sisterhood of Elune a Darnassus.\n\nPoi la corruzione la raggiunse a Teldrassil e la fece sprofondare in una violenta follia. Sathrah minacciava la sua prole e la foresta circostante. La Sacerdotessa A'moora chiede ai viaggiatori di porre fine alle sue sofferenze e recuperare le sue filiere, mostrando pietà per una creatura un tempo venerata tra i grandi rami."},{t="Un sacrificio per la rinascita",b="La Sisterhood offre le filiere recuperate a Elune presso la fontana centrale all'interno del Temple of the Moon. Nel rito chiamato Sacrificio di Sathrah, le sacerdotesse pregano affinché la Dea della Luna accolga lo spirito della creatura. Le chiedono di purificarla dalla follia che si è impadronita del corpo mortale di Sathrah e di concederle pace nella rinascita."}},faq={{q="Dove si ottiene la Filatura Argentea?",a="Recupera la Filatura Argentea da Lady Sathrah, un grande ragno vicino al Lago di Buonpozzo, lungo i confini settentrionali di Teldrassil.",al={"dove trovare filatura argentea","bottino filatura argentea","chi rilascia filatura argentea"}},{q="Perché la Sacerdotessa A'moora vuole le filiere?",a="La Sacerdotessa A'moora cerca le filiere per un sacrificio sacro a Elune. Il rito onora la purezza perduta di Lady Sathrah e chiede alla dea di purificarne lo spirito e concederle pace e rinascita.",al={"perché amoora vuole le filiere","scopo di tears of the moon"}},{q="Perché le tele di Lady Sathrah erano speciali?",a="Lady Sathrah tesseva una luminosa seta argentata che catturava la foschia serale al chiaro di luna. La rugiada racchiudeva una potente magia rigenerante, e la Sisterhood of Elune la apprezzava e la custodiva nel Temple of the Moon per curare.",al={"tele di lady sathrah","cosa faceva lady sathrah"}},{q="Perché Lady Sathrah è stata uccisa se era sacra?",a="La corruzione fece sprofondare Lady Sathrah in una follia incurabile, come accadde ad altri animali di Teldrassil. La sua aggressività metteva in pericolo la foresta e minacciava la sua prole, così le sacerdotesse considerarono la sua uccisione un doloroso atto di pietà.",al={"perché uccidere lady sathrah","perché sathrah è impazzita"}}},fx={["6e94bdc8"]={q="Che cosa sono le Filature Argentee?",a="Le Filature Argentee sono gli organi produttori di seta prelevati dal ragno sacro Lady Sathrah, nel nord di Teldrassil. In tempi più sereni, li usava per tessere fili d'argento scintillanti al chiaro di luna. Queste ragnatele catturavano la nebbia serale, producendo una rugiada miracolosa dalle potenti proprietà curative, molto apprezzata dalle Sacerdotesse di Elune.",al={"che cosa sono le filature argentee","informazioni sulle filature argentee","filature di lady sathrah"}},["48fdca9c"]={q="Da dove provengono le Filature Argentee?",a="Vengono raccolte da Lady Sathrah, un ragno gigante che vive vicino al Lago di Buonpozzo, lungo i confini settentrionali di Teldrassil. Un tempo venerata come creatura aggraziata e pura, benedetta da Elune, Sathrah è recentemente impazzita. Gli elfi della notte hanno dovuto porre fine alle sue sofferenze e recuperare i suoi resti sacri.",al={"origine delle filature argentee","chi ha prodotto le filature argentee","dove trovare le filature argentee"}}},fp="18,177,29.453.0,23.332.1,40.123.0,47.192.0,37.213.0,46.220.0"}
P.entries["item:simple-memorandum"] = {n="Promemoria Semplice",s="Nella Valle Crestafredda, i guerrieri gnomi novizi vengono inviati ad addestrarsi con Thran Khorman a Forgiamara. Si preparano alla guerra per riconquistare Gnomeregan.",h="Nella Valle Crestafredda, i guerrieri gnomi novizi vengono inviati ad addestrarsi con Thran Khorman a...",kw={"forgiamara","valle crestafredda","dun morogh","gnomeregan","promemoria semplice","thran khorman","addestramento dei guerrieri"},ang={["class:Warrior"]="Come guerriero, inizi l'addestramento formale al combattimento con Thran Khorman a Forgiamara. Vai oltre le schermaglie rudimentali.",["race:Gnome"]="Come gnomo esiliato, condividi l'obiettivo di affinare le tue abilità in battaglia al fianco dei tuoi alleati nani. Ti prepari alla liberazione di Gnomeregan."},sec={{t="Una convocazione a Forgiamara",b="I giovani combattenti gnomi affrontano animali selvatici e trogg nella Valle Crestafredda con lettere di presentazione in mano. Il Promemoria Semplice indirizza chi lo porta da Thran Khorman, l'istruttore dei guerrieri di Forgiamara.\n\nGli gnomi portano in battaglia intelletto e congegni, ma riconquistare Gnomeregan richiede forza e disciplina marziale. Il promemoria invita chi lo porta ad andare oltre l'addestramento iniziale per imparare l'arte della guerra da Thran."}},faq={{q="Che cos'è il Promemoria Semplice?",a="Il Promemoria Semplice è un messaggio scritto per i guerrieri gnomi novizi della Valle Crestafredda. Ordina loro di presentarsi all'istruttore dei guerrieri nano di Forgiamara.",al={"promemoria semplice","cos'è questa nota","oggetto promemoria"}},{q="Chi ha scritto il Promemoria Semplice?",a="Il Promemoria Semplice non reca alcuna firma. Sten Braccioforte ipotizza che l'abbia scritto Thran Khorman, ma le parole sulla riconquista di Gnomeregan lo identificano come una direttiva gnomesca. Ti ordina di presentarti a Thran, l'istruttore dei guerrieri nano di Forgiamara.",al={"chi ha scritto il promemoria","chi ha inviato la nota","autore del promemoria semplice"}},{q="Cosa succede dopo aver letto il Promemoria Semplice?",a="Dopo aver letto il Promemoria Semplice, lo porti a Thran Khorman a Forgiamara. Lui riconosce la tua determinazione a riconquistare la patria perduta e si offre di insegnarti le basi del combattimento dei guerrieri.",al={"cosa faccio con il promemoria","dove lo porto","consegnare promemoria semplice"}},{q="Perché un nano addestra guerrieri gnomi?",a="Un nano addestra i guerrieri gnomi perché i profughi gnomi si sono stabiliti a Forgiardente e Forgiamara dopo la caduta di Gnomeregan. I veterani nani come Thran Khorman mettono a disposizione la propria abilità marziale per aiutare gli alleati esiliati ad addestrarsi e riconquistare la loro città irradiata.",al={"perché thran addestra gli gnomi","nani che addestrano gnomi"}}},fx={b027c55a={q="Perché mi è stato consegnato il Promemoria Semplice?",a="Il promemoria è una direttiva degli gnomi che ti ordina di presentarti a Thran Khorman, l'addestratore di guerrieri nani a Forgiamara. In quanto guerriero gnomo sfollato, il tuo compito principale è prepararti alla guerra per riconquistare Gnomeregan, e Thran ha promesso di preparare te e il tuo popolo. Sten Braccioforte ti ha passato il messaggio mentre lo aiutavi nella Valle Crestafredda.",al={"perché il promemoria semplice","scopo del promemoria semplice","perché mi serve il promemoria semplice"}}},fp="17,142,21.407.0,30.159.0,32.237.0,49.185.0,39.244.0"}
P.entries["item:simple-rune"] = {n="Runa Semplice",s="Nella Valle Crestafredda, Thran Khorman invia i giovani guerrieri nani promettenti a Forgiamara con la Runa Semplice per addestrarsi.",h="Nella Valle Crestafredda, Thran Khorman invia i giovani guerrieri nani promettenti a Forgiamara con la Runa...",kw={"forgiamara","valle crestafredda","dun morogh","runa dei nani","runa semplice","thran khorman","addestramento dei guerrieri"},ang={["class:Warrior"]="Per te che sei un guerriero nano, la Runa Semplice segna il primo passo nell'addestramento formale sotto la guida dell'istruttore veterano Thran Khorman.",["race:Dwarf"]="Per te che sei un nano, la runa di Thran Khorman offre le basi del combattimento: la presa su un'ascia, il peso dell'armatura e il sudore della vera battaglia."},sec={{t="Una chiamata alle armi",b="I giovani combattenti che hanno iniziato a eliminare le minacce nella Valle Crestafredda ricevono la convocazione formale di Thran. I segni marziali della runa non racchiudono alcuna magia; indicano a ogni recluta di presentarsi da Thran all'interno di Forgiamara. Lì insegna le basi del combattimento e offre consigli pratici per sopravvivere nelle lande ostili di Dun Morogh."}},faq={{q="Qual è lo scopo della Runa Semplice?",a="La Runa Semplice indica alle reclute di recarsi da Thran Khorman, all'interno di Forgiamara, per ricevere un addestramento formale. I giovani guerrieri della Valle Crestafredda la ricevono come tavoletta d'istruzioni.",al={"uso della runa semplice","cosa fa la runa","oggetto di missione runa semplice"}},{q="Chi invia la Runa Semplice?",a="Thran Khorman invia la Runa Semplice. L'istruttore dei guerrieri nani all'interno di Forgiamara tiene d'occhio i combattenti promettenti che prestano aiuto nella valle.",al={"chi ha scritto la runa","chi mi ha dato la runa semplice","mittente della runa"}},{q="Dove porto la Runa Semplice?",a="Porta la Runa Semplice a Thran Khorman all'interno di Forgiamara, nella parte centrale della Valle Crestafredda.",al={"dove devo andare","consegna della runa","posizione di thran khorman"}}},fx={["0f0eb9fb"]={q="Che cos'è la Runa Semplice?",a="La Runa Semplice è una pietra nanica incisa, affidata ai guerrieri promettenti nella Valle Crestafredda. Non porta incantamenti mistici: è un ordine scritto di Thran Khorman, che convoca i combattenti novizi a Forgiamara per iniziare il loro addestramento marziale ufficiale.",al={"che cos'è la runa semplice","storia della runa semplice","oggetto runa semplice"}},["2d1fc984"]={q="Perché Thran Khorman vuole che tu abbia la Runa Semplice?",a="Thran Khorman ti invia la runa per reclutarti nell'addestramento formale dei guerrieri. Avendo intravisto il tuo potenziale nelle prime imprese nella Valle Crestafredda, vuole insegnarti la corretta disciplina marziale nanica e mostrarti cosa serve davvero per combattere per Forgiardente, mentre le minacce locali aumentano.",al={"perché thran invia la runa","perché mi serve la runa semplice","perché vogliono la runa semplice"}}},fp="11,120,17.305.0,39.169.0,26.137.0,32.83.0"}
P.entries["item:simple-sigil"] = {n="Sigillo Semplice",s="A Vallombra, un Sigillo Semplice chiama i guerrieri Elfi della Notte alle prime armi ad addestrarsi con Alyissia. Segna il loro primo passo nella difesa di Teldrassil.",h="A Vallombra, un Sigillo Semplice chiama i guerrieri Elfi della Notte alle prime armi ad addestrarsi con...",kw={"alyissia","ilthalaine","guerriero kaldorei","vallombra","sigillo semplice","teldrassil","addestramento dei guerrieri"},ang={["class:Warrior"]="Per te che sei un guerriero kaldorei, il Sigillo Semplice segna il primo passo nelle tradizioni marziali volte a proteggere Teldrassil.",["race:NightElf"]="Come Elfo della Notte, vedi l'urgenza della situazione che i kaldorei devono affrontare. Alyissia e altri istruttori reclutano combattenti capaci per contrastare la corruzione crescente tra i rami dell'Albero del Mondo."},sec={{t="Una chiamata alle armi",b="A Vallombra, il Conservatore Ilthalaine guida i giovani Elfi della Notte alla ricerca della propria vocazione. Un messaggero porta un Sigillo Semplice da parte di Alyissia, l'istruttrice dei guerrieri. Ilthalaine lo consegna ai guerrieri alle prime armi, e la sua iscrizione invita ogni recluta a presentarsi per l'addestramento. Il loro addestramento marziale inizia mentre tempi difficili si profilano per l'Albero del Mondo."},{t="Il fardello della difesa",b="Alyissia usa il sigillo per spiegare alle reclute di cosa hanno bisogno i kaldorei. Teldrassil è cresciuto di recente, la corruzione si diffonde tra le bestie della foresta e la riscoperta di terre lontane come Feralas ha disperso le forze dei protettori Elfi della Notte. Il sigillo non ha alcun potere. Accoglie ogni recluta tra i guardiani incaricati di proteggere il proprio popolo dalle minacce emergenti."}},faq={{q="Cos'è il Sigillo Semplice?",a="Il Sigillo Semplice è un pegno con un'iscrizione destinato ai guerrieri Elfi della Notte alle prime armi a Vallombra. Il Conservatore Ilthalaine lo consegna loro, e la sua iscrizione li invita a presentarsi da Alyissia per l'addestramento.",al={"oggetto sigillo semplice","cosa fa il sigillo semplice","cos'è questo sigillo"}},{q="Chi invia il Sigillo Semplice?",a="Un messaggero porta il Sigillo Semplice da Alyissia, l'istruttrice dei guerrieri a Vallombra, al Conservatore Ilthalaine. Ilthalaine lo consegna ai guerrieri alle prime armi.",al={"chi ha creato il sigillo","chi ha inviato il sigillo semplice"}},{q="Cosa dovrei farne?",a="Leggi l'iscrizione e porta il Sigillo Semplice ad Alyissia vicino alla base di Aldrassil, a Vallombra, per iniziare il tuo addestramento da guerriero.",al={"dove consegnare il sigillo semplice","chi accetta il sigillo semplice"}},{q="Il sigillo conferisce abilità speciali?",a="No. Il Sigillo Semplice è un avviso scritto che presenta gli aspiranti guerrieri alla loro mentore.",al={"poteri del sigillo","statistiche del sigillo semplice"}}},fp="12,138,17.341.0,21.366.0,25.193.0,27.150.0,25.131.0,43.91.0"}
P.entries["item:simple-tablet"] = {n="Tavoletta Semplice",s="Nella Valle delle Sfide, Gornek consegna ai nuovi guerrieri troll un messaggio da portare a Frang.",h="Nella Valle delle Sfide, Gornek consegna ai nuovi guerrieri troll un messaggio da portare a Frang.",kw={"puntascura","durotar","frang","gornek","tavoletta semplice","antro del tirocinio","valle delle sfide","istruttore dei guerrieri"},ang={["class:Warrior"]="In quanto guerriero, il messaggio ti presenta a Frang per l'addestramento al combattimento.",["race:Troll"]="In quanto troll Puntascura a Durotar, questa convocazione ti chiama a rafforzare le prime linee dell'Orda al fianco degli orchi."},sec={{t="Una Chiamata alla Battaglia",b="Gornek consegna ai nuovi guerrieri troll un messaggio di Tar'sere, indirizzato a Frang, l'istruttore dei guerrieri vicino all'Antro del Tirocinio. Il messaggio introduce la recluta all'addestramento al combattimento a Durotar e le chiede di presentarsi a Frang. Il messaggio la esorta a impugnare le armi per l'Orda."}},faq={{q="Che cos'è la Tavoletta Semplice?",a="Nella Valle delle Sfide, Gornek consegna agli aspiranti guerrieri troll un messaggio che li indirizza a Frang per l'addestramento al combattimento.",al={"tavoletta semplice","cos'è questa tavoletta","tavoletta guerriero troll"}},{q="Chi invia la tavoletta?",a="Tar'sere firma il messaggio e indirizza la recluta a Frang, l'istruttore dei guerrieri fuori dall'Antro del Tirocinio nella Valle delle Sfide.",al={"chi ha inviato la tavoletta semplice","chi ha scritto la tavoletta","mittente della tavoletta"}},{q="Dove porto la tavoletta?",a="Porta la Tavoletta Semplice a Frang, che riposa fuori dall'Antro del Tirocinio nella Valle delle Sfide.",al={"a chi consegno la tavoletta semplice","dove portare la tavoletta","posizione di frang"}},{q="Chi riceve questa tavoletta?",a="La Tavoletta Semplice viene consegnata ai guerrieri troll che iniziano i loro riti di passaggio nella Valle delle Sfide.",al={"chiunque può ottenere la tavoletta semplice","quale classe riceve la tavoletta semplice"}}},fx={["219776b3"]={q="Perché Frang ti manda la Tavoletta Semplice?",a="In realtà Frang non l'ha scritta. Gornek suppone che venga da Frang, ma la tavoletta è firmata dal troll Tar'sere, che ti manda da Frang, fuori dall'Antro del Tirocinio. Frang ha bisogno di astuti guerrieri troll che mostrino agli orchi come combattere anche con l'ingegno, non solo con la forza, e può addestrarti per le battaglie future dell'Orda.",al={"perché la tavoletta semplice","perché frang mi vuole","scopo della tavoletta semplice"}}},fp="13,85,19.269.0,26.116.0,21.121.0,27.83.0,25.98.0"}
P.entries["item:singed-scale"] = {n="Scaglia Strinata"}
P.entries["item:skeleton-finger"] = {n="Dito di Scheletro",s="A Boscovespro, i morti irrequieti forniscono il Dito di Scheletro a Dama Eva di Borgoscuro. Lei li raccoglie insieme a zanne di ghoul e veleno di ragno per creare talismani protettivi.",h="A Boscovespro, i morti irrequieti forniscono il Dito di Scheletro a Dama Eva di Borgoscuro.",kw={"borgoscuro","boscovespro","zanna di ghoul","dama eva","predone scheletrico","dito di scheletro","totem del castigo"},ang={["class:Mage"]="Come mago che studia la divinazione popolare, potresti trovare nell'uso di dita scheletriche e veleni naturali di Dama Eva per un incantamento di ritorsione un'insolita combinazione di stregoneria popolare e magia simpatetica.",["class:Paladin"]="Come paladino, potresti rabbrividire all'idea di profanare resti scheletrici e portarne con te le parti recise. Nella cupa oscurità di Boscovespro, usare le ossa degli empi per proteggere i vivi è una macabra necessità."},sec={{t="Ossa degli Irrequieti",b="Predoni e guerrieri scheletrici sorgono in tutta Boscovespro, insieme a maghi necrotici e immondi. La maggior parte dei viaggiatori lascia stare i loro resti ripugnanti, ma cartomanti e mistici ne apprezzano la fredda essenza. Dama Eva, la veggente di Borgoscuro, raccoglie le loro dita ossee per il Totem del Castigo. Vincola le loro persistenti energie necrotiche in una protezione che colpisce a sua volta gli aggressori."}},faq={{q="Quali creature rilasciano un Dito di Scheletro?",a="Le Dita di Scheletro si ottengono da predoni scheletrici, Healers, Warders, guerrieri scheletrici, Horrors, immondi e Skeletal Mages in tutta Boscovespro.",al={"dove si trovano le dita di scheletro","cosa rilascia dita di scheletro","fonte dito di scheletro"}},{q="Chi vuole le Dita di Scheletro a Boscovespro?",a="Dama Eva, la veggente di Borgoscuro, ha bisogno di Dita di Scheletro per creare una protezione.",al={"chi ha bisogno di dita di scheletro","chi assegna la missione dito di scheletro","a cosa servono le dita di scheletro"}},{q="Cos'è il Totem del Castigo?",a="Dama Eva crea il Totem del Castigo con dita di scheletro, zanne di ghoul e veleno di ragno. Vincola le loro energie oscure in un'aura che danneggia chiunque attacchi chi la porta.",al={"scopo del totem del castigo","cosa crea dama eva"}},{q="Perché Dama Eva ha bisogno di resti di non morti per un amuleto protettivo?",a="Dama Eva usa la contaminazione persistente e l'aggressività delle creature locali nei suoi rituali. Vincola le essenze violente degli scheletri, dei ghoul e delle bestie velenose di Boscovespro in una protezione che punisce gli aggressori.",al={"perché la magia delle ossa","perché dita di scheletro per il totem"}}},fx={["7c732e26"]={q="Che cos'è un Dito di Scheletro?",a="Un Dito di Scheletro è un frammento osseo reciso e disseccato, prelevato da uno degli orrori scheletrici animati che vagano per le foreste corrotte e le cripte di Boscovespro. Preservate dalla corruzione necromantica che ha invaso la regione, queste dita conservano tracce della magia oscura che mantiene gli inquieti non morti in movimento.",al={"che cos'è un dito di scheletro","che cosa sono le dita di scheletro","identificare un dito di scheletro"}},a7de6990={q="Da dove viene un Dito di Scheletro?",a="Queste dita provengono dai resti scheletrici risvegliati nei cimiteri infestati e tra le rovine di Boscovespro. Non vengono create né fabbricate: sono raccolte direttamente dai cadaveri animati, come guerrieri, demoni, custodi e razziatori scheletrici, che strisciano nell'oscurità, animati dalla misteriosa corruzione che si diffonde nei boschi.",al={"origine del dito di scheletro","da dove vengono le dita di scheletro","chi ha prodotto il dito di scheletro"}}},fp="15,157,21.373.0,38.125.0,39.84.0,32.179.0,63.206.0"}
P.entries["item:skin-of-sweet-rum"] = {n="Borraccia di Rum Dolce",s="Alla Locanda del Fiero Leone di Borgodoro, la Borraccia di Rum Dolce è destinata a Borgolago, dove la guerra ha ridotto le scorte della taverna.",h="Alla Locanda del Fiero Leone di Borgodoro, la Borraccia di Rum Dolce è destinata a Borgolago, dove la guerra...",kw={"daniels l'oste","dry times","borgodoro","borgolago","locanda del fiero leone","borraccia di rum dolce","rum dolce"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, puoi vedere come l'invasione degli orchi Roccianera metta a dura prova i piccoli insediamenti che difendono i confini orientali di Roccavento."},sec={{t="Un raro conforto per Borgolago",b="La taverna di Borgolago è a corto di bevande mentre l'invasione degli orchi Roccianera blocca le strade verso le Montagne Crestarossa. Daniels l'Oste ha bisogno di bevande per le guardie cittadine e i rifugiati. Così manda i viaggiatori a raccogliere specialità regionali, tra cui un otre di rum dolce dalla Locanda del Fiero Leone di Borgodoro."}},faq={{q="Dove posso trovare una Borraccia di Rum Dolce?",a="Puoi acquistare una Borraccia di Rum Dolce dal locandiere o dall'oste alla Locanda del Fiero Leone di Borgodoro, nella Foresta di Elwynn.",al={"posizione del rum dolce","dove comprare il rum dolce","chi vende il rum dolce"}},{q="Chi vuole questo rum?",a="Daniels l'Oste gestisce la taverna di Borgolago. Vuole una borraccia di rum dolce e altre bevande regionali per rifornire i suoi scaffali durante Dry Times.",al={"chi ha bisogno del rum dolce","consegna del rum dolce","missione del rum dolce"}},{q="Perché Borgolago sta esaurendo gli alcolici?",a="L'invasione degli orchi Roccianera ha interrotto le rotte commerciali verso Crestarossa. I carri dei mercanti non possono viaggiare in sicurezza e le scorte di alcolici di Borgolago sono quasi esaurite.",al={"perché sono a corto di alcolici","perché borgolago è a secco","motivo di dry times"}},{q="Quali altri alcolici servono oltre al rum?",a="Daniels l'Oste ha anche bisogno di un fusto di Thunderbrew Lager dalle Marche Occidentali, un Barile di Merlot da Roccavento e una Bottiglia di Torcibudella da Borgoscuro.",al={"bevande di dry times","lista bevande di daniels","altri alcolici necessari"}}},fx={efbd5e13={q="Che cos'è una Borraccia di Rum Dolce?",a="La Borraccia di Rum Dolce è una borraccia di pelle piena di liquore zuccherino, venduta a Borgodoro, nella Foresta di Elwynn. È una delle specialità alcoliche regionali apprezzate nei regni umani dell'Azeroth meridionale.",al={"che cos'è il rum dolce","informazioni sulla borraccia di rum dolce","rum dolce"}}},fp="17,123,28.311.0,37.117.0,19.140.0,39.152.0,48.148.0"}
P.entries["item:skittering-blood"] = {n="Sangue Brulicante",s="A Selva Pinargento, il Sangue Brulicante fornisce alla Società degli Speziali Reali materiale per la sua New Plague. Gli alchimisti dei Reietti lo estraggono dagli aracnidi dell'Oscurità Brulicante mentre cercano un'arma contro il Flagello e l'umanità.",h="A Selva Pinargento, il Sangue Brulicante fornisce alla Società degli Speziali Reali materiale per la sua New...",kw={"faranell","the new plague","renferrel","società degli speziali reali","selva pinargento","sangue brulicante","oscurità brulicante","skitterweb"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti gli speziali dei Reietti a mettere al sicuro Lordaeron con armi di loro creazione nella guerra contro il Flagello.",["race:Undead"]="Come Non Morto, aiuti la regina Sylvanas e la Società degli Speziali Reali a sviluppare un'arma biologica contro Arthas e l'umanità vivente."},sec={{t="Un distillato tossico",b="I predatori Skitterweb, gli assalitori e la loro matriarca Krethis la Filatrice d'Ombre forniscono sangue velenoso. Lo Speziale Renferrel scoprì che, raffinato con le tossine dei cuori di orso brizzolato, forma la base di un elisir eccezionalmente letale. I suoi agenti contaminanti si prestano anche agli esperimenti chimici dell'Apothecarium."},{t="Alimentare The New Plague",b="A Sepulcra, il Maestro Speziale Faranell dirige la ricerca di una New Plague da parte della Società degli Speziali Reali. I Reietti affrontano le orde del Flagello e i superstiti umani ostili, quindi ricorrono alla guerra biologica per riequilibrare le forze. Faranell studia la potenza tossica del sangue mentre lavora a un contagio capace di distruggere sia la non-morte sia la carne vivente."}},faq={{q="A cosa serve il Sangue Brulicante?",a="La Società degli Speziali Reali usa il Sangue Brulicante nelle ricerche sulla New Plague dei Reietti. Mescolato alle tossine dei cuori d'orso, crea una miscela instabile che il Maestro Speziale Faranell studia per usarla contro il Flagello e gli umani viventi.",al={"uso del sangue brulicante","perché raccogliere sangue di ragno","cosa fa faranell con il sangue brulicante"}},{q="Dove si trova il Sangue Brulicante?",a="I predatori Skitterweb, gli assalitori e Krethis la Filatrice d'Ombre forniscono Sangue Brulicante nell'Oscurità Brulicante e nei dintorni. Il bosco cupo e soffocato dalle ragnatele si trova nella parte nordoccidentale di Selva Pinargento.",al={"dove trovare sangue brulicante","posizione sangue brulicante","chi rilascia sangue brulicante"}},{q="Chi richiede questi campioni?",a="Lo Speziale Renferrel, a Mausolea nella Selva Pinargento, richiede il sangue. I campioni vengono inviati al Maestro Speziale Faranell nell'Apothecarium di Sepulcra.",al={"chi richiede sangue brulicante","chi assegna la missione per il sangue brulicante"}},{q="Perché ai Reietti serve il veleno delle bestie locali?",a="La Società degli Speziali Reali estrae tossine naturali dalla fauna corrotta di Lordaeron. Il veleno degli aracnidi giganti di Selva Pinargento fornisce patogeni biologici grezzi che possono essere concentrati e trasformati in armi sotto forma di piaghe sintetiche.",al={"perché il veleno di ragno","ricerca degli speziali sulle bestie"}}},fx={["8eea8a63"]={q="Che cos'è il Sangue Brulicante?",a="Il Sangue Brulicante è un icore virulento estratto dai ragni giganteschi che vivono nell'Oscurità Brulicante della Selva Pinargento. Le sue proprietà naturalmente velenose e contaminanti lo rendono un reagente biologico prezioso per gli esperimenti alchemici.",al={"che cos'è il sangue brulicante","oggetto sangue brulicante","informazioni sul sangue brulicante"}},f7d32240={q="Da dove viene il Sangue Brulicante e chi l'ha prodotto?",a="Non viene prodotto: si estrae naturalmente dagli aracnidi predatori che vivono nella zona nordoccidentale della Selva Pinargento, tra cui gli agguatatori e gli assalitori di Ragnatele Brulicanti e la matriarca Krethis Tessombra. Il sangue viene estratto direttamente dalle loro carcasse dai cacciatori che raccolgono materiali per i Reietti.",al={"da dove viene il sangue brulicante","chi ha prodotto il sangue brulicante","origine del sangue brulicante"}}},fp="16,224,18.307.0,22.345.0,34.245.0,32.185.0,27.156.0,49.221.0"}
P.entries["item:sleepers-key"] = {n="Chiave dei Dormienti",s="Al Picco di Petrartiglio, la Chiave dei Dormienti contribuisce a proteggere una sacra cripta druidica. I druidi elfi della notte la crearono come una delle tre chiavi incantate per il Talon Den Hoard.",h="Al Picco di Petrartiglio, la Chiave dei Dormienti contribuisce a proteggere una sacra cripta druidica.",kw={"chiave del custode del portale","scrigno dei dormienti","chiave dei dormienti","picco di petrartiglio","tesoro dell'eremo grinfialunga","antro del tirocinio"},ang={["class:Druid"]="Come druido, puoi vedere come le chiavi e i nascondigli dell'Eremo Grinfialunga creino più livelli di difesa. Nascondigli segreti e serrature a chiave tengono al sicuro reliquie di potere.",["faction:Horde"]="Come membro dell'Orda, ottenere la Chiave dei Dormienti fa parte di un'incursione pianificata nel cuore del Picco di Petrartiglio. L'incursione abbatte le barriere difensive degli elfi della notte per impadronirsi delle reliquie sigillate nel loro tesoro."},sec={{t="Una misura di sicurezza druidica",b="L'Eremo Grinfialunga è un ridotto e un santuario per i druidi di Kalimdor sul Picco di Petrartiglio. I custodi elfi della notte costruirono serrature e nascondigli segreti per proteggere sacre reliquie e potenti tesori da attenzioni indesiderate. La Chiave dei Dormienti è una delle tre chiavi che formano una barriera protettiva.\n\nLa Chiave dei Dormienti si trova in un nascondiglio appartato nelle profondità dell'antro. La Chiave del Custode del Portale, nascosta vicino alla soglia, apre quel nascondiglio. La Chiave del Bivalve e la Chiave del Tumulo completano il gruppo. Inserisci tutte e tre le chiavi nelle serrature di pietra del Talon Den Hoard e la barriera svanirà. Al suo interno sono custoditi antichi oggetti."}},faq={{q="A cosa serve la Chiave dei Dormienti?",a="La Chiave dei Dormienti apre il Talon Den Hoard insieme alla Chiave del Tumulo e alla Chiave del Bivalve. La cripta di pietra protetta dalla barriera si trova nelle profondità dell'antro sepolcrale al Picco di Petrartiglio.",al={"a cosa serve la chiave dei dormienti","scopo della chiave dei dormienti","chiavi del tesoro dell'eremo grinfialunga"}},{q="In che modo è stata rinchiusa la Chiave dei Dormienti?",a="I druidi collocarono la Chiave dei Dormienti nella Sleepers' Cache, nei cunicoli nordoccidentali dell'Eremo Grinfialunga. La Chiave del Custode del Portale la apre. I druidi nascosero quella chiave in una lanterna dall'aspetto ordinario vicino all'ingresso dell'antro.",al={"dove si trova la chiave dei dormienti","aprire lo scrigno dei dormienti","requisito chiave del custode del portale"}},{q="Perché i druidi hanno nascosto le loro reliquie con più chiavi?",a="I druidi elfi della notte crearono complesse difese per impedire che i loro potenti oggetti e sacri cimeli cadessero in mani nemiche se l'antro fosse stato attaccato. Nascondendo le chiavi in nascondigli separati, resero difficile agli intrusi saccheggiare il tesoro.",al={"perché così tante chiavi","difesa dell'eremo grinfialunga","enigma del tesoro dei druidi"}},{q="Perché si chiama Chiave dei Dormienti?",a="I druidi non spiegano mai il nome. La Chiave dei Dormienti condivide il nome con la Sleepers' Cache, il forziere nascosto nell'Eremo Grinfialunga in cui è custodita la chiave.",al={"chi sono i dormienti","significato nome chiave dei dormienti"}}},fx={["0a862a33"]={q="Che cos'è la Chiave dei Dormienti?",a="La Chiave dei Dormienti è una delle tre chiavi speciali forgiate dai druidi elfi della notte del Picco di Petrartiglio. Nascosta in un deposito chiuso a chiave, nel cuore dell'Eremo Grinfialunga, è una componente essenziale del sistema di protezione che custodisce il tesoro centrale dei druidi, composto da reliquie sacre.",al={"cos'è la chiave dei dormienti","storia della chiave dei dormienti","informazioni sulla chiave dei dormienti"}},["8275ad63"]={q="Da dove proviene la Chiave dei Dormienti e chi l'ha creata?",a="La chiave fu forgiata dai druidi che fondarono l'Eremo Grinfialunga sul Picco di Petrartiglio. Per proteggere i loro potenti artefatti dagli intrusi, idearono un elaborato sistema di sicurezza e chiusero la chiave in uno scrigno apposito chiamato Cassa dei Dormienti.",al={"chi ha creato la chiave dei dormienti","origine della chiave dei dormienti","da dove viene la chiave dei dormienti"}},["3884172c"]={q="Perché qualcuno vuole la Chiave dei Dormienti?",a="L'Orda cerca la chiave per aggirare le difese dei druidi e aprire il Tesoro dell'Eremo Grinfialunga. Insieme alla Chiave del Bivalve e alla Chiave del Tumulo, apre il caveau di pietra che custodisce le potenti reliquie riposte dai druidi sul Picco di Petrartiglio.",al={"perché cercare la chiave dei dormienti","perché serve la chiave dei dormienti","chi vuole la chiave dei dormienti"}}},fp="13,149,19.546.0,35.148.0,38.200.0,56.237.0,35.141.0"}
P.entries["item:smoky-iron-ingot"] = {n="Lingotto di Ferro Fumoso",s="A Windshear, i coboldi fondono Lingotti di Ferro Fumoso dal minerale estratto nelle Vette di Petrartiglio. Gli armaioli orcheschi apprezzano queste barre per realizzare robusti equipaggiamenti di maglia destinati ai guerrieri dell'Orda.",h="A Windshear, i coboldi fondono Lingotti di Ferro Fumoso dal minerale estratto nelle Vette di Petrartiglio.",kw={"brutal armor","coboldo","lingotto di ferro fumoso","petrartiglio","thun'grim firegaze","guerriero","tagliavento"},ang={["class:Warrior"]="Per i guerrieri dell'Orda, raccogliere questi lingotti mette alla prova la resistenza a Stonetalon. Le barre servono a forgiare il Brutal Hauberk.",["profession:Blacksmithing"]="Questi lingotti mostrano come gli scavatori coboldi fondano il metallo con metodi rudimentali, mentre i fabbri esperti usano tecniche raffinate."},sec={{t="Metallurgia Grezza dei Coboldi",b="I coboldi fondono Lingotti di Ferro Fumoso nei cunicoli della Landa di Tagliavento, nelle Vette di Petrartiglio. Estraggono il minerale dai pendii rocciosi e lo scaldano su fuochi rudimentali e fumanti. Residui e carbone vegetale aderiscono alle barre, ma il metallo resta compatto e resistente."},{t="Forgiare la Brutal Armor",b="Thun'grim Firegaze è un armaiolo orco quasi cieco in un accampamento impervio che domina le Savane. Richiede questi lingotti per creare armature destinate ai guerrieri dell'Orda che hanno dimostrato il proprio valore. Insieme a barre di ferro raffinato, Azurite Polverosa e phlogiston volatile, il metallo fumoso forma un nucleo resistente per i Brutal Hauberks."}},faq={{q="Da dove provengono i Lingotti di Ferro Fumoso?",a="I coboldi dei siti di scavo e dei cunicoli di Windshear, nelle Vette di Petrartiglio orientali, portano con sé Lingotti di Ferro Fumoso. Tra loro ci sono scavatori, tagliapietre, parassiti, geomanti e i loro signori.",al={"dove trovare il lingotto di ferro fumoso","posizione lingotto di ferro fumoso","chi rilascia i lingotti di ferro fumoso"}},{q="A cosa servono i Lingotti di Ferro Fumoso?",a="I guerrieri che rispondono alla chiamata di Thun'grim Firegaze raccolgono Lingotti di Ferro Fumoso. Il maestro armaiolo vive sulle cime vicino a Crocevia, nelle Savane, e ha bisogno di quindici lingotti per forgiare il Brutal Hauberk.",al={"uso lingotto di ferro fumoso","a cosa serve il lingotto di ferro fumoso","oggetto missione brutal armor"}},{q="Perché i lingotti sono descritti come \\\"fumosi\\\"?",a="I coboldi usano fuochi rudimentali dalla fiamma bassa per fondere il metallo nei loro cunicoli bui. Fuliggine, polvere di carbone vegetale e cenere aderiscono ai lingotti, privandoli di una lucentezza pulita.",al={"perché è fumoso","storia del ferro fumoso"}},{q="Qualsiasi fabbro può creare oggetti con questi lingotti?",a="No. Le barre irregolari e incrostate di fuliggine non sono adatte alle normali lavorazioni di forgia destinate al commercio. Solo fabbri come Thun'grim Firegaze sanno trasformarle in equipaggiamenti da combattimento su misura.",al={"i giocatori possono forgiare il ferro fumoso","il ferro fumoso è un bene commerciale"}}},fx={["18404e72"]={q="Che cos'è un Lingotto di Ferro Fumoso?",a="I Lingotti di Ferro Fumoso sono barre di ferro scuro, grezzamente fuse e striate di fuliggine, che si trovano in possesso dei koboldi di Tagliavento, intenti a scavare nelle profondità delle Vette di Petrartiglio. Sono rozzi rispetto ai metalli lavorati con cura, ma possiedono comunque la robustezza necessaria ai fabbri esperti che vogliono forgiare armature pesanti e resistenti.",al={"cos'è un lingotto di ferro fumoso","informazioni sul lingotto di ferro fumoso","parlami del lingotto di ferro fumoso"}},["9ee5c553"]={q="Da dove proviene il Lingotto di Ferro Fumoso e chi lo ha creato?",a="Questi lingotti vengono estratti e fusi dai koboldi della Landa di Tagliavento, nelle Vette di Petrartiglio. Nelle loro gallerie sotterranee, minatori e parassiti dissotterrano il minerale grezzo e lo fondono in lingotti di ferro utilizzabili, per rafforzare le loro attività nel sottosuolo e armare le loro bande di guerra.",al={"provenienza del lingotto di ferro fumoso","da dove provengono i lingotti di ferro fumoso","chi produce il lingotto di ferro fumoso"}},["8ab45f92"]={q="Perché qualcuno vuole il Lingotto di Ferro Fumoso?",a="Thun'grim Firegaze, il maestro fabbro orco quasi cieco che vive in cima alle scogliere delle Savane, ne richiede quindici per forgiare Brutal Armor per i guerrieri dell'Orda che se ne dimostrano degni. Combinato con altri rari agenti alchemici e minerali, questo metallo grezzo è il materiale di base per un'armatura progettata per resistere a una guerra brutale.",al={"perché procurarsi il lingotto di ferro fumoso","chi vuole il lingotto di ferro fumoso","storia dell'uso del lingotto di ferro fumoso"}}},fp="16,164,23.242.0,24.281.0,37.182.0,36.194.0,40.159.0,43.166.0"}
P.entries["item:smoldering-embers"] = {n="Braci Infuocate",s="Nella Valle Bruciata, le Braci Infuocate rimangono quando gli elementali del fuoco vengono estinti. Le Sentinelle degli Elfi della Notte le raccolgono come prova che le fiamme vengono domate.",h="Nella Valle Bruciata, le Braci Infuocate rimangono quando gli elementali del fuoco vengono estinti.",kw={"burning destroyer","burning ravager","valle bruciata","enraged spirits","kaela freccianera","rogue flame spirit","braci infuocate","petrartiglio","s.p.r. & co."},ang={["class:Druid"]="Come druido, vedi nelle braci la tragica prova che l'avidità industriale ha sconvolto l'equilibrio della natura. La furia elementale impedisce al suolo soffocato dalla cenere di rigenerarsi.",["race:NightElf"]="Per gli Elfi della Notte, l'incendio della Valle Bruciata è una ferita inferta a Kalimdor. Raccoglierne le braci è un dovere solenne per purificare la terra dalla profanazione straniera e ripristinare la pace sotto lo sguardo di Elune."},sec={{t="Resti della Valle Bruciata",b="Il disboscamento e le attività industriali della S.P.R. & Co. hanno incendiato la Valle Bruciata. Il loro lavoro ha risvegliato forze distruttive nelle profondità della terra. Burning Ravagers, Burning Destroyers e Rogue Flame Spirits hanno imperversato nella conca bruciata. Quando un elementale del fuoco viene estinto, rimane un nucleo coperto di cenere. Quel tizzone è una Brace Infuocata, la prova che le fiamme che invadono la valle vengono domate."}},faq={{q="Da dove provengono le Braci Infuocate?",a="Le Braci Infuocate provengono dagli elementali del fuoco della Valle Bruciata, nella parte meridionale delle Vette di Petrartiglio. Burning Ravagers, Burning Destroyers e Rogue Flame Spirits le lasciano tutti dietro di sé.",al={"dove trovare le braci infuocate","chi rilascia le braci infuocate","fonte delle braci infuocate"}},{q="Perché Kaela Freccianera vuole queste braci?",a="Kaela Freccianera vuole le braci come prova che gli elementali del fuoco della Valle Bruciata vengono abbattuti. Crede che la terra martoriata non possa guarire con la grazia di Elune finché gli spiriti violenti vagano senza controllo.",al={"perché raccogliere le braci infuocate","braci di kaela freccianera","obiettivo enraged spirits"}},{q="Cosa ha causato la comparsa degli elementali del fuoco nella Valle Bruciata?",a="La S.P.R. & Co. ha portato gli elementali del fuoco nella Valle Bruciata abbattendo l'antica foresta con macchinari devastanti e incendi indiscriminati. Il suo operato sconsiderato ha destabilizzato il terreno e scatenato elementali ostili di fiamma e pietra. Quelle forze hanno scacciato i goblin.",al={"cosa è successo alla valle bruciata","perché ci sono elementali del fuoco a petrartiglio","spiriti del fuoco s.p.r. & co."}}},fx={["4d13fc7e"]={q="Che cosa sono le Braci Infuocate?",a="Le Braci Infuocate sono i resti materiali ardenti lasciati dagli elementali del fuoco distruttivi che infestano la Valle Bruciata. Questi residui incandescenti rimangono dopo aver ucciso creature come Devastatori Ardenti, Spiriti della Fiamma Vaganti e Distruttori Ardenti, e sono la prova tangibile che la loro furia di fuoco nella foresta devastata è stata domata.",al={"cosa sono le braci infuocate","storia delle braci infuocate","cos'è una brace infuocata"}}},fp="17,159,28.404.0,37.182.0,45.208.0,62.277.0"}
P.entries["item:snellig-s-snuffbox"] = {n="Scatola di Tabacco di Snellig",s="Alla Flotta Perduta, la Scatola di Tabacco di Snellig resta con il suo proprietario non morto tra i relitti. Il Primo Ufficiale Fitzsimmons a Porto di Menethil la vuole come prova che il suo compagno di ciurma maledetto ha trovato pace.",h="Alla Flotta Perduta, la Scatola di Tabacco di Snellig resta con il suo proprietario non morto tra i relitti.",kw={"ciurma maledetta","fitzsimmons","kul tiras","flotta perduta","snellig","scatola di tabacco","the third fleet","paludi grigie"},ang={["faction:Alliance"]="Come avventuriero dell'Alleanza, recuperare gli averi dei marinai Kul Tirani caduti e dare pace ai loro spiriti maledetti è un triste dovere verso un antico alleato navale."},sec={{t="Un ricordo della The Third Fleet",b="Il Primo Ufficiale Snellig stringe ancora la sua scatola di tabacco in un relitto al largo delle Paludi Grigie settentrionali. La Third Fleet di Kul Tiras si arenò lì, e i suoi marinai e ufficiali annegarono per un potere misterioso legato a un tesoro nascosto a bordo delle navi. Vincolata a quel potere, la ciurma annegata risorse sotto forma di spiriti tormentati e non morti scheletrici.\n\nSnellig infesta la stiva marcescente del relitto più vicino alla costa. La sua scatola di tabacco è un semplice ricordo della sua vita mortale in mare. Il Primo Ufficiale Fitzsimmons, unico superstite vivente del disastro, la rivuole come prova che almeno un compagno di bordo perduto sia stato liberato dal tormento."}},faq={{q="Cos'è la Scatola di Tabacco di Snellig?",a="Il Primo Ufficiale Snellig possedeva un tempo il piccolo contenitore personale chiamato Scatola di Tabacco di Snellig. Ciò che resta di lui, ormai non morto, la porta con sé a bordo di un relitto al largo della costa settentrionale delle Paludi Grigie.",al={"cos'è questo oggetto","scatola di tabacco di snellig","scatola di tabacco"}},{q="Dove posso trovare la Scatola di Tabacco di Snellig?",a="Puoi prendere la scatola di tabacco dal Primo Ufficiale Snellig, che infesta la stiva del relitto più vicino alla costa presso la Flotta Perduta, nelle Paludi Grigie nordoccidentali.",al={"dove snellig rilascia la scatola di tabacco","trovare snellig","posizione del primo ufficiale snellig"}},{q="Chi desidera questa scatola di tabacco?",a="Il Primo Ufficiale Fitzsimmons vuole che tu gli porti la scatola di tabacco a Porto di Menethil. L'unico superstite vivente della Third Fleet la chiede come prova che Snellig abbia trovato pace.",al={"chi prende la scatola di tabacco","a chi devo consegnarlo","missione di fitzsimmons"}},{q="Perché il Primo Ufficiale Snellig è maledetto?",a="Fitzsimmons dice che un tesoro oscuro e terribile, nascosto a bordo di una nave della Third Fleet, condannò le ciurme quando le navi fecero naufragio. Le loro anime restano intrappolate nel legname marcescente, senza poter trovare pace.",al={"perché snellig è un non morto","maledizione della flotta perduta","maledizione della the third fleet"}}},fp="18,184,29.620.0,27.168.0,35.152.0,24.167.0,33.194.0"}
P.entries["item:snufflenose-command-stick"] = {n="Vincastro per Tartasniffo",s="A Porto Paranco, Mebok Ghignofolle manda citelli addestrati nelle Gallerie di Lamaspina a cercare Blueleaf Tubers.",h="A Porto Paranco, Mebok Ghignofolle manda citelli addestrati nelle Gallerie di Lamaspina a cercare Blueleaf...",kw={"tubero di foglia blu","vincastro di comando","citello","mebok ghignofolle","porto paranco","gallerie di lamaspina","tartasniffo","le savane"},ang={["profession:Cooking"]="I Blueleaf Tubers sono apprezzati come prelibatezza gastronomica in tutto il mondo. Per trovarli servono un animale addestrato e un vincastro da addestratore, anziché comuni utensili da cucina."},sec={{t="Una verga per roditori",b="Mebok Ghignofolle ha addestrato citelli tartasniffo a cercare Blueleaf Tubers nelle profondità delle Gallerie di Lamaspina. Le radici si nascondono sotto gallerie spinose, dove trovarle è quasi impossibile senza aiuto. Mebok è un mercante di Porto Paranco ed evita di entrare di persona nelle tane dei verrospini. Per questo dà agli avventurieri il Vincastro per Tartasniffo per guidare i citelli. Anche da cinquanta passi di distanza, il vincastro li dirige affinché fiutino e dissotterrino le radici."}},faq={{q="A cosa serve il Vincastro per Tartasniffo?",a="Il Vincastro per Tartasniffo guida un citello tartasniffo addestrato verso i Blueleaf Tubers nascosti nelle Gallerie di Lamaspina. Puntalo verso un citello e l'animale seguirà l'odore per dissotterrare le radici.",al={"come usare il vincastro di comando","cosa fa il vincastro di comando","scopo del vincastro di comando"}},{q="Dove si ottiene il Vincastro per Tartasniffo?",a="Ottieni il Vincastro per Tartasniffo a Porto Paranco, appena fuori dal laboratorio di Mebok Ghignofolle. Viene fornito insieme a una cassa contenente un citello addestrato e a un manuale di istruzioni.",al={"dove trovare il vincastro di comando","posizione del vincastro di comando","chi dà il vincastro di comando"}},{q="Perché Mebok Ghignofolle vuole i tuberi di foglia blu?",a="Mebok Ghignofolle cerca i Blueleaf Tubers perché sono rare prelibatezze che fruttano ingenti profitti grazie a facoltosi contatti gastronomici in tutto il mondo. Crescono nelle profondità delle Savane, in territorio verrospino, quindi assolda avventurieri per raccoglierli.",al={"perché i tuberi","scopo del tubero di foglia blu","perché mebok vuole i tuberi"}},{q="Si può tenere il bastone dopo aver trovato i tuberi?",a="No. Dopo aver raccolto i tuberi richiesti, restituisci il Vincastro per Tartasniffo e la cassa da trasporto a Mebok a Porto Paranco, insieme al raccolto.",al={"posso tenere il vincastro di comando","restituire il vincastro di comando"}}},fx={["8cc828c2"]={q="Che cos'è il Vincastro per Tartasniffo?",a="Il Vincastro per Tartasniffo è lo strumento brevettato per la gestione dei tartasnaf di Snuff Inc., fornito insieme ai tartasnaf addestrati dell'imprenditore goblin Mebok Ghignofolle a Porto Paranco. È progettato appositamente per dirigere i tartasnaf addestrati e dare loro il segnale di cercare prelibatezze nascoste e difficili da trovare, che una normale guida ignorerebbe del tutto.",al={"cos'è un vincastro","vincastro per tartasniffo","cos'è il vincastro per tartasniffo"}},["9fdd5faa"]={q="Da dove proviene il Vincastro per Tartasniffo e chi lo ha creato?",a="Il vincastro è un prodotto brevettato di Snuff Inc.; il proprietario Marwig Rustbolt ne spiega l'uso nel Manuale di Istruzioni del Tartasniffo. Mebok Ghignofolle, a Porto Paranco, ha addestrato i suoi tartasnaf a raccogliere prelibatezze rare e tiene insieme i vincastri, le gabbie e i manuali, così che i lavoratori assunti possano controllare adeguatamente le bestiole.",al={"chi ha creato il vincastro","origine del vincastro","da dove proviene il vincastro"}},fb1cfa60={q="Perché qualcuno vuole il Vincastro per Tartasniffo?",a="È impossibile individuare senza aiuto i rari tuberi Blueleaf sotto i rovi delle Gallerie di Lamaspina. Il vincastro è indispensabile perché induce un tartasnaf addestrato ad annusare fino a cinquanta passi di distanza e a dissotterrare i tuberi, che poi puoi riportare a Mebok Ghignofolle in cambio di una ricompensa generosa.",al={"perché serve il vincastro","perché si vuole il vincastro","perché procurarsi il vincastro per tartasniffo"}}},fp="25,93,17.432.0,47.178.0,50.166.0,45.247.0,54.141.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="Manuale di Istruzioni del Tartasniffo",s="Accanto a Mebok Ghignofolle a Porto Paranco, il Manuale di Istruzioni del Tartasniffo mostra come mandare un gopher addestrato alla ricerca dei Blueleaf Tubers nelle Gallerie di Lamaspina. Marwig Bullonaccio della Snuff Inc. lo ha scritto a questo scopo.",h="Accanto a Mebok Ghignofolle a Porto Paranco, il Manuale di Istruzioni del Tartasniffo mostra come mandare un...",kw={"tubero di foglia blu","gopher","manuale","mebok ghignofolle","porto paranco","gallerie di lamaspina","snufflenose"},ang={["profession:Cooking"]="Il manuale spiega come recuperare i Blueleaf Tubers, una radice sotterranea apprezzata come rara prelibatezza da buongustai e mercanti di tutta Azeroth."},sec={{t="Guida Operativa di un Goblin",b="Marwig Bullonaccio della Snuff Inc. ha scritto la guida per gestire i gopher snufflenose addestrati dell'azienda. Il loro olfatto acuto permette di trovare i Blueleaf Tubers sepolti sottoterra a cinquanta passi di distanza. Il manuale mostra come liberare un gopher da una cassa ventilata e guidarlo mentre scava con un bastone di comando. I cercatori lo conducono tra le spine e i cunicoli dei verrospini delle Gallerie di Lamaspina alla ricerca di tuberi."}},faq={{q="Qual è lo scopo del Manuale di Istruzioni del Tartasniffo?",a="Il manuale mostra come liberare il gopher snufflenose addestrato di Mebok Ghignofolle dalla sua cassa e guidarlo con un bastone di comando. Il gopher cerca i Blueleaf Tubers nelle Gallerie di Lamaspina.",al={"a cosa serve il manuale","perché leggere il manuale","scopo del manuale"}},{q="Dove posso trovare il manuale?",a="Puoi trovare il manuale a Porto Paranco accanto a Mebok Ghignofolle, alle casse e ai bastoni di comando usati per raccogliere i tuberi.",al={"posizione del manuale","dove si trova il libro","come ottenere il manuale"}},{q="Perché sono necessari i snufflenose gopher per trovare i Blueleaf Tubers?",a="I Blueleaf Tubers sono sepolti in profondità nelle Gallerie di Lamaspina, dove gli umanoidi riescono a malapena a individuarli. Un gopher addestrato può fiutarne uno a cinquanta passi di distanza.",al={"perché usare i gopher","si possono trovare i tuberi senza gopher"}},{q="Chi ha scritto il manuale?",a="Marwig Bullonaccio, proprietario della Snuff Inc., ha firmato il manuale. Lo ha scritto per insegnare ai nuovi proprietari come nutrire, portare a spasso e comandare i propri gopher con il bastone di comando brevettato.",al={"autore del manuale","chi l'ha creato"}}},fx={["1c231f00"]={q="Che cos'è il Manuale di Istruzioni del Tartasniffo?",a="È un manuale di istruzioni fornito insieme a un tartasnaf addestrato e a un vincastro. Guida gli avventurieri nell'uso della creatura nelle gallerie sotterranee delle Gallerie di Lamaspina e spiega come comandare al tartasnaf di fiutare gli introvabili tuberi Blueleaf sotterranei.",al={"cos'è il manuale di istruzioni del tartasniffo","identità del manuale del tartasniffo","cos'è il manuale"}}},fp="26,193,26.388.0,54.184.0,28.114.0,59.142.0,21.165.0"}
P.entries["item:sodium-nitrate"] = {n="Nitrato di Sodio",s="A Bael Modan, il Nitrato di Sodio entra nelle cariche che i nani usano contro la roccia delle Savane Meridionali. Gann Spira Dura cerca questa sostanza chimica per preparare cariche contro la fortezza.",h="A Bael Modan, il Nitrato di Sodio entra nelle cariche che i nani usano contro la roccia delle Savane...",kw={"bael modan","bael'dun","blackforge","gann spira dura","nitroglicerina","revenge of gann","nitrato di sodio","pasta di legno"},ang={["profession:Engineering"]="Gli ingegneri riconoscono nel Nitrato di Sodio, nella nitroglicerina e nella Pasta di Legno la ricetta della dinamite stabilizzata, alla base delle cariche improvvisate di Gann.",["race:Tauren"]="Da tauren, Gann Spira Dura ricorre alle sostanze chimiche naniche per vendicare la distruzione del suo territorio ancestrale."},sec={{t="Demolizione Industriale",b="A Bael Modan, gli scavatori nanici usano il Nitrato di Sodio per farsi strada nella roccia delle Savane Meridionali. La spedizione Bael'dun è entrata nelle terre ancestrali della tribù Spira Dura con macchine movimento terra e reagenti esplosivi. Fucilieri, soldati e ufficiali trasportano questa sostanza chimica all'interno degli scavi e nella vicina fortezza."},{t="Rovescio di Fronte e Ritorsione",b="Gann Spira Dura ha osservato gli invasori dopo che avevano devastato la terra natia della sua tribù e ha recuperato i loro schemi ingegneristici. Gli attacchi ordinari non potevano espugnare il mastio difeso, così il tauren esiliato rivolge contro i nani le loro scorte di esplosivi. Mescola il Nitrato di Sodio razziato con nitroglicerina e Pasta di Legno per creare cariche destinate a scuotere le fondamenta di Bael Modan."}},faq={{q="A cosa serve il Nitrato di Sodio nelle Savane?",a="I nani di Forgiardente usano il Nitrato di Sodio negli esplosivi per frantumare il terreno roccioso del loro sito di scavo. Gann Spira Dura lo mescola con nitroglicerina e Pasta di Legno per creare cariche contro Bael Modan.",al={"scopo del nitrato di sodio","a cosa serve il nitrato di sodio"}},{q="Da dove proviene il Nitrato di Sodio?",a="Le forze naniche di stanza a Bael Modan, nelle Savane Meridionali, trasportano Nitrato di Sodio. Fucilieri, soldati, ufficiali e comandanti come Lord Cyrik Blackforge ne tengono una scorta a portata di mano.",al={"chi rilascia il nitrato di sodio","dove trovare il nitrato di sodio"}},{q="Perché Gann Spira Dura ha bisogno di questa sostanza chimica?",a="Gann Spira Dura ha perso il suo villaggio ancestrale a causa degli scavi nanici. Senza pesanti macchine d'assedio, ha studiato i loro schemi e ha iniziato a preparare cariche capaci di abbattere le loro posizioni fortificate con le scorte dei nani stessi.",al={"perché gann vuole il nitrato di sodio","esplosivi di gann spira dura"}},{q="Il Nitrato di Sodio è pericoloso da solo?",a="Da solo, il Nitrato di Sodio è un ossidante e un sale chimico, non un esplosivo istantaneo. Mescolato con un combustibile e sostanze chimiche sensibili agli urti come la nitroglicerina, diventa pericoloso e instabile.",al={"il nitrato di sodio è un esplosivo"}}},fx={caaef0db={q="Che cos'è il Nitrato di Sodio?",a="Il nitrato di sodio è un agente chimico volatile conservato dalle forze di spedizione dei nani stanziate a Bael Modan. Pur essendo relativamente stabile se conservato, i nani lo usano come componente essenziale per preparare cariche esplosive di alta qualità, impiegate per far saltare la roccia compatta nei loro siti di scavo. Nelle mani di un sabotatore astuto, però, può essere facilmente riutilizzato per demolire la fortezza stessa.",al={"cos'è il nitrato di sodio","storia del nitrato di sodio","nitrato di sodio nelle savane"}}},fp="14,175,21.313.0,25.375.1,47.185.0,36.176.0,44.233.0,39.199.0"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="Appello di Solomon a Borgoscuro",s="Borgolago si rivolge a Borgoscuro mentre le minacce si fanno più vicine. Il Magistrato Solomon chiede a Ser Ello Serranero di inviare la Night Watch a nord e contribuire alla difesa di Redridge.",h="Borgolago si rivolge a Borgoscuro mentre le minacce si fanno più vicine.",kw={"borgoscuro","boscovespro","borgolago","ser ello serranero","magistrato solomon","messenger to darkshire","the night watch","redridge","appello di solomon"},ang={["faction:Alliance"]="Per l'Alleanza, l'appello di Solomon mostra come gli insediamenti meridionali cerchino aiuto gli uni dagli altri, mentre Roccavento offre scarso sostegno.",["race:Human"]="Come viaggiatore umano, porti un dispaccio che descrive il pericolo che minaccia Redridge e Boscovespro."},sec={{t="Una disperata richiesta d'aiuto",b="Orchi Roccianera, gnoll e murloc attaccano Borgolago, mentre da Roccavento arrivano pochi rinforzi. Il Magistrato Solomon invia un appello formale al sindaco Ello Serranero a Borgoscuro, chiedendogli di mandare la milizia della Night Watch a nord, a Redridge. Con il sostegno militare centrale che viene meno in tutta la parte meridionale di Azeroth, gli insediamenti umani devono aiutarsi a vicenda per sopravvivere."},{t="La tragica situazione di Borgoscuro",b="Borgoscuro fatica a difendere i propri confini dai non morti, dalle bestie fameliche e dall'oscurità che attanaglia Boscovespro. Le forze della Night Watch sono allo stremo, quindi la cittadina non può privarsi di difensori per Redridge quando arriva l'appello di Solomon."}},faq={{q="Cos'è l'Appello di Solomon a Borgoscuro?",a="L'urgente lettera del Magistrato Solomon a Ser Ello Serranero chiede alla Night Watch di contribuire alla difesa di Redridge contro gli orchi Roccianera e gli gnoll.",al={"lettera di solomon a borgoscuro","cos'è l'appello di solomon","lettera da borgolago a boscovespro"}},{q="Perché Borgolago chiede aiuto militare a Borgoscuro invece che a Roccavento?",a="Tra inerzia politica e lotte interne, Roccavento ha inviato poche truppe di guarnigione nei suoi territori periferici. Lasciato solo ad affrontare attacchi sempre più frequenti, il Magistrato Solomon cerca aiuto nelle vicine cittadine umane.",al={"perché chiedere a borgoscuro","perché non a roccavento","perché solomon ha bisogno di the night watch"}},{q="Chi è Ser Ello Serranero?",a="Ser Ello Serranero è il sindaco di Borgoscuro e la principale autorità civile di Boscovespro. Amministra la cittadina e coordina la Night Watch, la sua forza di difesa civile contro i pericoli dei boschi.",al={"chi è serranero","sindaco di borgoscuro","ser ello"}},{q="Borgoscuro può davvero fare a meno di The Night Watch per aiutare Borgolago?",a="No. Boscovespro deve affrontare non morti, worgen ferini e magia oscura, e la Night Watch riesce a malapena a difendere il perimetro di Borgoscuro. Non può privarsi di combattenti per mandarli a Redridge.",al={"borgoscuro aiuta","arriverà the night watch","serranero ha inviato guardie"}}},fx={a3b7e1d6={q="Da dove proviene l'Appello di Solomon a Borgoscuro e chi l'ha scritto?",a="La lettera fu scritta direttamente dal Magistrato Solomon, il capo della città di Borgolago, a Crestarossa. Con gli orchi del Martello del Crepuscolo che premono sulla città e Roccavento incapace di inviare rinforzi reali, Solomon scrisse di persona l'appello urgente dal municipio di Borgolago, nella speranza di ottenere aiuto dagli insediamenti vicini.",al={"chi ha scritto l'appello di solomon","origine dell'appello di solomon a borgoscuro","chi ha creato l'appello di solomon"}},["5061acb5"]={q="Perché Ser Ello Serranero vuole l'Appello di Solomon a Borgoscuro?",a="Ser Ello Serranero ha bisogno della lettera perché descrive ufficialmente la disperata difesa di Borgolago e la richiesta diretta di assistenza militare del Magistrato Solomon. In quanto sindaco di Borgoscuro e comandante della The Night Watch, Serranero si affida a dispacci ufficiali come questo per comprendere le minacce che affrontano i loro vicini dell'Alleanza e valutare se la città può permettersi di inviare delle guardie.",al={"perché consegnare l'appello di solomon","perché serranero ha bisogno della lettera","scopo dell'appello di solomon a borgoscuro"}}},fp="27,149,24.361.0,23.222.1,36.139.0,73.206.0,27.193.0,63.165.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="Appello di Solomon alle Marche Occidentali",s="A Borgolago, il Magistrato Solomon chiede aiuto alle Marche Occidentali mentre gli orchi Roccianera e gli gnoll minacciano Crestarossa. L'esercito reale di Roccavento non ha risposto, così chiede a Gryan Stoutmantle di inviare la People's Militia.",h="A Borgolago, il Magistrato Solomon chiede aiuto alle Marche Occidentali mentre gli orchi Roccianera e gli...",kw={"gryan stoutmantle","borgolago","magistrato solomon","the people's militia","crestarossa","appello di solomon","esercito di roccavento","marche occidentali"},ang={["faction:Alliance"]="Per l'Alleanza, l'appello di Solomon mostra come le cittadine periferiche si rivolgano ai volontari locali quando le truppe reali non arrivano.",["race:Human"]="In quanto umano, puoi vedere quanto siano ormai in difficoltà gli insediamenti rurali. La scomparsa del re e l'incuria politica lasciano vulnerabili le terre di frontiera."},sec={{t="Una disperata richiesta di aiuto",b="Gli orchi Roccianera e gli gnoll ostili minacciano Crestarossa, mentre il Magistrato Solomon è isolato a Borgolago. L'esercito reale di Roccavento non è giunto in forze a difendere i confini della regione. Non potendo attendere la capitale, Solomon scrive per cercare aiuto al di fuori dell'esercito regolare. Gli è giunta notizia di una forza difensiva di volontari che si sta formando a Elwynn, a ovest, così si rivolge alla People's Militia."},{t="Oltre il confine",b="Solomon indirizza il suo messaggio a Gryan Stoutmantle, un guerriero veterano che organizza la difesa della frontiera delle Marche Occidentali. Spera che Stoutmantle possa inviare alcuni combattenti a Borgolago finché Roccavento non manderà le riserve dell'esercito regolare. Un avventuriero trasporta il documento. I territori periferici di Roccavento sono scarsamente coordinati, così i magistrati locali devono organizzare da soli gli aiuti reciproci."}},faq={{q="Cos'è l'Appello di Solomon alle Marche Occidentali?",a="Il Magistrato Solomon di Borgolago scrive a Gryan Stoutmantle e chiede alla People's Militia nelle Marche Occidentali di inviare rinforzi per difendere Crestarossa.",al={"cos'è l'appello di solomon","lettera appello di solomon alle marche occidentali","lettera borgolago marche occidentali"}},{q="Perché il Magistrato Solomon chiede aiuto alle Marche Occidentali invece che a Roccavento?",a="Le truppe reali di Roccavento non sono giunte in forze mentre il pericolo cresce a Borgolago. Non potendo attendere la Corona, Solomon cerca aiuto presso una forza combattente nelle vicinanze.",al={"perché chiedere alle marche occidentali","perché non chiedere a roccavento","perché inviare l'appello alle marche occidentali"}},{q="Chi è Gryan Stoutmantle?",a="Gryan Stoutmantle guida la People's Militia, una lega difensiva di volontari composta da contadini e coloni locali che protegge le Marche Occidentali dalla Fratellanza dei Defias.",al={"chi è stoutmantle","ruolo di gryan stoutmantle"}},{q="Quali minacce stanno spingendo Solomon a inviare questa lettera?",a="Gli orchi Roccianera stanno invadendo la regione e gli gnoll compiono razzie in tutte le Montagne Crestarossa. I loro attacchi mettono a dura prova la guardia cittadina di Borgolago.",al={"perché borgolago è in pericolo","cosa minaccia crestarossa"}}},fx={["7804da1c"]={q="Da dove proviene l'Appello di Solomon alle Marche Occidentali e chi l'ha scritto?",a="La lettera è stata scritta direttamente dal Magistrato Solomon a Borgolago, la città assediata nelle Montagne Crestarossa. Disperato dopo che l'esercito di Roccavento non ha inviato i rinforzi promessi per difendere il suo popolo, Solomon ha scritto di persona questo messaggio urgente per implorare aiuto agli alleati vicini.",al={"chi ha scritto l'appello di solomon alle marche occidentali","da dove proviene l'appello di solomon","autore dell'appello di solomon"}},["6d6e291d"]={q="Perché Gryan Stoutmantle vuole l'Appello di Solomon alle Marche Occidentali?",a="Gryan Stoutmantle guida The People's Militia nelle Marche Occidentali e questo dispaccio lo informa della grave situazione di Borgolago. Solomon spera che la milizia possa inviare combattenti per rinforzare le difese ormai ridotte di Crestarossa, mentre la città attende notizie e truppe dalla corte di Re Anduin a Roccavento.",al={"perché consegnare l'appello di solomon","perché stoutmantle vuole l'appello","a cosa serve la lettera"}}},fp="26,207,24.381.0,26.355.0,35.148.0,72.165.0,25.151.0,53.124.0"}
P.entries["item:soran-ruk-fragment"] = {n="Frammento di Soran'ruk",s="Negli Abissi di Fondocupo, i cultisti attingono alle schegge di Soran'ruk, un globo prigione infranto. I frammenti racchiudono ancora l'energia vile del demone un tempo imprigionato al suo interno.",h="Negli Abissi di Fondocupo, i cultisti attingono alle schegge di Soran'ruk, un globo prigione infranto.",kw={"abissi di fondocupo","doan karhan","fel","globo di soran'ruk","soran'ruk","soranruk","twilight acolyte"},ang={["class:Warlock"]="Come stregone, puoi usare ricettacoli prigione demoniaci come il Globo di Soran'ruk per incanalare energia vile pura senza soggiogare direttamente un demone."},sec={{t="Una prigione infranta",b="Il globo prigione di Soran'ruk andò in frantumi dopo che il demone cadde in disgrazia presso la Legione Infuocata. Gli spiriti dei demoni che scontentano i propri padroni possono essere sigillati in globi, poi affidati a incantatori vili come fonti di potere. Nelle rovine sommerse degli Abissi di Fondocupo, i cultisti del Martello del Crepuscolo possiedono schegge più piccole provenienti da una metà del globo. Attingono all'essenza demoniaca residua per i propri incantesimi."},{t="Ricostruzione nelle Savane",b="Ogni frammento conserva una traccia della vitalità del demone imprigionato. Doan Karhan, uno studioso schivo delle Savane Meridionali, ha trascorso una vita a studiare i ricettacoli demoniaci. Possiede un globo simile, il Globo di Zargain. Uno stregone ambizioso può portargli tre piccoli frammenti e il pezzo più grande custodito a Silverpine. Doan può riforgiare la reliquia per renderla nuovamente integra e farne uno strumento di potere."}},faq={{q="Cos'è Soran'ruk?",a="Soran'ruk era un demone della Legione Infuocata caduto in disgrazia presso i suoi capi. Per punizione, il suo spirito fu estratto e intrappolato in un globo cristallino. Stregoni e maghi mortali usavano il globo come fonte di energia.",al={"chi è soranruk","storia di soran'ruk","soranruk è un demone"}},{q="Dove si trovano questi frammenti?",a="I Twilight Acolytes portano con sé le schegge più piccole attraverso le sale cavernose degli Abissi di Fondocupo, lungo la Spiaggia di Zoram.",al={"dove trovare frammento di soran'ruk","chi rilascia frammenti di soran'ruk","posizione frammento di soran'ruk"}},{q="Perché il Martello del Crepuscolo possiede queste schegge?",a="I cultisti del Martello del Crepuscolo raccolgono le schegge per l'essenza magica del demone intrappolato. Usano manufatti corrotti per alimentare i loro oscuri rituali e incanalare magie proibite.",al={"perché i cultisti ce l'hanno","martello del crepuscolo soranruk"}},{q="Chi può ripristinare il Globo di Soran'ruk?",a="Doan Karhan può ricostruire il Globo di Soran'ruk. L'eremita solitario vive nelle Savane Meridionali, vicino al confine con Millepicchi. Studia e riforgia i globi demoniaci della Legione Infuocata.",al={"chi ripara il globo","dove consegnare frammento di soran'ruk","globo di doan karhan"}}},fx={["49c59cce"]={q="Da dove provengono i Frammenti di Soran'ruk e chi li ha creati?",a="Sono i resti frantumati del Globo di Soran'ruk, un ricettacolo demoniaco forgiato dalla Legione Infuocata. Quando i demoni cadono in disgrazia, la Legione imprigiona i loro spiriti in globi di questo tipo e li affida ai suoi maghi e stregoni. Il Globo di Soran'ruk fu poi spezzato e i frammenti più piccoli finirono nelle mani degli accoliti del Martello del Crepuscolo negli Abissi di Fondocupo.",al={"origine del frammento di soran'ruk","chi ha creato i frammenti di soran'ruk","da dove provengono i frammenti di soran'ruk"}},["5e1e8c12"]={q="Perché qualcuno vuole i Frammenti di Soran'ruk?",a="Anche ridotti in schegge, i frammenti vibrano ancora dell'essenza e del potere del demone intrappolato. Lo stregone eremita Doan Karhan, nelle Savane, ha dedicato la vita allo studio e alla ricostruzione dei globi della Legione. Se gli porti queste schegge più piccole insieme al frammento più grande proveniente dal Forte di Zannascura, potrà riforgiare il Globo di Soran'ruk e trasformarlo in uno strumento potente per la tua professione.",al={"perché raccogliere i frammenti di soran'ruk","chi vuole i frammenti di soran'ruk","perché servono i frammenti di soran'ruk"}}},fp="18,150,18.407.0,29.373.1,18.217.0,32.115.0,49.168.0,37.191.0"}
P.entries["item:southsea-treasure"] = {n="Tesoro dei Mari del Sud",s="Il Tesoro dei Mari del Sud si trova su una nave pirata a sud di Porto Paranco, dove Wrenix il Miserabile cerca il bottino. La stiva più bassa della Tide Razor si trova sotto l'area di addestramento dei Southsea Freebooters.",h="Il Tesoro dei Mari del Sud si trova su una nave pirata a sud di Porto Paranco, dove Wrenix il Miserabile...",kw={"e.c.a.c.","scassinamento","polly","porto paranco","the shattered hand","tesoro dei mari del sud","tide razor","wrenix il miserabile"},ang={["class:Rogue"]="Per un ladro in formazione, recuperare il Tesoro dei Mari del Sud offre pratica nello scassinamento e un primo contatto con la Shattered Hand, un'organizzazione clandestina.",["faction:Horde"]="Come membro dell'Orda, puoi aiutare le autorità locali compromettendo la scorta di bottino dei Southsea Freebooters. I pirati ostacolano i commerci nelle Savane e nei dintorni del porto di Porto Paranco."},sec={{t="Un colpo mortale",b="La Tide Razor è ancorata lungo la Costa dei Mercanti, a sud di Porto Paranco. I Southsea Freebooters la usano come base avanzata e area di addestramento. Il loro bottino, chiamato Tesoro dei Mari del Sud, attende nella stiva più bassa.\n\nWrenix il Miserabile, una canaglia goblin di Porto Paranco, propone il furto come prova per gli aspiranti borseggiatori. Dice che gli ultimi cinque agenti inviati a recuperare il forziere sono tornati a pezzi. Pirati vigili sorvegliano la nave e una creatura feroce fa la guardia alla stiva."},{t="Il ricordo di Polly",b="Polly sorveglia il Tesoro dei Mari del Sud nella stiva. I ladri che eludono gli addestratori pirati e scassinano il forziere trovano il pappagallo ostile invece di un tesoro da raccogliere.\n\nIl dispositivo E.C.A.C. di Wrenix può aiutare a sconfiggere Polly. Solo allora è possibile prelevare il tesoro dalla stiva e riportarlo intatto a Porto Paranco."}},faq={{q="Dove si trova il Tesoro dei Mari del Sud?",a="Il Tesoro dei Mari del Sud è a bordo della Tide Razor, ancorata lungo la costa a sud di Porto Paranco, nelle Savane. Si trova nella stiva più bassa, sotto i locali di addestramento dei pirati.",al={"dove si trova il tesoro","posizione tide razor","come trovare il tesoro dei mari del sud"}},{q="Chi vuole il Tesoro dei Mari del Sud?",a="Wrenix il Miserabile, un goblin di Porto Paranco, vuole il Tesoro dei Mari del Sud. Assolda agenti segreti perché si introducano nella nave e lo recuperino per lui.",al={"chi assegna la missione","chi è wrenix","chi lo vuole"}},{q="Perché la cassa è vuota una volta scassinata?",a="Polly sorveglia il Tesoro dei Mari del Sud nella stiva. Scassinare il forziere fa entrare in combattimento il feroce pappagallo; sconfiggere Polly permette di ottenere il tesoro.",al={"da dove viene polly","perché è apparsa polly","perché il tesoro non è nella cassa"}},{q="Cos'è un E.C.A.C. e perché è necessario?",a="Wrenix il Miserabile fornisce l'E.C.A.C., un dispositivo sperimentale goblin progettato per indebolire minacce volanti insolitamente feroci. Intende usarlo contro Polly, il letale pappagallo guardiano nella stiva della nave.",al={"cos'è l'ecac","come sconfiggere polly","pappagallo ostile"}},{q="A cosa serve la nave ai Southsea Freebooter?",a="La Tide Razor è una base e un covo di ladri dei Southsea Freebooters. Al secondo livello, alcune cassette da scassinare offrono all'equipaggio un posto dove addestrare i propri borseggiatori.",al={"cos'è la tide razor","covo pirata savane","stiva nave mari del sud"}}},fx={c9f033cd={q="Che cos'è il Tesoro dei Mari del Sud?",a="Il Tesoro dei Mari del Sud è il bottino accumulato dai Predoni dei Mari del Sud a bordo della loro nave, la Tide Razor, ancorata al largo delle coste delle Savane. Custodito nelle profondità della stiva e protetto dal notoriamente feroce pappagallo pirata Polly, rappresenta i guadagni illeciti accumulati dai corsari durante le loro scorrerie lungo la Costa dei Mercanti.",al={"cos'è il tesoro dei mari del sud","oggetto tesoro dei mari del sud","che tipo di tesoro è il tesoro dei mari del sud"}}},fp="17,189,14.462.0,16.299.1,39.172.0,32.139.0,35.155.1,41.195.0,50.159.0"}
P.entries["item:spectral-comb"] = {n="Pettine Spettrale",s="A sud di Borgoscuro, il Pettine Spettrale raccoglie i capelli spettrali di Mary la Cieca in una fattoria in rovina.",h="A sud di Borgoscuro, il Pettine Spettrale raccoglie i capelli spettrali di Mary la Cieca in una fattoria in...",kw={"mary la cieca","pettine","borgoscuro","boscovespro","fantasma","filo di capelli spettrali","pettine spettrale"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, puoi portare il pettine a sud di Borgoscuro e scoprire il tragico destino degli antichi coloni di Boscovespro.",["profession:Tailoring"]="Come sarto, puoi usare il Pettine Spettrale per raccogliere fibre eteree da fantasmi consenzienti invece di tosarli con mezzi ordinari."},sec={{t="Uno strumento per i morti senza riposo",b="I comuni pettini non possono raggiungere i capelli di uno spirito, perciò pochi artigiani mortali riescono a raccoglierli. Il Pettine Spettrale attraversa quelle chiome invisibili. In una fattoria in rovina a sud di Borgoscuro, viene offerto a Mary la Cieca, un fantasma in lacrime che si lamenta in solitudine. Pettinarsi le dà conforto e lei prende volentieri il pettine. Le fibre che lascia possono essere tessute per ottenere il Filo di Capelli Spettrali."}},faq={{q="A cosa serve il Pettine Spettrale?",a="Consegni il Pettine Spettrale a Mary la Cieca, un fantasma in lacrime a sud di Borgoscuro. Mentre lei si pettina, il pettine raccoglie capelli eterei che possono essere filati per ottenere un filo soprannaturale.",al={"scopo del pettine spettrale","perché serve il pettine spettrale","cosa fa il pettine"}},{q="Chi è Mary la Cieca?",a="Mary la Cieca è uno spirito tormentato che infesta una casa abbandonata sulle colline a sud di Borgoscuro. Impazzita per una tragedia, si è strappata gli occhi e teme che gli altri la trovino ripugnante nella morte.",al={"storia di mary la cieca","chi è il fantasma con il pettine","mary la cieca"}},{q="Perché non si può usare un pettine ordinario?",a="Un comune pettine non può toccare i capelli intangibili di uno spirito. Il Pettine Spettrale attraversa la chioma di un'apparizione.",al={"perché pettine spettrale","pettine normale fantasma"}}},fx={e893aa2f={q="Che cos'è il Pettine Spettrale?",a="Il Pettine Spettrale è uno strumento etereo per la toelettatura, incantato appositamente per interagire con gli esseri incorporei. Mentre gli strumenti normali attraverserebbero un fantasma senza alcun effetto, questo pettine può toccare, districare e raccogliere i capelli spettrali di un fantasma.",al={"cos'è il pettine spettrale","pettine spettrale","identità del pettine spettrale"}}},fp="13,95,24.375.0,35.177.0,18.186.0,37.119.0"}
P.entries["item:spells-of-shadow"] = {n="Incantesimi dell'Ombra",s="Sotto Orgrimmar, Incantesimi dell'Ombra si trova tra i tesori sorvegliati della Lama Rovente. I capi dei Reietti a Sepulcra vogliono recuperarlo.",h="Sotto Orgrimmar, Incantesimi dell'Ombra si trova tra i tesori sorvegliati della Lama Rovente.",kw={"incanti del fatuo","baratro di fiamma furente","lama rovente","incantesimi dell'ombra","sylvanas","il potere di distruggere","sepulcra","varimathras"},ang={["class:Warlock"]="Come stregone, vedi come i cultisti della Lama Rovente praticano le arti dell'ombra e del fatuo grazie ai doni demoniaci della Legion.",["race:Undead"]="Come non morto, aiuti Dama Sylvanas a impadronirsi di pericolose conoscenze demoniache sotto Orgrimmar. Il loro potere è destinato a rafforzare Sepulcra contro il Flagello."},sec={{t="Tomi della Lama Rovente",b="Nel Baratro di Fiamma Furente, i cultisti della Lama Rovente custodiscono Incantesimi dell'Ombra tra i loro tesori. La setta scissionista è legata al Concilio dell'Ombra e i suoi membri praticano oscuri riti concessi dai signori demoniaci della Legione Infuocata. Il libro racchiude stregonerie dell'ombra e del vile. Cultisti e stregoni lo tengono a portata di mano mentre complottano sotto i piedi dell'Orda a Durotar."},{t="L'ambizione della Dama Oscura",b="La notizia dei doni demoniaci della Lama Rovente giunse alle stanze reali di Sepulcra. Dama Sylvanas Ventolesto e il suo luogotenente signore del terrore, Varimathras, giudicarono le reliquie sprecate nelle mani di cultisti dalle vedute limitate. Così Varimathras invia gli avventurieri dell'Orda nel Baratro di Fiamma Furente per impadronirsi di Incantesimi dell'Ombra e del tomo che lo accompagna, Incanti del Fatuo. Il loro potere è destinato a servire la causa dei Reietti contro il Flagello e il Re dei Lich."}},faq={{q="Che cos'è Incantesimi dell'Ombra?",a="I cultisti della Lama Rovente custodiscono Incantesimi dell'Ombra nel Baratro di Fiamma Furente. Il grimorio contiene magia dell'ombra concessa dalla Legione Infuocata.",al={"libro incantesimi dell'ombra","cos'è incantesimi dell'ombra","libro incantesimi dell'ombra rfc"}},{q="Chi vuole questo libro?",a="Varimathras cerca Incantesimi dell'Ombra per Dama Sylvanas Ventolesto. Il suo consigliere, un signore del terrore, risiede nel Quartiere Reale di Sepulcra.",al={"a chi serve incantesimi dell'ombra","a chi consegnare incantesimi dell'ombra","chi assegna la missione incantesimi dell'ombra"}},{q="Dove si può trovare il libro?",a="I cultisti e gli stregoni della Lama Rovente portano con sé Incantesimi dell'Ombra nel Baratro di Fiamma Furente, le caverne infuocate sotto Orgrimmar.",al={"posizione di incantesimi dell'ombra","dove trovare incantesimi dell'ombra","come ottenere incantesimi dell'ombra"}},{q="Perché i Reietti vogliono questo grimorio?",a="Dama Sylvanas crede che gli oscuri doni della Legion spettino ai Reietti anziché a cultisti di minor valore. Vuole che la magia rafforzi i Reietti contro il Flagello e il Re dei Lich.",al={"perché sylvanas vuole il libro","perché varimathras vuole incantesimi dell'ombra"}}},fp="16,148,26.335.0,24.437.0,29.130.0,20.133.0,28.114.0,39.193.0"}
P.entries["item:spotted-sunfish"] = {n="Pesce Mola Maculato",s="Al Lago Placido, i Pesci Mola Maculati attirano pescatori e murloc affamati. La loro pesca alimenta il commercio di Borgolago, mentre i murloc rendono pericolose le acque basse.",h="Al Lago Placido, i Pesci Mola Maculati attirano pescatori e murloc affamati.",kw={"dockmaster baren","lago placido","borgolago","murloc","montagne crestarossa","selling fish","pesce mola maculato"},ang={["profession:Cooking"]="Come cuoco, puoi usare il Pesce Mola Maculato, un pesce d'acqua dolce originario di Redridge."},sec={{t="Una Cattura Pregiata",b="I Pesci Mola Maculati alimentano il commercio ai moli di Borgolago. Il Capomolo Baren acquista il pescato regolare del lago, fornendo cibo e scambi commerciali a una cittadina sotto pressione. Tribù di murloc aggressivi si aggirano nelle acque basse e ostacolano la pesca. Nei loro accampamenti, i viaggiatori possono prendere con la forza i pesci mola che i murloc hanno raccolto."}},faq={{q="Dove si trovano i Pesci Mola Maculati?",a="I Pesci Mola Maculati vivono nel Lago Placido, nelle Montagne Crestarossa. I pescatori li catturano lì, mentre i murloc li raccolgono negli accampamenti lungo le rive.",al={"dove trovare il pesce mola maculato","posizione pesce mola maculato","pesce del lago placido"}},{q="Chi compra o ha bisogno di Pesci Mola Maculati?",a="Il Capomolo Baren acquista Pesci Mola Maculati ai moli di Borgolago. Commercia in questi pesci e paga per scorte fresche.",al={"chi vuole il pesce mola maculato","pesce del capomolo baren","missione selling fish"}},{q="Perché i murloc portano con sé questi pesci?",a="I murloc lungo il Lago Placido raccolgono pesci mola per nutrire le loro tribù in crescita. Conservano il pescato negli accampamenti lungo le acque basse.",al={"pesce mola maculato dei murloc","perché i murloc rilasciano pesci"}},{q="È possibile ottenerli senza pescare?",a="Sì. I viaggiatori senza una canna da pesca possono sconfiggere i murloc ostili lungo le rive del Lago Placido e prendere i pesci che hanno raccolto.",al={"ottenere pesce mola senza canna da pesca","pesce mola senza canna da pesca"}}},fx={["723094c5"]={q="Che cos'è il Pesce Mola Maculato?",a="Il Pesce Mola Maculato è un pregiato pesce d'acqua dolce originario del Lago Placido, nelle Montagne Crestarossa. Rinomato in tutta la regione per il suo sapore e il suo valore commerciale, prospera nelle acque profonde del lago ed è una merce fondamentale per i pescatori di Borgolago, oltre che una delle principali fonti di cibo per i murloc locali.",al={"cos'è il pesce mola maculato","informazioni sul pesce mola maculato","storia del pesce mola maculato"}},["1a933976"]={q="Da dove proviene il Pesce Mola Maculato?",a="Il Pesce Mola Maculato vive naturalmente nelle fresche acque del Lago Placido, nelle Montagne Crestarossa. Non viene creato né allevato: è un pesce selvatico pescato direttamente nel lago, con la lenza lungo i moli e le rive oppure strappato dalle grinfie dei bracconieri murloc locali.",al={"origine del pesce mola maculato","da dove proviene il pesce mola maculato","provenienza del pesce mola maculato"}}},fp="15,149,14.293.0,32.145.0,34.109.0,36.126.0,36.137.0"}
P.entries["item:stalker-claws"] = {n="Artiglio di Inseguitore",s="A Mulgore, gli sciamani tauren usano l'Artiglio di Inseguitore in un rito per purificare i pozzi contaminati. Legano gli artigli ai totem che purificano l'acqua avvelenata.",h="A Mulgore, gli sciamani tauren usano l'Artiglio di Inseguitore in un rito per purificare i pozzi contaminati.",kw={"totem della purificazione","mulgore","mull corno tonante","inseguitore delle praterie","artiglio di inseguitore","thunderhorn totem","pozzo d'acqua"},ang={["class:Shaman"]="Come sciamano, infondi nei totem della purificazione la fiera purezza dei predatori selvatici delle pianure. I loro artigli conferiscono potere ai totem.",["race:Tauren"]="Come tauren, raccogliendo questi artigli aiuti la tua tribù a risanare le sue acque sacre, avvelenate da invasori dediti all'industria senza alcun riguardo."},sec={{t="Predatori delle Pianure",b="Gli inseguitori delle praterie cacciano nelle steppe erbose di Mulgore. La furtività e la precisione li rendono letali, eppure mantengono un equilibrio necessario nel disegno della Madre Terra. A Mull Corno Tonante servono i loro artigli per contribuire a risanare la terra contaminata. Non desidera fare del male alle bestie, poiché la forza naturale della loro caccia racchiude il vigore spirituale necessario a contrastare la corruzione artificiale."},{t="Purificare i Pozzi",b="Le trivellazioni e gli scavi minerari dei goblin nel centro di Kalimdor hanno riversato veleni chimici nelle acque sotterranee che alimentano i pozzi ancestrali dei tauren. Il Pozzo dei Corno Tonante è contaminato da una melma immonda. Gli sciamani tribali legano l'Artiglio di Inseguitore e l'Artiglio di Puma a un Totem Purificatore dei Corno Tonante. Il totem ripulisce le sorgenti della terra dalla melma innaturale."}},faq={{q="Da dove provengono gli Artigli di Inseguitore?",a="Gli inseguitori delle praterie vagano sulle colline erbose di Mulgore, soprattutto a est e a ovest del Villaggio di Zoccolo Sanguinario. I loro artigli si raccolgono cacciandoli.",al={"dove trovare gli artigli di inseguitore","chi rilascia gli artigli di inseguitore","fonte degli artigli di inseguitore"}},{q="Perché a Mull Corno Tonante servono questi artigli?",a="A Mull Corno Tonante servono l'Artiglio di Inseguitore e gli artigli dei puma delle pianure per creare un Totem Purificatore dei Corno Tonante. La purezza e la forza dei predatori locali aiutano a purificare i pozzi avvelenati.",al={"perché raccogliere gli artigli di inseguitore","scopo di mull corno tonante","uso degli artigli di inseguitore"}},{q="Perché il Pozzo dei Corno Tonante è contaminato?",a="Le attività dei goblin a Mulgore causano un inquinamento industriale innaturale. Il loro lavoro sconvolge l'equilibrio naturale e avvelena la falda acquifera locale.",al={"chi ha avvelenato il pozzo","perché il pozzo dei corno tonante è contaminato","inquinamento dei corno tonante"}},{q="Cosa succede dopo aver raccolto gli artigli?",a="Mull intaglia gli artigli raccolti per creare un totem della purificazione. Il totem va poi portato direttamente al Pozzo dei Corno Tonante per eliminare la corruzione che vi permane.",al={"what comes next","fase successiva dopo gli artigli","rituale del totem della purificazione"}}},fx={a496bd75={q="Cosa sono gli Artigli di Inseguitore?",a="Gli Artigli di Inseguitore sono gli artigli naturali ricavati dagli inseguitori della prateria, feroci predatori felini che vagano per le pianure di Mulgore. Per gli estranei sono semplici trofei di caccia, ma gli sciamani tauren li considerano l'incarnazione dell'istinto predatorio della creatura e della sua armonia con la terra.",al={"cosa sono gli artigli di inseguitore","oggetto artigli di inseguitore","artiglio di inseguitore"}}},fp="13,148,23.364.0,19.338.0,33.136.0,43.173.0,42.141.0,42.152.0"}
P.entries["item:steelgrill-s-tools"] = {n="Attrezzi di Grigliafredda",s="Allo Scalo di Grigliafredda, Beldin Grigliafredda ha bisogno di nuovi attrezzi per mantenere operativa la sua officina. Sottopone macchine d'assedio e attrezzature a un uso intenso, così Kharanos continua a inviare ricambi.",h="Allo Scalo di Grigliafredda, Beldin Grigliafredda ha bisogno di nuovi attrezzi per mantenere operativa la sua...",kw={"beldin","scalo","kharanos","porto paranco","macchina d'assedio","chiave inglese","grigliafredda","attrezzi"},ang={["profession:Engineering"]="Come ingegnere, sai quanto le riparazioni delle pesanti macchine d'assedio consumino le chiavi ad arco e le chiavi più delicate.",["race:Dwarf"]="Come nano, conosci l'orgoglio di mantenere operative le macchine d'assedio corazzate dell'Alleanza. Rifornire Beldin aiuta la vanguardia corazzata di Forgiardente a restare pronta al combattimento."},sec={{t="Un artigiano dai modi bruschi",b="Beldin Grigliafredda è uno dei migliori tecnici di macchine d'assedio di Dun Morogh. I mercanti, però, conoscono i suoi modi bruschi. Lavora senza sosta su carri armati e congegni meccanici, e gli attrezzi delicati si rompono presto tra le sue mani. Le chiavi ad arco si spezzano e i cricchetti dentati si consumano, così continua a ordinare ricambi da Kharanos per i suoi banchi di riparazione."},{t="Mantenere i motori in marcia",b="Nel suo scalo a nord-est di Kharanos, Beldin esegue la manutenzione dei veicoli da combattimento per piloti esperti come il Pilota Grancingolo. Gli attrezzi mantengono operative le macchine da guerra di Forgiardente. Nuove chiavi e nuovi cricchetti permettono di proseguire le riparazioni delle macchine d'assedio assemblate sul posto, sostenendo le difese locali."}},faq={{q="A cosa servono gli Attrezzi di Grigliafredda?",a="Gli attrezzi sostituiscono gli strumenti da meccanico usurati dello Scalo di Grigliafredda. Beldin Grigliafredda li usa per revisionare i pesanti macchinari nanici, compresa la macchina d'assedio danneggiata del Pilota Grancingolo.",al={"cosa sono questi attrezzi","scopo attrezzi di grigliafredda"}},{q="Perché Beldin Grigliafredda consuma così tanti attrezzi?",a="Beldin lavora con modi bruschi e mette a dura prova i suoi attrezzi. Le chiavi ad arco si spezzano e i cricchetti dentati si rompono così spesso che i fornitori di Kharanos faticano a tenere il passo.",al={"perché utensili rotti","perché beldin ha bisogno di attrezzi"}},{q="Da dove proviene questa cassa di attrezzi?",a="La cassa viene assemblata e riempita nella vicina Kharanos, poi trasportata a nord-est fino allo Scalo di Grigliafredda.",al={"dove trovo gli attrezzi","origine spedizione attrezzi"}},{q="Chi è Beldin Grigliafredda?",a="Beldin è un maestro meccanico nano che gestisce lo Scalo di Grigliafredda a nord-est di Kharanos. È considerato il miglior tecnico di macchine d'assedio della regione.",al={"chi è beldin","storia di beldin grigliafredda"}}},fx={["8eb066d8"]={q="Cosa sono gli Attrezzi di Grigliafredda?",a="Gli Attrezzi di Grigliafredda sono una fornitura appena imballata di pesanti attrezzature meccaniche, tra cui chiavi arcobaleno e cricchetti a zanna. Sono stati preparati per essere consegnati direttamente a Beldin Grigliafredda, il tecnico esperto di macchine d'assedio che lavora allo Scalo di Grigliafredda, vicino a Kharanos.",al={"cosa sono gli attrezzi di grigliafredda","cassa degli attrezzi di grigliafredda"}},["11454cb4"]={q="Perché Beldin Grigliafredda ha bisogno di questa cassa di attrezzi?",a="Beldin è un meccanico esperto, ma mette a dura prova i suoi attrezzi mentre ripara macchinari pesanti. Ha appena spezzato il suo ultimo cricchetto a zanna e ha urgente bisogno di questa nuova fornitura per completare riparazioni fondamentali alle macchine d'assedio, come quelle di Pilota Grancingolo.",al={"perché beldin vuole gli attrezzi","perché servono gli attrezzi di grigliafredda","perché vogliono gli attrezzi"}}},fp="18,182,24.349.0,27.287.0,37.180.0,52.151.0,40.99.0,25.147.0"}
P.entries["item:steelsnap-s-rib"] = {n="Costola di Ganascia",s="A Millepicchi, la Costola di Ganascia testimonia la fine di una iena temuta. Melor Zoccolo Granitico, a Picco del Tuono, vuole che venga portata all'Altura dei Cacciatori per dimostrare che Steelsnap è stato ucciso.",h="A Millepicchi, la Costola di Ganascia testimonia la fine di una iena temuta.",kw={"accampamento e'thok","altura dei cacciatori","iena","melor zoccolo granitico","steelsnap","costola di ganascia","millepicchi","picco del tuono"},ang={["class:Hunter"]="Come cacciatore, seguire le tracce di Steelsnap mette alla prova la tua abilità contro un pericoloso capobranco. Aiuta anche a eliminare una minaccia per l'equilibrio della natura.",["race:Tauren"]="Come tauren, riportare la Costola di Ganascia significa adempiere al tuo dovere verso la Madre Terra. Elimini una creatura crudele che contamina il sacro equilibrio."},sec={{t="Una Caccia al di Fuori della Benedizione",b="I tauren cacciano spesso per procurarsi cibo, ottenere onore o cercare l'armonia con la natura. Steelsnap è un'altra faccenda. La iena alfa si aggira sul fondo del canyon a sud dell'Accampamento E'thok, a Millepicchi. Terrorizza la fauna pacifica e raduna predatori minori spingendoli al massacro.\n\nIl maestro di caccia Melor Zoccolo Granitico attende sull'Altura dei Cacciatori. Condanna a morte Steelsnap e chiede una costola della iena come prova. Una volta ucciso Steelsnap, il canyon potrà essere purificato dalla sua piaga."}},faq={{q="A cosa serve la Costola di Ganascia?",a="Porta la Costola di Ganascia a Melor Zoccolo Granitico sull'Altura dei Cacciatori, a Picco del Tuono. L'osso dimostra che Steelsnap è stato sconfitto.",al={"missione costola di ganascia","chi vuole la costola di ganascia","cosa fare con la costola di ganascia"}},{q="Dove posso trovare Steelsnap per ottenere la costola?",a="Steelsnap si aggira sul fondo del canyon nella parte nordoccidentale di Millepicchi, a sud dell'Accampamento E'thok. I suoi fedeli compagni di branco lo affiancano spesso.",al={"posizione di steelsnap","dove si trova steelsnap","trova steelsnap"}},{q="Perché Melor Zoccolo Granitico vuole la morte di Steelsnap?",a="Melor considera Steelsnap un tiranno contro natura, privo della benedizione della Madre Terra. La iena semina massacri e paura tra le bestie pacifiche, a differenza dei predatori che cacciano per sopravvivere.",al={"perché uccidere steelsnap","movente di melor zoccolo granitico","storia di steelsnap"}},{q="Chi è Melor Zoccolo Granitico?",a="Melor Zoccolo Granitico è un esperto cacciatore tauren che si trova sull'Altura dei Cacciatori, a Picco del Tuono. Manda aspiranti battitori sulle tracce di bestie pericolose in tutta Kalimdor.",al={"chi è melor","posizione di melor zoccolo granitico","melor altura dei cacciatori"}}},fx={["27efcb35"]={q="Cos'è la Costola di Ganascia?",a="È un osso pesante ricavato dalla carcassa di Steelsnap, una iena notoriamente feroce che terrorizza i canyon di Millepicchi. Non è un materiale utile per la fabbricazione né carne: serve come prova tangibile che la bestia sanguinaria è stata abbattuta.",al={"cos'è la costola di ganascia","osso di ganascia"}},["57ae26da"]={q="Da dove proviene la Costola di Ganascia?",a="La costola proviene direttamente dai resti di Steelsnap, una iena insolitamente feroce che si aggira per le aride pianure di Millepicchi, a sud di The Barrens. Per ottenerla, un cacciatore deve rintracciare la bestia e sconfiggere sia Steelsnap sia il suo branco.",al={"dove si trova la costola di ganascia","origine della costola di ganascia","chi rilascia la costola di ganascia"}},["4a69fb67"]={q="Perché Melor Zoccolo Granitico vuole la Costola di Ganascia?",a="Melor Zoccolo Granitico chiede la costola come prova tangibile della morte di Steelsnap. A differenza delle cacce intraprese per procurarsi cibo o onore, Melor manda i cacciatori a eliminare Steelsnap perché la bestia vive al di fuori della benedizione della Madre Terra e diffonde violenza e paura tra le creature più pacifiche. Riportare l'osso conferma che il canyon è stato liberato da quella contaminazione.",al={"perché portare la costola di ganascia a melor","perché a melor serve la costola","perché raccogliere la costola di ganascia"}}},fp="15,181,27.428.0,33.118.0,42.121.0,47.180.0,23.142.0"}
P.entries["item:stolen-silver"] = {n="Argento Rubato",s="A Crocevia, l'Argento Rubato è scomparso dalla torre di guardia. I raptor Sunscale hanno portato le monete a sud di Porto Paranco, nei loro nidi ai Raptor Grounds.",h="A Crocevia, l'Argento Rubato è scomparso dalla torre di guardia.",kw={"paghe delle savane","crocevia","gazrog","raptor grounds","cassetta d'argento","argento rubato","sunscale raptor"},ang={["faction:Horde"]="Crocevia è il cuore della presenza dell'Orda nelle Savane. Recuperare la paga permette ai grunt locali di nutrirsi e ricevere il soldo, pronti a tenere la linea contro le incursioni dei centauri e dell'Alleanza."},sec={{t="Un colpo bestiale",b="I raptor Sunscale hanno portato via una cassetta di monete d'argento dalla torre di guardia di Crocevia. Le monete erano destinate alla paga delle guardie della guarnigione. I raptor hanno trascinato la cassetta chiusa a chiave nei loro nidi comuni ai Raptor Grounds, a sud di Porto Paranco. Gazrog e gli altri sovrintendenti non sanno spiegare cosa abbia spinto i predatori a prenderla. Si chiedono se i raptor apprezzino gli oggetti luccicanti o siano più astuti delle comuni bestie selvatiche."}},faq={{q="Cos'è l'Argento Rubato?",a="L'Argento Rubato è una pesante cassetta chiusa a chiave contenente monete destinate alla paga delle guardie di Crocevia. I raptor l'hanno rubata dalla torre di guardia e portata nei loro territori di nidificazione.",al={"cos'è l'argento rubato","cos'è l'argento"}},{q="Perché i raptor hanno rubato una cassetta di monete?",a="Nemmeno Gazrog sa spiegare perché i raptor abbiano preso la cassetta. Forse il metallo luccicante li ha attirati, oppure un'insolita astuzia li ha spinti a portarla nel cuore della loro tana.",al={"perché i raptor vogliono l'argento","intelligenza dei raptor","perché l'argento"}},{q="Dov'è stato portato l'argento?",a="I raptor hanno portato la cassetta ai Raptor Grounds, un aspro canyon pieno di nidi a sud di Porto Paranco, nelle Savane orientali.",al={"posizione dell'argento rubato","dov'è l'argento"}},{q="Chi sta cercando l'Argento Rubato?",a="Gazrog, un orco di stanza a Crocevia, sta cercando la cassetta. L'argento rappresenta un intero mese di paga per i difensori dell'avamposto, messi a dura prova.",al={"chi vuole l'argento","a chi consegnare l'argento rubato"}}},fp="13,157,15.406.0,26.160.0,41.157.0,27.120.0,37.146.0"}
P.entries["item:stone-of-relu"] = {n="Pietra di Relu",s="Nelle Paludi Grigie, la Pietra di Relu va perduta dopo un'imboscata dei raptor all'Archeologo Granrutto. Lui crede che possa svelare i segreti racchiusi negli antichi fossili.",h="Nelle Paludi Grigie, la Pietra di Relu va perduta dopo un'imboscata dei raptor all'Archeologo Granrutto.",kw={"archeologo granrutto","lega degli esploratori","fossile","raptor chiazzato","prospettore whelgar","pietra di relu","paludi grigie"},ang={["faction:Alliance"]="Le spedizioni dell'Alleanza a Porto di Menethil contano sui manufatti recuperati, come la Pietra di Relu, per giustificare difficili scavi nelle pericolose paludi.",["race:Dwarf"]="Per la Lega degli Esploratori, la Pietra di Relu potrebbe aiutare a ricostruire le origini della vita antica e il retaggio dimenticato del mondo."},sec={{t="Una chiave per antiche reliquie",b="La Lega degli Esploratori ha scoperto la Pietra di Relu. L'Archeologo Granrutto crede che il manufatto possa decifrare i fossili preistorici raccolti a Kalimdor e nei Regni Orientali. Intende studiare i suoi campioni delle Paludi Grigie e il fossile dissotterrato dal Prospettore Errasogni a Rivafosca."},{t="Perduta nelle paludi",b="L'Archeologo Granrutto percorreva una strada delle Paludi Grigie per incontrare il Prospettore Whelgar quando alcuni raptor chiazzati gli tesero un'imboscata. Nella confusione, la reliquia andò perduta, poi fu inghiottita da una delle bestie. Ora la Lega cerca i raptor della palude, sperando di estrarre l'antica pietra dai loro gozzi."}},faq={{q="Cos'è la Pietra di Relu?",a="L'Archeologo Granrutto cerca la Pietra di Relu, un antico manufatto che ritiene capace di svelare i misteri nascosti e il potere racchiusi nei fossili preistorici.",al={"pietra di relu","cos'è questa pietra","manufatto di relu"}},{q="Come è finita la pietra dentro un raptor?",a="Alcuni raptor chiazzati attaccarono l'Archeologo Granrutto su una strada delle Paludi Grigie, mentre si recava a incontrare il Prospettore Whelgar. Nel caos, una bestia inghiottì la pietra perduta.",al={"perché i raptor ce l'hanno","chi ha perso la pietra","come è andata perduta"}},{q="Cosa intende fare Granrutto con la pietra?",a="Granrutto intende usare la Pietra di Relu sul fossile che ha recuperato e su quello trovato dal Prospettore Errasogni a Rivafosca. Spera di decifrare e sprigionare i loro segreti magici latenti.",al={"cosa vuole granrutto","scopo della pietra di relu"}}},fp="13,142,23.275.0,19.285.0,26.146.0,41.160.0,48.179.0"}
